// Runtime rules for Blender library materials (look pass, requests from the willow canopy pass,
// commit c277388). GLTFLoader's defaults don't match how these are painted:
//   - MAT_willow_bark and the vertex-coloured kit materials (MAT_vc_*, the willow strands among them)
//     carry their baked AO and gradients in vertex colours: vertexColors on;
//   - MAT_vc_foliage (the crown's leaf cards) is a cut-out: alphaTest 0.45, both sides, drawn with
//     the solid things (no blending, writes depth), so cards sort and shadow correctly.
// The zone loader (P3) and the turntable's binder call this on every library material they keep.
import * as THREE from "three";

// Leaf cards and crowns dissolve (screen-door dither) within ~1.6 m of the camera, so a camera
// backed into a tree never fills the screen with leaves (pilot review fix 8). Chained after any
// patch the material already has; one more program variant per material.
// (TODO 27: a scooter or unicorn rides through a crown: the leaves part round the rider and swing back.
// PUSH holds up to four pushers, (x, z, ground y, amount in metres; 0 = none), set each frame by ridefx.js;
// a negative amount is the spring swinging back past rest. Every leaf material takes it: it rides on nearFade.)
export const PUSH = { value: [new THREE.Vector4(), new THREE.Vector4(), new THREE.Vector4(), new THREE.Vector4()] };
// How the two fades below (near the lens, and on the camera's line of sight) take a piece away. An on/off dither
// of a lit paper lantern was a field of full-bright dots, and the glow pass spread each one (the lanterns' speckle,
// review 2026-11-28). Where the picture is smoothed by samples (every tier's usual path), a solid piece gives each
// pixel a share of its samples instead (alpha to coverage; its four steps are spread by the same still screen
// pattern, so nothing shimmers from frame to frame), and a see-through piece simply fades. Only without samples is
// it the on/off dither.
let fadeSmooth = false;
export function setFadeSmooth(on) {
  fadeSmooth = Boolean(on);
}
// (a solid piece: its coverage is the fade's alone, whatever its picture's alpha; a leaf card keeps its own cut-out)
function fadeKind(m) {
  const solid = !m.transparent && !(m.alphaTest > 0);
  if (fadeSmooth && solid) m.alphaToCoverage = true;
  return () => (m.transparent ? "a" : m.alphaToCoverage ? (solid ? "s" : "c") : "d");
}
// the shader lines that keep the share k of a fragment (h: the screen pattern, 0..1)
const fadeTake = (how, k) =>
  how === "d" ? `if ( h > ${k} ) discard;` : how === "a" ? `tddFadeA *= ${k}; if ( tddFadeA < 0.004 ) discard;` : `tddFadeA *= clamp( ${k} + ( h - 0.5 ) * 0.25, 0.0, 1.0 ); if ( tddFadeA < 0.06 ) discard;`;
// (once per shader, whichever fade comes first. A solid piece's alpha is its opacity alone, as three's own opaque
// path: its fade copies, render/fade.js, blend by it)
function fadeAlpha(sh, how) {
  if (how === "d" || sh.fragmentShader.includes("float tddFadeA")) return;
  sh.fragmentShader = sh.fragmentShader
    .replace("#include <common>", "#include <common>\nfloat tddFadeA = 1.0;")
    .replace("#include <dithering_fragment>", `#include <dithering_fragment>\n  gl_FragColor.a = ${how === "s" ? "opacity" : "gl_FragColor.a"} * tddFadeA;`);
}
// (blend: a small lit piece on its own, a lantern, a bulb: drawn see-through from the start, so near the lens it
// fades by its alpha on every tier. Shared samples left a lit lantern a glass of dots still: its light is several
// times white, and one step of coverage of that is a visible dot. Not for the kits' big merged pieces.)
export function nearFade(m, near = 0.5, far = 1.6, blend = false) {
  if (m.userData.nearFade) return m;
  m.userData.nearFade = true;
  if (blend && !(m.alphaTest > 0)) m.transparent = true;
  const mode = fadeKind(m);
  const prev = m.onBeforeCompile;
  const prevKey = m.customProgramCacheKey;
  m.onBeforeCompile = (sh, r) => {
    prev.call(m, sh, r);
    const how = mode();
    fadeAlpha(sh, how);
    sh.uniforms.tddPush = PUSH;
    sh.vertexShader = sh.vertexShader.replace("#include <common>", "#include <common>\nuniform vec4 tddPush[4];").replace(
      "#include <project_vertex>",
      `{
        mat4 tpm = modelMatrix;
        #ifdef USE_INSTANCING
          tpm = modelMatrix * instanceMatrix;
        #endif
        vec3 tpw = ( tpm * vec4( transformed, 1.0 ) ).xyz;
        vec3 tpo = vec3( 0.0 );
        for ( int i = 0; i < 4; i ++ ) {
          vec4 q = tddPush[ i ];
          if ( q.w == 0.0 ) continue;
          vec2 d = tpw.xz - q.xy;
          float dl = length( d );
          // (the crown round the rider, never the trunk's foot: more the higher the leaf)
          float f = ( 1.0 - smoothstep( 0.3, 2.6, dl ) ) * smoothstep( 0.3, 2.0, tpw.y - q.z );
          tpo.xz += d / max( dl, 0.05 ) * q.w * f;
          tpo.y -= abs( q.w ) * f * 0.18;
        }
        if ( dot( tpo, tpo ) > 0.0 ) {
          // (back into the mesh's own frame: its rotation and its even scale)
          mat3 tp3 = mat3( tpm );
          transformed += transpose( tp3 ) * tpo / max( dot( tp3[ 0 ], tp3[ 0 ] ), 1e-6 );
        }
      }
      #include <project_vertex>`,
    );
    sh.fragmentShader = sh.fragmentShader.replace(
      "#include <clipping_planes_fragment>",
      `#include <clipping_planes_fragment>
      {
        float nd = length( vViewPosition );
        if ( nd < ${far.toFixed(2)} ) {
          float h = fract( 52.9829189 * fract( dot( gl_FragCoord.xy, vec2( 0.06711056, 0.00583715 ) ) ) );
          ${fadeTake(how, `smoothstep( ${near.toFixed(2)}, ${far.toFixed(2)}, nd )`)}
        }
      }`,
    );
  };
  m.customProgramCacheKey = () => `${prevKey.call(m)}|near${mode()}|push`;
  m.needsUpdate = true;
  return m;
}

export function libraryMaterial(m, geo) {
  const n = m?.name || "";
  if (!/^MAT_(vc_|willow_)/.test(n)) return m;
  if (n === "MAT_willow_bark" || n.startsWith("MAT_vc_") || /strand/i.test(n)) {
    if (!geo || geo.attributes.color) m.vertexColors = true;
  }
  if (n === "MAT_vc_foliage") {
    m.alphaTest = 0.45;
    m.side = THREE.DoubleSide;
    m.transparent = false;
    m.depthWrite = true;
    m.blending = THREE.NormalBlending;
  }
  m.needsUpdate = true;
  return m;
}

// Cut-out leaf cards lose their crowns far off: each smaller mip of the leaf atlas averages the cards' edges
// with the clear around them, so alpha falls under the cut-out line and only the opaque trunks (same atlas)
// stay (the user, 2026-11-20, from the lookout: bare red trunks). Alpha is scaled back up by how far down the
// mip chain the fragment samples, so a crown keeps its coverage at any distance. One more program variant.
export function keepFarAlpha(m) {
  if (m.userData.keepFarAlpha) return m;
  m.userData.keepFarAlpha = true;
  const prev = m.onBeforeCompile;
  const prevKey = m.customProgramCacheKey;
  m.onBeforeCompile = (sh, r) => {
    prev.call(m, sh, r);
    sh.fragmentShader = sh.fragmentShader.replace(
      "#include <alphatest_fragment>",
      `#ifdef USE_MAP
      {
        vec2 tsz = vec2( textureSize( map, 0 ) );
        vec2 dx = dFdx( vMapUv * tsz ), dy = dFdy( vMapUv * tsz );
        float lod = max( 0.0, 0.5 * log2( max( dot( dx, dx ), dot( dy, dy ) ) ) );
        diffuseColor.a *= 1.0 + lod * 0.3;
      }
      #endif
      #include <alphatest_fragment>`,
    );
  };
  m.customProgramCacheKey = () => `${prevKey.call(m)}|farA`;
  m.needsUpdate = true;
  return m;
}
// The close-up detail of the kit atlases (TODO 25, the user: "Low-res: the scarecrow, room and object exteriors,
// the tree house, and trees"). A kit atlas gives a room house 8-30 px a metre, so a near camera saw a blur; the
// baked faces carry a second UV (TEXCOORD_1, tdd_kit_atlas.py detail_uv): u = 256 x kind + the tile u, v = the
// tile v, and the matching seamless Blender tile (build_kit_detail.py: a = planks / shingles / plaster, b = stone
// / bark / wood) is multiplied over the atlas colour (0.5 grey = as painted), fading out by `far` metres. Faces
// without the UV (LODs, lite, other kits) read kind 0 and are left alone. One more program variant per kit.
export const KIT_DETAIL_GAIN = [0, 0.85, 0.85, 0.38, 0.6, 0.8, 0.55];
export function kitDetail(m, a, b, far = 40) {
  if (m.userData.kitDetail) return m;
  m.userData.kitDetail = true;
  const prev = m.onBeforeCompile;
  const prevKey = m.customProgramCacheKey;
  const base = prevKey === THREE.Material.prototype.customProgramCacheKey ? () => prev.toString() : () => prevKey.call(m);
  const g = KIT_DETAIL_GAIN.map((x) => x.toFixed(2));
  m.onBeforeCompile = (sh, r) => {
    prev.call(m, sh, r);
    sh.uniforms.tddDetA = { value: a };
    sh.uniforms.tddDetB = { value: b };
    sh.vertexShader = sh.vertexShader
      .replace("#include <common>", "#include <common>\n#ifndef USE_UV1\nattribute vec2 uv1;\n#endif\nvarying vec3 vTddDet;")
      .replace("#include <uv_vertex>", "#include <uv_vertex>\n{ float k = floor( uv1.x / 256.0 ); vTddDet = vec3( uv1.x - 256.0 * k, uv1.y, k ); }");
    sh.fragmentShader = sh.fragmentShader.replace("#include <common>", "#include <common>\nuniform sampler2D tddDetA;\nuniform sampler2D tddDetB;\nvarying vec3 vTddDet;").replace(
      "#include <map_fragment>",
      `#include <map_fragment>
      {
        vec2 dt = vTddDet.xy;
        vec2 ddx = dFdx( dt ), ddy = dFdy( dt );
        float dk = floor( vTddDet.z + 0.5 );
        float dfade = 1.0 - smoothstep( ${(far * 0.55).toFixed(1)}, ${far.toFixed(1)}, length( vViewPosition ) );
        if ( dk > 0.5 && dfade > 0.0 ) {
          vec3 dtx = dk < 3.5 ? textureGrad( tddDetA, dt, ddx, ddy ).rgb : textureGrad( tddDetB, dt, ddx, ddy ).rgb;
          float dsel = mod( dk - 1.0, 3.0 );
          float dg = dsel < 0.5 ? dtx.r : dsel < 1.5 ? dtx.g : dtx.b;
          float dgain = dk < 1.5 ? ${g[1]} : dk < 2.5 ? ${g[2]} : dk < 3.5 ? ${g[3]} : dk < 4.5 ? ${g[4]} : dk < 5.5 ? ${g[5]} : ${g[6]};
          diffuseColor.rgb *= max( 1.0 + ( dg * 2.0 - 1.0 ) * dgain * dfade, 0.0 );
        }
      }`,
    );
  };
  m.customProgramCacheKey = () => `${base()}|kdet`;
  m.needsUpdate = true;
  return m;
}

// The trees' trunks (TODO 25): every Blender tree maps its trunk, roots and limbs into a 24 x 28 px bark patch of
// T_veg_leaves (trees_v3 bark_uv, about 150 px a metre on PC, 75 on phones). Those fragments (the patch's UV box)
// also take the bark detail tile (T_kit_detail_b green: furrows up the trunk, 0.5 m across x 1 m up), laid round
// the limb in the tree's own space (two side projections blended by the normal, so the furrows stay put as the
// tree is instanced anywhere). Leaves and the fill cores are untouched.
export function treeBark(m, b, far = 30) {
  if (m.userData.treeBark) return m;
  m.userData.treeBark = true;
  const prev = m.onBeforeCompile;
  const prevKey = m.customProgramCacheKey;
  const base = prevKey === THREE.Material.prototype.customProgramCacheKey ? () => prev.toString() : () => prevKey.call(m);
  m.onBeforeCompile = (sh, r) => {
    prev.call(m, sh, r);
    sh.uniforms.tddBark = { value: b };
    sh.vertexShader = sh.vertexShader
      .replace("#include <common>", "#include <common>\nvarying vec3 vBkP;\nvarying vec3 vBkN;")
      .replace("#include <begin_vertex>", "#include <begin_vertex>\nvBkP = position;\nvBkN = normal;");
    sh.fragmentShader = sh.fragmentShader.replace("#include <common>", "#include <common>\nuniform sampler2D tddBark;\nvarying vec3 vBkP;\nvarying vec3 vBkN;").replace(
      "#include <map_fragment>",
      `#include <map_fragment>
      #ifdef USE_MAP
      {
        vec2 bx = vBkP.zy * vec2( 2.0, 1.0 ), bz = vBkP.xy * vec2( 2.0, 1.0 );
        vec2 bxx = dFdx( bx ), bxy = dFdy( bx ), bzx = dFdx( bz ), bzy = dFdy( bz );
        float bfade = 1.0 - smoothstep( ${(far * 0.5).toFixed(1)}, ${far.toFixed(1)}, length( vViewPosition ) );
        if ( vMapUv.x > 0.425 && vMapUv.x < 0.49 && vMapUv.y > 0.918 && vMapUv.y < 0.99 && bfade > 0.0 ) {
          vec3 bn = abs( normalize( vBkN ) );
          vec2 bw = pow( bn.xz + 1e-3, vec2( 4.0 ) );
          bw /= bw.x + bw.y;
          float bg = textureGrad( tddBark, bx, bxx, bxy ).g * bw.x + textureGrad( tddBark, bz, bzx, bzy ).g * bw.y;
          diffuseColor.rgb *= max( 1.0 + ( bg * 2.0 - 1.0 ) * 0.8 * bfade, 0.0 );
        }
      }
      #endif`,
    );
  };
  m.customProgramCacheKey = () => `${base()}|bark`;
  m.needsUpdate = true;
  return m;
}

// The willow's trunk and limbs (TODO 25): its painted bark map repeats along the limb UVs (plates and cracks, v up
// the limb); the bark detail tile adds the fine furrows over it, `k` tiles per repeat, fading out by `far` metres.
// Phones then need only the 256 bark map (zones/runtime.js), a quarter of the 512's memory.
export function willowBark(m, b, k = 3, far = 30) {
  if (m.userData.willowBark) return m;
  m.userData.willowBark = true;
  const prev = m.onBeforeCompile;
  const prevKey = m.customProgramCacheKey;
  const base = prevKey === THREE.Material.prototype.customProgramCacheKey ? () => prev.toString() : () => prevKey.call(m);
  m.onBeforeCompile = (sh, r) => {
    prev.call(m, sh, r);
    sh.uniforms.tddBark = { value: b };
    sh.fragmentShader = sh.fragmentShader.replace("#include <common>", "#include <common>\nuniform sampler2D tddBark;").replace(
      "#include <map_fragment>",
      `#include <map_fragment>
      #ifdef USE_MAP
      {
        float wfade = 1.0 - smoothstep( ${(far * 0.5).toFixed(1)}, ${far.toFixed(1)}, length( vViewPosition ) );
        if ( wfade > 0.0 ) {
          float wg = texture2D( tddBark, vMapUv * ${k.toFixed(1)} ).g;
          diffuseColor.rgb *= max( 1.0 + ( wg * 2.0 - 1.0 ) * 0.6 * wfade, 0.0 );
        }
      }
      #endif`,
    );
  };
  m.customProgramCacheKey = () => `${base()}|wbark`;
  m.needsUpdate = true;
  return m;
}

// The follow camera's line of sight, in view space: xyz = the point it looks at (your head), w = 1
// while the main picture of the follow camera is drawn outdoors (island.js sets it round that one
// render, so the shadows, the snapshots and every other view never see it).
export const SIGHT = { value: new THREE.Vector4() };

// Trees and small props no longer pull the camera in (the user, 2026-11-27: "dont let the camera zoom
// in if im close to an object"): the camera keeps its distance and what stands on the line from it
// to you dissolves (the same screen-door dither as nearFade) in a tube that is widest at the lens (a
// stall roof or a crown the camera sits in is cut, never seen from inside) and closes before your feet.
// The houses still shorten the arm, so the tube never reaches them. One more program variant.
// (smooth where the picture has samples to share: fadeKind above)
export function sightFade(m) {
  if (m.userData.sightFade) return m;
  m.userData.sightFade = true;
  const mode = fadeKind(m);
  const prev = m.onBeforeCompile;
  const prevKey = m.customProgramCacheKey;
  // (three's default key is the hook's own source: take the previous hook's, not this wrapper's)
  const base = prevKey === THREE.Material.prototype.customProgramCacheKey ? () => prev.toString() : () => prevKey.call(m);
  m.onBeforeCompile = (sh, r) => {
    prev.call(m, sh, r);
    sh.uniforms.tddSight = SIGHT;
    // (the unlit materials, a photo board: no view position of their own, so it is passed here)
    if (!/varying vec3 vViewPosition/.test(sh.vertexShader)) {
      sh.vertexShader = sh.vertexShader.replace("#include <common>", "#include <common>\nvarying vec3 vViewPosition;").replace("#include <project_vertex>", "#include <project_vertex>\nvViewPosition = - mvPosition.xyz;");
      sh.fragmentShader = sh.fragmentShader.replace("#include <common>", "#include <common>\nvarying vec3 vViewPosition;");
    }
    const how = mode();
    fadeAlpha(sh, how);
    sh.fragmentShader = sh.fragmentShader.replace("#include <common>", "#include <common>\nuniform vec4 tddSight;").replace(
      "#include <clipping_planes_fragment>",
      `#include <clipping_planes_fragment>
      if ( tddSight.w > 0.5 ) {
        vec3 sp = -vViewPosition;
        vec3 sb = tddSight.xyz;
        float st = clamp( dot( sp, sb ) / max( dot( sb, sb ), 1e-4 ), 0.0, 1.0 );
        float sr = mix( 1.5, 0.85, st );
        float sk = max( smoothstep( sr * 0.45, sr, length( sp - sb * st ) ), smoothstep( 0.8, 0.92, st ) );
        if ( sk < 1.0 ) {
          float h = fract( 52.9829189 * fract( dot( gl_FragCoord.xy, vec2( 0.06711056, 0.00583715 ) ) ) );
          ${fadeTake(how, "sk")}
        }
      }`,
    );
  };
  m.customProgramCacheKey = () => `${base()}|sight${mode()}`;
  m.needsUpdate = true;
  return m;
}
