// The animals from the Blender animals kit (Wave 9, rebuild/reports/assets-animals.md): every legacy
// creature model (creatures.js cats, bunnies, deer and pets; farm.js; lake.js ducks; garden.js
// hedgehog, bees, butterflies; fx.js dookie) is first built the old procedural way, as before (so
// gameplay and randomness stay identical), and registered here. Once the kit is in (runtime.js
// streamAnimals, v2 zones only) each one wears its GLB rig instead: the holder group (root / g) is
// kept, its procedural children leave, and the model's fields (body, head, legs, ...) point at the
// rig's ANIM_ pivots, which sit exactly where the legacy groups sat. Behaviour code is unchanged.
// Levels: full near on computers, _lite on phones and past 25 m, _far (one rest-pose mesh) where
// the farm and the lake stop animating. Under zones=legacy nothing is ever loaded: procedural only.
import * as THREE from "three";
import { mergeGeometries } from "three/examples/jsm/utils/BufferGeometryUtils.js";
import { zoneMode } from "./mode.js";
import { fade, warmFades } from "../render/fade.js";

const LITE_AT = 75; // (PC: the lite rigs only far off, where the swap is a few pixels; phones load lite only)
const PHONE_FAR = 70;
const PHONE_FAR_STILL = 75; // (phones: past this a standing far-mesh animal dithers out, Skin.pick) // (phones: past this a creature with no far mesh dithers out, Skin.away)
let lib = null; // { scenes: Map(name -> scene), small, roles }
const waiting = []; // skins registered before the kit came in
const skins = []; // skins worn, for the level switch
const tintCache = new Map();
const readyFns = [];
let v2 = null; // (zones=legacy: nothing registers, nothing loads)
const isV2 = () => (v2 ??= zoneMode().v2);

export const animalsReady = () => Boolean(lib);
export const animalsSmall = () => Boolean(lib?.small);

// (W16: the tint mask is a one-hot region map; the low-res masks (phones: 256 px) blur it to part strength at
// every UV island edge, which showed as pale steps on the pets' heads: a covered texel takes its dominant
// region at full strength)
const MASK_OF = "vec3 tddMaskOf(vec3 km) { float m = max(km.r, max(km.g, km.b)); return m < 0.45 ? vec3(0.0) : step(vec3(m - 1e-4), km); }";

// ---- per-node tints: one material instance per colour set (same program "tdd_kit", own uniform) ----
function tinted(base, t) {
  const key = base.uuid + "|" + (t.fur || "") + "|" + (t.paint || "") + "|" + (t.user || "");
  if (tintCache.has(key)) return tintCache.get(key);
  const mask = base.userData.kitMask;
  const roles = lib?.roles || { r: "fur", g: "paint", b: "user" };
  if (!mask) return base;
  // (TODO 50: a material's clone copies its userData through JSON, and this one holds the mask texture: the whole mask
  // image was encoded to a data URL, about 120 ms, each time a pet or creature was dressed as you walked by)
  const ud = base.userData;
  base.userData = {};
  const m = base.clone();
  base.userData = ud;
  const tints = [0, 1, 2].map(() => new THREE.Color(1, 1, 1));
  ["r", "g", "b"].forEach((ch, i) => {
    const r = roles[ch];
    if (r && t[r]) tints[i].set(t[r]);
  });
  m.userData = { ...base.userData, tinted: true, tints, base };
  m.onBeforeCompile = (sh) => {
    sh.uniforms.tddKitMask = { value: mask };
    sh.uniforms.tddKitTint = { value: tints };
    sh.fragmentShader = sh.fragmentShader
      .replace("#include <common>", "#include <common>\nuniform sampler2D tddKitMask;\nuniform vec3 tddKitTint[3];\n" + MASK_OF)
      .replace(
        "#include <map_fragment>",
        "#include <map_fragment>\n{ vec3 km = tddMaskOf(texture2D(tddKitMask, vMapUv).rgb);\n  diffuseColor.rgb *= mix(vec3(1.0), tddKitTint[0], km.r) * mix(vec3(1.0), tddKitTint[1], km.g) * mix(vec3(1.0), tddKitTint[2], km.b); }",
      );
  };
  m.customProgramCacheKey = () => "tdd_kit";
  tintCache.set(key, m);
  return m;
}

// ---- petLook (creatures.js makeCat / makeBunny / buildPetModels as "show these nodes, tint each") ----
const shade = (hex, k) => "#" + new THREE.Color(hex).multiplyScalar(k).getHexString();
export function petLook(species, L, { pet = true, golden = false } = {}) {
  const { fur, accent = "#ffffff", pattern = "solid", coat = "short", eyes = "#2b1d24", eyes2 = "", collar = "#e2557f" } = L;
  const ears = L.ears || "pointy";
  const tail = L.tail || "long";
  const point = pattern === "siamese" ? "#4a3528" : null;
  const tux = pattern === "tuxedo";
  const socks = pattern === "socks";
  const stripe = shade(fur, fur === "#2b2633" ? 1.8 : 0.62);
  const bib = tux ? "#ffffff" : accent;
  const c1 = accent && accent !== fur ? accent : "#f4a259";
  const c2 = fur === "#2b2633" ? "#fff7f0" : "#2b2633";
  const mane = shade(fur, fur === "#2b2633" ? 1.25 : 1.06);
  const earCol = point || fur;
  const T = {};
  const show = (n, t) => (T[n] = t || {});
  show("body_" + coat, { fur, paint: bib });
  if (tux) show("bib_tuxedo_" + coat);
  if (pattern === "tabby") {
    show("stripes_" + coat, { fur: stripe });
    show("head_stripes", { fur: stripe });
  }
  if (pattern === "calico") {
    show("calico_a_" + coat, { fur: c1 });
    show("calico_b_" + coat, { fur: c2 });
    show("head_calico", { fur: c1 });
  }
  if (eyes2) show("iris_odd", { user: eyes2 });
  if (pet) show("collar_" + coat, { user: collar });
  if (species === "cat") {
    const paw = tux || socks ? "#ffffff" : point;
    show("head", { fur, paint: bib, user: eyes });
    if (coat === "fluffy") show("ruff", { fur: mane });
    if (point || tux) show("muzzle", { fur: point || "#ffffff" });
    if (ears === "fold") show("ears_fold", { fur: earCol });
    else show("ears_pointy", { fur: earCol });
    if (ears === "tufts") show("ears_tufts", { fur: shade(earCol, 0.72) });
    for (let i = 0; i < 4; i++) show("leg_" + i, { fur, paint: paw || fur });
    const segs = tail === "stubby" ? 1 : 4;
    for (let i = 0; i < segs; i++) {
      const tip = i === segs - 1;
      const col = tip ? point || (pattern === "tabby" ? stripe : accent) : pattern === "tabby" && i % 2 ? stripe : fur;
      show("tail_" + (tail === "stubby" ? "stubby" : tail) + "_" + i, { fur: col });
    }
  } else {
    const paw = tux || socks ? "#ffffff" : point || fur;
    show("head", { fur, paint: tux ? "#ffffff" : accent, user: eyes });
    show("tail_" + tail, { fur: point || accent });
    if (point) show("point");
    if (tux) show("blaze");
    if (coat === "fluffy") show("mane", { fur: mane });
    if (golden) show("goldbow");
    show("nose");
    for (let i = 0; i < 2; i++) {
      if (ears === "fold") show("ear_lop_" + i, { fur: earCol });
      else show("ear_up_" + i, { fur: earCol });
      if (ears === "tufts") show("ear_tuft_" + i, { fur: shade(earCol, 0.72) });
      show("paw_" + i, { fur: paw });
      show("foot_" + i, { fur: socks ? "#ffffff" : point || fur });
    }
  }
  return T;
}

// ---- one rig: a clone of the asset with only the shown meshes, tinted ----
function rig(asset, { show = null, hide = null, tint = null, hat = null, collar = null } = {}) {
  const src = lib.scenes.get(asset);
  if (!src) return null;
  const root = src.clone(true);
  const nodes = {};
  const pre = "ANIM_" + asset + "_";
  const sm = "SM_" + asset + "_";
  const drop = [];
  root.traverse((o) => {
    const n = o.name || "";
    if (n.startsWith(pre)) {
      nodes[n.slice(pre.length)] = o;
      // (its rest, for the clip binding: anim/runtime.js RigBinding)
      o.userData.restTRS = Float32Array.of(o.position.x, o.position.y, o.position.z, o.quaternion.x, o.quaternion.y, o.quaternion.z, o.quaternion.w, o.scale.x, o.scale.y, o.scale.z);
    }
    if (!o.isMesh) return;
    const sfx = n.startsWith(sm) ? n.slice(sm.length) : null;
    let t = tint;
    if (show) {
      if (sfx === null || show[sfx] === undefined) return drop.push(o);
      t = show[sfx];
    } else if (hide && sfx !== null && hide.includes(sfx)) return drop.push(o);
    if (t && Object.keys(t).length && o.material?.userData?.kitMask) o.material = tinted(o.material, t);
  });
  for (const o of drop) o.removeFromParent();
  if (hat && hat !== "none" && nodes.head) {
    const species = asset.includes("bunny") ? "bunny" : "cat";
    const h = lib.scenes.get("ani_pet_hats")?.getObjectByName(`INST_ani_pet_hats_${hat}_${species}`);
    if (h) {
      const c = h.clone(true);
      c.position.set(0, 0, 0);
      c.rotation.set(0, 0, 0);
      c.scale.set(1, 1, 1);
      if (c.material?.userData?.kitMask) c.material = tinted(c.material, { user: collar });
      nodes.head.add(c);
    }
  }
  merge(root);
  // (a kit with no ANIM_ pivot, the frog, hedgehog and bee: its one mesh is the clips' body)
  if (!Object.keys(nodes).length)
    root.traverse((o) => {
      if (nodes.body || !o.isMesh) return;
      nodes.body = o;
      o.userData.restTRS = Float32Array.of(o.position.x, o.position.y, o.position.z, o.quaternion.x, o.quaternion.y, o.quaternion.z, o.quaternion.w, o.scale.x, o.scale.y, o.scale.z);
    });
  return { root, nodes };
}

// ---- one draw per animal (review-threejs performance 1) ----
// Every kit part of a rig (each a mesh under its ANIM_ pivot, each tinted part its own material) is
// joined into ONE skinned mesh whose bones are those very pivots: the behaviour code still turns and
// scales the same nodes, and the three tints ride on each vertex, so one material serves every
// animal of the kit. Parts on other materials (the halo hat's glow) stay as they are.
const skinMats = new Map();
function skinMat(base) {
  if (skinMats.has(base)) return skinMats.get(base);
  const mask = base.userData.kitMask;
  // (clone() runs userData through JSON: the mask texture in it was encoded to a data URL, a long hitch, TODO 50)
  const ud = base.userData;
  base.userData = {};
  const m = base.clone();
  base.userData = ud;
  m.userData = { ...base.userData, skinned: true };
  m.onBeforeCompile = (sh) => {
    sh.uniforms.tddKitMask = { value: mask };
    sh.vertexShader = sh.vertexShader
      .replace("#include <common>", "#include <common>\nattribute vec3 aTintR;\nattribute vec3 aTintG;\nattribute vec3 aTintB;\nvarying vec3 vTintR;\nvarying vec3 vTintG;\nvarying vec3 vTintB;")
      .replace("#include <uv_vertex>", "#include <uv_vertex>\nvTintR = aTintR; vTintG = aTintG; vTintB = aTintB;");
    sh.fragmentShader = sh.fragmentShader
      .replace("#include <common>", "#include <common>\nuniform sampler2D tddKitMask;\nvarying vec3 vTintR;\nvarying vec3 vTintG;\nvarying vec3 vTintB;\n" + MASK_OF)
      .replace(
        "#include <map_fragment>",
        "#include <map_fragment>\n{ vec3 km = tddMaskOf(texture2D(tddKitMask, vMapUv).rgb);\n  diffuseColor.rgb *= mix(vec3(1.0), vTintR, km.r) * mix(vec3(1.0), vTintG, km.g) * mix(vec3(1.0), vTintB, km.b); }",
      );
  };
  m.customProgramCacheKey = () => "tdd_kit_skin";
  skinMats.set(base, m);
  return m;
}
const WHITE3 = [new THREE.Color(1, 1, 1), new THREE.Color(1, 1, 1), new THREE.Color(1, 1, 1)];
function merge(root) {
  root.updateMatrixWorld(true);
  const parts = [];
  root.traverse((o) => {
    if (o.isMesh && !o.isInstancedMesh && !o.isSkinnedMesh && o.material?.userData?.kitMask && o.parent) parts.push(o);
  });
  if (parts.length < 2) return;
  const base = parts[0].material.userData.base || parts[0].material;
  const bones = [];
  const boneOf = new Map();
  const geos = [];
  const inv = new THREE.Matrix4().copy(root.matrixWorld).invert();
  const m = new THREE.Matrix4();
  for (const o of parts) {
    const b = o.parent;
    if (!boneOf.has(b)) {
      boneOf.set(b, bones.length);
      bones.push(b);
    }
    const src = o.geometry;
    if (!src.attributes.position || !src.attributes.normal || !src.attributes.uv) return; // (not a kit part: leave the rig as it is)
    const g = new THREE.BufferGeometry();
    for (const k of ["position", "normal", "uv"]) g.setAttribute(k, src.attributes[k].clone());
    if (src.index) g.setIndex(src.index.clone());
    g.applyMatrix4(m.multiplyMatrices(inv, o.matrixWorld));
    const n = g.attributes.position.count;
    const bi = boneOf.get(b);
    g.setAttribute("skinIndex", new THREE.Uint16BufferAttribute(new Uint16Array(n * 4).fill(0).map((_, i) => (i % 4 === 0 ? bi : 0)), 4));
    g.setAttribute("skinWeight", new THREE.Float32BufferAttribute(new Float32Array(n * 4).map((_, i) => (i % 4 === 0 ? 1 : 0)), 4));
    const t = o.material.userData.tints || WHITE3;
    ["aTintR", "aTintG", "aTintB"].forEach((k, c) => {
      const a = new Float32Array(n * 3);
      for (let i = 0; i < n; i++) t[c].toArray(a, i * 3);
      g.setAttribute(k, new THREE.Float32BufferAttribute(a, 3));
    });
    geos.push(g);
  }
  const merged = mergeGeometries(geos);
  for (const g of geos) g.dispose();
  if (!merged) return;
  merged.userData.kit = false;
  for (const o of parts) o.removeFromParent();
  const sk = new THREE.SkinnedMesh(merged, skinMat(base));
  sk.name = "animal.skin";
  root.add(sk);
  root.updateMatrixWorld(true);
  sk.bind(new THREE.Skeleton(bones));
  // (the sphere a little roomier than the rest pose: legs and tails swing out of it)
  merged.computeBoundingSphere();
  sk.boundingSphere = merged.boundingSphere.clone();
  sk.boundingSphere.radius += 0.35;
}

// ---- levels ----
const copyPose = (a, b) => {
  if (!a || !b || a === b) return;
  if (Array.isArray(a)) return a.forEach((x, i) => copyPose(x, b[i]));
  if (!a.isObject3D) return;
  b.position.copy(a.position);
  b.quaternion.copy(a.quaternion);
  b.scale.copy(a.scale);
};

function wear(s) {
  const { holder, target, spec } = s;
  const base = spec.asset;
  const lite = lib.scenes.has(base + "_lite") ? base + "_lite" : null;
  const names = lib.small ? [lite || base] : lite ? [base, lite] : [base];
  const levels = names.map((n) => rig(n, spec.look || {})).filter(Boolean);
  if (!levels.length) return;
  const far = spec.far && lib.scenes.has(base + "_far") ? rig(base + "_far", { tint: spec.look?.tint || null }) : null;
  // (only the children it had when it was built: anything added since, a speech bubble, stays)
  let cast = false;
  let item = null;
  for (const c of s.old) {
    c.traverse((o) => {
      if (o.isMesh && o.castShadow) cast = true;
      if (o.userData.item) item = o.userData.item;
    });
    c.removeFromParent();
    if (spec.dispose) c.traverse((o) => o.geometry?.userData.kit || o.geometry?.dispose());
  }
  const all = far ? [...levels, far] : levels;
  for (const l of all) {
    l.root.traverse((o) => {
      if (o.isMesh) {
        o.castShadow = cast && !spec.noCast;
        o.receiveShadow = true;
      }
      if (item) o.userData.item = item;
    });
    holder.add(l.root);
  }
  s.levels = levels.map((l) => ({ root: l.root, nodes: l.nodes, fields: spec.fields ? spec.fields(l.nodes) : null }));
  s.far = far ? { root: far.root, fields: null } : null;
  warmFades([...s.levels.map((l) => l.root), s.far?.root]);
  s.cur = -1;
  s.still = Boolean(s.still);
  s.set(0);
  skins.push(s);
}

class Skin {
  constructor(holder, target, spec) {
    Object.assign(this, { holder, target, spec, old: [...holder.children], still: false, cur: -1, levels: null, far: null, fieldsFrom: null });
  }
  get worn() {
    return Boolean(this.levels);
  }
  // 0..n-1 the rigs (near to far), n the far mesh
  set(i) {
    if (!this.levels) return;
    const n = this.levels.length;
    if (i >= n && !this.far) i = n - 1;
    if (i === this.cur) return;
    // (a swap after the first: the new tier dithers in over the old one, which then goes, render/fade.js;
    // a hard cut read as the animal popping, review 2026-11-20)
    const rootOf = (k) => (k === n ? this.far?.root : this.levels[k]?.root);
    const old = this.cur >= 0 ? rootOf(this.cur) : null;
    this.cur = i;
    this.levels.forEach((l, k) => (l.root.visible = k === i || l.root === old));
    if (this.far) this.far.root.visible = i === n || this.far.root === old;
    const nw = rootOf(i);
    // (the old tier fades out after: where it stood past the new one's outline it went at once)
    const gone = () => this.cur === i && old !== rootOf(this.cur);
    if (old && nw && old !== nw) fade(nw, 0, 1, 0.45, () => gone() && fade(old, 1, 0, 0.25, () => gone() && (old.visible = false)));
    const l = this.levels[i];
    if (l?.fields) {
      if (this.fieldsFrom && this.fieldsFrom !== l) for (const k of Object.keys(l.fields)) copyPose(this.fieldsFrom.fields[k], l.fields[k]);
      Object.assign(this.target, l.fields);
      this.fieldsFrom = l;
    }
  }
  // the zone's own rule: its animals stand still (farm past 60 m, lake past 55 m)
  setStill(on) {
    if (on === this.still) return;
    this.still = on;
    this.pick(this.lastD ?? 0);
  }
  pick(d) {
    this.lastD = d;
    if (!this.levels) return;
    if (this.still && this.far) {
      this.set(this.levels.length);
      // (phones, TODO 1: a zone's standing animals (the farm's, the lake's ducks) seen from across the island were a
      // draw each, a few pixels big: past PHONE_FAR_STILL they dither out, and back in 8 m nearer)
      if (lib.small) this.away(this.hidden ? d > PHONE_FAR_STILL - 8 : d > PHONE_FAR_STILL);
      // (computers: only where it is under about three pixels: a duckling past ~70 m, a hen past ~120 m, never a cow)
      else {
        const far = this.farReach();
        this.away(this.hidden ? d > far - 8 : d > far);
      }
      return;
    }
    if (this.far && this.hidden) this.hidden = false; // (moving again, near: its rig is shown by set)
    this.set(this.levels.length > 1 && d > LITE_AT ? 1 : 0);
    // (phones, TODO 1: a pet, wild cat, bunny or deer with no far mesh, some 3-5k triangles, is a few pixels past
    // PHONE_FAR: it dithers out there and back in 8 m nearer, so it never flickers on the line and never pops)
    if (lib.small && !this.far) this.away(this.hidden ? d > PHONE_FAR - 8 : d > PHONE_FAR);
  }
  farReach() {
    if (this._farReach) return this._farReach;
    let r = 0;
    this.far.root.updateWorldMatrix(true, true);
    this.far.root.traverse((o) => {
      const g = o.isMesh && o.geometry;
      if (!g) return;
      if (!g.boundingSphere) g.computeBoundingSphere();
      r = Math.max(r, g.boundingSphere.radius * o.matrixWorld.getMaxScaleOnAxis());
    });
    return (this._farReach = Math.max(60, r * 440));
  }
  away(on) {
    if (on === Boolean(this.hidden)) return;
    this.hidden = on;
    const r = this.cur === this.levels.length ? this.far?.root : this.levels[this.cur]?.root;
    if (!r) return;
    if (on) fade(r, 1, 0, 0.5, () => this.hidden && (r.visible = false));
    else {
      r.visible = true;
      fade(r, 0, 1, 0.5);
    }
  }
}

// register a legacy model: holder (its root / g group), target (the object whose fields the
// behaviour code reads), spec { asset, look: { show | hide | tint, hat, collar }, fields(nodes),
// far, dispose }. Worn at once if the kit is in, else when it comes.
export function skinAnimal(holder, target, spec) {
  if (!holder || !isV2()) return null;
  const s = new Skin(holder, target, spec);
  if (lib) wear(s);
  else if (waiting.length < 400) waiting.push(s);
  return s;
}

// a mesh that the code moves itself (garden bees): its geometry and material become the asset's
export function meshOf(asset) {
  if (!lib) return null;
  const n = lib.small && lib.scenes.has(asset + "_lite") ? asset + "_lite" : asset;
  const src = lib.scenes.get(n);
  if (!src) return null;
  let m = null;
  src.updateMatrixWorld(true);
  src.traverse((o) => {
    if (!m && o.isMesh) m = o;
  });
  if (!m) return null;
  if (!m.userData.bakedGeo) m.userData.bakedGeo = m.geometry.clone().applyMatrix4(m.matrixWorld);
  return { geometry: m.userData.bakedGeo, material: m.material };
}

// the kit is in: everything built so far wears its rig
export function setAnimalLib(l) {
  lib = l;
  for (const s of waiting.splice(0)) {
    try {
      wear(s);
    } catch (e) {
      console.warn("animal skin", s.spec.asset, e);
    }
  }
  for (const fn of readyFns.splice(0)) fn();
}
// run once the kit is in (now if it is)
export function onAnimals(fn) {
  if (lib) fn();
  else if (isV2()) readyFns.push(fn);
}

const _p = new THREE.Vector3();
let timer = 0;
// every few frames: full or lite by distance (computers), the far mesh where the zone stands still
let idleT = 0;
export function tickAnimals(dt, camPos) {
  // the far meshes (one static rest-pose mesh, past the zone's animation cut-off) keep a light idle: a slow
  // breath, a weight shift from side to side and now and then a little nod, each animal on its own phase
  idleT += dt;
  for (const s of skins) {
    if (!s.far || !s.levels || s.cur !== s.levels.length) continue;
    const r = s.far.root;
    const ph = (s.idlePh ??= Math.random() * 100);
    const t = idleT + ph;
    r.scale.set(1, 1 + 0.018 * Math.sin(t * 1.9), 1);
    r.rotation.z = 0.025 * Math.sin(t * 0.55);
    const nod = Math.max(0, Math.sin(t * 0.23)) ** 8;
    r.rotation.x = 0.06 * nod;
  }
  timer -= dt;
  if (timer > 0 || !skins.length) return;
  timer = 0.3;
  for (let i = skins.length - 1; i >= 0; i--) {
    const s = skins[i];
    if (!s.holder.parent) {
      skins.splice(i, 1);
      continue;
    }
    s.holder.getWorldPosition(_p);
    s.pick(_p.distanceTo(camPos));
  }
}
export const animalStats = () => ({ ready: Boolean(lib), worn: skins.length, waiting: waiting.length, mats: tintCache.size });

// leaving the island: the kit, its tinted materials and every rig worn belong to that visit (the
// zone materials and atlases they use are released with it); a second visit starts clean
export function resetAnimals() {
  for (const m of tintCache.values()) m.dispose();
  tintCache.clear();
  for (const m of skinMats.values()) m.dispose();
  skinMats.clear();
  lib = null;
  v2 = null;
  timer = 0;
  waiting.length = 0;
  skins.length = 0;
  readyFns.length = 0;
}
