// A cute pastel scooter to zip around the island on.
import * as THREE from "three";
import { clipLib } from "./anim/clips.js";
import { RigBinding, Animator, AnimClock, mulberry, rotateRole, isCalm, STRIDE } from "./anim/runtime.js";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { MeshoptDecoder } from "three/examples/jsm/libs/meshopt_decoder.module.js";
import { zoneMode } from "./zones/mode.js";
import { RainbowTrail } from "./rainbowtrail.js";

const mat = (color, extra = {}) => new THREE.MeshStandardMaterial({ color, flatShading: true, roughness: 0.55, ...extra });

export const SCOOTER_COLORS = ["#ff8fb1", "#8fd3f0", "#b79be8", "#ffd166", "#8fd3b6"];
export const SEAT_H = 0.88; // the top of the seat

// ---- the Blender rides (assets/blender/vehicles/_build_vehicles.py): soft modelled scooter and unicorn on the very
// pivots the clips drive (lean, bars, wheels; lean > bob > neck > head, mane_i, tail, leg_i > knee_i). Every ride is
// built procedurally first (synchronous callers, legacy zones); when the GLBs are in, each one wears them: its
// procedural meshes leave its groups and the model's meshes, cloned per pivot role, take their place. Phones (low /
// mid tier) load the _lite set. Geometry is shared by every ride (never disposed with one).
const made = new Set();
let rideLib = null; // Map(asset -> Map(role -> [mesh]))
let rideSmall = false;
let rideLoad = null;
export function setRideTier(small) {
  rideSmall = Boolean(small);
}
// (the phone tiers: other props that come in a _lite copy follow the same choice, e.g. the photo tripod)
export const smallProps = () => rideSmall;
function loadRides() {
  if (rideLoad) return rideLoad;
  const zm = zoneMode();
  if (!zm.v2 || !zm.base) return (rideLoad = Promise.resolve(null));
  const loader = new GLTFLoader().setMeshoptDecoder(MeshoptDecoder);
  const sfx = rideSmall ? "_lite" : "";
  rideLoad = Promise.all(
    ["veh_scooter", "veh_unicorn"].map((n) =>
      loader.loadAsync(zm.base + "vehicles/" + n + sfx + ".glb").then((g) => {
        const roles = new Map();
        // (the unicorn's coat is skinned to its pivots: their rest transforms in the model's frame, the skin's bind)
        roles.rest = new Map();
        g.scene.updateMatrixWorld(true);
        g.scene.traverse((o) => {
          const role = o.userData?.tdd_role;
          if (!role) return;
          roles.rest.set(role, o.matrixWorld.clone());
          const list = [];
          for (const c of o.children) {
            if (!c.isMesh) continue;
            c.geometry.userData.kit = true;
            c.material.flatShading = false;
            c.material.vertexColors = true;
            if (skinGeometry(c.geometry)) c.userData.bind = c.matrixWorld.clone();
            list.push(c);
          }
          roles.set(role, list);
        });
        return [n, roles];
      }),
    ),
  )
    .then((pairs) => {
      rideLib = new Map(pairs);
      for (const v of made) wearRide(v);
      return rideLib;
    })
    .catch((e) => {
      console.warn("rides", e);
      return null;
    });
  return rideLoad;
}
// (2026-11-27, TODO 16: the unicorn's joints showed while it moved) its coat, fetlocks, hooves, face and saddle are
// one skin over these pivots, weighted in Blender (_build_vehicles.py skin_unicorn: SKIN_A/B/C = TEXCOORD_1..3, three
// joints a vertex, indices stored / 16; glTF flips each map's v): the clips drive the pivots, the skin bends smoothly
// at the hips, knees, withers and poll. The mane and tail locks stay rigid on their spring pivots.
const UNI_BONES = ["bob", "neck", "head", "leg_0", "knee_0", "leg_1", "knee_1", "leg_2", "knee_2", "leg_3", "knee_3"];
function skinGeometry(geo) {
  if (geo.attributes.skinIndex) return true;
  const a = geo.attributes.uv1;
  const b = geo.attributes.uv2;
  const c = geo.attributes.uv3;
  if (!a || !b || !c) return false;
  const n = a.count;
  const si = new Uint16Array(n * 4);
  const sw = new Float32Array(n * 4);
  for (let i = 0; i < n; i++) {
    const w = [1 - b.getY(i), c.getX(i), 1 - c.getY(i)];
    const sum = w[0] + w[1] + w[2] || 1;
    si[i * 4] = Math.round(a.getX(i) * 16);
    si[i * 4 + 1] = Math.round((1 - a.getY(i)) * 16);
    si[i * 4 + 2] = Math.round(b.getX(i) * 16);
    for (let k = 0; k < 3; k++) sw[i * 4 + k] = Math.max(0, w[k]) / sum;
  }
  geo.setAttribute("skinIndex", new THREE.Uint16BufferAttribute(si, 4));
  geo.setAttribute("skinWeight", new THREE.Float32BufferAttribute(sw, 4));
  for (const k of ["uv1", "uv2", "uv3"]) geo.deleteAttribute(k);
  return true;
}
// the groups of a ride by clip role (the same names rideClips binds)
function rideRoles(v) {
  if (v.isUnicorn) {
    const R = { lean: v.lean, bob: v.bob, neck: v.neck, head: v.head, tail: v.tail };
    v.legs.forEach(({ g, knee }, i) => {
      R["leg_" + i] = g;
      R["knee_" + i] = knee;
    });
    v.mane.forEach((m, i) => (R["mane_" + i] = m));
    v.tailLocks.forEach((m, i) => (R["tail_" + i] = m));
    return R;
  }
  return { lean: v.lean, bars: v.bars, wheel_f: v.wheels[0], wheel_r: v.wheels[1] };
}
function wearRide(v) {
  const lib = rideLib?.get(v.isUnicorn ? "veh_unicorn" : "veh_scooter");
  if (!lib || v.worn) return;
  v.worn = true;
  const R = rideRoles(v);
  // the procedural look leaves (the groups and their transforms stay: clips and riders use them)
  for (const g of Object.values(R))
    for (const c of [...g.children])
      if (c.isMesh) {
        g.remove(c);
        c.geometry.dispose();
      }
  let paint = null;
  let skel = null;
  for (const [role, meshes] of lib) {
    const g = R[role];
    if (!g) continue;
    for (const src of meshes) {
      const bind = src.userData.bind;
      if (bind && v.isUnicorn) {
        // one skeleton for the whole skin: the clip pivots themselves are its bones (their rest, the model's)
        skel ??= v.skel = new THREE.Skeleton(
          UNI_BONES.map((r) => R[r]),
          UNI_BONES.map((r) => lib.rest.get(r).clone().invert()),
        );
        const m = new THREE.SkinnedMesh(src.geometry, src.material);
        bind.decompose(m.position, m.quaternion, m.scale);
        m.bind(skel, bind);
        // (culling: one sphere round the whole rig at any pose, a rear included, in this part's own frame)
        m.boundingSphere = new THREE.Sphere(new THREE.Vector3(0, 1.0, 0).applyMatrix4(bind.clone().invert()), 2.0);
        m.castShadow = true;
        m.receiveShadow = true;
        v.root.add(m);
        continue;
      }
      const m = new THREE.Mesh(src.geometry, src.material);
      m.position.copy(src.position);
      m.quaternion.copy(src.quaternion);
      m.scale.copy(src.scale);
      m.castShadow = true;
      m.receiveShadow = true;
      if (/paint/.test(src.material.name)) {
        paint ??= src.material.clone();
        m.material = paint;
      }
      g.add(m);
    }
  }
  if (paint) {
    paint.color.set(v.color || "#ff8fb1");
    v.paint = paint;
  }
}
// called by every make*: wear the models now if they are in, else fetch them shortly (after the island's
// first-frame set; each ride is about 0.1-0.2 MB); phones later, about 0.2 MB in all
function register(v) {
  made.add(v);
  if (rideLib) wearRide(v);
  else if (!rideLoad) setTimeout(loadRides, rideSmall ? 15000 : 4000); // (phones: well after the first-frame set)
  return v;
}
// the island closes: every ride and trail of this visit goes (the loaded models stay for the next visit)
export function resetRides() {
  for (const v of made) {
    v.trail?.dispose();
    v.skel?.dispose();
  }
  made.clear();
}
// a ride that leaves the scene for good (a remote player's, on a colour change or when they go)
export function dropRide(v) {
  made.delete(v);
  v?.trail?.dispose();
  v?.skel?.dispose();
}

export function makeScooter(color = "#ff8fb1") {
  const root = new THREE.Group();
  const lean = new THREE.Group();
  root.add(lean);
  const body = mat(color);
  const cream = mat("#fff7f2");
  const dark = mat("#2b2633", { roughness: 0.8 });
  const chrome = mat("#e8e8f0", { metalness: 0.6, roughness: 0.3 });
  const add = (geo, m, x, y, z, rx = 0, ry = 0, rz = 0) => {
    const mesh = new THREE.Mesh(geo, m);
    mesh.position.set(x, y, z);
    mesh.rotation.set(rx, ry, rz);
    mesh.castShadow = true;
    lean.add(mesh);
    return mesh;
  };
  // rounded body and floorboard
  const shell = add(new THREE.SphereGeometry(0.42, 12, 8), body, 0, 0.5, -0.32);
  shell.scale.set(0.9, 0.75, 1.25);
  add(new THREE.BoxGeometry(0.42, 0.1, 0.8), cream, 0, 0.3, 0.12);
  // seat
  const seat = add(new THREE.CapsuleGeometry(0.15, 0.42, 3, 8), mat("#7a4a3a"), 0, 0.78, -0.3, Math.PI / 2);
  seat.scale.set(1.2, 1, 0.75);
  // front shield and steering column
  const shield = add(new THREE.SphereGeometry(0.3, 10, 8, 0, Math.PI * 2, 0, Math.PI / 2), body, 0, 0.55, 0.55, -Math.PI / 2 + 0.25);
  shield.scale.set(0.95, 1.5, 0.5);
  add(new THREE.CylinderGeometry(0.04, 0.04, 0.6, 6), chrome, 0, 0.76, 0.55, -0.22);
  // handlebars
  const bars = new THREE.Group();
  bars.position.set(0, 1.04, 0.5);
  lean.add(bars);
  const bar = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 0.62, 6), chrome);
  bar.rotation.z = Math.PI / 2;
  bars.add(bar);
  for (const s of [-1, 1]) {
    const grip = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 0.12, 6), dark);
    grip.rotation.z = Math.PI / 2;
    grip.position.x = s * 0.33;
    bars.add(grip);
    const mirror = new THREE.Mesh(new THREE.SphereGeometry(0.06, 8, 6), chrome);
    mirror.position.set(s * 0.28, 0.2, -0.02);
    mirror.scale.z = 0.4;
    bars.add(mirror);
  }
  // headlight
  const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.09, 10, 8), new THREE.MeshStandardMaterial({ color: "#fff8d8", emissive: "#fff2b0", emissiveIntensity: 1.2 }));
  lamp.position.set(0, 0.92, 0.66);
  lamp.scale.z = 0.6;
  lean.add(lamp);
  // a heart on the front
  const heart = add(new THREE.IcosahedronGeometry(0.07, 0), mat("#e2557f"), 0, 0.72, 0.78);
  heart.scale.set(1.2, 1, 0.5);
  // wheels
  const wheels = [];
  for (const z of [0.62, -0.62]) {
    const w = new THREE.Group();
    w.position.set(0, 0.2, z);
    lean.add(w);
    const tyre = new THREE.Mesh(new THREE.TorusGeometry(0.16, 0.07, 6, 14), dark);
    tyre.rotation.y = Math.PI / 2;
    tyre.castShadow = true;
    w.add(tyre);
    const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 0.1, 8), cream);
    hub.rotation.z = Math.PI / 2;
    w.add(hub);
    wheels.push(w);
  }
  // little back basket with a flower
  add(new THREE.BoxGeometry(0.34, 0.16, 0.26), mat("#c9a27e"), 0, 0.95, -0.78);
  add(new THREE.IcosahedronGeometry(0.07, 0), mat("#ffd166"), 0.06, 1.08, -0.78);
  add(new THREE.IcosahedronGeometry(0.06, 0), mat("#fff7f2"), -0.07, 1.06, -0.74);
  return register({ root, lean, wheels, bars, color });
}

// ---- the rides' clips (scale.md): named pivots on these very groups, bound by role; the legacy motion stays
// until the carrier is in. cue: "summon" / "rear" (set when it is called or mounted), played once.
function rigScooter(s) {
  s.lean.name = "ANIM_veh_scooter_lean";
  s.bars.name = "ANIM_veh_scooter_bars";
  s.wheels[0].name = "ANIM_veh_scooter_wheel_f";
  s.wheels[1].name = "ANIM_veh_scooter_wheel_r";
}
function rigUnicorn(u) {
  const n = (o, r) => (o.name = "ANIM_veh_unicorn_" + r);
  n(u.lean, "lean");
  n(u.bob, "bob");
  n(u.neck, "neck");
  n(u.head, "head");
  n(u.tail, "tail");
  u.legs.forEach(({ g, knee }, i) => {
    n(g, "leg_" + i);
    n(knee, "knee_" + i);
  });
  u.mane.forEach((m, i) => n(m, "mane_" + i));
}
let rideSeed = 3;
function rideClips(v, carrier, isU) {
  if (v.clips) return v.clips;
  const lib = clipLib(carrier);
  if (!lib) return null;
  if (isU) rigUnicorn(v);
  else rigScooter(v);
  const pre = isU ? "ANIM_veh_unicorn_" : "ANIM_veh_scooter_";
  const map = {};
  v.root.traverse((c) => c.name.startsWith(pre) && (map[c.name.slice(pre.length)] = c));
  // (rest: where each group was built, unturned; the legacy motion may have left it mid-stride)
  for (const [r, o] of Object.entries(map)) {
    if (r.startsWith("wheel")) continue;
    o.rotation.set(0, 0, 0);
    if (o === v.bob || o === v.lean) o.position.set(0, 0, 0);
    o.userData.restTRS = Float32Array.of(o.position.x, o.position.y, o.position.z, 0, 0, 0, 1, 1, 1, 1);
  }
  // (the wheels spin procedurally, by distance: the clips leave them alone)
  const b = new RigBinding(lib, (r) => (r.startsWith("wheel") ? null : map[r] || null), null);
  const an = new Animator(b);
  // the unicorn's gaits, slowest first (walk, trot, canter, gallop, sprint; an older carrier has walk, trot,
  // gallop): each plays over its own speed range, a change of gait crossfades over 0.35 s (runtime locoSwitch)
  const loco = isU ? GAITS.filter((n) => lib.get(n)).map((n) => ({ clip: lib.get(n), speed: lib.get(n).extras.tdd_speed })) : null;
  if (loco && loco.length > 3) loco.fade = 0.35;
  // the gaits' hoof strikes (each leg's stance start), for the hoof sound
  const contacts = isU ? loco.map((l) => Object.values(JSON.parse(l.clip.extras.tdd_contacts || "{}")).map((w) => w[0])) : null;
  an.play(isU ? "idle_breathe" : "idle", 0);
  v.clips = { lib, b, an, loco, contacts, clock: new AnimClock(), rng: mulberry(rideSeed++), last: 0, idleIn: 6, lean: 0, cool: 0 };
  if (isU) {
    const ri = (r) => lib.index.get(r) ?? -1;
    Object.assign(v.clips, {
      bobI: ri("bob"),
      neckI: ri("neck"),
      acc: 0, // forward acceleration, smoothed (m/s^2)
      sp: 0,
      bobY: null,
      bobV: 0,
      ay: 0, // the back's vertical acceleration (from the gait's bounce), smoothed
      surge: new Spring1(1.7, 0.55), // the body pitching over its hips as it speeds up / brakes
      mane: v.mane.map((_, i) => new Spring2(3.3 - i * 0.22, 0.32)),
      tailS: v.tailLocks.map((_, i) => new Spring2(2.3 + ((i * 7) % 6) * 0.12, 0.3)),
      rp: 0, // the rider's bounce phase
    });
  }
  return v.clips;
}
const GAITS = ["walk", "trot", "canter", "gallop", "sprint"];
const BOUNCES = { walk: 2, trot: 2 }; // back bounces per stride (the rest: one)
const LOCK_MAX = 0.6;
// damped springs on fixed sub-steps (AnimClock.h): x'' = w^2 (target - x) - 2 zeta w x'
class Spring1 {
  constructor(freq, zeta) {
    this.w = 2 * Math.PI * freq;
    this.z = zeta;
    this.x = 0;
    this.v = 0;
  }
  step(h, n, t) {
    const w = this.w;
    for (let i = 0; i < n; i++) {
      this.v += (w * w * (t - this.x) - 2 * this.z * w * this.v) * h;
      this.x += this.v * h;
    }
    return this.x;
  }
}
class Spring2 {
  constructor(freq, zeta) {
    this.a = new Spring1(freq, zeta);
    this.b = new Spring1(freq * 0.9, zeta);
  }
  step(h, n, tx, tz) {
    this.a.step(h, n, tx);
    this.b.step(h, n, tz);
    this.a.x = THREE.MathUtils.clamp(this.a.x, -LOCK_MAX, LOCK_MAX);
    this.b.x = THREE.MathUtils.clamp(this.b.x, -LOCK_MAX, LOCK_MAX);
  }
}
// hooves never below the ground: where a blend of two gaits (their joint angles averaged) or the surge pitch
// would push a hoof under, the leg is re-solved as two bones (thigh 0.38, cannon + hoof 0.42, as the gaits are
// authored) to reach the same spot on the ground, the knee folding forward on the forelegs, back on the hinds
const _gv = new THREE.Vector3();
const _gh = new THREE.Vector3();
const _gx = new THREE.Vector3(1, 0, 0);
const _gm = new THREE.Matrix4();
const LEG_A = 0.38;
const LEG_B = 0.42;
function groundHooves(u) {
  u.root.updateMatrixWorld(true);
  _gm.copy(u.root.matrixWorld).invert();
  u.legs.forEach(({ g, knee }, i) => {
    _gv.set(0, -LEG_B, 0).applyMatrix4(knee.matrixWorld).applyMatrix4(_gm);
    if (_gv.y >= 0) return;
    _gv.y = 0;
    u.bob.worldToLocal(_gv.applyMatrix4(u.root.matrixWorld));
    _gh.copy(g.position);
    const dy = _gv.y - _gh.y;
    const dz = _gv.z - _gh.z;
    const D = Math.min(Math.hypot(dy, dz), (LEG_A + LEG_B) * 0.9995);
    const sgn = i < 2 ? 1 : -1;
    const gam = Math.acos(THREE.MathUtils.clamp((LEG_A * LEG_A + LEG_B * LEG_B - D * D) / (2 * LEG_A * LEG_B), -1, 1));
    const al = Math.acos(THREE.MathUtils.clamp((LEG_A * LEG_A + D * D - LEG_B * LEG_B) / (2 * LEG_A * D), -1, 1));
    g.quaternion.setFromAxisAngle(_gx, Math.atan2(-dz, -dy) - sgn * al);
    knee.quaternion.setFromAxisAngle(_gx, sgn * (Math.PI - gam));
    g.updateMatrixWorld(true);
  });
}
const _sq = new THREE.Quaternion();
const _se = new THREE.Euler();
// pivot offsets for a pitch th about the point (y0, z0) of the bob's frame (as w13_anim_rides.pivot_about)
const pivotDy = (th, y0, z0) => y0 - (y0 * Math.cos(th) - z0 * Math.sin(th));
const pivotDz = (th, y0, z0) => z0 - (y0 * Math.sin(th) + z0 * Math.cos(th));
// the lean layers at a set weight (|lean| over its authored full lean)
function leanLayers(an, lean, full) {
  const w = Math.min(1, Math.abs(lean) / full);
  const l = an.overlay("lean_l", true, 0.1);
  const r = an.overlay("lean_r", true, 0.1);
  if (l) Object.assign(l, { fixed: true, w: lean > 0 ? w : 0, target: lean > 0 ? w : 0 });
  if (r) Object.assign(r, { fixed: true, w: lean < 0 ? w : 0, target: lean < 0 ? w : 0 });
}
// how high the rider's seat rides over its rest (the bob's bounce, the scooter's wheelie): the riders sit on it
export const riderLift = (v) => (v.isUnicorn ? v.bob.position.y : v.lean.position.y);

// spin the wheels and lean into turns
export function animateScooter(s, dt, speed, turn) {
  if (!rideLoad) loadRides();
  for (const w of s.wheels) w.rotation.x += (speed * dt) / 0.2;
  const C = rideClips(s, "veh_scooter_clips", false);
  if (C) {
    const an = C.an;
    const cur = an.current();
    const accel = dt > 0 ? (speed - C.last) / dt : 0;
    C.last = speed;
    C.cool -= dt;
    if (s.cue) {
      an.play(s.cue === "rear" ? "summon" : s.cue, 0.1);
      s.cue = null;
    } else if (C.cool <= 0 && accel > 9 && speed > 6) {
      an.play("turbo", 0.12);
      s.turbo = 1;
      C.cool = 2;
    } else if (C.cool <= 0 && accel < -12 && speed > 2) {
      an.play("brake", 0.1);
      C.cool = 1.5;
    } else if (cur.clip && !cur.clip.loop) {
      if (cur.t >= cur.clip.duration - 0.1) an.play(speed > 0.4 ? "ride_loop" : "idle", 0.2);
    } else an.play(speed > 0.4 ? "ride_loop" : "idle", 0.3);
    // (the legacy lean chase, now the weight of the lean layers; the bars turn with them)
    C.lean += (THREE.MathUtils.clamp(-turn * speed * 0.06, -0.35, 0.35) - C.lean) * (1 - Math.exp(-dt * 6));
    leanLayers(an, C.lean, 0.3);
    C.b.apply(an.update(C.clock.tick(dt).dt, speed, null));
    s.lean.rotation.setFromQuaternion(s.lean.quaternion, undefined, false); // (the riders lean with it: island.js)
    return;
  }
  const want = THREE.MathUtils.clamp(-turn * speed * 0.06, -0.35, 0.35);
  s.lean.rotation.z += (want - s.lean.rotation.z) * (1 - Math.exp(-dt * 6));
  s.bars.rotation.y += (THREE.MathUtils.clamp(turn * 0.6, -0.5, 0.5) - s.bars.rotation.y) * (1 - Math.exp(-dt * 8));
}

// ---- a unicorn for two: summon it, ride it, and your person can hop on behind ----
export const UNI_SEAT_H = 1.32; // the top of the saddle
export const UNI_FRONT = 0.08; // where the rider sits, along the back
export const UNI_BACK = -0.48; // and the one holding on behind
const RAINBOW = ["#ff8fb1", "#ffb36b", "#ffe07a", "#9fe0a6", "#8fd3f0", "#b79be8"];

export function makeUnicorn() {
  const root = new THREE.Group();
  const lean = new THREE.Group();
  root.add(lean);
  const bob = new THREE.Group();
  lean.add(bob);
  const coat = mat("#fffafc", { roughness: 0.7 });
  const blush = mat("#ffc2da");
  const hoof = mat("#d9b8ff", { roughness: 0.5 });
  const gold = mat("#ffd36b", { metalness: 0.5, roughness: 0.3, emissive: "#ffb000", emissiveIntensity: 0.25 });
  const dark = mat("#2b2633");
  const part = (parent, geo, m, x, y, z, rx = 0, ry = 0, rz = 0) => {
    const mesh = new THREE.Mesh(geo, m);
    mesh.position.set(x, y, z);
    mesh.rotation.set(rx, ry, rz);
    mesh.castShadow = true;
    parent.add(mesh);
    return mesh;
  };
  // body
  const body = part(bob, new THREE.CapsuleGeometry(0.36, 0.78, 4, 12), coat, 0, 0.95, -0.05, Math.PI / 2);
  body.scale.set(1, 1, 0.92);
  // a long saddle with room for two
  const saddle = part(bob, new THREE.CapsuleGeometry(0.2, 0.62, 3, 10), mat("#ff8fb1"), 0, 1.25, -0.2, Math.PI / 2);
  saddle.scale.set(1.25, 1, 0.45);
  part(bob, new THREE.TorusGeometry(0.33, 0.035, 5, 16, Math.PI), gold, 0, 0.98, 0.2, 0, Math.PI / 2, 0);
  // neck and head
  const neck = new THREE.Group();
  neck.position.set(0, 1.12, 0.48);
  bob.add(neck);
  part(neck, new THREE.CylinderGeometry(0.17, 0.24, 0.62, 10), coat, 0, 0.24, 0.1, 0.5);
  const head = new THREE.Group();
  head.position.set(0, 0.56, 0.3);
  neck.add(head);
  const skull = part(head, new THREE.SphereGeometry(0.24, 12, 10), coat, 0, 0, 0);
  skull.scale.set(0.9, 1, 1.1);
  part(head, new THREE.SphereGeometry(0.16, 10, 8), blush, 0, -0.08, 0.22).scale.set(1, 0.85, 1);
  for (const s of [-1, 1]) {
    part(head, new THREE.SphereGeometry(0.045, 8, 6), dark, s * 0.15, 0.05, 0.15);
    part(head, new THREE.SphereGeometry(0.035, 6, 4), blush, s * 0.17, -0.06, 0.15);
    part(head, new THREE.ConeGeometry(0.06, 0.18, 5), coat, s * 0.1, 0.24, -0.05, 0, 0, -s * 0.25);
  }
  // the horn, spiralled in gold
  const horn = part(head, new THREE.ConeGeometry(0.06, 0.42, 8), gold, 0, 0.36, 0.08, 0.35);
  const sparkle = new THREE.Mesh(new THREE.IcosahedronGeometry(0.05, 0), new THREE.MeshStandardMaterial({ color: "#ffffff", emissive: "#fff2b0", emissiveIntensity: 1.5 }));
  sparkle.position.set(0, 0.25, 0);
  horn.add(sparkle);
  // rainbow mane down the neck and a rainbow tail
  // (each tuft in its own group at the clip pivot mane_i, so a worn model's locks hang from the same place)
  const mane = [];
  RAINBOW.forEach((c, i) => {
    const t = i / (RAINBOW.length - 1);
    const g = new THREE.Group();
    g.position.set(0, 0.62 - t * 0.55, -0.02 - t * 0.12);
    neck.add(g);
    const m = part(g, new THREE.IcosahedronGeometry(0.11 - t * 0.02, 0), mat(c), 0, 0, 0);
    m.scale.set(0.8, 1, 1.3);
    mane.push(g);
  });
  const tail = new THREE.Group();
  tail.position.set(0, 1.05, -0.62);
  bob.add(tail);
  // (each tail lock on its own spring pivot tail_i at the dock: the worn model's locks hang there too)
  const tailLocks = RAINBOW.map((c, i) => {
    const g = new THREE.Group();
    tail.add(g);
    const m = part(g, new THREE.IcosahedronGeometry(0.12 - i * 0.008, 0), mat(c), 0, -0.08 - i * 0.1, -0.08 - i * 0.05);
    m.scale.set(0.8, 1.2, 0.8);
    return g;
  });
  // four legs that gallop
  // the legs split at the knee (a 0.38 thigh, a 0.28 cannon, the hoof in the knee) so the gaits can fold them
  const legs = [];
  for (const [x, z, ph] of [[-0.18, 0.38, 0], [0.18, 0.38, Math.PI], [-0.18, -0.42, Math.PI * 0.5], [0.18, -0.42, Math.PI * 1.5]]) {
    const leg = new THREE.Group();
    leg.position.set(x, 0.8, z);
    bob.add(leg);
    part(leg, new THREE.CylinderGeometry(0.08, 0.072, 0.38, 8), coat, 0, -0.19, 0);
    const knee = new THREE.Group();
    knee.position.set(0, -0.38, 0);
    leg.add(knee);
    part(knee, new THREE.CylinderGeometry(0.072, 0.065, 0.28, 8), coat, 0, -0.14, 0);
    part(knee, new THREE.CylinderGeometry(0.085, 0.09, 0.12, 8), hoof, 0, -0.34, 0.01);
    legs.push({ g: leg, knee, ph });
  }
  const u = { root, lean, bob, legs, head, neck, tail, tailLocks, mane, sparkle, isUnicorn: true, phase: 0 };
  u.trail = new RainbowTrail(u);
  return register(u);
}

// gallop, toss the head and swish the tail
export function animateUnicorn(u, dt, speed, turn) {
  const s = Math.abs(speed);
  if (!rideLoad) loadRides();
  u.trail?.update(s);
  const C = rideClips(u, "veh_unicorn_clips", true);
  if (C) {
    const an = C.an;
    const cur = an.current();
    const name = cur.name;
    u.sparkle.rotation.y += dt * 3;
    const clock = C.clock.tick(dt);
    const cdt = clock.dt;
    // forward acceleration, smoothed (the ride's own speed is eased in island.js: toward its target at 2.2/s
    // speeding up and 3.5/s slowing down, so s + acc / 3.5 is about where a slow-down is heading)
    // (a remote rider's speed arrives in steps, one per packet: the gait, the surge and the hair follow it through
    // a short low-pass, so a step is never read as a jolt of acceleration)
    if (cdt > 0) {
      const sp = C.sp + (s - C.sp) * (1 - Math.exp(-cdt * 10));
      C.acc += ((sp - C.sp) / cdt - C.acc) * (1 - Math.exp(-cdt * 14));
      C.sp = sp;
    }
    const sv = C.sp;
    const longStop = name === "stop" && cur.t < cur.clip.duration - 0.12;
    if (u.cue) {
      // (air_kick: the double jump's kick, TODO 27; an older clip carrier without it keeps its gait)
      if (C.lib.get(u.cue)) an.play(u.cue, u.cue === "air_kick" ? 0.06 : 0.12);
      u.cue = null;
    } else if (name === "@loco") {
      // a hard brake from a canter or faster: the sliding halt (it skids on under the braced legs); a gentle
      // slow-down walks itself out and eases into the idle as the walk winds down
      if (sv > 6 && C.acc < -12 && sv + C.acc / 3.5 < 1.5) an.play("stop", 0.16);
      else if (sv < 0.25) an.play("idle_breathe", 0.45);
    } else if (longStop) {
      if (C.acc > 2 && sv > 1) an.play("@loco", 0.3); // pushed on again mid-halt
    } else if (sv > 0.3 && (C.acc > -0.5 || sv > 1.2) && !((name === "summon" || name === "rear" || name === "air_kick") && cur.t < cur.clip.duration - 0.25)) {
      an.play("@loco", 0.3);
    } else if (cur.clip && !cur.clip.loop) {
      if (cur.t >= cur.clip.duration - 0.12) an.play(cur.clip.extras.tdd_next || "idle_breathe", 0.3);
    } else if ((C.idleIn -= dt) <= 0) {
      C.idleIn = 5 + C.rng() * 6;
      const r = C.rng();
      an.play(r < 0.35 ? "idle_paw" : r < 0.55 ? "neigh" : r < 0.8 ? "idle_look" : "idle_breathe", 0.35);
    }
    C.lean += (THREE.MathUtils.clamp(-turn * sv * 0.05, -0.3, 0.3) - C.lean) * (1 - Math.exp(-dt * 6));
    leanLayers(an, C.lean, 0.22);
    const prev = an.phase;
    const P = an.update(cdt, sv, C.loco);
    const calm = isCalm();
    const h = clock.h;
    const n = clock.steps;
    if (C.bobI >= 0 && cdt > 0) {
      // the back's vertical acceleration from the gait's bounce (drives the hair)
      const y = P[C.bobI * STRIDE + 1];
      if (C.bobY != null) {
        const vy = (y - C.bobY) / cdt;
        C.ay += (THREE.MathUtils.clamp((vy - C.bobV) / cdt, -45, 45) - C.ay) * (1 - Math.exp(-cdt * 30));
        C.bobV = vy;
      }
      C.bobY = y;
      // surge: speeding up, the rump sinks and the nose lifts over the hind hips (the push), the head dips to
      // pull; braking, the weight rolls onto the forehand; a soft spring, so it overshoots once and settles
      const stopping = name === "stop" ? 0.3 : 1;
      const th = calm ? 0 : C.surge.step(h, n, THREE.MathUtils.clamp(-C.acc * 0.0032, -0.085, 0.05) * stopping);
      const o = C.bobI * STRIDE;
      const hz = th < 0 ? -0.42 : 0.38;
      P[o + 1] += pivotDy(th, 0.8, hz);
      P[o + 2] += pivotDz(th, 0.8, hz);
      rotateRole(P, C.bobI, th, 0, 0);
      rotateRole(P, C.neckI, -th * 0.7, 0, 0);
    }
    C.b.apply(P);
    u.lean.rotation.setFromQuaternion(u.lean.quaternion, undefined, false);
    if (an.current().name === "@loco" || cur.name === "stop") groundHooves(u);
    // hair on springs: each mane / tail lock lags the body's bounce, surge and turns and swings back past it
    // (stiffer at the poll, looser down the crest; the tail locks each a little different, so they part and
    // fan instead of moving as one block); at speed they stream back
    const fwd = calm ? 0 : C.acc;
    const up = calm ? 0 : C.ay;
    const side = calm ? 0 : C.lean;
    C.mane.forEach((sp, i) => {
      const g = 1 + i * 0.12;
      sp.step(h, n, (fwd * 0.006 + up * 0.0075 + sv * 0.006) * g, side * 0.9 * g);
      _sq.setFromEuler(_se.set(sp.a.x, 0, sp.b.x));
      u.mane[i].quaternion.multiply(_sq);
    });
    C.tailS.forEach((sp, i) => {
      const g = 0.85 + ((i * 5) % 6) * 0.06;
      sp.step(h, n, (fwd * 0.008 - up * 0.008 + sv * 0.008) * g, -side * 1.1 * g + (i - 2.5) * 0.02);
      u.tailLocks[i].quaternion.setFromEuler(_se.set(sp.a.x, 0, sp.b.x));
    });
    // the rider's bounce phase (the avatar's ride_unicorn_gait: one bounce per cycle of it): two bounces per
    // stride at the walk and trot, one in the canter and gallop, accumulated so a change of gait never jumps
    const locoOn = an.current().name === "@loco";
    if (locoOn && an.k) {
      let m = 0;
      let j = 0;
      for (let i = 0; i < an.k.length; i++) {
        m += an.k[i] * (BOUNCES[C.loco[i].clip.name] || 1);
        if (an.k[i] > an.k[j]) j = i;
      }
      let dph = an.phase - prev;
      if (dph < -0.5) dph += 1;
      const want = (an.phase * (BOUNCES[C.loco[j].clip.name] || 1)) % 1;
      let err = want - C.rp;
      err -= Math.round(err);
      C.rp = (((C.rp + dph * m + err * (1 - Math.exp(-cdt * 3))) % 1) + 1) % 1;
    }
    u.gait = locoOn ? C.rp : null;
    if (locoOn && an.k) {
      let j = 0;
      for (let i = 1; i < an.k.length; i++) if (an.k[i] > an.k[j]) j = i;
      const ph = an.phase;
      for (const c of C.contacts[j]) if (ph >= prev ? prev < c && ph >= c : c > prev || c <= ph) u.onHoof?.();
    }
    return;
  }
  u.phase += dt * (2 + s * 1.15);
  const k = Math.min(1, s / 3);
  for (const l of u.legs) l.g.rotation.x = Math.sin(u.phase + l.ph) * 0.75 * k;
  u.bob.position.y = Math.abs(Math.sin(u.phase)) * 0.08 * k + Math.sin(u.phase * 0.35) * 0.015 * (1 - k);
  u.neck.rotation.x = Math.sin(u.phase) * 0.08 * k;
  u.tail.rotation.x = 0.3 + Math.sin(u.phase * 0.8) * 0.15 + k * 0.4;
  u.tail.rotation.y = Math.sin(u.phase * 0.6) * 0.3;
  u.sparkle.rotation.y += dt * 3;
  const want = THREE.MathUtils.clamp(-turn * s * 0.05, -0.3, 0.3);
  u.lean.rotation.z += (want - u.lean.rotation.z) * (1 - Math.exp(-dt * 6));
  u.head.rotation.y += (THREE.MathUtils.clamp(turn * 0.4, -0.4, 0.4) - u.head.rotation.y) * (1 - Math.exp(-dt * 6));
}
