// Our island's story (TODO 17, user 2026-11-27: "a big sign (wall) with a picture of our world from up, and if possible we
// could see how it changed like in days or updates ... everything that changed since the start"): a big picture wall
// in the meadow beside the gate path, showing the island photographed from above, one picture per update since the
// very first island, with its date and a little line about what changed.
// The wall is Blender (assets/blender/props/story/_build_story.py, props/prp_story_wall[_lite].glb): pivots screen
// (the picture's centre), prev and next (the two arrow buttons on their lecterns). The pictures are real renders of the
// game at past commits (rebuild/tools/island-story/snap.py: assets/story/story.json + <id>.webp, <id>_s.webp for
// phones), fetched one at a time, only once you come near, and kept on the device like the rest of the pack.
// Step through them with the two arrows in front of the wall, or tap the picture for a big view with a slider.
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { MeshoptDecoder } from "three/examples/jsm/libs/meshopt_decoder.module.js";
import { zoneMode } from "./zones/mode.js";

// where it stands: the open meadow right of the gate path, turned to face you as you walk up from the gate
const SPOT = new THREE.Vector3(15, 0, 62);
const FACE = new THREE.Vector3(0, 0, 70);
const YAW = Math.atan2(FACE.x - SPOT.x, FACE.z - SPOT.z);
// (the Blender builder's numbers: the picture, the lecterns)
const SCREEN_W = 7.2;
const SCREEN_H = 4.5;
const BX = 2.75;
const BZ = 1.45;
// what stands on the ground and a lawn in front of it to look from (local metres): the meadow's trees, flowers and
// tufts keep off it (zones/runtime.js)
const CLEAR = { x0: -6.6, x1: 6.6, z0: -2.4, z1: 8.5 };
const NEAR = 70; // m: the pictures start loading once you are this close
const FONT = '"Fredoka", "Quicksand", "Noto Sans", sans-serif';
const _v = new THREE.Vector3();

const MONTHS = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
const dayOf = (s) => {
  const [y, m, d] = String(s).split("-").map(Number);
  return Date.UTC(y, (m || 1) - 1, d || 1);
};
const niceDate = (s) => {
  const t = new Date(dayOf(s));
  return `${t.getUTCDate()} ${MONTHS[t.getUTCMonth()]} ${t.getUTCFullYear()}`;
};

export class StoryWall {
  constructor(scene, world, { small = false } = {}) {
    this.world = world;
    this.small = small;
    this.root = new THREE.Group();
    this.root.name = "story";
    this.root.position.copy(SPOT);
    this.root.rotation.y = YAW;
    this.root.updateMatrixWorld(true);
    scene.add(this.root);
    this.snaps = [];
    this.index = -1;
    this.images = new Map(); // id -> Promise<HTMLImageElement | null>
    this.loaded = new Map(); // id -> HTMLImageElement
    this.ready = false;
    this.near = false;
    this.press = { prev: 0, next: 0 };
    this.pivots = {};

    // the meadow keeps off it; the legacy colliders of what stood there go
    const inv = new THREE.Matrix4().copy(this.root.matrixWorld).invert();
    const clearing = {
      has: (x, z) => {
        const p = _v.set(x, 0, z).applyMatrix4(inv);
        return p.x > CLEAR.x0 && p.x < CLEAR.x1 && p.z > CLEAR.z0 && p.z < CLEAR.z1;
      },
    };
    (world.clearings ||= []).push(clearing);
    for (let i = world.circles.length - 1; i >= 0; i--) {
      const c = world.circles[i];
      if (c.r <= 2.5 && clearing.has(c.x, c.z)) world.circles.splice(i, 1);
    }
    // its colliders: the two posts, the flower box and the wall between them, the two lecterns
    for (const x of [-4.18, 4.18]) world.circles.push({ ...this.flat(x, 0), r: 0.32, top: Infinity });
    const a = this.flat(-4.0, 0.0), b = this.flat(4.0, 0.0);
    world.segments.push({ ax: a.x, az: a.z, bx: b.x, bz: b.z, h: 7.2, room: "" });
    const c = this.flat(-3.95, 0.8), d = this.flat(3.95, 0.8);
    world.segments.push({ ax: c.x, az: c.z, bx: d.x, bz: d.z, h: 0.85, room: "" });
    for (const x of [-BX, BX]) world.circles.push({ ...this.flat(x, BZ), r: 0.34, top: 1.1 });

    // the picture: our own plane on the felt, its texture a canvas (the photo, its date and line)
    const W = small ? 800 : 1280;
    const H = Math.round((W * SCREEN_H) / SCREEN_W);
    this.canvas = document.createElement("canvas");
    this.canvas.width = W;
    this.canvas.height = H;
    this.ctx = this.canvas.getContext("2d");
    this.tex = new THREE.CanvasTexture(this.canvas);
    this.tex.colorSpace = THREE.SRGBColorSpace;
    this.tex.anisotropy = small ? 2 : 8;
    // (lit like the world, with a soft glow of its own so it still reads at dusk and at night)
    this.mat = new THREE.MeshStandardMaterial({ map: this.tex, emissiveMap: this.tex, emissive: new THREE.Color(0.32, 0.32, 0.32), roughness: 0.72, metalness: 0 });
    this.screen = new THREE.Mesh(new THREE.PlaneGeometry(SCREEN_W, SCREEN_H), this.mat);
    this.screen.name = "story.picture";
    this.screen.position.set(0, 3.55, 0);
    this.screen.receiveShadow = true;
    this.root.add(this.screen);
    this.paint();

    // what you can do here
    const self = this;
    const items = [
      { id: "story-look", dir: 0, at: this.toWorld(0, 0, 3.2), radius: 3.0, hits: [this.screen], get label() { return self.label(0); } },
      { id: "story-prev", dir: -1, at: this.toWorld(-BX, 0, BZ + 0.6), radius: 1.25, hits: [], get label() { return self.label(-1); } },
      { id: "story-next", dir: 1, at: this.toWorld(BX, 0, BZ + 0.6), radius: 1.25, hits: [], get label() { return self.label(1); } },
    ];
    this.items = {};
    for (const it of items) {
      const item = {
        id: it.id,
        get label() {
          return it.label;
        },
        pos: it.at,
        radius: it.radius,
        action: { type: "story", dir: it.dir },
        hits: it.hits,
      };
      for (const m of it.hits) m.userData.item = item;
      world.interactables.push(item);
      this.items[it.dir] = item;
    }
    this.load(small);
    this.fetchList();
  }

  toWorld(x, y, z, out = new THREE.Vector3()) {
    return out.set(x, y, z).applyMatrix4(this.root.matrixWorld);
  }
  flat(x, z) {
    const p = this.toWorld(x, 0, z);
    return { x: p.x, z: p.z };
  }

  label(dir) {
    const n = this.snaps.length;
    if (!n) return dir ? "" : "our island's story 🗺️";
    if (dir < 0) return this.index > 0 ? "◀ an older picture" : "◀ back to today";
    if (dir > 0) return this.index < n - 1 ? "a newer picture ▶" : "▶ back to the very start";
    return "our island's story 🗺️ · look closer";
  }

  load(small) {
    const zm = zoneMode();
    if (!zm.v2 || !zm.base) return;
    new GLTFLoader()
      .setMeshoptDecoder(MeshoptDecoder)
      .loadAsync(zm.base + "props/prp_story_wall" + (small ? "_lite" : "") + ".glb")
      .then((g) => {
        const roles = {};
        g.scene.traverse((o) => {
          if (o.userData?.tdd_role) roles[o.userData.tdd_role] = o;
        });
        if (!roles.screen || !roles.prev || !roles.next) return;
        g.scene.traverse((m) => {
          if (!m.isMesh) return;
          m.material.flatShading = false;
          m.material.vertexColors = true;
          // (the long flat pieces throw the shadow; the little ones only take it)
          m.castShadow = !/flora|_prev|_next/.test(m.name);
          m.receiveShadow = true;
        });
        // the arrows' tops press in; tapping them steps through too
        for (const dir of ["prev", "next"]) {
          const p = roles[dir];
          this.pivots[dir] = { o: p, y: p.position.y };
          const item = this.items[dir === "prev" ? -1 : 1];
          p.traverse((m) => {
            if (m.isMesh) {
              m.userData.item = item;
              item.hits.push(m);
            }
          });
        }
        g.scene.traverse((m) => m.isMesh && !m.userData.item && (m.userData.item = this.items[0]));
        this.root.add(g.scene);
        this.ready = true;
      })
      .catch((e) => console.warn("story wall", e));
  }

  // the list of pictures (assets/story/story.json, in the pack)
  fetchList() {
    const zm = zoneMode();
    if (!zm.base) return;
    this.base = zm.base + "story/";
    fetch(this.base + "story.json")
      .then((r) => (r.ok ? r.json() : null))
      .then((j) => {
        const list = (j?.snaps || []).filter((s) => s && /^[\w-]+$/.test(s.id) && /^\d{4}-\d\d-\d\d$/.test(s.date));
        if (!list.length) return;
        this.snaps = list;
        this.first = dayOf(list[0].date);
        this.index = list.length - 1; // (it opens on today's island)
        this.paint();
        if (this.near) this.show(this.index);
      })
      .catch(() => {});
  }

  image(i) {
    const s = this.snaps[i];
    if (!s) return Promise.resolve(null);
    if (!this.images.has(s.id)) {
      const p = new Promise((res) => {
        const im = new Image();
        im.decoding = "async";
        im.onload = () => {
          this.loaded.set(s.id, im);
          res(im);
        };
        im.onerror = () => res(null);
        im.src = this.base + s.id + (this.small ? "_s" : "") + ".webp";
      });
      this.images.set(s.id, p);
    }
    return this.images.get(s.id);
  }
  // a picture for the big view: always the sharp one
  bigImage(i) {
    const s = this.snaps[i];
    return s ? this.base + s.id + ".webp" : "";
  }

  // show picture i on the wall (and fetch its neighbours, so the arrows answer at once)
  show(i) {
    const n = this.snaps.length;
    if (!n) return;
    this.index = ((i % n) + n) % n;
    const want = this.index;
    this.paint();
    if (this.near || this.isOpen())
      this.image(want).then((im) => {
        if (im && this.index === want) this.paint();
      });
    if (this.near) for (const k of [want - 1, want + 1]) if (k >= 0 && k < n) this.image(k);
    this.onChange?.();
  }

  step(dir) {
    if (!this.snaps.length) return;
    const p = this.pivots[dir < 0 ? "prev" : "next"];
    if (p) this.press[dir < 0 ? "prev" : "next"] = 1;
    this.show(this.index + dir);
  }

  // the face: the photo, a date tag (with the day since the very first picture), the line about it and dots for where
  // you are in the story
  paint() {
    const g = this.ctx;
    const W = this.canvas.width;
    const H = this.canvas.height;
    const k = W / 1280;
    const s = this.snaps[this.index];
    // (its picture, once it is here; until then a soft sky with a heart)
    const im = s ? this.loaded.get(s.id) : null;
    if (im) g.drawImage(im, 0, 0, W, H);
    else {
      const grd = g.createLinearGradient(0, 0, 0, H);
      grd.addColorStop(0, "#cfe6ff");
      grd.addColorStop(1, "#ffe3ee");
      g.fillStyle = grd;
      g.fillRect(0, 0, W, H);
      g.fillStyle = "#e2557f";
      g.textAlign = "center";
      g.textBaseline = "middle";
      g.font = `700 ${Math.round(120 * k)}px ${FONT}`;
      g.fillText("♡", W / 2, H / 2 - 30 * k);
      g.font = `700 ${Math.round(44 * k)}px ${FONT}`;
      g.fillStyle = "#8a6d82";
      g.fillText("our island, from up above", W / 2, H / 2 + 70 * k);
    }
    if (!s) {
      this.tex.needsUpdate = true;
      return;
    }
    const pill = (x, y, w, h, r) => {
      g.beginPath();
      g.moveTo(x + r, y);
      g.arcTo(x + w, y, x + w, y + h, r);
      g.arcTo(x + w, y + h, x, y + h, r);
      g.arcTo(x, y + h, x, y, r);
      g.arcTo(x, y, x + w, y, r);
      g.closePath();
    };
    g.save();
    // the date tag, top left: "day 13 · 27 nov 2026"
    const day = Math.round((dayOf(s.date) - this.first) / 86400000) + 1;
    const isLast = this.index === this.snaps.length - 1;
    const tag = isLast ? `today ♡ · ${niceDate(s.date)}` : `day ${day} · ${niceDate(s.date)}`;
    g.font = `700 ${Math.round(42 * k)}px ${FONT}`;
    const tw = g.measureText(tag).width;
    g.shadowColor = "rgba(90, 40, 70, 0.35)";
    g.shadowBlur = 14 * k;
    g.shadowOffsetY = 4 * k;
    g.fillStyle = "#fff8ec";
    pill(28 * k, 26 * k, tw + 64 * k, 72 * k, 36 * k);
    g.fill();
    g.shadowColor = "transparent";
    g.fillStyle = "#e2557f";
    g.textAlign = "left";
    g.textBaseline = "middle";
    g.fillText(tag, 60 * k, 63 * k);
    // the line about it, on a soft ribbon along the bottom, and the dots
    const bh = 132 * k;
    const grd = g.createLinearGradient(0, H - bh, 0, H);
    grd.addColorStop(0, "rgba(255, 248, 236, 0.0)");
    grd.addColorStop(0.35, "rgba(255, 248, 236, 0.88)");
    grd.addColorStop(1, "rgba(255, 248, 236, 0.96)");
    g.fillStyle = grd;
    g.fillRect(0, H - bh, W, bh);
    let size = 44;
    const text = String(s.caption || "").slice(0, 90);
    g.font = `700 ${Math.round(size * k)}px ${FONT}`;
    while (g.measureText(text).width > W - 120 * k && size > 24) g.font = `700 ${Math.round((size -= 2) * k)}px ${FONT}`;
    g.fillStyle = "#5b3a55";
    g.textAlign = "center";
    g.fillText(text, W / 2, H - 66 * k);
    const n = this.snaps.length;
    const gap = Math.min(30, 700 / n) * k;
    for (let i = 0; i < n; i++) {
      const x = W / 2 + (i - (n - 1) / 2) * gap;
      g.beginPath();
      g.arc(x, H - 22 * k, (i === this.index ? 8 : 5) * k, 0, Math.PI * 2);
      g.fillStyle = i === this.index ? "#e2557f" : "rgba(138, 109, 130, 0.55)";
      g.fill();
    }
    g.restore();
    this.tex.needsUpdate = true;
  }

  // each frame: are you near (then the pictures load), the arrows springing back up
  update(dt, playerPos) {
    if (playerPos) {
      const near = playerPos.distanceTo(SPOT) < NEAR;
      if (near && !this.near) {
        this.near = true;
        if (this.snaps.length) this.show(this.index);
      } else if (!near && this.near && playerPos.distanceTo(SPOT) > NEAR + 20) this.near = false;
    }
    for (const dir of ["prev", "next"]) {
      const p = this.pivots[dir];
      if (!p) continue;
      const t = this.press[dir];
      if (t > 0) this.press[dir] = Math.max(0, t - dt * 5);
      // (down quickly, then springs back)
      const d = t > 0.6 ? (1 - t) / 0.4 : t / 0.6;
      p.o.position.y = p.y - 0.045 * d;
    }
  }

  // ---- the big view: the picture large, its date and line, a slider through them all, arrows -------------------
  attachUI({ h, audio, onOpen, onClose }) {
    this.audio = audio;
    if (!document.getElementById("g3d-story-style")) {
      const st = document.createElement("style");
      st.id = "g3d-story-style";
      st.textContent = `
        .g3d-story .g3d-sheet { max-width: min(980px, 96vw); }
        .g3d-story-pic { position: relative; border-radius: 18px; overflow: hidden; background: linear-gradient(#cfe6ff, #ffe3ee); aspect-ratio: 16 / 10; box-shadow: 0 6px 22px rgba(90, 40, 70, .18); }
        .g3d-story-pic img { display: block; width: 100%; height: 100%; object-fit: cover; }
        .g3d-story-tag { position: absolute; left: 12px; top: 12px; padding: 6px 14px; border-radius: 999px; background: #fff8ec; color: #e2557f; font-weight: 700; box-shadow: 0 3px 10px rgba(90, 40, 70, .25); }
        .g3d-story-cap { margin: 12px 4px 4px; text-align: center; font-weight: 700; color: inherit; font-size: 1.05rem; min-height: 1.4em; }
        .g3d-story-row { display: flex; align-items: center; gap: 10px; margin-top: 8px; }
        .g3d-story-row input[type=range] { flex: 1; accent-color: #e2557f; min-width: 0; height: 28px; }
        .g3d-story-row button { flex: none; width: 46px; height: 46px; border-radius: 50%; border: 0; background: #ffe3ee; color: #e2557f; font-size: 1.25rem; font-weight: 700; cursor: pointer; }
        .g3d-story-row button:disabled { opacity: .4; cursor: default; }
        .g3d-story-ends { display: flex; justify-content: space-between; font-size: .8rem; color: inherit; opacity: .7; margin: 2px 56px 0; }
      `;
      document.head.append(st);
    }
    this.onOpen = onOpen;
    this.onClose = onClose;
    this.ui = {};
    const U = this.ui;
    U.img = h("img", { alt: "our island from above", decoding: "async" });
    U.tag = h("div", { class: "g3d-story-tag" });
    U.cap = h("p", { class: "g3d-story-cap", "aria-live": "polite" });
    U.range = h("input", { type: "range", min: "0", max: "0", step: "1", value: "0", "aria-label": "which day" });
    U.range.addEventListener("input", () => {
      if (+U.range.value !== this.index) {
        audio?.play("ui_slider");
        this.show(+U.range.value);
      }
    });
    U.prev = h("button", { type: "button", "aria-label": "an older picture", onclick: () => this.use({ dir: -1 }, true) }, "◀");
    U.next = h("button", { type: "button", "aria-label": "a newer picture", onclick: () => this.use({ dir: 1 }, true) }, "▶");
    U.first = h("span");
    U.last = h("span");
    this.el = h("div", { class: "g3d-overlay g3d-story", hidden: true, role: "dialog", "aria-label": "our island's story" },
      h("div", { class: "g3d-sheet" },
        h("header", { class: "g3d-panel-head" }, h("h2", { class: "g3d-sheet-title" }, "˚₊‧ our island's story ‧₊˚"), h("button", { class: "g3d-close", type: "button", "aria-label": "close", onclick: () => this.close() }, "✕")),
        h("div", { class: "g3d-help-body" },
          h("div", { class: "g3d-story-pic" }, U.img, U.tag),
          U.cap,
          h("div", { class: "g3d-story-row" }, U.prev, U.range, U.next),
          h("div", { class: "g3d-story-ends" }, U.first, U.last),
        ),
      ),
    );
    for (const type of ["touchstart", "touchmove", "touchend"]) this.el.addEventListener(type, (e) => e.stopPropagation(), { passive: true });
    this.el.addEventListener("keydown", (e) => {
      if (e.key === "ArrowLeft") this.use({ dir: -1 }, true);
      else if (e.key === "ArrowRight") this.use({ dir: 1 }, true);
      else return;
      e.preventDefault();
      e.stopPropagation();
    });
    document.body.append(this.el);
    this.onChange = () => this.syncUI();
  }
  isOpen() {
    return !!this.el && !this.el.hidden;
  }
  open() {
    if (!this.el || !this.snaps.length) return;
    this.onOpen?.();
    this.el.hidden = false;
    this.audio?.play("ui_open");
    this.syncUI();
    this.ui.range.focus({ preventScroll: true });
  }
  close() {
    if (!this.el || this.el.hidden) return;
    this.el.hidden = true;
    this.audio?.play("ui_close");
    this.onClose?.();
  }
  syncUI() {
    if (!this.el || this.el.hidden) return;
    const U = this.ui;
    const n = this.snaps.length;
    const s = this.snaps[this.index];
    if (!s) return;
    const src = this.bigImage(this.index);
    if (U.img.getAttribute("src") !== src) U.img.src = src;
    const day = Math.round((dayOf(s.date) - this.first) / 86400000) + 1;
    U.tag.textContent = this.index === n - 1 ? `today ♡ · ${niceDate(s.date)}` : `day ${day} · ${niceDate(s.date)}`;
    U.cap.textContent = s.caption || "";
    U.range.max = String(n - 1);
    U.range.value = String(this.index);
    U.range.setAttribute("aria-valuetext", `${niceDate(s.date)}: ${s.caption || ""}`);
    U.prev.disabled = this.index <= 0;
    U.next.disabled = this.index >= n - 1;
    U.first.textContent = niceDate(this.snaps[0].date);
    U.last.textContent = "today";
  }

  // an arrow (dir -1 / 1), or the picture itself (0: the big view); fromUI: the big view's own buttons (no wrap)
  use(a, fromUI = false) {
    const dir = a?.dir || 0;
    if (!dir) return this.open();
    if (!this.snaps.length) return;
    if (fromUI && (this.index + dir < 0 || this.index + dir >= this.snaps.length)) return;
    this.audio?.play("ui_tab");
    this.step(dir);
  }
}
