// Coplanar faces (z-fighting) inside a zone, resolved once when the zone comes in.
//
// The Blender kits mount trim, lids, plates and decks flush on the faces they sit on, and the zone merge
// keeps both faces: two triangles in one plane, facing the same way, draw in whichever order the depth
// test happens to pick on that pixel, which is the shimmer on the bakery's corners, the gift and pin it
// lids, the porch decks over their raw copy... (user feedback 2026-11-17d). Here every pair of static
// triangles that face the same way, lie in the same plane (within TOL) and overlap gets pulled apart:
// the smaller one (the thing mounted on the other) moves out along its normal by STEP per layer, on its
// own copy of its corners, so the faces it shares corners with stay put. A few millimetres: invisible,
// but well past the depth buffer's resolution at play distances (24-bit depth, near 0.2: about 1 mm at 60 m).
import * as THREE from "three";

const TOL = 0.0015; // (metres: closer than this is one plane)
const STEP = 0.005; // (metres per layer)
const MAX_BUCKET = 60000; // (a plane holding more triangles than this is left alone)
const CELL = 1; // (metres: the in-plane grid the overlap search runs on)

const _v = new THREE.Vector3();
const _inv = new THREE.Matrix4();

// static meshes only: no skins, morphs or instances (their shapes move), nothing that skips the depth write
// (a LOD alternate is only ever drawn instead of its LOD0, never with it: each LOD level is its own pass,
// the far ones with a bigger step, since they are seen where the depth buffer is coarsest)
const LOD_ALT = /_LOD([12])$/;
const lodLevel = (o) => {
  for (let q = o; q; q = q.parent) {
    const m = LOD_ALT.exec(q.userData?.name || q.name || "");
    if (m) return +m[1];
  }
  return 0;
};
// a piece that moves (a zone's ANIM_ node: the spinning record, a swinging lid, an ornament): what lies in one
// plane with it at the moment of the search is chance, and lifting a few of its triangles off a smooth face
// tore it open (the song room's record: a lifted wedge drew a light line across the vinyl and a dark wedge
// through its label). It stays in the mesh list (the plans' indices and signature are unchanged) but is never
// moved, nor counted against anything else
function moving(o) {
  for (let q = o; q; q = q.parent) if (/^ANIM_/.test(q.userData?.name || q.name || "") || q.userData?.tdd_anim) return true;
  return false;
}
function wanted(o, level) {
  if (lodLevel(o) !== level) return false;
  // (a room's rug liner is laid 1 mm over the thick rug on purpose and drawn in front of it, zones/v2-local.js: the
  // thick rug's fan of thin wedges counted as "the smaller face" and was lifted over the rug's picture, a dark disc
  // over the clock rug from above, the user 2026-11-20)
  if (/room_rug/.test(o.name || "")) return false;
  if (!o.isMesh || o.isSkinnedMesh || o.isInstancedMesh || o.morphTargetInfluences) return false;
  const g = o.geometry;
  if (!g?.attributes?.position || g.morphAttributes?.position) return false;
  const ms = Array.isArray(o.material) ? o.material : [o.material];
  return ms.every((m) => m && m.depthWrite !== false && m.depthTest !== false);
}

// world-space triangles of the given meshes, as flat arrays
function gather(meshes) {
  let total = 0;
  for (const o of meshes) total += (o.geometry.index ? o.geometry.index.count : o.geometry.attributes.position.count) / 3;
  total |= 0;
  const P = new Float32Array(total * 9); // corners
  const Nw = new Float32Array(total * 4); // normal + plane offset
  const A = new Float32Array(total); // area
  const M = new Uint16Array(total); // mesh
  const I = new Uint32Array(total); // triangle in its mesh
  let t = 0;
  meshes.forEach((o, mi) => {
    const g = o.geometry, pos = g.attributes.position, idx = g.index, n = (idx ? idx.count : pos.count) / 3;
    const e = o.matrixWorld.elements;
    // (plain float positions read straight from the array: getX per corner was most of a phone's time)
    const fast = !pos.isInterleavedBufferAttribute && !pos.normalized && pos.array instanceof Float32Array && pos.itemSize === 3;
    const pa = pos.array, ia = idx?.array;
    for (let k = 0; k < n; k++, t++) {
      for (let c = 0; c < 3; c++) {
        const vi = ia ? ia[k * 3 + c] : k * 3 + c;
        const x = fast ? pa[vi * 3] : pos.getX(vi), y = fast ? pa[vi * 3 + 1] : pos.getY(vi), z = fast ? pa[vi * 3 + 2] : pos.getZ(vi);
        P[t * 9 + c * 3] = e[0] * x + e[4] * y + e[8] * z + e[12];
        P[t * 9 + c * 3 + 1] = e[1] * x + e[5] * y + e[9] * z + e[13];
        P[t * 9 + c * 3 + 2] = e[2] * x + e[6] * y + e[10] * z + e[14];
      }
      const o9 = t * 9;
      const ux = P[o9 + 3] - P[o9], uy = P[o9 + 4] - P[o9 + 1], uz = P[o9 + 5] - P[o9 + 2];
      const vx = P[o9 + 6] - P[o9], vy = P[o9 + 7] - P[o9 + 1], vz = P[o9 + 8] - P[o9 + 2];
      let nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
      const L = Math.hypot(nx, ny, nz);
      A[t] = L / 2;
      if (L > 1e-12) {
        nx /= L;
        ny /= L;
        nz /= L;
      }
      Nw[t * 4] = nx;
      Nw[t * 4 + 1] = ny;
      Nw[t * 4 + 2] = nz;
      Nw[t * 4 + 3] = nx * P[o9] + ny * P[o9 + 1] + nz * P[o9 + 2];
      M[t] = mi;
      I[t] = k;
    }
  });
  return { P, Nw, A, M, I, total };
}

// do two triangles in (nearly) one plane overlap with some area? (separating axes in the plane's
// dominant projection, with a small margin so triangles that only share an edge do not count)
function overlap(P, a, b, Nw) {
  const ax = Math.abs(Nw[a * 4]), ay = Math.abs(Nw[a * 4 + 1]), az = Math.abs(Nw[a * 4 + 2]);
  const [i, j] = ax > ay && ax > az ? [1, 2] : ay > az ? [0, 2] : [0, 1];
  const pa = [P[a * 9 + i], P[a * 9 + j], P[a * 9 + 3 + i], P[a * 9 + 3 + j], P[a * 9 + 6 + i], P[a * 9 + 6 + j]];
  const pb = [P[b * 9 + i], P[b * 9 + j], P[b * 9 + 3 + i], P[b * 9 + 3 + j], P[b * 9 + 6 + i], P[b * 9 + 6 + j]];
  for (const S of [pa, pb])
    for (let e = 0; e < 3; e++) {
      const x0 = S[e * 2], y0 = S[e * 2 + 1], x1 = S[((e + 1) % 3) * 2], y1 = S[((e + 1) % 3) * 2 + 1];
      const nx = y1 - y0, ny = x0 - x1, L = Math.hypot(nx, ny);
      if (L < 1e-9) continue;
      let a0 = Infinity, a1 = -Infinity, b0 = Infinity, b1 = -Infinity;
      for (let k = 0; k < 3; k++) {
        const s = (pa[k * 2] * nx + pa[k * 2 + 1] * ny) / L;
        if (s < a0) a0 = s;
        if (s > a1) a1 = s;
        const r = (pb[k * 2] * nx + pb[k * 2 + 1] * ny) / L;
        if (r < b0) b0 = r;
        if (r > b1) b1 = r;
      }
      if (a1 <= b0 + 0.002 || b1 <= a0 + 0.002) return false;
    }
  return true;
}

// move the listed triangles of one mesh out by their offsets, each on its own new corners
function apply(o, moves) {
  let g = o.geometry;
  if (g.userData.__shared) g = o.geometry = g.clone();
  const idx = g.index;
  const pos = g.attributes.position;
  const add = moves.size * 3;
  const base = pos.count;
  const names = Object.keys(g.attributes);
  for (const name of names) {
    let at = g.attributes[name];
    if (at.isInterleavedBufferAttribute) at = at.clone();
    const arr = new at.array.constructor((at.count + add) * at.itemSize);
    arr.set(at.array.subarray(0, at.count * at.itemSize));
    const na = new THREE.BufferAttribute(arr, at.itemSize, at.normalized);
    let w = at.count;
    for (const tri of moves.keys())
      for (let c = 0; c < 3; c++, w++) {
        const vi = idx ? idx.getX(tri * 3 + c) : tri * 3 + c;
        for (let s = 0; s < at.itemSize; s++) arr[w * at.itemSize + s] = at.array[vi * at.itemSize + s] ?? at.getComponent(vi, s);
      }
    g.setAttribute(name, na);
  }
  // the moved corners: out along the world normal, back into the mesh's own space
  _inv.copy(o.matrixWorld).invert();
  const P2 = g.attributes.position;
  const e = o.matrixWorld.elements;
  let w = base;
  for (const [, off] of moves)
    for (let c = 0; c < 3; c++, w++) {
      _v.fromBufferAttribute(P2, w);
      const x = _v.x, y = _v.y, z = _v.z;
      _v.set(e[0] * x + e[4] * y + e[8] * z + e[12] + off[0], e[1] * x + e[5] * y + e[9] * z + e[13] + off[1], e[2] * x + e[6] * y + e[10] * z + e[14] + off[2]).applyMatrix4(_inv);
      P2.setXYZ(w, _v.x, _v.y, _v.z);
    }
  // the triangles now point at their own corners
  const triCount = idx ? idx.count / 3 : pos.count / 3;
  const need = base + add;
  const I = new (need > 65535 ? Uint32Array : idx?.array.constructor || Uint32Array)(triCount * 3);
  if (idx) I.set(idx.array.subarray(0, idx.count));
  else for (let k = 0; k < I.length; k++) I[k] = k;
  w = base;
  for (const tri of moves.keys()) for (let c = 0; c < 3; c++, w++) I[tri * 3 + c] = w;
  g.setIndex(new THREE.BufferAttribute(I, 1));
  g.computeBoundingBox();
  g.computeBoundingSphere();
}

// pull apart the coplanar faces of every static mesh under `roots` (one zone's files); returns how many moved
// plan: what an earlier run moved (zones/decoplanar_<set>.json, made by the QA harness): applied as is when
// the zone's meshes still match it, so a phone never pays for the search; else worked out here.
// Returns { moved, plan } (the plan of this run, to be saved by the harness).
export function decoplanar(roots, plan = null) {
  const out = { moved: 0, plan: [], planned: 0 };
  [0, 1, 2].forEach((level) => {
    const r = pass(roots, level, STEP * [1, 2.4, 4][level], plan?.[level]);
    out.moved += r.n;
    out.plan.push(r.plan);
    out.planned += r.planned ? 1 : 0;
  });
  return out;
}

function pass(roots, level, STEP, given) {
  const meshes = [];
  const seen = new Map();
  for (const root of [].concat(roots)) {
    root.updateMatrixWorld(true);
    root.traverse((o) => {
      if (!wanted(o, level)) return;
      meshes.push(o);
      seen.set(o.geometry, (seen.get(o.geometry) || 0) + 1);
    });
  }
  if (!meshes.length || meshes.length > 65535) return { n: 0, plan: null };
  let tris = 0;
  for (const o of meshes) tris += (o.geometry.index ? o.geometry.index.count : o.geometry.attributes.position.count) / 3;
  const sig = [meshes.length, tris];
  for (const [geo, n] of seen) if (n > 1) geo.userData.__shared = true;
  const done = (per, n, planned = false) => {
    for (const [o, m] of per) apply(o, m);
    for (const [geo] of seen) delete geo.userData.__shared;
    const list = [];
    for (const [o, m] of per) for (const [t, d] of m) list.push([meshes.indexOf(o), t, ...d.map((v) => Math.round(v * 1e4) / 1e4)]);
    return { n, plan: { sig, m: list }, planned };
  };
  const still = meshes.map((o) => !moving(o));
  if (given && given.sig?.[0] === sig[0] && given.sig?.[1] === sig[1]) {
    const per = new Map();
    for (const [mi, t, x, y, z] of given.m) {
      const o = meshes[mi];
      if (!o || !still[mi]) continue;
      if (!per.has(o)) per.set(o, new Map());
      per.get(o).set(t, [x, y, z]);
    }
    return done(per, given.m.length, true);
  }
  const { P, Nw, A, M, I, total } = gather(meshes);
  // planes: the normal to about a degree, the offset to TOL (a neighbour bucket catches the edge cases)
  // (by the normal's dominant axis and sign, not its rounded direction: two near-identical normals
  // rounding to neighbouring keys were never compared, the gift lid's residual shimmer at range)
  const key = (t, d) => {
    const x = Nw[t * 4], y = Nw[t * 4 + 1], z = Nw[t * 4 + 2], ax = Math.abs(x), ay = Math.abs(y), az = Math.abs(z);
    const dom = ax > ay && ax > az ? (x > 0 ? 0 : 1) : ay > az ? (y > 0 ? 2 : 3) : z > 0 ? 4 : 5;
    return `${dom},${Math.floor(Nw[t * 4 + 3] / TOL) + d}`;
  };
  const buckets = new Map();
  for (let t = 0; t < total; t++) {
    if (A[t] < 1e-6 || !still[M[t]]) continue;
    const k = key(t, 0);
    let b = buckets.get(k);
    if (!b) buckets.set(k, (b = []));
    b.push(t);
  }
  // largest first: each triangle sits one layer above the largest-layered triangle it overlaps that is
  // bigger than it (or, the same size, came first)
  const layer = new Map();
  const stamp = new Int32Array(total).fill(-1);
  for (const [k, list] of buckets) {
    const nb = buckets.get(k.replace(/,(-?\d+)$/, (_, d) => "," + (+d - 1)));
    const pool = nb ? list.concat(nb) : list;
    if (pool.length > MAX_BUCKET) continue;
    list.sort((a, b) => A[b] - A[a] || a - b);
    // (a coarse grid in the plane, so a path's thousand cobbles are not each tested against all the others)
    const t0 = pool[0], ax = Math.abs(Nw[t0 * 4]), ay = Math.abs(Nw[t0 * 4 + 1]), az = Math.abs(Nw[t0 * 4 + 2]);
    const [pi, pj] = ax > ay && ax > az ? [1, 2] : ay > az ? [0, 2] : [0, 1];
    const box = (t) => {
      let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
      for (let c = 0; c < 3; c++) {
        const x = P[t * 9 + c * 3 + pi], y = P[t * 9 + c * 3 + pj];
        if (x < x0) x0 = x;
        if (x > x1) x1 = x;
        if (y < y0) y0 = y;
        if (y > y1) y1 = y;
      }
      return [Math.floor(x0 / CELL), Math.floor(x1 / CELL), Math.floor(y0 / CELL), Math.floor(y1 / CELL)];
    };
    const grid = new Map(), big = [];
    if (pool.length > 32)
      for (const u of pool) {
        const [a0, a1, b0, b1] = box(u);
        if ((a1 - a0 + 1) * (b1 - b0 + 1) > 64) {
          big.push(u);
          continue;
        }
        for (let a = a0; a <= a1; a++)
          for (let b = b0; b <= b1; b++) {
            const g = a * 73856093 + b * 19349663;
            let c = grid.get(g);
            if (!c) grid.set(g, (c = []));
            c.push(u);
          }
      }
    const near = (t) => {
      if (pool.length <= 32) return pool;
      const out = big.slice();
      const [a0, a1, b0, b1] = box(t);
      if ((a1 - a0 + 1) * (b1 - b0 + 1) > 64) return pool;
      for (let a = a0; a <= a1; a++)
        for (let b = b0; b <= b1; b++)
          for (const u of grid.get(a * 73856093 + b * 19349663) || [])
            if (stamp[u] !== t) {
              stamp[u] = t;
              out.push(u);
            }
      return out;
    };
    for (const t of list) {
      let L = layer.get(t) || 0;
      for (const u of near(t)) {
        if (u === t) continue;
        const bigger = A[u] > A[t] * 1.001 || (Math.abs(A[u] - A[t]) <= A[t] * 0.001 && u < t);
        if (!bigger) continue;
        if (Nw[t * 4] * Nw[u * 4] + Nw[t * 4 + 1] * Nw[u * 4 + 1] + Nw[t * 4 + 2] * Nw[u * 4 + 2] < 0.9995) continue;
        if (Math.abs(Nw[t * 4 + 3] - Nw[u * 4 + 3]) > TOL) continue;
        if (!overlap(P, t, u, Nw)) continue;
        L = Math.max(L, (layer.get(u) || 0) + 1);
      }
      if (L) layer.set(t, L);
    }
  }
  const per = new Map();
  for (const [t, L] of layer) {
    const o = meshes[M[t]];
    let m = per.get(o);
    if (!m) per.set(o, (m = new Map()));
    const s = STEP * L;
    m.set(I[t], [Nw[t * 4] * s, Nw[t * 4 + 1] * s, Nw[t * 4 + 2] * s]);
  }
  return done(per, layer.size);
}

// ---- legacy overlays -------------------------------------------------------------------------
// What the zone did not take over still stands where the legacy builder put it: a canvas sign flat
// on the zone's roof (Our Diary's lettering), a wall item flush on a room zone's wall (the note room),
// a frame on the cinema screen's edge, shelf items against the bakery glass. Those fight the zone's
// faces the same way (review 2026-11-20). They are found here (only triangles inside their boxes are
// looked at, so it stays cheap on a phone) and drawn as decals: a small depth offset towards the
// camera on their material, the standard fix for something laid on a surface.
const _b = new THREE.Box3();
const G3 = 0.5; // (metres: the zone's triangles are hashed in cells this size)
export function overlayDecals(zoneRoots, scene, zonesRoot, maxTris = 600) {
  const zb = new THREE.Box3();
  const zm = [];
  for (const r of [].concat(zoneRoots)) {
    r.updateMatrixWorld(true);
    r.traverse((o) => {
      if (!wanted(o, 0)) return;
      zm.push(o);
      if (!o.geometry.boundingBox) o.geometry.computeBoundingBox();
      zb.union(_b.copy(o.geometry.boundingBox).applyMatrix4(o.matrixWorld));
    });
  }
  if (!zm.length || zb.isEmpty()) return 0;
  // (a zone spread over the whole island, the race road, the shell: nothing is laid on those, and
  // every legacy piece on the island would be a candidate)
  if (zb.min.distanceTo(zb.max) > 160) return 0;
  zb.expandByScalar(0.05);
  // the legacy pieces standing in the zone's box: small ones only (signs, plates, wall items)
  const cands = [];
  const walk = (o) => {
    // (hidden ones too: a room's legacy inside is hidden until you are near, when its zone already stands)
    if (o === zonesRoot) return;
    // (a room's own floor and rug, kept on phones under the zone's modelled floor, world.js roomFloor: a base, never
    // a decal laid on it. Pulled towards the camera, the slope part of the pull grew with the view's slant, so the old
    // canvas floor won over the modelled one in a band that moved as you looked up or down, the user 2026-11-22)
    if (o.userData?.roomFloor) return;
    if (o.isMesh && !o.isSkinnedMesh && !o.isInstancedMesh && o.geometry?.attributes?.position) {
      const g = o.geometry;
      const nt = (g.index ? g.index.count : g.attributes.position.count) / 3;
      if (nt <= maxTris) {
        if (!g.boundingBox) g.computeBoundingBox();
        // (laid-on things only: flat ones, see-through boards and signs, and plain boxes such as frames
        // and trims, a few dozen triangles)
        const s = g.boundingBox.getSize(_v);
        const m = Array.isArray(o.material) ? o.material[0] : o.material;
        if ((Math.min(s.x, s.y, s.z) <= 0.04 || m?.transparent || nt <= 64) && _b.copy(g.boundingBox).applyMatrix4(o.matrixWorld).intersectsBox(zb)) cands.push(o);
      }
    }
    for (const c of o.children) walk(c);
  };
  walk(scene);
  if (!cands.length) return 0;
  // the zone's triangles, hashed by the cells their boxes cover (only those near a candidate)
  const cb = new THREE.Box3();
  for (const o of cands) cb.union(_b.copy(o.geometry.boundingBox).applyMatrix4(o.matrixWorld));
  cb.expandByScalar(0.02);
  // (only the zone meshes whose box meets a candidate's)
  const Z = gather(zm.filter((z) => _b.copy(z.geometry.boundingBox).applyMatrix4(z.matrixWorld).intersectsBox(cb)));
  if (!Z.total) return 0;
  const cell = (x, y, z) => (Math.floor(x / G3) * 73856093) ^ (Math.floor(y / G3) * 19349663) ^ (Math.floor(z / G3) * 83492791);
  const grid = new Map();
  const tb = (P, t) => {
    let x0 = Infinity, y0 = Infinity, z0 = Infinity, x1 = -Infinity, y1 = -Infinity, z1 = -Infinity;
    for (let c = 0; c < 3; c++) {
      const x = P[t * 9 + c * 3], y = P[t * 9 + c * 3 + 1], z = P[t * 9 + c * 3 + 2];
      x0 = Math.min(x0, x); y0 = Math.min(y0, y); z0 = Math.min(z0, z);
      x1 = Math.max(x1, x); y1 = Math.max(y1, y); z1 = Math.max(z1, z);
    }
    return [x0, y0, z0, x1, y1, z1];
  };
  const big = [];
  for (let t = 0; t < Z.total; t++) {
    if (Z.A[t] < 1e-6) continue;
    const [x0, y0, z0, x1, y1, z1] = tb(Z.P, t);
    if (x1 < cb.min.x || x0 > cb.max.x || y1 < cb.min.y || y0 > cb.max.y || z1 < cb.min.z || z0 > cb.max.z) continue;
    const nx = Math.floor(x1 / G3) - Math.floor(x0 / G3) + 1, ny = Math.floor(y1 / G3) - Math.floor(y0 / G3) + 1, nz = Math.floor(z1 / G3) - Math.floor(z0 / G3) + 1;
    if (nx * ny * nz > 216) {
      big.push(t);
      continue;
    }
    for (let a = 0; a < nx; a++)
      for (let b = 0; b < ny; b++)
        for (let d = 0; d < nz; d++) {
          const k = cell(x0 + a * G3, y0 + b * G3, z0 + d * G3);
          let l = grid.get(k);
          if (!l) grid.set(k, (l = []));
          l.push(t);
        }
  }
  // each candidate triangle against the zone triangles in its cells
  const P2 = new Float32Array(18), N2 = new Float32Array(8);
  let n = 0;
  for (const o of cands) {
    const C = gather([o]);
    let hit = false;
    for (let t = 0; t < C.total && !hit; t++) {
      if (C.A[t] < 1e-6) continue;
      const [x0, y0, z0, x1, y1, z1] = tb(C.P, t);
      const seen = new Set();
      for (let x = x0; x <= x1 + G3 && !hit; x += G3)
        for (let y = y0; y <= y1 + G3; y += G3)
          for (let z = z0; z <= z1 + G3; z += G3) for (const u of grid.get(cell(Math.min(x, x1), Math.min(y, y1), Math.min(z, z1))) || []) seen.add(u);
      for (const u of big.length ? [...seen, ...big] : seen) {
        if (C.Nw[t * 4] * Z.Nw[u * 4] + C.Nw[t * 4 + 1] * Z.Nw[u * 4 + 1] + C.Nw[t * 4 + 2] * Z.Nw[u * 4 + 2] < 0.9995) continue;
        if (Math.abs(C.Nw[t * 4 + 3] - Z.Nw[u * 4 + 3]) > 0.004) continue;
        P2.set(C.P.subarray(t * 9, t * 9 + 9), 0);
        P2.set(Z.P.subarray(u * 9, u * 9 + 9), 9);
        N2.set(C.Nw.subarray(t * 4, t * 4 + 4), 0);
        N2.set(Z.Nw.subarray(u * 4, u * 4 + 4), 4);
        if (overlap(P2, 0, 1, N2)) {
          hit = true;
          break;
        }
      }
    }
    if (!hit) continue;
    // (on the material itself: its live redraws and colour changes carry on; anything else sharing it
    // only gains a fraction of a millimetre towards the camera)
    for (const m of Array.isArray(o.material) ? o.material : [o.material]) {
      if (m.polygonOffset) continue; // (already layered on purpose, e.g. the ground paints)
      m.polygonOffset = true;
      m.polygonOffsetFactor = -1;
      m.polygonOffsetUnits = -4;
    }
    n++;
  }
  return n;
}