import { icon } from "./hud.js";

// Phone layout for the 3D island (user, 2026-11-17, iPhone screenshots): the look editor took half the screen in
// landscape and nearly all of it in portrait, and toasts sat in the middle of the action. The 3D game's own sheet
// of rules, injected while the island runs (island.css is shared with the 2D site and stays untouched):
// - portrait phones: a slim editor sheet (36 % of the height) with smaller tabs, pills and swatches;
// - landscape phones (short screens): the editor is a narrow panel on the right, the toast a small strip at the top;
// - full screen: see below.
const CSS = `
@media (pointer: coarse) and (max-aspect-ratio: 4/5) and (max-width: 640px) {
  html .g3d-editor .g3d-editor-sheet { max-height: 36%; border-radius: 22px 22px 0 0; }
  html .g3d-editor .g3d-sheet-title, html .g3d-editor .g3d-panel-head { padding-top: 8px; padding-bottom: 4px; font-size: 15px; }
  html .g3d-editor .g3d-editor-body { padding: 2px 12px 12px; }
  html .g3d-editor .g3d-ed-tabs > .g3d-chips:first-child .g3d-chip { padding: 5px 10px; font-size: 13px; }
  html .g3d-editor .g3d-ed-tabs .g3d-ed-parts { margin-top: 6px; flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; }
  html .g3d-editor .g3d-ed-row .g3d-chip.g3d-chip-part { padding: 6px 8px 8px; font-size: 13px; white-space: nowrap; }
  html .g3d-editor .g3d-editor-body .g3d-ed-row:not(.g3d-ed-tabs) .g3d-chip { padding: 5px 10px; font-size: 12.5px; }
  html .g3d-editor .g3d-ed-row h3 { margin: 10px 0 5px; font-size: 10px; }
  html .g3d-editor .g3d-chips, html .g3d-editor .g3d-swatches { gap: 6px; }
  html .g3d-editor .g3d-swatch { width: 28px; height: 28px; }
}
@media (pointer: coarse) and (min-aspect-ratio: 5/4) and (max-height: 540px) {
  html .g3d-toast {
    top: calc(6px + env(safe-area-inset-top, 0px));
    padding: 6px 14px;
    font-size: 12.5px;
    max-width: min(46vw, 420px);
  }
  html .g3d-editor { place-items: stretch end; padding: 0; }
  html .g3d-editor .g3d-editor-sheet {
    width: min(330px, 40vw);
    max-height: 100%;
    height: 100%;
    border-radius: 20px 0 0 20px;
    padding-right: env(safe-area-inset-right, 0px);
  }
  html .g3d-editor .g3d-sheet-title, html .g3d-editor .g3d-panel-head { padding-top: 6px; padding-bottom: 2px; font-size: 14px; }
  html .g3d-editor .g3d-editor-body { padding: 2px 10px 10px; }
  html .g3d-editor .g3d-ed-tabs > .g3d-chips:first-child .g3d-chip { padding: 4px 8px; font-size: 12px; }
  html .g3d-editor .g3d-ed-tabs .g3d-ed-parts { margin-top: 4px; flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; }
  html .g3d-editor .g3d-ed-row .g3d-chip.g3d-chip-part { padding: 5px 7px 7px; font-size: 12px; white-space: nowrap; }
  html .g3d-editor .g3d-editor-body .g3d-ed-row:not(.g3d-ed-tabs) .g3d-chip { padding: 4px 9px; font-size: 12px; }
  html .g3d-editor .g3d-ed-row h3 { margin: 8px 0 4px; font-size: 10px; }
  html .g3d-editor .g3d-chips, html .g3d-editor .g3d-swatches { gap: 5px; }
  html .g3d-editor .g3d-swatch { width: 24px; height: 24px; }
  html .g3d-overlay:not(.g3d-editor) .g3d-sheet { max-height: 94%; }
}`;

let styleEl = null;
export function phoneUI({ isTouch }) {
  if (!styleEl) {
    styleEl = document.createElement("style");
    styleEl.id = "g3d-phone-ui";
    styleEl.textContent = CSS;
    document.head.appendChild(styleEl);
  }
  if (!isTouch || standalone()) return;
  // (iPhone: no swipe-up veil any more, the user asked for it gone; full screen stays in the menu: Add to Home Screen)
  if (!iphone() && fsApi()) tapForFull();
}

// ---- full screen (TODO 54) ----------------------------------------------------------------------------------------------
// - Android Chrome, iPad Safari and computers have the Fullscreen API: a tap asks for it (it needs a tap).
// - iPhone Safari has none for pages: its bars only fold away when the page itself is scrolled by a finger, and the only
//   true full screen is the island added to the Home Screen (the manifest opens standalone). The swipe-up veil that
//   made the page taller to fold the bars was removed at the user's request (2026-11-28); the menu's "full screen"
//   shows how to add it to the Home Screen.
const iphone = () => /iPhone|iPod/.test(navigator.userAgent);
const ios = () => /iPhone|iPad|iPod/.test(navigator.userAgent) || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
const standalone = () => Boolean(navigator.standalone) || matchMedia("(display-mode: standalone)").matches || matchMedia("(display-mode: fullscreen)").matches;
const fsApi = () => Boolean(document.fullscreenEnabled || document.webkitFullscreenEnabled);
const fsEl = () => document.fullscreenElement || document.webkitFullscreenElement;
let weWentFull = false;
function toggleFull() {
  const d = document.documentElement;
  if (fsEl()) {
    (document.exitFullscreen || document.webkitExitFullscreen)?.call(document)?.catch?.(() => {});
    return;
  }
  try {
    const r = (d.requestFullscreen || d.webkitRequestFullscreen)?.call(d, { navigationUI: "hide" });
    weWentFull = true;
    // (refused, or nothing went full screen: on Apple devices the Home Screen is the way)
    const refused = () => {
      weWentFull = false;
      if (ios()) installGuide();
    };
    if (r?.then) r.then(() => !fsEl() && refused(), refused);
    else setTimeout(() => !fsEl() && refused(), 400);
  } catch {
    if (ios()) installGuide();
  }
}
// the "full screen" row in the island's menu: the real thing where there is one, else how to install the island
export function fullscreenEntry() {
  if (standalone()) return null;
  if (fsApi() && !iphone()) return { label: "full screen", icon: "expand", run: toggleFull };
  if (ios()) return { label: "full screen", icon: "expand", run: installGuide };
  return null;
}

const VEIL_CSS = `
.g3d-veil {
  position: fixed; inset: 0; z-index: 2147483000; display: flex; flex-direction: column; align-items: center; justify-content: flex-end;
  padding: 24px 16px calc(24px + env(safe-area-inset-bottom, 0px)); box-sizing: border-box; touch-action: pan-y;
  background: linear-gradient(to top, rgba(14, 6, 26, 0.72), rgba(14, 6, 26, 0.32) 60%, rgba(14, 6, 26, 0.18));
  color: #fff; font-family: Quicksand, system-ui, sans-serif; text-align: center; -webkit-user-select: none; user-select: none;
  animation: g3d-veil-in 0.4s ease both;
}
.g3d-veil-card {
  width: min(360px, 100%); padding: 22px 20px 16px; border-radius: 28px; box-sizing: border-box;
  background: color-mix(in srgb, var(--g3d-card, #2a1f3d) 62%, transparent); border: 1px solid rgba(255, 255, 255, 0.24);
  -webkit-backdrop-filter: blur(20px) saturate(170%); backdrop-filter: blur(20px) saturate(170%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.3), 0 30px 60px -24px rgba(0, 0, 0, 0.6);
  color: var(--g3d-ink, #fff); animation: g3d-veil-card 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.g3d-veil-hand {
  width: 56px; height: 56px; margin: 0 auto 10px; border-radius: 50%; display: grid; place-items: center;
  background: var(--g3d-accent, #e2557f); color: #fff; box-shadow: 0 10px 24px -8px var(--g3d-accent, #e2557f);
}
.g3d-veil-hand svg { width: 28px; height: 28px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
.g3d-veil h2 { margin: 0 0 4px; font-size: 19px; font-weight: 700; }
.g3d-veil p { text-wrap: balance; margin: 0 0 14px; font-size: 14px; line-height: 1.45; opacity: 0.8; font-weight: 600; }
.g3d-veil-row { display: flex; gap: 8px; }
.g3d-veil button { flex: 1; min-height: 46px; border-radius: 15px; border: 0; font: 700 14px/1.1 Quicksand, system-ui, sans-serif; cursor: pointer; touch-action: manipulation; }
.g3d-veil .g3d-veil-main { background: var(--g3d-accent, #e2557f); color: #fff; font-weight: 800; box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.3), 0 10px 22px -10px var(--g3d-accent-ink, #e2557f); }
.g3d-veil .g3d-veil-soft { background: color-mix(in srgb, var(--g3d-ink, #fff) 12%, transparent); color: inherit; }
@keyframes g3d-veil-in { from { opacity: 0; } }
@keyframes g3d-veil-card { from { opacity: 0; transform: translateY(30px) scale(0.97); } }
@media (max-height: 480px) {
  .g3d-veil { justify-content: center; }
  .g3d-veil-card { padding: 14px 16px 12px; }
  .g3d-veil-hand { width: 44px; height: 44px; margin-bottom: 6px; }
  .g3d-veil p { margin-bottom: 10px; }
}
@media (prefers-reduced-motion: reduce) { .g3d-veil, .g3d-veil-card { animation: none; } }`;
const ARROW = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 19V5M6 11l6-6 6 6"/></svg>';
let veilStyle = null;
function addVeilStyle() {
  if (veilStyle) return;
  veilStyle = document.createElement("style");
  veilStyle.textContent = VEIL_CSS;
  document.head.appendChild(veilStyle);
}
function makeVeil({ title, text, main, soft, hand = ARROW }) {
  const v = document.createElement("div");
  v.className = "g3d-veil";
  v.setAttribute("role", "dialog");
  v.setAttribute("aria-label", title);
  v.innerHTML = `<div class="g3d-veil-card"><div class="g3d-veil-hand">${hand}</div><h2></h2><p></p><div class="g3d-veil-row"></div></div>`;
  v.querySelector("h2").textContent = title;
  v.querySelector("p").textContent = text;
  const row = v.querySelector(".g3d-veil-row");
  for (const [label, cls, fn] of [soft, main]) {
    const b = document.createElement("button");
    b.type = "button";
    b.className = cls;
    b.textContent = label;
    b.addEventListener("click", (e) => {
      e.stopPropagation();
      fn();
    });
    row.append(b);
  }
  // (the classic page's own swipe and pull-to-refresh never see these touches)
  for (const t of ["touchstart", "touchmove", "touchend"]) v.addEventListener(t, (e) => e.stopPropagation(), { passive: true });
  return v;
}

let veilOff = null;
// Android and iPad: one tap and the island fills the screen (offered once a visit; the menu has it too)
function tapForFull() {
  addVeilStyle();
  const close = () => {
    clearTimeout(t);
    veil.remove();
  };
  const veil = makeVeil({
    title: "play full screen",
    text: "the island looks best with nothing round it",
    hand: icon("expand"),
    soft: ["not now", "g3d-veil-soft", close],
    main: ["full screen", "g3d-veil-main", () => {
      toggleFull();
      close();
    }],
  });
  const t = setTimeout(() => {
    if (!fsEl() && document.documentElement.classList.contains("g3d-on")) document.body.appendChild(veil);
  }, 1400);
  veilOff = close;
}

// how to put the island on the Home Screen (iPhone): Share, Add to Home Screen, open it from there
let guide = null;
function installGuide() {
  if (guide) return;
  const close = () => {
    guide?.remove();
    guide = null;
  };
  guide = document.createElement("div");
  guide.className = "g3d-overlay g3d-ui-install";
  guide.setAttribute("role", "dialog");
  guide.setAttribute("aria-label", "play full screen");
  guide.style.zIndex = "2147483001";
  guide.innerHTML = `<div class="g3d-sheet">
    <header class="g3d-panel-head"><h2 class="g3d-sheet-title">play full screen</h2><button class="g3d-close g3d-ui-x" type="button" aria-label="close">${icon("close")}</button></header>
    <div class="g3d-help-body">
      <p>Safari keeps its bars round a web page. Added to your Home Screen, the island opens full screen, like an app:</p>
      <ol class="g3d-ui-steps">
        <li>${icon("share")}<span>tap Share in Safari</span></li>
        <li>${icon("plusSquare")}<span>choose “Add to Home Screen”</span></li>
        <li>${icon("home")}<span>open TOTO &amp; DODO from your Home Screen</span></li>
      </ol>
      <button class="g3d-big-btn" type="button">got it</button>
    </div>
  </div>`;
  guide.addEventListener("click", (e) => {
    if (e.target === guide || e.target.closest(".g3d-close, .g3d-big-btn")) close();
  });
  for (const t of ["touchstart", "touchmove", "touchend"]) guide.addEventListener(t, (e) => e.stopPropagation(), { passive: true });
  document.body.appendChild(guide);
}

// (when the island closes: the 3D rules leave with it, and a full screen it asked for ends)
export function phoneUIOff() {
  styleEl?.remove();
  styleEl = null;
  veilOff?.();
  veilOff = null;
  guide?.remove();
  guide = null;
  veilStyle?.remove();
  veilStyle = null;
  if (weWentFull && fsEl()) (document.exitFullscreen || document.webkitExitFullscreen)?.call(document)?.catch?.(() => {});
  weWentFull = false;
}
