// The bakery's treat kit (assets/blender/props/treats/_build_treats.py): every treat base and topping, made in Blender,
// three small shared GLBs of instance sources (vertex colours, no texture) fetched on their own, never inside a zone (the
// phone bakery room is at its byte cap). Phones (low / mid tier) load the _lite copies. bakery.js makeTreat builds
// each treat from these shapes; their geometry is shared by every treat and never disposed with one.
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { MeshoptDecoder } from "three/examples/jsm/libs/meshopt_decoder.module.js";
import { zonePack } from "./zones/mode.js";
import { smallProps } from "./vehicle.js";

let kit = null; // Map(part -> BufferGeometry)
let loading = null;
const waiting = [];

export function loadTreatKit() {
  if (loading) return loading;
  // (the pack, not the zone mode: with ?zones=legacy the treats are still the Blender ones)
  const base = zonePack();
  if (!base) return (loading = Promise.resolve(null));
  const sfx = smallProps() ? "_lite" : "";
  const loader = new GLTFLoader().setMeshoptDecoder(MeshoptDecoder);
  // (three files: the treat bases, one L asset, the toppings and the drizzles laid over each base)
  loading = Promise.all(
    ["bases", "toppings", "drizzles"].map((k) =>
      loader.loadAsync(`${base}props/prp_treats_${k}${sfx}.glb`).then((g) => [new RegExp(`^INST_prp_treats_${k}${sfx}_(.+)$`), g.scene]),
    ),
  )
    .then((files) => {
      const m = new Map();
      for (const [re, scene] of files)
        scene.traverse((o) => {
          if (!o.isMesh) return;
          const role = o.userData?.tdd_role || re.exec(o.name)?.[1];
          if (!role) return;
          o.geometry.userData.kit = true;
          o.geometry.computeBoundingBox();
          m.set(role, o.geometry);
          o.material?.dispose?.();
        });
      kit = m;
      for (const cb of waiting.splice(0)) cb(m);
      return m;
    })
    .catch((e) => {
      console.warn("treat kit", e);
      loading = null; // (the next treat asks again)
      return null;
    });
  return loading;
}

// run cb(kit) now if the kit is in, or once it arrives (fetching it, unless `fetch` is false: a module that only
// listens must not start it before the device tier is known)
export function withTreatKit(cb, fetch = true) {
  if (kit) cb(kit);
  else {
    waiting.push(cb);
    if (fetch) loadTreatKit();
  }
}
