    const live = new Set();
    for (const a of actors) {
      if (!a?.pos) continue;
      const id = a.id ?? a.pos;
      live.add(id);
      let s = this.actors.get(id);
      if (!s) this.actors.set(id, (s = { x: a.pos.x, z: a.pos.z, inside: false, next: 0 }));
      const sp = Math.hypot(a.pos.x - s.x, a.pos.z - s.z) / Math.max(dt, 1e-3);
      s.x = a.pos.x;
      s.z = a.pos.z;
      const pool = this.poolAt(a.pos.x, a.pos.z);
      const wet = pool && a.pos.y < pool.y + 0.35;
      if (wet && !s.inside) {
        this.ripple(a.pos.x, a.pos.z, 1.6);
        // (the sound of going in is the swimmer's own: swim.js)
        s.next = t + 0.15;
      } else if (wet && t > s.next) {
        this.ripple(a.pos.x, a.pos.z, sp > 0.4 ? 0.8 : 0.35);
        s.next = t + (sp > 0.4 ? 0.28 : 1.6);
      }
      s.inside = Boolean(wet);
    }
    for (const id of this.actors.keys()) if (!live.has(id)) this.actors.delete(id);
