// Soft fades for things that appear or swap (review 2026-11-20: animals cut from one tier to the next,
// LOD swaps and far houses popped). While a fade runs, the meshes under a root draw with a copy of their
// material drawn see-through at the fade's opacity (blended: a hashed dither read as grain), over what
// stands behind it; when it ends they get their own material back. Each fade makes its own copies (two things fading at
// once keep their own opacity); a copy shares its original's shader program after the first time.
import * as THREE from "three";

const live = new Map(); // root -> { t, dur, from, to, done, meshes, mine }
// (each source material keeps its copies for the next fade instead of freeing them: a freed copy let its
// see-through shader program go, so every animal-tier, LOD or room swap linked one again on the spot, a
// 100-400 ms freeze while walking; the copies' programs are compiled ahead, warmFades)
const pool = new WeakMap(); // source material -> { free: [copies], ready: Set of kinds compiled, warming: Set }
let compiler = null;
const waiting = new Set();

function quietCopy(c, m) {
  // (Material.copy runs userData through JSON: textures in it were turned into PNG data URLs every time)
  const ud = m.userData;
  m.userData = {};
  try {
    if (c) c.copy(m);
    else c = m.clone();
  } finally {
    m.userData = ud;
  }
  // (clone() leaves out the shader hooks: the tint masks, weather and wind live there)
  c.onBeforeCompile = m.onBeforeCompile;
  if (m.customProgramCacheKey !== THREE.Material.prototype.customProgramCacheKey) c.customProgramCacheKey = m.customProgramCacheKey;
  c.transparent = true;
  // (a solid piece that shares its samples for its near or sight fade, libmat.js fadeKind: its copy blends only)
  if (c.alphaToCoverage && !(c.alphaTest > 0)) c.alphaToCoverage = false;
  c.depthWrite = true;
  c.userData = ud;
  return c;
}

function entry(m) {
  let e = pool.get(m);
  if (!e) {
    e = { free: [], ready: new Set(), warming: new Set() };
    pool.set(m, e);
    m.addEventListener("dispose", () => {
      for (const c of e.free) c.dispose();
      e.free.length = 0;
      pool.delete(m);
    });
  }
  return e;
}

function take(m) {
  const e = entry(m);
  return e.free.length ? quietCopy(e.free.pop(), m) : quietCopy(null, m);
}

function standIn(o, c) {
  let s = null;
  if (o.isInstancedMesh) {
    s = new THREE.InstancedMesh(o.geometry, c, 1);
    if (o.instanceColor) s.setColorAt(0, new THREE.Color(1, 1, 1));
  } else if (o.isSkinnedMesh) {
    s = new THREE.SkinnedMesh(o.geometry, c);
    s.bind(o.skeleton, o.bindMatrix);
  } else s = new THREE.Mesh(o.geometry, c);
  s.frustumCulled = false;
  s.morphTargetInfluences = o.morphTargetInfluences;
  return s;
}

// (a copy's program also depends on what draws it: skinned, instanced, coloured per instance, morphed)
// and which attributes its shape carries (a second UV set, tangents, colours with alpha)
const kindOf = (o) => {
  const g = o.geometry;
  const c = g.attributes.color;
  return `${o.isSkinnedMesh ? "s" : o.isInstancedMesh ? (o.instanceColor ? "ic" : "i") : "m"}${o.morphTargetInfluences ? "+" : ""}|${g.attributes.uv1 ? 1 : 0}${g.attributes.uv2 ? 1 : 0}${g.attributes.tangent ? 1 : 0}${c && c.itemSize === 4 ? 1 : 0}`;
};

// the see-through copies of everything under roots, compiled ahead (in the background, in parallel) by
// compile(group) -> Promise (the island's own warm-up for the picture's render target)
export function warmFades(roots) {
  if (!compiler) {
    for (const r of roots) r && waiting.add(r);
    return Promise.resolve();
  }
  const g = new THREE.Group();
  const es = [];
  for (const r of roots) {
    if (!r) continue;
    for (const [o, m] of meshesOf(r)) {
      const e = entry(m);
      const k = kindOf(o);
      if (e.ready.has(k) || e.warming.has(k)) continue;
      e.warming.add(k);
      if (!e.free.length) e.free.push(quietCopy(null, m));
      g.add(standIn(o, e.free[e.free.length - 1]));
      // (and its own look: a pet's tinted kit parts were first drawn, and linked, as it walked into view)
      g.add(standIn(o, m));
      es.push([e, k]);
    }
  }
  if (!g.children.length) return Promise.resolve();
  g.updateMatrixWorld(true);
  const done = () => {
    for (const [e, k] of es) {
      e.ready.add(k);
      e.warming.delete(k);
    }
  };
  return Promise.resolve()
    .then(() => compiler(g))
    .then(done, done);
}

// (when the island closes: the compiler is the old island's, and with it the whole old island stayed alive)
export function resetFades() {
  compiler = null;
  live.clear();
  waiting.clear();
}

export function setFadeCompiler(fn) {
  compiler = fn;
  if (waiting.size) {
    const rs = [...waiting];
    waiting.clear();
    warmFades(rs);
  }
}

function meshesOf(root) {
  const out = [];
  root.traverse((o) => {
    if (!o.isMesh || !o.material || Array.isArray(o.material)) return;
    const m = o.material;
    // (only plain opaque surfaces: glass, glows, additive halos and cut-out cards keep their own way)
    if (m.transparent || m.alphaTest > 0 || m.blending !== THREE.NormalBlending || !("opacity" in m)) return;
    out.push([o, m]);
  });
  return out;
}

// fade root from opacity `from` to `to` over dur s; done() when finished (root stays as it is then)
export function fade(root, from, to, dur = 0.5, done = null) {
  if (!root) return;
  const prev = live.get(root);
  if (prev) finish(root, prev, false);
  const meshes = meshesOf(root);
  // (a copy whose shader is not compiled yet would be linked on the spot, freezing the frame: this
  // once the swap is a cut, and the copies are compiled for the next one)
  if (meshes.some(([o, m]) => !entry(m).ready.has(kindOf(o)))) {
    warmFades([root]);
    done?.();
    return;
  }
  const mine = new Map();
  for (const [o, m] of meshes) {
    if (!mine.has(m)) mine.set(m, take(m));
    const c = mine.get(m);
    c.opacity = from;
    o.material = c;
  }
  live.set(root, { t: 0, dur, from, to, done, meshes, mine });
}

function finish(root, f, call = true) {
  for (const [o, m] of f.meshes) if (o.material === f.mine.get(m)) o.material = m;
  for (const [m, c] of f.mine) {
    const e = pool.get(m);
    if (e) e.free.push(c);
    else c.dispose();
  }
  live.delete(root);
  if (call) f.done?.();
}

// once a frame
export function tickFades(dt) {
  for (const [root, f] of live) {
    f.t += dt;
    const k = Math.min(1, f.t / f.dur);
    const a = f.from + (f.to - f.from) * k;
    for (const c of f.mine.values()) c.opacity = a;
    if (k >= 1) finish(root, f);
  }
}

export const fading = (root) => live.has(root);
