// Where you really sit (TODO 15, user 2026-11-22: "i don't sit properly on the sofas and beanbags"): every seat's
// Blender-measured top (seat-anchors.json, assets/blender/furniture/seats/seat_anchors.py) and the sit clips' contact
// spheres (extras.contact, from the rig in w12_anim_avatar.py) give, for each body, the pose, the hip spot and the
// seat height: hips on the cushion (a little into a bean bag), back to the backrest, the legs clear of the cushion.
import A from "./seat-anchors.json";

const { U0, DU } = A.frame;
// seats that have no Blender furniture yet (the heart and weather places' benches, the bakery) are measured from what
// is drawn there, once, into the same record (island.js measureSeat)
export const SEAT_ANCHORS = A;

// the anchor of a seat (legacy seats by their interactable id, the cinema's loveseat by its key), the phone's own
// values where its furniture differs (lite: the phone tiers' _lite zones are in)
export function anchorFor(id, lite = false) {
  const a = A.seats[id] || A.extra.find((e) => e.key === id);
  if (!a) return null;
  return lite && a.lite ? { ...a, ...a.lite } : a;
}
export const extraSeats = (room) => A.extra.filter((e) => e.room === room && e.label);

const topAt = (a, u, T = a.top) => {
  const f = (u - U0) / DU;
  const i = Math.floor(f);
  const v0 = T[Math.max(0, Math.min(T.length - 1, i))];
  const v1 = T[Math.max(0, Math.min(T.length - 1, i + 1))];
  if (v0 == null && v1 == null) return -Infinity; // nothing modelled: the floor or open air
  const t = Math.max(0, Math.min(1, f - i));
  if (v0 == null) return t > 0.5 ? v1 : -Infinity; // (an edge: the nearer sample)
  if (v1 == null) return t <= 0.5 ? v0 : -Infinity;
  return v0 + (v1 - v0) * t;
};
// how far a sphere (u back from the front edge, y up, r) goes into the seat's top: > 0 inside
function into(T, a, u, y, r) {
  let d = -Infinity;
  for (const s of [-1, -0.6, -0.25, 0, 0.25, 0.6, 1]) {
    const du = s * r;
    d = Math.max(d, topAt(a, u + du, T) - (y - Math.sqrt(r * r - du * du)));
  }
  return d;
}
// how far a sphere may press in: wood none, upholstery a little, a bean bag gives
const SINK = [0.004, 0.02, 0.055];
// the contact spheres: 0 seat of the pants, 1 pelvis back, 2-3 back, 4 head, 5 thigh, 6 knee, 7 shin, 8 foot; the
// seat and the legs meet the top below the knees (low: a table over a chair's front is not in the way), the back
// and the head everything (top)
const LOW = [true, false, false, false, false, true, true, true, true];

// the lowest seat height (the clip's seat top; hips above it by the clip) with no sphere in the seat, root at u
// (and how high the seat of the pants alone would sit: more than that and something else props you up)
function lowest(a, C, k, u, tol) {
  let h = -Infinity;
  let own = -Infinity;
  for (let i = 0; i < C.length; i++) {
    const [z, y, r] = C[i];
    const need = into(LOW[i] && a.low ? a.low : a.top, a, u - z * k, y * k, r) - tol;
    if (i === 0) own = need;
    if (need > h) h = need;
  }
  return [h, own];
}
// a backrest: going back over the seat, the top rises 25 cm over it before the seat ends
function backOf(a) {
  for (let i = 0; i < a.top.length; i++) {
    const u = U0 + i * DU;
    if (u < 0.1) continue;
    const v = a.top[i];
    if (v == null || v < a.h - 0.15) return false;
    if (v > a.h + 0.25) return true;
  }
  return false;
}

// fit a body (k: its scale from the clips' rest) to a seat: { pose, u (root, metres back from the front edge), h }
// pose: "bench" (upright, knees over the front edge), "sofa" (back against the back, legs out along the cushion),
// "bag" (slouched into a bean bag)
export function fitSeat(a, contacts, k) {
  const soft = a.soft || 0;
  const tol = SINK[soft] ?? 0;
  const order = soft === 2 ? ["bag"] : ["bench", "sofa"];
  const hasBack = backOf(a);
  const L = a.low || a.top;
  let last = null;
  for (const pose of order) {
    const C = contacts[pose];
    if (!C) continue;
    const seat = C[0];
    // root positions from the front edge back; the deepest one whose seat of the pants still rests on the seat
    // (further back, the back or the head meets the backrest, or the shins the front edge, and it would be lifted)
    let best = null;
    let alt = null; // (none rests freely: the least propped-up spot, for a bean bag too small for a big body)
    const knee = C[6][0] * k;
    const cap = hasBack ? 1.2 : Math.max(0.05, knee - 0.03);
    for (let u = 0.02; u <= cap + 1e-6; u += 0.01) {
      const [h, own] = lowest(a, C, k, u, tol);
      const under = topAt(a, u - seat[0] * k, L);
      const gap = h - own; // the seat of the pants held off the cushion by something else
      if (under === -Infinity || under < a.h - 0.12) continue; // over the front edge or off the seat
      if (!alt || gap < alt.gap) alt = { pose, u, h, gap };
      if (gap > 0.012) {
        if (best) break;
        continue;
      }
      best = { pose, u, h };
      // a bean bag: the first spot (from its front) where the back lies on it; deeper, you'd perch on its crown
      if (pose === "bag" && backRest(a, C, k, u, h) < 0.03) break;
    }
    if (!best && pose === order[order.length - 1] && !last) best = alt;
    if (!best) continue;
    // with a backrest the back has to reach it (a gap: the upright pose leaves the legs too short for this seat)
    if (hasBack && pose !== "bag") {
      const gapBack = backGap(a, C, k, best.u, best.h);
      best.gapBack = gapBack;
      // (upright on a hard bench you may sit a hand off its back, knees over the edge; on a sofa or an armchair you
      // sink back into it)
      if (gapBack > (soft ? 0.05 : 0.16) && pose === "bench") {
        last = best;
        continue;
      }
    }
    return best;
  }
  return last;
}
// the room between the back (pelvis, back, head spheres) and what is behind it
function backGap(a, C, k, u, h) {
  let g = Infinity;
  for (const i of [1, 2, 3]) {
    const [z, y, r] = C[i];
    const uc = u - z * k;
    const yc = h + y * k;
    for (let d = 0; d < 0.6; d += 0.01) if (topAt(a, uc + r + d) > yc) {
      g = Math.min(g, d);
      break;
    }
  }
  return g;
}

// how far the back (the two back spheres) is off the surface under it (a reclined back lies on a bean bag's slope)
function backRest(a, C, k, u, h) {
  let g = Infinity;
  for (const i of [2, 3]) {
    const [z, y, r] = C[i];
    g = Math.min(g, -into(a.top, a, u - z * k, h + y * k, r));
  }
  return g;
}

// the world spot of a fitted seat: the front edge E (anchor f / l from the legacy spot) and u back from it
export function placeSeat(base, facing, a, u) {
  const fx = Math.sin(facing), fz = Math.cos(facing);
  const rx = Math.cos(facing), rz = -Math.sin(facing);
  const ex = base.x + fx * a.f + rx * a.l;
  const ez = base.z + fz * a.f + rz * a.l;
  return { x: ex - fx * u, z: ez - fz * u };
}
