// The far range's own runtime (sky race scenery pass, 2026-11-20): the sculpted zon_shell_far terrain drawn smooth,
// painted per pixel as soft pastel peaks (green foothills, sage, lilac-blue tops, snow caps, base mist; round 3,
// 2026-11-22) with a tiling detail map for gentle painterly variation; the arched falls with their streak / foam map scrolling downhill;
// and the soft cloud sea at its feet (2026-11-27), in the range's own air.
// The Blender zone binds the two materials by name through world.zoneMats (zones/runtime.js, its default case).
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { MeshoptDecoder } from "three/examples/jsm/libs/meshopt_decoder.module.js";
import { mergeGeometries, mergeVertices } from "three/examples/jsm/utils/BufferGeometryUtils.js";
import { waterOf, flowWater } from "./render/water.js";

// look.js hazeScenery sets onBeforeCompile / customProgramCacheKey itself: keep ours and run both.
// (one shared getter / setter pair for every material, reading the material's own userData.skyHooks: a getter closure
// defined per object sits in its hidden class, which the JS engine keeps for good, and would hold the old island after
// leaving it, as ee37f02c found for the live labels)
// (a clone's userData is a JSON copy, without the hooks: it then keeps three's defaults)
const noop = () => {};
const noKey = () => "";
function obcGet() {
  return this.userData.skyHooks?.run || noop;
}
function obcSet(fn) {
  if (this.userData.skyHooks) this.userData.skyHooks.extra = fn;
}
function keyGet() {
  return this.userData.skyHooks?.keyFn || noKey;
}
function keySet(fn) {
  if (this.userData.skyHooks) this.userData.skyHooks.extraKey = fn || null;
}
function composable(m, own, key, post) {
  const h = { extra: null, extraKey: null };
  h.run = (sh, r) => {
    own(sh, r);
    h.extra?.(sh, r);
    post?.(sh);
  };
  h.keyFn = () => key + "|" + (h.extraKey ? h.extraKey() : "");
  m.userData.skyHooks = h;
  Object.defineProperty(m, "onBeforeCompile", { get: obcGet, set: obcSet, configurable: true });
  Object.defineProperty(m, "customProgramCacheKey", { get: keyGet, set: keySet, configurable: true });
}

let loader = null;
export function skyLoader() {
  if (!loader) {
    loader = new GLTFLoader();
    loader.setMeshoptDecoder(MeshoptDecoder);
  }
  return loader;
}

export function skyRangeMaterials(world) {
  const base = world.zones?.base;
  if (!base || !world.zoneMats) return;
  const small = world.lowEnd;
  const tl = new THREE.TextureLoader();
  const tex = (name, repeat) => {
    const t = tl.load(base + "tex/" + name);
    t.colorSpace = THREE.SRGBColorSpace;
    if (repeat) t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.anisotropy = small ? 4 : 8;
    return t;
  };
  const det = tex(`T_sky_rockgrass_${small ? 256 : 512}.webp`, true);
  det.colorSpace = THREE.NoColorSpace; // (data: a light / shade modulation, not a colour)
  const terrain = new THREE.MeshStandardMaterial({ name: "MAT_far_terrain_soft", vertexColors: true, roughness: 0.95, metalness: 0, fog: false });
  composable(
    terrain,
    (sh) => {
      sh.uniforms.skyDet = { value: det };
      sh.vertexShader = sh.vertexShader
        .replace("#include <common>", "#include <common>\nvarying vec3 vSkyW;\nvarying vec3 vSkyN;")
        .replace("#include <worldpos_vertex>", "#include <worldpos_vertex>\nvSkyW = (modelMatrix * vec4(transformed, 1.0)).xyz;\nvSkyN = normalize(mat3(modelMatrix) * objectNormal);");
      sh.fragmentShader = sh.fragmentShader
        .replace("#include <common>", "#include <common>\nuniform sampler2D skyDet;\nvarying vec3 vSkyW;\nvarying vec3 vSkyN;")
        .replace(
          "#include <color_fragment>",
          `#include <color_fragment>
{ // painted per pixel (2026-11-22 round 3: soft, cozy pastel peaks; the vertices carry data: R light / AO, G forest floor, B haze)
  vec3 n = normalize(vSkyN); vec3 P = vSkyW; float slope = n.y;
  float macro = texture2D(skyDet, P.xz * 0.0035).b;
  float mid = texture2D(skyDet, P.xz * 0.016 + 0.37).b;
  float h = P.y + (macro - 0.6) * 22.0 + (mid - 0.6) * 8.0;
  // a smooth painterly climb: fresh green foothills, soft meadow, sage, then lilac-blue peaks
  vec3 cLow = pow(vec3(0.44, 0.75, 0.42), vec3(2.2)), cMeadow = pow(vec3(0.58, 0.82, 0.46), vec3(2.2));
  vec3 cSage = pow(vec3(0.58, 0.76, 0.58), vec3(2.2)), cPeak = pow(vec3(0.63, 0.62, 0.86), vec3(2.2));
  vec3 cSteep = pow(vec3(0.56, 0.59, 0.84), vec3(2.2)), cSnow = pow(vec3(0.99, 0.97, 1.0), vec3(2.2));
  vec3 col = mix(cLow, cMeadow, smoothstep(-45.0, 15.0, h));
  col = mix(col, cSage, smoothstep(20.0, 62.0, h));
  col = mix(col, cPeak, smoothstep(52.0, 100.0, h));
  // the steeper flanks lean periwinkle (soft, never rock)
  col = mix(col, cSteep, (1.0 - smoothstep(0.5, 0.82, slope)) * smoothstep(5.0, 60.0, h) * 0.55);
  // soft snow caps on the tallest peaks, a gently wavering line, lower on the gentle crowns
  float line = 100.0 + (mid - 0.6) * 14.0 + (1.0 - slope) * 20.0;
  float snow = smoothstep(line, line + 9.0, P.y + (macro - 0.6) * 10.0);
  col = mix(col, cSnow, snow);
  float rockM = step(0.98, vColor.g) * step(0.98, vColor.b);   // the rounded outcrops (G = B = 1)
  float grassy = (1.0 - smoothstep(55.0, 95.0, h)) * (1.0 - snow) * (1.0 - rockM);
  // tone: lighter crests, deeper gullies (the baked light), sunny dabs and cool hollows in the grass
  float cav = 1.0 - smoothstep(0.72, 0.97, vColor.r);
  col = mix(col, col * vec3(0.74, 0.86, 0.84), cav * 0.85 * (1.0 - snow));
  col = mix(col, col * vec3(1.12, 1.1, 0.92), smoothstep(0.96, 1.0, vColor.r) * smoothstep(0.75, 0.95, slope) * grassy);
  float dab = texture2D(skyDet, P.xz * 0.045 + 0.13).g;
  col = mix(col, col * mix(vec3(0.86, 0.94, 0.9), vec3(1.1, 1.08, 0.94), smoothstep(0.5, 0.7, dab)), grassy * 0.8);
  // meadow-flower patches on the low gentle slopes (pink, cream, butter), soft dabs at range distance
  float patchM = smoothstep(0.58, 0.64, texture2D(skyDet, P.xz * 0.011 + 0.52).b) * smoothstep(0.8, 0.92, slope) * (1.0 - smoothstep(25.0, 55.0, h));
  float dots = smoothstep(0.6, 0.7, texture2D(skyDet, P.xz * 0.27).g);
  float hue = texture2D(skyDet, P.xz * 0.06 + 0.8).b;
  vec3 flower = hue < 0.55 ? pow(vec3(0.98, 0.72, 0.84), vec3(2.2)) : (hue < 0.68 ? pow(vec3(1.0, 0.96, 0.86), vec3(2.2)) : pow(vec3(1.0, 0.9, 0.55), vec3(2.2)));
  col = mix(col, flower, patchM * (0.35 + 0.55 * dots) * (1.0 - vColor.g) * grassy);
  // forest floor, a breath of painterly variation
  col = mix(col, pow(vec3(0.34, 0.6, 0.4), vec3(2.2)), vColor.g * 0.5 * (1.0 - snow) * (1.0 - rockM));
  col *= (0.93 + 0.14 * (mid - 0.55)) * (0.94 + 0.16 * (macro - 0.55) * (1.0 - snow));
  // the outcrops: soft warm stone, lighter on top, a little moss low down
  vec3 stone = mix(pow(vec3(0.70, 0.66, 0.74), vec3(2.2)), pow(vec3(0.88, 0.84, 0.86), vec3(2.2)), smoothstep(0.85, 1.0, vColor.r));
  stone = mix(stone, pow(vec3(0.55, 0.72, 0.5), vec3(2.2)), (1.0 - smoothstep(0.78, 0.86, vColor.r)) * 0.5);
  col = mix(col, stone * (0.92 + 0.16 * (mid - 0.5)), rockM);
  col *= mix(0.6 + 0.4 * vColor.r, 1.0, rockM);
  // atmosphere: the back layers fade lilac-blue, a soft mist at the base
  col = mix(col, pow(vec3(0.80, 0.82, 0.94), vec3(2.2)), vColor.b * 0.32 * (1.0 - rockM));
  float mist = 1.0 - smoothstep(-66.0, -22.0, P.y + (mid - 0.6) * 14.0);
  col = mix(col, pow(vec3(0.93, 0.92, 0.98), vec3(2.2)), mist * 0.65);
  diffuseColor.rgb = col;
}`,
        );
    },
    "skyTerrain",
    // (the look pass's distance haze at half strength here: the range paints its own layered haze and base mist)
    (sh) => (sh.fragmentShader = sh.fragmentShader.replace("lookHaze.a * smoothstep", "lookHaze.a * 0.5 * smoothstep")),
  );
  const falls = tex(`T_sky_falls_${small ? 128 : 256}.webp`, true);
  const fallMat = new THREE.MeshStandardMaterial({ name: "MAT_far_falls", map: falls, transparent: true, depthWrite: false, side: THREE.DoubleSide, fog: false, roughness: 0.3, metalness: 0, emissive: "#ffffff", emissiveMap: falls, emissiveIntensity: 0.35 });
  world.zoneMats.MAT_far_terrain_soft = terrain;
  // (TODO 37: real running water, render/water.js)
  world.zoneMats.MAT_far_falls = flowWater(fallMat, waterOf(world), { speed: 0.5, strength: 1 });
  world.animated.push((t, dt = 0.016) => {
    falls.offset.y += dt * 0.5; // the streaks run downhill (glTF turns v over: it grows uphill here)
  });
}

// The range's atmosphere on its trees and clouds (2026-11-27): the same layered lilac haze toward the back and the soft
// mist at the base that the terrain paints (above), from the world position, so a tree takes the colour of the slope it
// stands on instead of standing out dark and crisp on a hazy pastel slope; `lift` leans the tops toward the range's
// sage and lilac as they climb (trees only)
function rangeAir(m, key, haze, lift, soft = false) {
  composable(
    m,
    (sh) => {
      // (soft: the phone's coarser cloud heaps light from normals bent toward the sky, so their facets never read as
      //  planes of rock; the white-to-lilac paint by height gives them their form)
      if (soft) sh.vertexShader = sh.vertexShader.replace("#include <beginnormal_vertex>", "#include <beginnormal_vertex>\nobjectNormal = normalize(objectNormal + vec3(0.0, 0.8, 0.0));");
      sh.vertexShader = sh.vertexShader.replace("#include <common>", "#include <common>\nvarying vec3 vAirW;").replace(
        "#include <worldpos_vertex>",
        `#include <worldpos_vertex>
#ifdef USE_INSTANCING
vAirW = (modelMatrix * instanceMatrix * vec4(transformed, 1.0)).xyz;
#else
vAirW = (modelMatrix * vec4(transformed, 1.0)).xyz;
#endif`,
      );
      sh.fragmentShader = sh.fragmentShader.replace("#include <common>", "#include <common>\nvarying vec3 vAirW;").replace(
        "#include <color_fragment>",
        `#include <color_fragment>
{ vec3 P = vAirW; float r = length(P.xz);
  ${lift ? "diffuseColor.rgb = mix(diffuseColor.rgb, diffuseColor.rgb * vec3(0.93, 1.0, 1.1) + pow(vec3(0.58, 0.62, 0.8), vec3(2.2)) * 0.12, smoothstep(0.0, 60.0, P.y) * 0.6);" : ""}
  float hz = min(1.0, min(0.3, max(0.0, (-35.0 - P.y) / 120.0)) / 0.3 * 0.4 + smoothstep(250.0, 364.0, r) * 0.6);
  diffuseColor.rgb = mix(diffuseColor.rgb, pow(vec3(0.80, 0.82, 0.94), vec3(2.2)), hz * 0.32);
  diffuseColor.rgb = mix(diffuseColor.rgb, pow(vec3(0.93, 0.92, 0.98), vec3(2.2)), (1.0 - smoothstep(-66.0, -22.0, P.y)) * ${lift ? "0.65" : "0.3"});
}`,
      );
    },
    key,
    // (the look pass's distance haze at half strength, as on the terrain)
    (sh) => (sh.fragmentShader = sh.fragmentShader.replace("lookHaze.a * smoothstep", "lookHaze.a * 0.5 * smoothstep")),
  );
  if (haze) {
    const g = new THREE.Group();
    g.add(new THREE.InstancedMesh(new THREE.BufferGeometry(), m, 1));
    haze(g);
  }
}

// every mesh of a loaded GLB in one geometry, in its own frame (the exporter splits a wide asset into cells)
function oneGeometry(gl) {
  const parts = [];
  gl.scene.updateMatrixWorld(true);
  gl.scene.traverse((o) => o.isMesh && parts.push(o.geometry.clone().applyMatrix4(o.matrixWorld)));
  if (parts.length < 2) return parts[0] || null;
  const keep = Object.keys(parts[0].attributes).filter((k) => parts.every((g) => g.attributes[k]));
  for (const g of parts) for (const k of Object.keys(g.attributes)) if (!keep.includes(k)) g.deleteAttribute(k);
  // (each cell came with its own normals: weld the cells back together and light it as one surface, no seam lines)
  const g = mergeGeometries(parts.map((p) => (p.index ? p.toNonIndexed() : p)), false);
  g.deleteAttribute("normal");
  const w = mergeVertices(g, 1e-3);
  w.computeVertexNormals();
  return w;
}

// the cloud sea the range rises out of (2026-11-27; the old faceted lumps read as grey rock): soft Blender heaps
// (sky_mtn.blend env_sky_seacloud_a/b) on sky_range.py's layout (zones/far_sea*.json: x, y, z, sx, sy, yaw, kind), in the
// theme's cloud colour (it follows the time of day), lit soft and a touch self-lit like the big cumulus, the range's air
export function skySea(world, small, haze = null) {
  const base = world.zones?.base;
  if (!base) return;
  fetch(base + `zones/far_sea${small ? "_lite" : ""}.json`)
    .then((r) => (r.ok ? r.json() : null))
    .catch(() => null)
    .then((rows) => {
      if (!Array.isArray(rows) || !rows.length) return;
      const mat = new THREE.MeshStandardMaterial({ name: "MAT_sky_sea", vertexColors: true, roughness: 1, metalness: 0, emissive: "#ffffff", emissiveIntensity: 0.16, fog: false });
      if (world.cloudMat) mat.color = world.cloudMat.color; // (shared: the theme / night tint follows)
      rangeAir(mat, small ? "skySeaSoft" : "skySea", haze, false, small);
      ["a", "b"].forEach((v, kind) => {
        const mine = rows.filter((r) => r[6] === kind);
        if (!mine.length) return;
        skyLoader().load(base + `sky/env_sky_seacloud_${v}${small ? "_lite" : ""}.glb`, (gl) => {
          const geo = oneGeometry(gl);
          if (!geo) return;
          const im = new THREE.InstancedMesh(geo, mat, mine.length);
          const m = new THREE.Matrix4(), q = new THREE.Quaternion(), p = new THREE.Vector3(), s = new THREE.Vector3(), up = new THREE.Vector3(0, 1, 0);
          mine.forEach(([x, y, z, sx, sy, yaw], i) => im.setMatrixAt(i, m.compose(p.set(x, y, z), q.setFromAxisAngle(up, yaw), s.set(sx, sy, sx))));
          im.computeBoundingSphere();
          im.castShadow = false;
          im.receiveShadow = false;
          im.name = "sky_far_sea_" + v;
          world.scene.add(im);
        });
      });
    });
}
