// The local zones (Waves 3 and 4): which files each one is, where it stands (for streaming by
// proximity), and the little wiring each needs once it is in. Their gameplay, runtime pieces and
// legacy builders are untouched (zones/sink.js says what of the legacy look leaves).
import * as THREE from "three";
import { withSurfaceMap } from "../textures.js";
import { datesBoard, isDatesBoard } from "../datesboards.js";

export function localZones(world, small) {
  const room = (id) => world.rooms.get(id)?.group.position;
  // (phones: the zone's own phone tier, zones/zon_phone_lite_build.py: a decimated LOD0 / LOD1 / LOD2 family, when the
  // pack carries it; zones/runtime.js streamLocal falls back to the computers' files otherwise)
  const phoneLite = (z) => (small ? [`${z}_lite.glb`, `${z}_lite_raw.glb`, `${z}_lite_lod.glb`] : null);
  return [
    { id: "bakery", files: ["zon_bakery.glb", "zon_bakery_raw.glb"], lite: phoneLite("zon_bakery"), at: room("bakery") },
    { id: "stall", files: ["zon_bakery_stall.glb"], lite: phoneLite("zon_bakery_stall"), at: room("stall") },
    { id: "garden", files: small ? ["zon_garden_lite.glb", "zon_garden_lite_raw.glb"] : ["zon_garden.glb", "zon_garden_raw.glb"], at: room("garden") },
    { id: "farm", files: ["zon_farm.glb", "zon_farm_raw.glb"], lite: phoneLite("zon_farm"), at: room("farm") },
    { id: "lake", files: ["zon_lake.glb", "zon_lake_raw.glb"], at: room("lake") },
    { id: "chill", files: ["zon_lake_chill.glb", "zon_lake_chill_raw.glb"], at: room("chill") },
    { id: "swings", files: ["zon_lake_swings.glb", "zon_lake_swings_raw.glb"], at: room("swings") },
    { id: "picnic", files: ["zon_lake_picnic.glb"], at: world.picnic?.position },
    // Wave 7 games: the sky trail out past the fence, and the games (pitch, moles, signs)
    { id: "trail", files: ["zon_trail.glb", "zon_trail_raw.glb"], at: world.zoneAt?.trail },
    { id: "games", files: ["zon_games.glb", "zon_games_raw.glb"], at: world.zoneAt?.games },
    // Wave 7 rides: the coaster (its train stays coaster.js's) and the race road round the island
    { id: "coaster", files: small ? ["zon_coaster_lite.glb", "zon_coaster_lite_raw.glb"] : ["zon_coaster.glb", "zon_coaster_raw.glb"], at: world.coasterSpot },
    { id: "race", files: small ? ["zon_race_lite.glb", "zon_race_lite_raw.glb"] : ["zon_race.glb", "zon_race_raw.glb"], at: new THREE.Vector3(0, 0, 79.6) },
    // Wave 6: the balloon station, the cinema, the lookout (its crowns and roof are their own zones,
    // hidden as you climb / stand on top, as legacy)
    { id: "balloon", files: ["zon_balloon.glb", "zon_balloon_raw.glb"], at: room("balloon") },
    { id: "cinema", files: ["zon_cinema.glb", "zon_cinema_raw.glb"], lite: phoneLite("zon_cinema"), at: room("cinema") },
    { id: "lookout", lite: small ? ["zon_lookout_lite.glb", "zon_lookout_leaves_lite.glb", "zon_lookout_leaves_lite_raw.glb", "zon_lookout_roof.glb", "zon_lookout_lite_lod.glb"] : null, files: ["zon_lookout.glb", small ? "zon_lookout_leaves_lite.glb" : "zon_lookout_leaves.glb", small ? "zon_lookout_leaves_lite_raw.glb" : "zon_lookout_leaves_raw.glb", "zon_lookout_roof.glb"], at: room("lookout") },
    // the diary ring (Wave 2a): the 9 houses and 3 outdoor places; their insides stay legacy
    // (and, since the leftovers pass, the heart place and the photo wall)
    ...["song", "note", "photos", "calendar", "poems", "gift", "art", "diary", "weather", "wishlist", "discord", "heart", "pinboard"].map((id) => ({
      id: `dr_${id}`,
      // (phones: the place's one _lite zone, pass 2; same colliders, sockets and interactables)
      files: small ? [`zon_diaryring_${id}_lite.glb`] : [`zon_diaryring_${id}.glb`, `zon_diaryring_${id}_raw.glb`],
      at: room(id),
      ring: true,
    })),
    // the rooms' insides (Wave 8): each one streams in once you are within 55 m of it (the legacy
    // furnish distance), so a door never shows an empty room; phones stream only the room you are at
    // (zones/runtime.js), as its _lite zone: the flat phone floor and rug (art pass 3 room floors)
    ...["diary", "song", "note", "photos", "calendar", "poems", "gift", "art", "bakery"].map((id) => ({
      id: `rm_${id}`,
      files: small ? (id === "bakery" ? ["zon_room_bakery_lite.glb"] : [`zon_room_${id}_lite.glb`, `zon_room_${id}_lite_raw.glb`]) : id === "bakery" ? ["zon_room_bakery.glb"] : [`zon_room_${id}.glb`, `zon_room_${id}_raw.glb`],
      at: room(id),
      ring: true,
      near: 55,
      room: id,
    })),
    // (phones draw the ring's _lite zones, each hidden beyond its cull_m, 60 m: zones/runtime.js)
  ].filter((z) => z.at);
}

// nodes the legacy runtime still draws itself (its own animals, plants, fire, swinging seats):
// the zone's copies of them stay hidden
const HIDE = {
  coaster: /^(INST_|HIT_)/,
  // (the moving pad, star, ring, moles, dummies and flags are the legacy pieces, kept)
  trail: /^(ANIM_|INST_|HIT_)/,
  // (the moles and straw dummies are the zone's, riding the legacy groups: bindGames)
  games: /^(ANIM_(?!act_games_(mole|dummy))|INST_|HIT_)/,
  race: /^(INST_|HIT_)/,
  // (Wave 6: what moves, blinks or is tapped stays the legacy piece, zones/sink.js motion test)
  balloon: /^(ANIM_|INST_|HIT_)/,
  cinema: /^(ANIM_|INST_|HIT_)/,
  lookout: /^(ANIM_|INST_|HIT_)/,
  // (the diary ring: every moving part is the legacy piece, which stays: zones/sink.js motion)
  ...Object.fromEntries(["song", "note", "photos", "calendar", "poems", "gift", "art", "diary", "weather", "wishlist", "discord", "heart", "pinboard"].map((id) => [`dr_${id}`, /^(ANIM_|INST_|HIT_)/])),
  // (the rooms: what moves, is tapped or shows live content is the legacy piece; the zone's
  // SCREEN_ planes stay hidden, the legacy screens are drawn and tapped where they stand)
  // (the bakery's chalk menu is no tap target: its zone plane shows the legacy canvas, as the signs do)
  ...Object.fromEntries(["diary", "song", "note", "photos", "calendar", "poems", "gift", "art", "bakery"].map((id) => [`rm_${id}`, id === "bakery" ? /^(ANIM_|INST_|HIT_)/ : /^(ANIM_|INST_|HIT_|SCREEN_)/])),
  garden: /^(ANIM_|INST_|SM_env_garden_(fountain_birdbody|pond_duckbody|pond_frogbody|pond_padleaf|potstack_pinwheel))/,
  swings: /^(ANIM_prp_lake_swing_|INST_)/,
  lake: /^(ANIM_|INST_)/,
  chill: /^INST_/,
  farm: /^INST_/,
  bakery: /^INST_/,
};

const UP = new THREE.Vector3(0, 1, 0);

// N: the zone's nodes by name; faces: the legacy canvas faces that just left (zones/sink.js)
export function wireLocal(id, { world, N, faces, anims, mats, root, renderer = null, scenes = [], files = [], consts = null }) {
  // the lookout: island.js hides lookoutTop.leaves while you climb and lookoutTop.hide up top; the
  // zone's crowns (files 1, 2) and roof (file 3) take their places
  if (id === "lookout" && world.lookoutTop) {
    const L = world.lookoutTop;
    const leaves = new THREE.Group();
    leaves.name = "lookout.leaves";
    root.add(leaves);
    scenes.forEach((s, i) => /leaves/.test(files[i]) && leaves.attach(s));
    leaves.visible = !L.faded;
    L.leaves = leaves;
    const roofs = scenes.filter((s, i) => /roof/.test(files[i]));
    for (const r of roofs) r.visible = !L.hidden;
    L.hide = roofs;
  }
  // explicit obstacle tops from the zone's export (no raycast against whatever is drawn yet)
  for (const [name, o] of N) {
    if (!/^COL_circ_/.test(name) || o.userData.tdd_top == null) continue;
    const p = new THREE.Vector3();
    o.getWorldPosition(p);
    const c = world.circles.find((q) => Math.abs(q.x - p.x) < 0.03 && Math.abs(q.z - p.z) < 0.03 && Math.abs(q.r - (o.userData.tdd_r ?? q.r)) < 0.02);
    if (c) c.top = o.userData.tdd_top;
  }
  const hide = HIDE[id];
  if (hide) for (const [name, o] of N) if (hide.test(name)) o.visible = false;
  if (id === "dr_calendar") clockHands(world, N, anims);
  // the pieces that move (a room's hanging ornaments, speakers, record, hourglass, present lid, bookstand page,
  // quill, fire; the two swing seats): the zone's ANIM_ twins ride the legacy pivots that move them, whose own
  // meshes then stop drawing (furniture pass 2026-11-20: no legacy look left on the furniture)
  if (/^rm_/.test(id) || id === "swings") rideAnims(world, id, N, anims);
  if (id === "rm_bakery") bakeryDecor(world, N, anims);
  // a room's inside (fur_room_<id>) brings its own wall lamps: the legacy ones go, now or when furnished
  if (/^rm_/.test(id)) {
    const rid = id.slice(3);
    (world.zoneLampRooms ||= new Set()).add(rid);
    for (const L of world.rooms.get(rid)?.wallLamps || []) L.lamp.visible = false;
  }
  // the signs and boards: each SCREEN_ plane shows the legacy canvas that stood nearest (its
  // material itself, so live redraws, the bakery's design or the chalk menu, carry on)
  const p = new THREE.Vector3();
  const live = [];
  const rm = /^rm_/.test(id);
  // (a see-through legacy sign is not a look the zone sinks, so it never reached `faces`: the board
  // then took whatever small canvas stood nearest, the coaster gate's "red blob" (user 2026-11-17d).
  // Those still-standing canvases are candidates too, and the shape has to fit: a wide board takes a
  // wide canvas)
  const standing = [];
  if (!rm || id === "rm_bakery")
    world.scene?.traverse((c) => {
      if (!c.isMesh || c.userData.item || !c.visible) return;
      const m = Array.isArray(c.material) ? null : c.material;
      if (!m?.transparent || !m.map?.isCanvasTexture || !m.map.image) return;
      for (let q = c.parent; q; q = q.parent) if (q.name === "zones") return;
      if (!c.geometry.boundingSphere) c.geometry.computeBoundingSphere();
      standing.push({ material: m, at: c.geometry.boundingSphere.center.clone().applyMatrix4(c.matrixWorld), mesh: c });
    });
  const aspectOf = (o) => {
    if (!o.geometry.boundingBox) o.geometry.computeBoundingBox();
    const s = o.geometry.boundingBox.getSize(new THREE.Vector3()).multiply(o.getWorldScale(new THREE.Vector3()));
    const d = [s.x, s.y, s.z].sort((a, b) => b - a);
    return d[1] > 1e-4 ? d[0] / d[1] : 1;
  };
  const fit = (o, f) => {
    const im = f.material.map?.image;
    if (!im?.width || !im?.height) return 0;
    const a = aspectOf(o), b = Math.max(im.width / im.height, im.height / im.width);
    return Math.abs(Math.log(a / b));
  };
  for (const [name, o] of N) {
    if ((rm && id !== "rm_bakery") || !/^SCREEN_/.test(name) || !o.isMesh) continue;
    // the dates tower's boards: days together and our anniversary countdown (datesboards.js), drawn live
    const dates = id === "dr_calendar" && name.match(/^SCREEN_calendar_date_([ab])/);
    if (dates) {
      o.material = datesBoard(dates[1]);
      o.castShadow = false;
      continue;
    }
    if (!o.geometry.boundingSphere) o.geometry.computeBoundingSphere();
    p.copy(o.geometry.boundingSphere.center).applyMatrix4(o.matrixWorld);
    let best = null;
    let bd = 3;
    for (const f of [...faces, ...standing]) {
      if (isDatesBoard(f.material)) continue;
      const d = f.at.distanceTo(p);
      if (d > 3) continue;
      const score = d + fit(o, f) * 1.5;
      if (score < bd) {
        bd = score;
        best = f;
      }
    }
    if (!best) {
      o.visible = false;
      continue;
    }
    // (the legacy board it now shows leaves: two copies in one place would fight)
    if (best.mesh) best.mesh.visible = false;
    o.material = best.material;
    o.castShadow = false;
    live.push(best.material);
  }
  // the bakery's menu board: its own live canvas, by name. The nearest-canvas match only finds it the first
  // time the room streams in (the legacy board then leaves for good): a phone frees the room when you walk off
  // and streams it back later, and the board came back black (user: "the board in the bakery is empty")
  if (id === "rm_bakery") {
    const menu = world.rooms.get("bakery")?.bakery?.menu;
    for (const [name, o] of N)
      if (/^SCREEN_fur_bk_menu/.test(name) && o.isMesh && menu?.mat) {
        o.material = menu.mat;
        o.visible = true;
        o.castShadow = false;
        if (!live.includes(menu.mat)) live.push(menu.mat);
      }
  }
  // (glTF UVs: a canvas drawn the legacy way shows upright with flipY off; redrawn maps too)
  const fix = () => {
    for (const m of live)
      if (m.map && m.map.flipY) {
        // (a phone's painted pixels are let go once uploaded, textures.js: flipped in its UVs instead of sent again)
        if (m.map.userData.dropped) {
          if (!m.map.userData.uvFlipped) {
            m.map.userData.uvFlipped = true;
            m.map.repeat.y *= -1;
            m.map.offset.y = 1 - m.map.offset.y;
          }
          continue;
        }
        m.map.flipY = false;
        m.map.needsUpdate = true;
      }
  };
  fix();
  if (live.length) anims.push(fix);

  if (rm) wireRoom(id.slice(3), { world, N, anims, mats });
  if (id === "games" || id === "trail") {
    // a sign whose front face is tapped (bonk-a-mole, catch the bunnies...) kept its legacy screen
    // (an item hit) at the very spot of the zone's front plane: the zone plane takes over the tap
    // and the legacy face hides, so the two never fight and the canvas shows the zone's way up
    const legacy = [];
    world.scene?.traverse((o) => o.isMesh && o.userData.item && live.includes(o.material) && legacy.push(o));
    const q = new THREE.Vector3();
    for (const [name, o] of N) {
      if (!/^SCREEN_.*front/.test(name) || !o.isMesh || !o.visible) continue;
      p.copy(o.geometry.boundingSphere.center).applyMatrix4(o.matrixWorld);
      for (const l of legacy) {
        if (l.material !== o.material) continue;
        if (!l.geometry.boundingSphere) l.geometry.computeBoundingSphere();
        if (q.copy(l.geometry.boundingSphere.center).applyMatrix4(l.matrixWorld).distanceTo(p) > 0.3) continue;
        o.userData.item = l.userData.item;
        if (Array.isArray(l.userData.item.hits)) l.userData.item.hits.push(o);
        l.visible = false;
      }
    }
    applyConstants(id, world, N, consts);
    if (id === "games") bindGames(world, N);
  }
  // the cinema's rug (2026-11-22): the rooms' fabric material (floorMat), crisp at any distance
  if (id === "cinema")
    for (const [, o] of N) {
      if (!o.isMesh) continue;
      const fm = floorMat((o.material?.name || "").replace(/\.\d+$/, ""));
      if (fm) o.material = fm;
    }
  if (id === "bakery") {
    // the porch (2026-11-22): modelled in vertex colours on the rooms' wood / paint / cloth materials (floorMat)
    for (const [, o] of N) {
      if (!o.isMesh) continue;
      const fm = floorMat((o.material?.name || "").replace(/\.\d+$/, ""));
      if (fm) o.material = fm;
    }
    const bk = world.rooms.get("bakery")?.bakery;
    const M = bk?.mats || {};
    // the neon name over the door and the chalk menu: their own legacy materials, by name (the
    // nearest-canvas match took the wrong face for the sign, pilot review bug 3)
    for (const [re, m] of [[/^SCREEN_bld_bakery_shell_sign/, M.sign], [/^SCREEN_bld_bakery_aframe_chalk/, M.chalk]])
      for (const [name, o] of N)
        if (re.test(name) && o.isMesh && m) {
          o.material = m;
          o.visible = true;
          if (!live.includes(m)) live.push(m);
        }
    fix();
    // the design floor stops at the walls and the door sill: the zone's floor reached out through the
    // doorway onto the path (the red checker outside the door, the user's report 2026-11-16)
    // (the floor's corners are moved in to the inside faces of the walls, its UVs following, so the
    // picture keeps its scale; no clipping planes, no extra shader)
    const room = world.rooms.get("bakery");
    let floorUvPerM = 0;
    if (room && M.floor) {
      void renderer;
      room.group.updateMatrixWorld(true);
      const HW = 7, HD = 5; // (bakery.js W / 2, D / 2)
      for (const [name, o] of N) if (/bakery_floor/.test(name) && o.isMesh && o.material === M.floor) floorUvPerM = cropToRoom(o, room.group, HW, HD) || floorUvPerM;
    }
    const tints = mats.kitTints?.get("bakery");
    // the awning's design colours on the kit's tint mask (paint = stripe a, trim = stripe b);
    // the paper and floor tile in metres on the zone's UVs
    anims.push(() => {
      if (tints && M.scallopA) {
        tints[0].copy(M.scallopA.color);
        tints[1].copy(M.scallopB.color);
      }
      for (const m of [M.paper, M.floor]) {
        const t = m?.map;
        // (the paper's zone UVs are in tiles already; the floor's are not: its checker keeps the
        // legacy size, two squares every 1.4 m, from how many UV units the floor gives a metre)
        const r = m === M.floor && floorUvPerM ? 1 / (1.4 * floorUvPerM) : 1;
        if (t && (t.wrapS !== THREE.RepeatWrapping || Math.abs(t.repeat.x - r) > 1e-4 || Math.abs(t.repeat.y - r) > 1e-4)) {
          // (only a new wrap needs the picture sent again; the repeat is a uniform. A phone's painted pixels
          // are gone once sent, textures.js: sent again, the bakery's floor and paper came out black)
          if ((t.wrapS !== THREE.RepeatWrapping || t.wrapT !== THREE.RepeatWrapping) && !t.userData.dropped) {
            t.wrapS = t.wrapT = THREE.RepeatWrapping;
            t.needsUpdate = true;
          }
          t.repeat.set(r, r);
        }
      }
    });
    // the big cinnamon roll on the roof, swaying (legacy: sin .6t x .15, bob sin 1.2t x .12)
    const roll = N.get("ANIM_bld_bakery_roll_sway__0");
    if (roll) {
      root.attach(roll);
      const q0 = roll.quaternion.clone();
      const p0 = roll.position.clone();
      const z = new THREE.Vector3(0, 0, 1);
      const q = new THREE.Quaternion();
      anims.push((t) => {
        roll.quaternion.copy(q0).multiply(q.setFromAxisAngle(z, Math.sin(t * 0.6) * 0.15));
        roll.position.copy(p0).setY(p0.y + Math.sin(t * 1.2) * 0.12);
      });
    }
  }
  if (id === "coaster") {
    // the six balloons on the entrance arch (TODO 17: they glitched): the zone's Blender balloons stood still while the
    // legacy ones, kept because they move, bobbed through them in the same spots. Now the zone's bob as the legacy did
    // (y = by + sin(1.4 t + i + sx) * .06, sx -1.15 left / 1.15 right) with a slow sway on the string, and the legacy
    // balloons stop drawing
    const q = new THREE.Quaternion();
    const e = new THREE.Euler();
    const bs = [];
    for (const [name, o] of N) {
      const m = name.match(/^ANIM_act_coaster_station_balloon_([lr])(\d)/);
      if (!m) continue;
      root.attach(o);
      bs.push({ b: o, p: o.position.clone(), q: o.quaternion.clone(), ph: +m[2] + (m[1] === "l" ? -1.15 : 1.15) });
    }
    if (bs.length) {
      for (const b of world.coasterBalloons || []) b.visible = false;
      anims.push((t) => {
        for (const r of bs) {
          r.b.position.copy(r.p).setY(r.p.y + Math.sin(t * 1.4 + r.ph) * 0.06);
          r.b.quaternion.copy(r.q).multiply(q.setFromEuler(e.set(Math.sin(t * 0.9 + r.ph) * 0.06, Math.sin(t * 0.5 + r.ph) * 0.3, Math.sin(t * 0.7 + r.ph) * 0.07)));
        }
      });
    }
  }
  if (id === "picnic") {
    // the three heart balloons on the basket, bobbing as legacy (lowest = k 0)
    const bs = [...N].filter(([n]) => /^ANIM_prp_lake_picnic_balloon/.test(n)).map(([, o]) => o);
    bs.sort((a, b) => a.getWorldPosition(p).y - b.getWorldPosition(new THREE.Vector3()).y);
    const q = new THREE.Quaternion();
    const rest = bs.map((b) => {
      root.attach(b);
      return { b, p: b.position.clone(), q: b.quaternion.clone() };
    });
    anims.push((t) => {
      rest.forEach((r, k) => {
        r.b.position.copy(r.p).setY(r.p.y + Math.sin(t * 1.2 + k) * 0.07);
        r.b.quaternion.copy(r.q).multiply(q.setFromAxisAngle(UP, Math.sin(t * 0.5 + k) * 0.5));
      });
    });
  }
}

// the dates tower's clock (TODO 9, user: "the clock here isnt working"): the legacy hands left with the zone's
// motion test (over its two samples a minute hand looks still) while the zone's own were hidden as legacy-driven,
// so the face stood blank. The Blender hands now show the live local time, sweeping smoothly; any legacy hand
// still standing goes, so there are never two sets
function clockHands(world, N, anims) {
  const hands = [];
  for (const [name, o] of N) {
    const m = name.match(/^ANIM_bld_calendar(?:_lite)?_hand_(hour|min|sec)__\d+$/);
    if (!m) continue;
    o.visible = true;
    hands.push({ o, kind: m[1], q0: o.quaternion.clone() });
  }
  if (!hands.length) return;
  world.rooms.get("calendar")?.group?.traverse((c) => c.userData.clockHand && (c.visible = false));
  const q = new THREE.Quaternion();
  const Z = new THREE.Vector3(0, 0, 1);
  anims.push(() => {
    const d = new Date();
    const s = d.getSeconds() + d.getMilliseconds() / 1000;
    const mi = d.getMinutes() + s / 60;
    const h = (d.getHours() % 12) + mi / 60;
    for (const H of hands) {
      const turns = H.kind === "sec" ? s / 60 : H.kind === "min" ? mi / 60 : h / 12;
      H.o.quaternion.copy(H.q0).multiply(q.setFromAxisAngle(Z, -turns * Math.PI * 2));
    }
  });
}

// a zone's ANIM_ nodes onto the legacy pieces that move: each joins the nearest legacy pivot that moves, at the pose
// the zone was exported in (the layout snapshot ran every room animation once, at t = 0), and the pivot's own
// meshes stop drawing. Taps and colliders are untouched (a raycast still hits hidden meshes; colliders are data).
// the bakery's design-toggled decor (plants, balloons, the cats' basket) and the neon heart: the room zone models
// them (ANIM_fur_bk_*), but nothing moves them by a room clock, so rideAnims left them hidden and the legacy faceted
// look stayed (the user's "old cactus", 2026-11-22). Each zone piece now shows with its legacy design group (the
// toggles in the design menu), bobs / pulses as the legacy did, and the legacy meshes stop drawing.
function bakeryDecor(world, N, anims) {
  const bk = world.rooms.get("bakery")?.bakery;
  if (!bk) return;
  const d = bk.decor || {};
  const groupOf = (n) => (/_plant_/.test(n) ? d.plants : /_balloon_/.test(n) ? d.balloons : /_basket_/.test(n) ? d.cats : /_neon_heart_/.test(n) ? true : null);
  let n = 0;
  for (const [name, z] of N) {
    if (!/^ANIM_fur_bk_/.test(name) || z.userData.zoneLive) continue;
    const g = groupOf(name);
    if (!g) continue;
    z.traverse((c) => (c.visible = true));
    z.userData.zoneLive = true;
    n++;
    const s0 = z.scale.clone();
    const y0 = z.position.y;
    const bi = Number(/_balloon_(\d+)_/.exec(name)?.[1] ?? -1);
    if (g === true && bk.neonHeart) bk.neonHeart.visible = false;
    anims.push((t) => {
      if (g !== true) z.visible = g.visible;
      if (g === true) z.scale.copy(s0).multiplyScalar(1 + Math.max(0, Math.sin(t * 2.4)) * 0.06);
      else if (bi >= 0) z.position.y = y0 + Math.sin(t * 1.4 + bi) * 0.06;
      else return;
      z.updateMatrix();
      z.matrixWorldNeedsUpdate = true;
    });
  }
  if (!n) return;
  for (const o of bk.basketLook || []) if (o.isMesh) o.visible = false;
  // (each decor group merges its still pieces a moment after it is built, bakery.js: hidden again when that lands)
  const looks = [d.plants, d.balloons].filter(Boolean);
  const seen = looks.map(() => -1);
  anims.push(() =>
    looks.forEach((g, i) => {
      if (seen[i] === g.children.length) return;
      seen[i] = g.children.length;
      g.traverse((c) => c.isMesh && (c.visible = false));
    }),
  );
}

function rideAnims(world, id, N, anims) {
  const swings = id === "swings";
  const room = world.rooms.get(swings ? "swings" : id.slice(3));
  if (!room) return;
  const fns = (world.animated || []).filter((f) => f.__room === room);
  const run = (t) => {
    for (const f of fns)
      try {
        f(t, 0.016);
      } catch {}
  };
  const key = (o) => [o.position.x, o.position.y, o.position.z, o.quaternion.x, o.quaternion.y, o.quaternion.z, o.quaternion.w, o.scale.x, o.scale.y, o.scale.z].map((v) => v.toFixed(5)).join();
  const zoneNode = (o) => {
    for (let q = o; q; q = q.parent) if (q.name === "zones") return true;
    return false;
  };
  const hasMesh = (o) => {
    let m = false;
    o.traverse((c) => (m ||= c.isMesh && !zoneNode(c)));
    return m;
  };
  let tops;
  const arms = swings ? (world.swings || []).map((s) => s.arm) : null;
  if (swings) {
    // (the swing physics turns each arm about its bough: at rest it hangs straight)
    for (const a of arms) a.rotation.set(0, 0, 0);
    tops = arms;
  } else {
    // (what moves: its pose at two moments differs; the top-most moving object of each piece)
    const at = new Map();
    run(0.731);
    room.group.traverse((o) => at.set(o, key(o)));
    run(2.417);
    const moving = new Set();
    room.group.traverse((o) => !zoneNode(o) && at.get(o) !== key(o) && moving.add(o));
    tops = [...moving].filter((o) => !moving.has(o.parent) && hasMesh(o));
    run(0);
  }
  room.group.updateMatrixWorld(true);
  const p = new THREE.Vector3();
  const q = new THREE.Vector3();
  const used = new Set();
  const st = ((world.zoneRideStats ||= {})[id] = { bound: [], free: [] });
  for (const [name, z] of N) {
    if (!/^ANIM_.*__\d+$/.test(name) || z.userData.zoneLive) continue;
    z.getWorldPosition(p);
    let best = null;
    let bd = swings ? 1.2 : 0.6;
    for (const o of tops) {
      if (used.has(o)) continue;
      o.getWorldPosition(q);
      const d = q.distanceTo(p);
      if (d < bd) {
        bd = d;
        best = o;
      }
    }
    if (!best) {
      st.free.push(name);
      continue;
    }
    used.add(best);
    // (the zone node stays where it is and follows the pivot every frame: a pivot that is itself a mesh is
    // hidden, and a hidden parent would hide the node with it)
    best.updateMatrixWorld(true);
    z.updateMatrixWorld(true);
    const rel = best.matrixWorld.clone().invert().multiply(z.matrixWorld);
    z.matrixAutoUpdate = false;
    const inv = new THREE.Matrix4();
    anims.push(() => {
      best.updateWorldMatrix(true, false);
      z.parent.updateWorldMatrix(true, false);
      z.matrix.copy(inv.copy(z.parent.matrixWorld).invert().multiply(best.matrixWorld).multiply(rel));
      z.matrixWorldNeedsUpdate = true;
    });
    best.traverse((c) => c.isMesh && (c.visible = false));
    // (HIDE hid every ANIM_ node, the pieces inside this one too: a record and its label)
    z.traverse((c) => (c.visible = true));
    z.userData.zoneLive = true;
    st.bound.push(name);
  }
  if (!swings) run(world.time || 0);
}

// the zone's gameplay constants (zon_<id>.constants.json, packed with the GLBs): the data the collider
// JSON cannot carry. The legacy builders made these very colliders already (frozen world): each one
// is found by where it stands and given the flag / data, so they say the same thing as the export.
// the moles and the straw dummies (zon_games ANIM_ nodes): each zone body joins the nearest legacy
// group, which games.js bobs and fx.js wobbles as before; the legacy meshes stop drawing (they still
// take the rifle's hits: a raycast does not skip hidden meshes)
function bindGames(world, N) {
  const p = new THREE.Vector3();
  const near = (list, at) => list.reduce((b, g) => (!b || g.d < b.d ? g : b), null);
  for (const [name, o] of N) {
    const mole = /^ANIM_act_games_mole_body__\d+$/.test(name);
    const dummy = /^ANIM_act_games_dummy_\d+_body__0$/.test(name);
    if (!mole && !dummy) continue;
    o.getWorldPosition(p);
    const groups = mole ? (world.zoneMoles || []).map((m) => m.group) : world.zoneDummies || [];
    const best = near(groups.map((g) => ({ g, d: Math.hypot(g.getWorldPosition(new THREE.Vector3()).x - p.x, g.getWorldPosition(new THREE.Vector3()).z - p.z) })));
    if (!best || best.d > 1) continue;
    const g = best.g;
    for (const c of g.children) if (c.isMesh) c.visible = false;
    if (mole) {
      // (attached at the mole's rest, down in its hole, whatever the game is doing right now)
      const y = g.position.y;
      g.position.y = -0.6;
      g.updateMatrixWorld(true);
      g.attach(o);
      g.position.y = y;
    } else {
      g.updateMatrixWorld(true);
      g.attach(o);
      o.traverse((c) => (c.userData.target = g.children[0]?.userData.target));
    }
    o.visible = true;
    o.userData.zoneLive = true;
  }
}

// (stats in world.zoneConstStats: applied, and any the export placed where no collider stands)
function applyConstants(id, world, N, c) {
  if (!c) return;
  const st = ((world.zoneConstStats ||= {})[id] = { applied: 0, missing: [] });
  if (id === "games")
    for (const k of c.ball_only || []) {
      // (COL_seg_<k>: its middle, its turn and its length; the world segment with the same ends)
      const o = N.get(`COL_seg_${k}`);
      if (!o) {
        st.missing.push(`seg ${k}: no node`);
        continue;
      }
      const m = new THREE.Vector3();
      o.getWorldPosition(m);
      const len = o.userData.tdd_len ?? 0;
      const s = world.segments.find((g) => Math.hypot((g.ax + g.bx) / 2 - m.x, (g.az + g.bz) / 2 - m.z) < 0.03 && Math.abs(Math.hypot(g.bx - g.ax, g.bz - g.az) - len) < 0.03);
      if (!s) st.missing.push(`seg ${k}`);
      else {
        s.ballOnly = true;
        st.applied++;
      }
    }
  if (id === "trail")
    for (const pad of c.trail_pads || []) {
      const s = (world.solids || []).find((q) => q.base && Math.hypot(q.base.x - pad.base[0], q.base.z - pad.base[2]) < 0.03);
      if (!s) {
        st.missing.push(`pad ${pad.i}`);
        continue;
      }
      // (a plain pad is kind null in the JSON, kind undefined in the game: games.js asks
      // on.kind !== undefined, so it stays undefined)
      if (pad.kind != null) s.kind = pad.kind;
      s.i = pad.i;
      // (the export rounds to 0.1 mm: the legacy base is the same spot, kept unless it is not)
      if (Math.hypot(s.base.x - pad.base[0], s.base.z - pad.base[2]) > 0.001) s.base.set(pad.base[0], pad.base[1], pad.base[2]);
      st.applied++;
    }
}

// the room props' glass (the hourglass, cloches; room props redesign 2026-11-22): clear, a soft sheen, drawn after
// the solid pieces (no depth write, so what is inside shows)
let glass = null;
function glassMat(n) {
  if (n !== "MAT_room_glass") return null;
  if (!glass) {
    glass = new THREE.MeshStandardMaterial({ name: n, color: 0xe8f6ff, transparent: true, opacity: 0.22, roughness: 0.06, metalness: 0, depthWrite: false });
    glass.userData.shared = true;
  }
  return glass;
}

// the rooms' modelled floors and rugs (art pass 3, w8_floors.py): MAT_room_floor_<kind> / MAT_room_rug_fabric carry
// their colours in the vertex colours; the Blender surface map of their kind (T_detail_*) lays its grain, weave,
// tooth or glaze over them around its own mean (so the colour stays the modelled one) and lifts it as a bump.
// One shared material per name for every room (never freed with a room: userData.shared)
const FLOOR_LOOK = {
  wood: { map: "wood", k: 0.42, bump: 0.7, rough: 0.62, rep: 1 },
  glaze: { map: "glaze", k: 0.3, bump: 0.25, rough: 0.32, rep: 1 },
  plaster: { map: "plaster", k: 0.2, bump: 0.25, rough: 0.78, rep: 1 },
  // (the weave map is fine cloth: spread wider, a chunky pile reads on the rugs and the carpet)
  fabric: { map: "fabric", k: 0.55, bump: 0.9, rough: 0.95, rep: 0.3 },
  gloss: { map: "glaze", k: 0.16, bump: 0.12, rough: 0.22, rep: 1 },
};
// (each map's mean, in its own sRGB values: assets/textures/surface/T_detail_*_512.webp)
const DETAIL_MEAN = { wood: 0.242, glaze: 0.219, plaster: 0.22, fabric: 0.27 };
const floorMats = new Map();
function floorMat(n) {
  const hit = /^MAT_room_(floor|rug)_(\w+)$/.exec(n);
  const L = hit && FLOOR_LOOK[hit[1] === "rug" ? "fabric" : hit[2]];
  if (!L) return null;
  if (floorMats.has(n)) return floorMats.get(n);
  const m = new THREE.MeshStandardMaterial({ name: n, vertexColors: true, roughness: L.rough, metalness: 0 });
  m.userData.shared = true;
  const U = { uDetailK: { value: L.k }, uDetailMean: { value: DETAIL_MEAN[L.map] } };
  m.onBeforeCompile = (sh) => {
    Object.assign(sh.uniforms, U);
    sh.fragmentShader = sh.fragmentShader.replace("void main() {", "uniform float uDetailK;\nuniform float uDetailMean;\nvoid main() {").replace(
      "#include <map_fragment>",
      `#ifdef USE_MAP
  {
    vec3 dT = texture2D(map, vMapUv).rgb;
    float dl = pow(max(dot(dT, vec3(0.3333)), 1e-4), 1.0 / 2.2) / uDetailMean;
    diffuseColor.rgb *= clamp(mix(1.0, dl, uDetailK), 0.4, 1.6);
  }
#endif`,
    );
  };
  m.customProgramCacheKey = () => "roomFloorDetail";
  withSurfaceMap(L.map, L.rep, (t) => {
    m.map = t;
    m.bumpMap = t;
    m.bumpScale = L.bump;
    m.needsUpdate = true;
  });
  floorMats.set(n, m);
  return m;
}

// a room's inside (zon_room_<id>): its wallpaper and ceiling liners wear the room's own legacy canvases
// (MAT_room_paper / _ceiling: the zone's UVs carry the legacy repeat, so the maps repeat once), its floor and rug
// are modelled (floorMat);
// the bakery's counter tops take the design's counter colour (kit tint "paint"); the gallery's
// FRAME_0..7 and the vase socket are checked against the legacy save slots (world.zoneConstStats)
const once1 = (t) => {
  if (!t) return null;
  const c = t.clone();
  c.wrapS = c.wrapT = THREE.RepeatWrapping;
  c.repeat.set(1, 1);
  c.offset.set(0, 0);
  c.needsUpdate = true;
  return c;
};
function wireRoom(rid, { world, N, anims, mats }) {
  const room = world.rooms.get(rid);
  if (!room) return;
  const S = room.roomSurf || {};
  const made = new Map();
  const surf = (n) => {
    if (made.has(n)) return made.get(n);
    let m = floorMat(n) || glassMat(n);
    if (!m && n === "MAT_room_paper" && S.paper) m = new THREE.MeshStandardMaterial({ name: n, map: once1(S.paper), roughness: S.paperMat?.roughness ?? 0.9, flatShading: false });
    else if (!m && n === "MAT_room_ceiling" && S.ceil) {
      m = S.ceil.clone();
      m.map = m.emissiveMap = once1(S.ceil.map);
    }
    made.set(n, m);
    return m;
  };
  const st = ((world.zoneConstStats ||= {})[`rm_${rid}`] = { bound: 0, unbound: [] });
  for (const [, o] of N) {
    if (!o.isMesh) continue;
    const n = (o.material?.name || "").replace(/\.\d+$/, "");
    if (!/^MAT_room_/.test(n)) continue;
    const m = surf(n);
    if (m) {
      o.material = m;
      st.bound++;
    } else {
      o.visible = false;
      st.unbound.push(n);
    }
  }
  // the bakery: the counter, island and café-table tops in the design's counter colour
  if (rid === "bakery") {
    const M = room.bakery?.mats || {};
    const tints = mats.kitTints?.get("interior");
    if (tints && M.counter) anims.push(() => tints[0].copy(M.counter.color));
  }
  const p = new THREE.Vector3();
  // the 8 gallery frames keep their save index: FRAME_<k> stands where the legacy frame k hangs
  if (room.galleryFrames?.length) {
    let worst = 0;
    const q = new THREE.Vector3();
    room.galleryFrames.forEach((pic, k) => {
      const f = N.get(`FRAME_${k}`);
      if (!f) return (worst = Infinity);
      f.getWorldPosition(p);
      pic.getWorldPosition(q);
      worst = Math.max(worst, Math.hypot(p.x - q.x, p.z - q.z));
    });
    st.frames = { n: room.galleryFrames.length, worstM: +worst.toFixed(3) };
  }
  // the vase: bouquets.js's own (save index 9 + room), standing at the zone's SOCK_vase
  const sock = N.get("SOCK_vase");
  if (sock) {
    sock.getWorldPosition(p).setY(0);
    const vase = world.interactables.find((it) => /^vase-/.test(it.id) && it.pos.distanceTo(p) < 0.6);
    st.vase = vase ? vase.id : "none near";
  }
}

// a flat floor cut to a room's inside: its vertices (in the room's frame) clamped to the room's half
// sizes, its UVs worked out again from the same straight-line map position -> UV the export used
function cropToRoom(o, roomGroup, hw, hd) {
  const g = o.geometry;
  const pos = g.attributes.position;
  const uv = g.attributes.uv;
  if (!pos || !uv) return;
  o.updateWorldMatrix(true, false);
  const toRoom = new THREE.Matrix4().copy(roomGroup.matrixWorld).invert().multiply(o.matrixWorld);
  const back = new THREE.Matrix4().copy(toRoom).invert();
  const v = new THREE.Vector3();
  const pts = [];
  for (let i = 0; i < pos.count; i++) pts.push(v.fromBufferAttribute(pos, i).applyMatrix4(toRoom).clone());
  // least squares: u = a x + b z + c, the same for v
  const fit = (get) => {
    let sxx = 0, sxz = 0, szz = 0, sx = 0, sz = 0, n = 0, sxu = 0, szu = 0, su = 0;
    pts.forEach((p, i) => {
      const u = get(i);
      sxx += p.x * p.x; sxz += p.x * p.z; szz += p.z * p.z; sx += p.x; sz += p.z; n++;
      sxu += p.x * u; szu += p.z * u; su += u;
    });
    const A = new THREE.Matrix3().set(sxx, sxz, sx, sxz, szz, sz, sx, sz, n);
    if (Math.abs(A.determinant()) < 1e-9) return null;
    return new THREE.Vector3(sxu, szu, su).applyMatrix3(A.invert());
  };
  const fu = fit((i) => uv.getX(i));
  const fv = fit((i) => uv.getY(i));
  if (!fu || !fv) return;
  const p2 = g.attributes.position.clone();
  const uv2 = uv.clone();
  pts.forEach((p, i) => {
    p.x = Math.max(-hw, Math.min(hw, p.x));
    p.z = Math.max(-hd, Math.min(hd, p.z));
    uv2.setXY(i, fu.x * p.x + fu.y * p.z + fu.z, fv.x * p.x + fv.y * p.z + fv.z);
    const w = p.clone().applyMatrix4(back);
    p2.setXYZ(i, w.x, w.y, w.z);
  });
  const ng = g.clone();
  ng.setAttribute("position", p2);
  ng.setAttribute("uv", uv2);
  ng.computeBoundingSphere();
  ng.computeBoundingBox();
  o.geometry = ng;
  return Math.hypot(fu.x, fu.y);
}
