// The island's sound set (rebuild/reports/audio/runtime-design.md): the rendered sounds in assets/audio
// (manifest.json; Opus .ogg, AAC .m4a where Opus does not play), on buses, positional where they happen,
// with voice pools per device tier, ducking, and the ambience beds crossfading by zone, room, height,
// theme, day and night and weather. Nothing loads or plays before the first tap or key (mobile unlock);
// until the context runs, play() drops silently (no burst of stale sounds later).
//   play("a+b:1@0.6", { pos, gain, rate, voice })   layered ids, ":n" a chosen variant, "@s" a delay
//   loop(id, { pos, gain, rate }) -> handle { gain(v), rate(r), at(pos), stop(fade) }
//   update(dt, state)   the beds, the sprinklers, the packs near you, the indoor filter
//   duck(key, on)       cinema / media / voice / stinger / timer
import * as THREE from "three";

const BUS_DB = { ui: 0, sfx: 0, foley: -3, voice: 0, creature: -2, amb: -4, weather: -3 };
// the wind / breeze beds' level (the meadow, night, spooky and winter beds are mostly air; the sky bed is open wind)
const WIND_BED = { amb_day: 0.4, amb_night: 0.45, amb_spooky: 0.45, amb_winter: 0.45, amb_sky: 0.35 };
const STEAL_ORDER = { foley: 0, creature: 1, sfx: 2, voice: 3, ui: 4, amb: 5, weather: 5 };
const TIERS = {
  high: { voices: 32, pos: 20, beds: 4, perId: 4 },
  mid: { voices: 24, pos: 14, beds: 3, perId: 3 },
  low: { voices: 14, pos: 8, beds: 3, perId: 2 },
};
// positional classes: [distanceModel, refDistance, maxDistance, rolloff]
const CLASS = {
  foley: ["inverse", 1.5, 18, 1.6],
  small: ["inverse", 2, 25, 1.3],
  creature: ["inverse", 3, 40, 1.2],
  big: ["inverse", 6, 90, 1.0],
  bed: ["linear", 2, 20, 1],
  vehicle: ["exponential", 4, 70, 1.1],
};
const BIG = new Set(["shot", "bumper", "burner", "horn", "chain_clack", "brakes", "wx_thunder", "rooster_crow", "duck_quack", "fall_whistle", "scooter_summon", "unicorn_summon"]);
const LOUD_CREATURE = new Set(["rooster_crow", "duck_quack"]);
const POS_BEDS = new Set(["loop_fire", "loop_fountain", "amb_plaza", "loop_projector", "loop_crystal", "loop_bee"]);
const VEHICLE = new Set(["loop_scooter", "loop_coaster_roll"]);
// ducking (gain multipliers per bus group): music, amb+weather, sfx/creature/foley
const DUCKS = {
  cinema: [0, 0.2, 0.4],
  media: [0, 0.32, 0.63],
  voice: [0.5, 0.5, 0.71],
  stinger: [0.5, 0.63, 1],
  timer: [1, 0.5, 1],
  cave: [0.12, 0.25, 1], // (down in the secret cave: its own beds and tune instead, cave.js)
};
const STINGERS = { game_win: 1, new_best: 1, golden_bloom: 1, willow_grow: 1 };
const PACK_ORDER_CORE = ["ui", "foley", "voice", "sfx", "creature"];
const db = (x) => Math.pow(10, x / 20);

export class Sound {
  constructor(ctx, out, { base, tier = "high", isTouch = false, music = null }) {
    this.ctx = ctx;
    this.base = base ? base + "audio/" : null;
    this.T = TIERS[tier === "ultra" ? "high" : tier] || TIERS.high;
    this.isTouch = isTouch;
    this.gen = 1;
    this.files = new Map(); // file -> Promise<AudioBuffer|null>
    this.got = new Map(); // file -> AudioBuffer (oldest use first: the phones' budget evicts from the front)
    // phones (iOS kills the page for memory): at most 15 MB decoded, decoded on demand, least recently used out
    this.budget = isTouch ? 15e6 : Infinity;
    this.bytes = 0;
    this.packs = new Map(); // pack -> last time wanted (s)
    this.voices = []; // { src, bus, loop, id, t, pos }
    this.lastAt = new Map();
    this.lastFile = new Map();
    this.beds = new Map(); // id -> { h, want }
    this.ducks = new Set();
    this.sfxVol = readVol("tdd3d.sfx", 1);
    this.ambVol = readVol("tdd3d.amb", 1);
    this.ext = (() => {
      try {
        return new window.Audio().canPlayType('audio/ogg; codecs="opus"') ? "ogg" : "m4a";
      } catch {
        return "m4a";
      }
    })();
    // master: gain 0.8 then a gentle limiter (out = the existing chain's input)
    const c = ctx;
    this.master = c.createGain();
    this.master.gain.value = 0.8;
    const lim = c.createDynamicsCompressor();
    lim.threshold.value = -6;
    lim.ratio.value = 12;
    lim.attack.value = 0.003;
    lim.release.value = 0.12;
    this.master.connect(lim).connect(out);
    this.music = music;
    // indoors: the outdoor beds pass a 900 Hz lowpass at -6 dB
    this.indoorF = c.createBiquadFilter();
    this.indoorF.type = "lowpass";
    this.indoorF.frequency.value = 20000;
    this.indoorG = c.createGain();
    this.indoorF.connect(this.indoorG).connect(this.master);
    this.bus = {};
    this.duckG = {};
    for (const [b, d] of Object.entries(BUS_DB)) {
      const user = c.createGain();
      const duck = c.createGain();
      user.gain.value = db(d) * (b === "amb" || b === "weather" ? this.ambVol : this.sfxVol);
      user.connect(duck).connect(b === "amb" || b === "weather" ? this.indoorF : this.master);
      this.bus[b] = user;
      this.duckG[b] = duck;
    }
    this.manifest = null;
    this.ready = this.base
      ? fetch(this.base + "manifest.json")
          .then((r) => (r.ok ? r.json() : null))
          .then((m) => {
            this.manifest = m?.sounds || null;
            if (this.manifest) this.loadCore();
          })
          .catch(() => null)
      : Promise.resolve();
    this.sprinkle = { bird: 3, song: 20, owl: 20, cricket: 2, bat: 8, fish: 25 };
    this.scratch = new THREE.Vector3();
    this.listenerPos = new THREE.Vector3();
  }

  // ---- the listener (one, on the active camera; moved, never duplicated) ----
  attach(camera) {
    if (!camera) return;
    if (!this.listener) {
      THREE.AudioContext.setContext(this.ctx);
      this.listener = new THREE.AudioListener();
      // (positional voices go to their bus, not through the listener's own gain)
      this.listener.gain.disconnect();
    }
    if (this.listener.parent !== camera) camera.add(this.listener);
  }

  // ---- loading ----
  url(file) {
    return `${this.base}${this.ext}/${file}.${this.ext}`;
  }
  load(file) {
    if (this.files.has(file)) return this.files.get(file);
    const gen = this.gen;
    const p = fetch(this.url(file))
      .then((r) => (r.ok ? r.arrayBuffer() : Promise.reject(new Error(r.status))))
      .then((b) => new Promise((res, rej) => this.ctx.decodeAudioData(b, res, rej)))
      .then((buf) => {
        if (gen !== this.gen || this.files.get(file) !== p) return null;
        this.got.set(file, buf);
        this.bytes += buf.length * buf.numberOfChannels * 4;
        if (this.bytes > this.budget) this.trim();
        return buf;
      })
      .catch((e) => {
        if (!this.warned) console.warn("sound", file, e?.message || e);
        this.warned = true;
        return null;
      });
    this.files.set(file, p);
    return p;
  }
  // forget one decoded file (a voice still playing it keeps its own reference)
  unload(file) {
    const b = this.got.get(file);
    if (b) this.bytes -= b.length * b.numberOfChannels * 4;
    this.got.delete(file);
    this.files.delete(file);
  }
  // over the phones' budget: the least recently used go first, never a bed that is playing
  trim() {
    const keep = new Set();
    for (const b of this.beds.values()) if (b.h?.m) keep.add(b.h.m.files[0]);
    for (const f of this.got.keys()) {
      if (this.bytes <= this.budget * 0.8) break;
      if (!keep.has(f)) this.unload(f);
    }
  }
  // the core pack after the first tap (ui, foley, voice first); beds only when wanted. Phones: only the
  // footsteps and the ui up front, everything else decoded the first time it is asked for
  async loadCore() {
    const M = this.manifest;
    const ids = Object.keys(M).filter((id) => M[id].pack === "core" && !M[id].loop && (!this.isTouch || M[id].bus === "ui" || M[id].cat === "footsteps"));
    ids.sort((a, b) => order(M[a].bus) - order(M[b].bus));
    this.packs.set("core", Infinity);
    for (let i = 0; i < ids.length; i += 6) await Promise.all(ids.slice(i, i + 6).flatMap((id) => M[id].files.map((f) => this.load(f))));
  }
  wantPack(p, now) {
    if (!this.manifest || p === "core") return;
    if (!this.packs.has(p)) {
      this.packs.set(p, now);
      if (!this.isTouch) for (const [id, m] of Object.entries(this.manifest)) if (m.pack === p && !m.loop) m.files.forEach((f) => this.load(f));
    } else this.packs.set(p, now);
  }
  // a zone pack's decoded sounds go 45 s after you leave it
  evict(now) {
    for (const [p, t] of this.packs) {
      if (t === Infinity || now - t < 45) continue;
      this.packs.delete(p);
      for (const m of Object.values(this.manifest)) {
        if (m.pack !== p) continue;
        for (const f of m.files) this.unload(f);
      }
    }
  }

  warm(id) {
    const m = this.manifest?.[id];
    if (m && this.ctx.state === "running") for (const f of m.files) if (!this.got.has(f)) this.load(f);
  }

  // ---- one-shots ----
  play(spec, o = {}) {
    if (!this.manifest || this.ctx.state !== "running") return;
    if (spec.indexOf("+") >= 0) {
      for (const p of spec.split("+")) this.play(p, o);
      return;
    }
    let id = spec;
    let delay = o.delay || 0;
    let v = o.v;
    const at = id.indexOf("@");
    if (at > 0) {
      delay += Number(id.slice(at + 1)) || 0;
      id = id.slice(0, at);
    }
    const c = id.indexOf(":");
    if (c > 0) {
      v = Number(id.slice(c + 1)) || 0;
      id = id.slice(0, c);
    }
    const m = this.manifest[id];
    if (!m) return;
    const now = this.ctx.currentTime;
    if (m.pack !== "core") this.wantPack(m.pack, now);
    // retrigger guard: the same id not within 35 ms of itself (footsteps 90)
    const last = this.lastAt.get(id) || -1;
    if (!delay && now - last < (m.cat === "footsteps" ? 0.09 : 0.035)) return;
    // a positional one-shot past its reach is skipped
    const cls = o.pos ? this.classOf(id, m) : null;
    if (o.pos && this.listener && o.pos.distanceTo(this.listenerAt()) > cls[2]) return;
    let file;
    if (m.pick === "index") file = m.files[Math.min(m.files.length - 1, Math.max(0, v | 0))];
    else if (v != null && m.files.length > 1) file = m.files[(v | 0) % m.files.length];
    else {
      const prev = this.lastFile.get(id);
      let k = (Math.random() * m.files.length) | 0;
      if (m.files.length > 1 && m.files[k] === prev) k = (k + 1) % m.files.length;
      file = m.files[k];
    }
    const buf = this.got.get(file);
    if (!buf) {
      this.load(file);
      return;
    }
    if (this.isTouch) {
      // (recently used: to the back of the eviction queue)
      this.got.delete(file);
      this.got.set(file, buf);
    }
    // per-id cap and the voice pool (steal the oldest one-shot on the same or a lower bus)
    let same = 0;
    let posN = 0;
    for (const x of this.voices) {
      if (x.id === id) same++;
      if (x.panner) posN++;
    }
    if (same >= this.T.perId) return;
    if (this.voices.length >= this.T.voices || (o.pos && posN >= this.T.pos)) {
      let best = -1;
      for (let i = 0; i < this.voices.length; i++) {
        const x = this.voices[i];
        if (x.loop || STEAL_ORDER[x.bus] > STEAL_ORDER[m.bus] || (o.pos && !x.panner)) continue;
        if (best < 0 || x.t < this.voices[best].t) best = i;
      }
      if (best < 0) return;
      this.kill(this.voices[best]);
    }
    this.lastAt.set(id, now);
    this.lastFile.set(id, file);
    let rate0 = o.rate || 1;
    if (m.pick !== "index") rate0 *= 1 + (Math.random() * 2 - 1) * (m.bus === "ui" ? 0.02 : 0.04);
    if (o.voice) rate0 *= o.voice;
    if (o.pos && this.listener) return void this.playAt(id, m, buf, o, rate0, delay, cls || this.classOf(id, m));
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    src.playbackRate.value = rate0;
    const g = this.ctx.createGain();
    g.gain.value = o.gain ?? 1;
    src.connect(g);
    const x = { src, g, bus: m.bus, loop: false, id, t: now + delay, panner: null };
    this.route(x, g, o.pos, cls || (o.pos ? this.classOf(id, m) : null));
    src.onended = () => this.drop(x);
    src.start(now + delay);
    this.voices.push(x);
    // the big stingers duck the beds and the music for their length
    if (STINGERS[id]) {
      this.duck("stinger", true);
      clearTimeout(this.stingT);
      this.stingT = setTimeout(() => this.duck("stinger", false), (m.dur || 2) * 1000);
    }
  }
  // a positional one-shot: a pooled THREE.PositionalAudio, its output into the bus
  playAt(id, m, buf, o, rate, delay, cls) {
    let pa = null;
    for (const p of (this.paPool ??= [])) if (!p.busy) pa = p;
    if (!pa) {
      if (this.paPool.length >= this.T.pos) return;
      pa = new THREE.PositionalAudio(this.listener);
      pa.gain.disconnect();
      pa.panner.panningModel = this.isTouch ? "equalpower" : "HRTF";
      this.paPool.push(pa);
    }
    pa.gain.disconnect();
    pa.gain.connect(this.bus[m.bus]);
    pa.busy = true;
    pa.setBuffer(buf);
    pa.setDistanceModel(cls[0]);
    pa.setRefDistance(cls[1]);
    pa.setMaxDistance(cls[2]);
    pa.setRolloffFactor(cls[3]);
    pa.setVolume(o.gain ?? 1);
    pa.playbackRate = rate;
    pa.position.copy(o.pos);
    pa.updateMatrixWorld(true);
    const x = { src: null, g: null, pa, bus: m.bus, loop: false, id, t: this.ctx.currentTime + delay, panner: pa.panner };
    pa.onEnded = () => {
      pa.isPlaying = false;
      pa.busy = false;
      const i = this.voices.indexOf(x);
      if (i >= 0) this.voices.splice(i, 1);
    };
    pa.play(delay);
    x.src = pa.source;
    this.voices.push(x);
  }
  classOf(id, m) {
    if (POS_BEDS.has(id)) return CLASS.bed;
    if (VEHICLE.has(id)) return CLASS.vehicle;
    if (BIG.has(id)) return CLASS.big;
    if (m.bus === "foley") return CLASS.foley;
    if (m.bus === "creature") return LOUD_CREATURE.has(id) ? [...CLASS.creature.slice(0, 1), 5, 40, 1.2] : CLASS.creature;
    return CLASS.small;
  }
  listenerAt() {
    return this.listener ? this.listener.getWorldPosition(this.listenerPos) : this.listenerPos;
  }
  // a positional voice: a THREE.PositionalAudio from a pool, its panner into the bus
  route(x, node, pos, cls) {
    const bus = this.bus[x.bus];
    if (!pos || !this.listener) return void node.connect(bus);
    const p = this.ctx.createPanner();
    p.panningModel = this.isTouch ? "equalpower" : "HRTF";
    p.distanceModel = cls[0];
    p.refDistance = cls[1];
    p.maxDistance = cls[2];
    p.rolloffFactor = cls[3];
    setPannerPos(p, pos, this.ctx.currentTime);
    node.connect(p).connect(bus);
    x.panner = p;
  }
  kill(x) {
    if (x.pa) {
      try {
        x.pa.stop();
      } catch {}
      return x.pa.onEnded();
    }
    try {
      x.src.stop();
    } catch {}
    this.drop(x);
  }
  drop(x) {
    const i = this.voices.indexOf(x);
    if (i >= 0) this.voices.splice(i, 1);
    try {
      x.g?.disconnect();
      x.panner?.disconnect();
    } catch {}
  }

  // ---- loops (between loopStart and loopEnd; AAC priming shifts both points) ----
  loop(id, o = {}) {
    const m = this.manifest?.[id];
    if (!m || !m.loop) return null;
    const h = { id, m, src: null, g: this.ctx.createGain(), panner: null, live: true, rateV: o.rate || 1 };
    const target = o.gain ?? 1;
    h.g.gain.value = 0;
    const x = { src: null, g: h.g, bus: m.bus, loop: true, id, t: this.ctx.currentTime, panner: null };
    this.route(x, h.g, o.pos, o.pos ? this.classOf(id, m) : null);
    h.panner = x.panner;
    h.x = x;
    const fade = o.fade ?? 0.3;
    this.load(m.files[0]).then((buf) => {
      if (!buf || !h.live || this.ctx.state === "closed") return;
      const src = this.ctx.createBufferSource();
      src.buffer = buf;
      const shift = Math.abs(buf.duration - (m.loopEnd + 0.5)) > 0.002 ? buf.duration - (m.loopEnd + 0.5) : 0;
      src.loop = true;
      src.loopStart = m.loopStart + shift;
      src.loopEnd = m.loopEnd + shift;
      src.playbackRate.value = h.rateV;
      src.connect(h.g);
      const len = m.loopEnd - m.loopStart;
      // (a bed starts somewhere inside its loop, so stacked beds do not line up)
      src.start(this.ctx.currentTime, src.loopStart + (o.random === false ? 0 : Math.random() * len));
      h.src = src;
      x.src = src;
      h.g.gain.setTargetAtTime(target, this.ctx.currentTime, fade / 3);
    });
    h.gain = (v, tc = 0.15) => h.live && h.g.gain.setTargetAtTime(v, this.ctx.currentTime, tc);
    h.rate = (r) => {
      h.rateV = r;
      if (h.src) h.src.playbackRate.setTargetAtTime(r, this.ctx.currentTime, 0.08);
    };
    h.at = (pos) => h.panner && setPannerPos(h.panner, pos, this.ctx.currentTime);
    h.stop = (f = 0.3) => {
      if (!h.live) return;
      h.live = false;
      const t = this.ctx.currentTime;
      h.g.gain.setTargetAtTime(0, t, Math.max(0.01, f / 3));
      setTimeout(() => {
        try {
          h.src?.stop();
        } catch {}
        try {
          h.g.disconnect();
          h.panner?.disconnect();
        } catch {}
      }, f * 1000 + 200);
    };
    return h;
  }

  // ---- ducking ----
  duck(key, on) {
    if (on) this.ducks.add(key);
    else this.ducks.delete(key);
    const k = [1, 1, 1];
    for (const d of this.ducks) for (let i = 0; i < 3; i++) k[i] *= DUCKS[d]?.[i] ?? 1;
    const t = this.ctx.currentTime;
    const tc = on ? 0.15 : 0.6;
    this.musicDuck = k[0];
    for (const b of ["amb", "weather"]) this.duckG[b].gain.setTargetAtTime(k[1], t, tc);
    for (const b of ["sfx", "creature", "foley", "voice"]) this.duckG[b].gain.setTargetAtTime(k[2], t, tc);
  }
  setVolumes(sfx = this.sfxVol, amb = this.ambVol) {
    this.sfxVol = sfx;
    this.ambVol = amb;
    try {
      localStorage.setItem("tdd3d.sfx", String(sfx));
      localStorage.setItem("tdd3d.amb", String(amb));
    } catch {}
    const t = this.ctx.currentTime;
    for (const [b, d] of Object.entries(BUS_DB)) this.bus[b].gain.setTargetAtTime(db(d) * (b === "amb" || b === "weather" ? amb : sfx), t, 0.1);
  }

  // ---- the ambience (beds) and the sprinklers ----
  // st: { theme, night, weather, indoors, room, zone: { id, w }, height, sky, idle, packs: [] }
  update(dt, st) {
    if (!this.manifest || this.ctx.state !== "running") return;
    const now = this.ctx.currentTime;
    for (const p of st.packs || []) this.wantPack(p, now);
    if ((this.evictT = (this.evictT || 0) + dt) > 5) {
      this.evictT = 0;
      this.evict(now);
    }
    // the indoor filter on the outdoor beds
    const inside = Boolean(st.indoors);
    if (inside !== this.inside) {
      this.inside = inside;
      this.indoorF.frequency.setTargetAtTime(inside ? 900 : 20000, now, 0.3);
      this.indoorG.gain.setTargetAtTime(inside ? 0.5 : 1, now, 0.3);
    }
    const want = this.bedWant || (this.bedWant = new Map());
    want.clear();
    const idle = st.idle > 120 ? 0.5 : 1;
    const sky = st.sky ? 1 : smooth((st.height || 0) - 10, 12);
    const out = 1 - 0.5 * sky;
    let base;
    if (inside) base = st.room === "bakery" ? "amb_bakery" : "amb_interior";
    else if (st.theme === "halloween") base = "amb_spooky";
    else if (st.theme === "christmas") base = "amb_winter";
    else base = st.night ? "amb_night" : "amb_day";
    // (user 2026-11-22: the wind / air in the outdoor beds was too loud: well under half)
    want.set(base, (inside ? 1 : out * (WIND_BED[base] ?? 1)) * idle);
    const wx = st.weather;
    const wxId = wx === "rain" ? (inside ? "wx_rain_roof" : "wx_rain") : wx === "snow" ? "wx_snow" : wx === "blizzard" ? "wx_blizzard" : wx === "autumn" || wx === "fall" ? "wx_autumn" : wx === "flurry" ? "wx_snow" : null;
    if (wxId) want.set(wxId, (wx === "flurry" ? db(-8) : 1) * idle);
    if (!inside && st.zone?.id && st.zone.w > 0.01) {
      const z = { farm: "amb_farm", garden: "amb_forest", forest: "amb_forest", lake: "amb_lake", willow: "amb_willow" }[st.zone.id];
      if (z && this.manifest[z]) {
        want.set(z, st.zone.w * out * idle);
        this.wantPack(this.manifest[z].pack, now);
      }
    }
    if (!inside && sky > 0.01) {
      want.set("amb_sky", sky * WIND_BED.amb_sky);
      this.wantPack("rides", now);
    }
    // at most `beds` at once: the base, the weather, then the zone and the sky by gain
    if (want.size > this.T.beds) {
      const keep = [...want.entries()].sort((a, b) => (b[0] === base) - (a[0] === base) || (b[0] === wxId) - (a[0] === wxId) || b[1] - a[1]).slice(0, this.T.beds);
      want.clear();
      for (const [k, v] of keep) want.set(k, v);
    }
    const fade = inside !== this.wasInside ? 1.2 : 2.5;
    this.wasInside = inside;
    for (const [id, g] of want) {
      let b = this.beds.get(id);
      if (!b) {
        const h = this.loop(id, { gain: g, fade });
        if (!h) continue;
        this.beds.set(id, (b = { h, g }));
      } else if (Math.abs(b.g - g) > 0.01) {
        b.h.gain(g, fade / 3);
        b.g = g;
      }
    }
    for (const [id, b] of this.beds) {
      if (want.has(id)) continue;
      b.h.stop(fade);
      this.beds.delete(id);
    }
    if (inside || st.sky) return;
    // sprinklers: birds by day, owls and crickets by night, a random point 8-30 m away
    const S = this.sprinkle;
    const fire = (key, id, lo, hi) => {
      if ((S[key] -= dt) > 0) return;
      S[key] = lo + Math.random() * (hi - lo);
      if (this.voices.length > this.T.voices - 4) return;
      const a = Math.random() * Math.PI * 2;
      const r = 8 + Math.random() * 22;
      const L = this.listenerAt();
      this.scratch.set(L.x + Math.cos(a) * r, L.y, L.z + Math.sin(a) * r);
      this.play(id, { pos: this.scratch });
    };
    if (st.theme === "halloween") fire("bat", "bat_squeak", 8, 20);
    if (st.night) {
      fire("owl", "owl_hoot", 25, 60);
      fire("cricket", "cricket_chirp", 3, 8);
    } else if (!wxId || wx === "autumn" || wx === "fall") {
      fire("bird", "bird_chirp", 4, 12);
      fire("song", "bird_song", 25, 60);
    }
    if (st.zone?.id === "lake" && st.zone.w > 0.3) fire("fish", "fish_plop", 20, 50);
  }

  pause(p) {
    if (p) this.ctx.suspend().catch(() => {});
    else this.ctx.resume().catch(() => {});
  }
  destroy() {
    this.gen++;
    for (const x of [...this.voices]) this.kill(x);
    for (const b of this.beds.values()) b.h.stop(0.05);
    this.beds.clear();
    this.listener?.removeFromParent();
    this.got.clear();
    this.bytes = 0;
    this.files.clear();
  }
}

function order(bus) {
  const i = PACK_ORDER_CORE.indexOf(bus);
  return i < 0 ? 9 : i;
}
function smooth(x, w) {
  const u = Math.max(0, Math.min(1, x / w));
  return u * u * (3 - 2 * u);
}
function readVol(key, def) {
  try {
    const v = localStorage.getItem(key);
    const n = v == null ? def : Number(v);
    return Number.isFinite(n) ? Math.max(0, Math.min(1, n)) : def;
  } catch {
    return def;
  }
}
function setPannerPos(p, pos, t) {
  if (p.positionX) {
    p.positionX.setValueAtTime(pos.x, t);
    p.positionY.setValueAtTime(pos.y, t);
    p.positionZ.setValueAtTime(pos.z, t);
  } else p.setPosition(pos.x, pos.y, pos.z);
}
