// A grid over the island's colliders (REBUILD-PLAN §6.4), so a collision test only looks at what is
// near instead of all of them (671 wall segments, 494 round obstacles, 190 platforms, twice per test,
// for you and every animal, every frame).
//
// It answers "which colliders could touch this spot" with a list of their indices in the ORIGINAL
// order, and island.js runs exactly the same test on each, in that order, as before. Whatever is left
// out could not have touched (its box, grown by MARGIN, misses the spot), so the pushes, their order
// and their side effects (an obstacle's height measured on first touch) are identical: a parity test
// in the QA harness checks this on recorded paths (rebuild/qa/harness/colgrid_parity.py).
//
// Colliders can change after they are added: pushed or removed (a room furnished, a lantern thinned),
// or moved in place (the drifting cloud on the sky trail, the photo tripod, the willow's trunk as it
// grows). check() (every test, O(1)) rebuilds a kind when its list was replaced or changed length;
// sync() (twice a frame, island.js) compares every collider with what it was and sends anything that
// changed to an always-tested list, read live like before. A collider that first moves in the middle
// of a frame is covered by MARGIN until the next sync (the drifting cloud moves ~0.1 m a frame).
const CELL = 4; // m
const MARGIN = 0.6; // m
const BIG = 400; // a collider covering more cells than this is simply always tested
const OFF = 4096;
const key = (gx, gz) => (gx + OFF) * 8192 + (gz + OFF);

const KINDS = ["segments", "circles", "solids"];

export class ColGrid {
  constructor(world) {
    this.__e1 = "colgrid";
    this.world = world;
    this.k = KINDS.map(() => ({ arr: null, n: -1, refs: [], snap: null, cells: new Map(), vol: [], isVol: null }));
    this.stamp = new Uint32Array(1024);
    this.mark = 1;
    this.stats = { rebuilds: 0, volatile: 0 };
    for (let i = 0; i < 3; i++) this.build(i);
  }

  // the numbers that say where a collider is
  vals(kind, o, out, at) {
    if (kind === 0) {
      out[at] = o.ax;
      out[at + 1] = o.az;
      out[at + 2] = o.bx;
      out[at + 3] = o.bz;
    } else {
      out[at] = o.x;
      out[at + 1] = o.z;
      out[at + 2] = o.r;
      out[at + 3] = 0;
    }
  }

  build(kind) {
    const K = this.k[kind];
    const arr = this.world[KINDS[kind]];
    K.arr = arr;
    K.n = arr.length;
    K.refs = arr.slice();
    K.snap = new Float64Array(arr.length * 4);
    K.cells = new Map();
    const wasVol = K.volSet || new Set();
    K.vol = [];
    K.isVol = new Uint8Array(arr.length);
    K.volSet = new Set();
    for (let i = 0; i < arr.length; i++) {
      const o = arr[i];
      this.vals(kind, o, K.snap, i * 4);
      if (wasVol.has(o) || !this.place(kind, K, i)) this.setVol(K, i);
    }
    if (this.stamp.length < arr.length + 1) this.stamp = new Uint32Array(Math.max(arr.length + 1, this.stamp.length * 2));
    this.stats.rebuilds++;
  }

  setVol(K, i) {
    if (K.isVol[i]) return;
    K.isVol[i] = 1;
    K.volSet.add(K.refs[i]);
    // (kept in order)
    let j = K.vol.length;
    K.vol.push(i);
    while (j > 0 && K.vol[j - 1] > i) {
      K.vol[j] = K.vol[j - 1];
      j--;
    }
    K.vol[j] = i;
    this.stats.volatile = this.k.reduce((n, k) => n + k.vol.length, 0);
  }

  // into the cells its box covers; false if it can't be (not a finite box, or too big)
  place(kind, K, i) {
    const s = K.snap;
    const a = i * 4;
    let x0, x1, z0, z1;
    if (kind === 0) {
      x0 = Math.min(s[a], s[a + 2]);
      x1 = Math.max(s[a], s[a + 2]);
      z0 = Math.min(s[a + 1], s[a + 3]);
      z1 = Math.max(s[a + 1], s[a + 3]);
    } else {
      x0 = s[a] - s[a + 2];
      x1 = s[a] + s[a + 2];
      z0 = s[a + 1] - s[a + 2];
      z1 = s[a + 1] + s[a + 2];
    }
    if (!(Number.isFinite(x0) && Number.isFinite(x1) && Number.isFinite(z0) && Number.isFinite(z1))) return false;
    const gx0 = Math.floor((x0 - MARGIN) / CELL), gx1 = Math.floor((x1 + MARGIN) / CELL);
    const gz0 = Math.floor((z0 - MARGIN) / CELL), gz1 = Math.floor((z1 + MARGIN) / CELL);
    if ((gx1 - gx0 + 1) * (gz1 - gz0 + 1) > BIG || gx0 < -OFF || gz0 < -OFF || gx1 >= OFF || gz1 >= OFF) return false;
    for (let gx = gx0; gx <= gx1; gx++)
      for (let gz = gz0; gz <= gz1; gz++) {
        const k = key(gx, gz);
        let c = K.cells.get(k);
        if (!c) K.cells.set(k, (c = []));
        c.push(i);
      }
    return true;
  }

  // every test: a list that was replaced or changed length is rebuilt
  check() {
    const w = this.world;
    for (let kind = 0; kind < 3; kind++) {
      const K = this.k[kind];
      const arr = w[KINDS[kind]];
      if (arr !== K.arr || arr.length !== K.n) this.build(kind);
    }
  }

  // twice a frame: anything swapped in place is rebuilt, anything moved is always tested from now on
  sync() {
    this.check();
    const tmp = this._tmp || (this._tmp = new Float64Array(4));
    for (let kind = 0; kind < 3; kind++) {
      const K = this.k[kind];
      const arr = K.arr;
      const s = K.snap;
      for (let i = 0; i < arr.length; i++) {
        const o = arr[i];
        if (o !== K.refs[i]) {
          this.build(kind);
          break;
        }
        if (K.isVol[i]) continue;
        this.vals(kind, o, tmp, 0);
        const a = i * 4;
        if (tmp[0] !== s[a] || tmp[1] !== s[a + 1] || tmp[2] !== s[a + 2] || tmp[3] !== s[a + 3]) {
          // (NaN never equals itself: such a collider is always tested too, as before)
          this.setVol(K, i);
        }
      }
    }
  }

  // indices (ascending, all >= from) of the colliders of one kind whose box meets the square
  // [x0, x1] x [z0, z1]; written into out (reused) and returned
  box(kind, x0, z0, x1, z1, from, out) {
    const K = this.k[kind];
    out.length = 0;
    if (++this.mark >= 0xffffffff) {
      this.stamp.fill(0);
      this.mark = 1;
    }
    const m = this.mark;
    const st = this.stamp;
    const gx0 = Math.floor(x0 / CELL), gx1 = Math.floor(x1 / CELL);
    const gz0 = Math.floor(z0 / CELL), gz1 = Math.floor(z1 / CELL);
    let cellsHit = 0;
    if (Number.isFinite(gx0) && Number.isFinite(gx1) && Number.isFinite(gz0) && Number.isFinite(gz1) && (gx1 - gx0 + 1) * (gz1 - gz0 + 1) <= 4096) {
      for (let gx = gx0; gx <= gx1; gx++)
        for (let gz = gz0; gz <= gz1; gz++) {
          const c = K.cells.get(key(gx, gz));
          if (!c) continue;
          cellsHit++;
          for (let j = 0; j < c.length; j++) {
            const i = c[j];
            if (i < from || st[i] === m) continue;
            st[i] = m;
            out.push(i);
          }
        }
    } else {
      // (a huge or broken query: everything, as before)
      for (let i = from; i < K.n; i++) out.push(i);
      return out;
    }
    const v = K.vol;
    for (let j = 0; j < v.length; j++) {
      const i = v[j];
      if (i < from || st[i] === m) continue;
      st[i] = m;
      out.push(i);
      cellsHit++;
    }
    if (cellsHit > 1 && out.length > 1) out.sort((a, b) => a - b);
    return out;
  }

  near(kind, x, z, q, from, out) {
    return this.box(kind, x - q, z - q, x + q, z + q, from, out);
  }
}
