// Zone registry (REBUILD-PLAN 6.2): the per-zone switch between a place's legacy builder and
// its rebuilt one. The World asks here first; a place not listed is still built inside
// world.js. Flipping a zone to "v2" must leave every gameplay contract identical (colliders,
// interactables, seats, slots, save keys); visuals are free to change.
import * as legacyGate from "./legacy-gate.js";
import * as legacyPlaza from "./legacy-plaza.js";
import * as v2Gate from "./v2-gate.js";
import * as v2Plaza from "./v2-plaza.js";

// (which impl a World uses is its own: world.zones from zones/mode.js, decided before it is built;
// "v2" = the Blender zone GLB draws it, this module only registers gameplay. The paths and the
// scatter have no module here: their v2 switch is inside World.buildDecor.)
export const ZONES = {
  gate: { impl: "legacy" }, // the welcome plaza, where you arrive
  plaza: { impl: "legacy" }, // the willow in the middle (the Willow class itself is tree.js)
};

// impl -> zone id -> module; each module exports the parts it builds (see below)
const IMPLS = {
  legacy: { gate: legacyGate, plaza: legacyPlaza },
  v2: { gate: v2Gate, plaza: v2Plaza },
};

// the module that builds this zone, or null if the zone is not carved out of world.js
export function zoneModule(id, world = null) {
  const z = ZONES[id];
  if (!z) return null;
  const impl = world?.zones?.ids?.has(id) ? "v2" : z.impl;
  const mod = IMPLS[impl]?.[id];
  if (!mod) throw new Error(`zone "${id}": no "${impl}" implementation`);
  return mod;
}

// The World's hooks. Parts run with the World as `this`, at the very point of the build where
// world.js used to build them, so creation order and every RNG stream stay as they were.
//   interior(room, kit)   the room's INTERIORS builder (buildRoom: eager, or furnish later)
//   ringLamps(kit, ringR) the plaza ring's lamp posts (buildDecor)
export function zoneInterior(id, kit, world = null) {
  const mod = zoneModule(id, world);
  if (!mod?.interior) return null;
  return function (room) {
    return mod.interior.call(this, room, kit);
  };
}

export function buildZone(world, id, part, ...args) {
  const fn = zoneModule(id, world)?.[part];
  if (!fn) throw new Error(`zone "${id}": no part "${part}"`);
  return fn.call(world, ...args);
}
