// The teleport animation (TODO 29, user 2026-11-27: "add a cute animation between teleporting, not a loading screen. an
// animation."). Every jump (map travel, the games, the race grid, the trail, the coaster, meeting up, a fall) plays it:
// a sparkle portal opens at your feet, a spiral of hearts, stars and petals wraps round you, you hop in (the keyed
// avatar clip warp_out) and shrink away into it; a flurry of hearts sweeps across the view while the island moves you
// (any loading at the other end waits behind the portal there, which keeps turning); then you pop out of it (warp_in)
// in a puff of cloud and confetti. The pieces are the Blender kit assets/blender/props/warp/_build_warp.py (prp_warp,
// phones prp_warp_lite), fetched once on their own. Each kind of piece is one InstancedMesh with one unlit
// vertex-colour material; every particle is worked out from its burst's clock and a fixed seed (no state, nothing
// allocated per frame), so the partner's screen draws the very same thing.
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { MeshoptDecoder } from "three/examples/jsm/libs/meshopt_decoder.module.js";
import { zonePack } from "./zones/mode.js";

const PARTS = ["portal", "swirl", "heart", "star", "petal", "sparkle", "confetti", "puff"];
const CONF_COLS = ["#ff8fb1", "#ffd166", "#b79be8", "#8fd3f0", "#8fd3b6", "#ffffff", "#ffa8d6"];
const TAU = Math.PI * 2;

// the timeline (seconds), normal and quick (a repeat within a little while, a fall)
export const WARP = {
  out: 0.78, // the hop in: at VANISH of it you are gone
  vanish: 0.62,
  wipe: 0.5, // the flurry across the view, starting at WIPE_AT; the move happens at its peak
  wipeAt: 0.42,
  in: 0.95, // popping out: you are back (and free to move) at POP of it
  pop: 0.32,
  hold: 1.5, // the longest the portal waits at the other end for the place to be in
};

const clamp01 = (x) => (x < 0 ? 0 : x > 1 ? 1 : x);
const smooth = (a, b, x) => {
  const t = clamp01((x - a) / (b - a));
  return t * t * (3 - 2 * t);
};
const easeOutCubic = (x) => 1 - (1 - x) ** 3;
const easeInCubic = (x) => x * x * x;
const easeOutBack = (x) => {
  const c = 1.9;
  return 1 + (c + 1) * (x - 1) ** 3 + c * (x - 1) ** 2;
};
// a fixed random number for (seed, i, k)
const rnd = (s, i, k = 0) => {
  let h = (s * 374761393 + i * 668265263 + k * 2246822519) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
};

// the avatar's own motion round the clips: [scale, lift, extra turn]
export function outPose(u, out) {
  const v = clamp01(u);
  const hop = Math.sin(Math.PI * smooth(0.28, 0.82, v)) * 0.42 * (1 - smooth(0.6, 0.82, v) * 0.6);
  const s = 1 - easeInCubic(smooth(0.42, 0.8, v));
  // (a squash as you dip, a stretch as you spring)
  const sq = 1 - 0.08 * Math.sin(Math.PI * smooth(0.1, 0.32, v)) + 0.06 * Math.sin(Math.PI * smooth(0.32, 0.5, v));
  out.s = Math.max(0, s);
  out.sy = sq;
  out.y = hop;
  out.spin = easeInCubic(smooth(0.35, 0.8, v)) * TAU * 1.5;
  return out;
}
export function inPose(u, out) {
  const v = clamp01(u);
  const k = clamp01(v / 0.34);
  out.s = k <= 0 ? 0 : Math.max(0, easeOutBack(k));
  out.sy = 1 + 0.1 * Math.sin(Math.PI * smooth(0.3, 0.55, v)) - 0.08 * Math.sin(Math.PI * smooth(0.5, 0.7, v));
  out.y = Math.sin(Math.PI * smooth(0.0, 0.42, v)) * 0.35;
  out.spin = (1 - easeOutCubic(k)) * -TAU;
  return out;
}

let kitP = null;
function loadKit(small) {
  if (kitP) return kitP;
  const base = zonePack();
  if (!base) return (kitP = Promise.resolve(null));
  const sfx = small ? "_lite" : "";
  const re = new RegExp(`^INST_prp_warp${sfx}_(.+)$`);
  kitP = new GLTFLoader()
    .setMeshoptDecoder(MeshoptDecoder)
    .loadAsync(`${base}props/prp_warp${sfx}.glb`)
    .then((g) => {
      const m = new Map();
      g.scene.traverse((o) => {
        if (!o.isMesh) return;
        const role = o.userData?.tdd_role || re.exec(o.name)?.[1];
        if (!role) return;
        o.geometry.userData.kit = true;
        m.set(role, o.geometry);
        o.material?.dispose?.();
      });
      return m;
    })
    .catch((e) => {
      console.warn("warp kit", e);
      kitP = null;
      return null;
    });
  return kitP;
}

const _m = new THREE.Matrix4();
const _q = new THREE.Quaternion();
const _q2 = new THREE.Quaternion();
const _e = new THREE.Euler();
const _p = new THREE.Vector3();
const _s = new THREE.Vector3();
const _c = new THREE.Vector3();

export class Warp {
  constructor({ scene, camera, small }) {
    this.scene = scene;
    this.camera = camera;
    this.small = Boolean(small);
    this.bursts = [];
    this.wipes = [];
    this.mesh = null;
    this.n = {};
    const S = this.small;
    // per burst: the most pieces of a kind one burst draws
    this.per = { portal: 1, swirl: 2, heart: S ? 7 : 11, star: S ? 4 : 7, petal: S ? 7 : 12, sparkle: S ? 10 : 15, confetti: S ? 22 : 40, puff: S ? 5 : 7 };
    this.wipeN = { heart: S ? 64 : 80, petal: S ? 12 : 22, star: S ? 6 : 10, sparkle: S ? 8 : 14 };
    this.mat = new THREE.MeshBasicMaterial({ vertexColors: true });
    this.matIC = new THREE.MeshBasicMaterial({ vertexColors: true });
    // (the flurry over the view: drawn last, over everything, never hidden by what is close to the camera)
    this.wipeMat = new THREE.MeshBasicMaterial({ vertexColors: true, transparent: true, depthTest: false, depthWrite: false, fog: false });
    this.group = new THREE.Group();
    this.group.name = "warp";
    this.group.userData.live = true;
    scene.add(this.group);
    this.ready = loadKit(this.small).then((kit) => kit && this.build(kit));
  }

  build(kit) {
    const mk = (geo, mat, cap, order) => {
      const m = new THREE.InstancedMesh(geo, mat, cap);
      m.count = 0;
      m.visible = false;
      m.frustumCulled = false;
      m.castShadow = m.receiveShadow = false;
      m.renderOrder = order;
      m.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      this.group.add(m);
      return m;
    };
    const MAX = 4; // bursts at once (you and your person, each leaving and arriving)
    this.mesh = {};
    for (const p of PARTS) {
      const g = kit.get(p);
      if (!g) continue;
      const m = mk(g, p === "confetti" ? this.matIC : this.mat, this.per[p] * MAX, 0);
      if (p === "confetti") for (let i = 0; i < this.per[p] * MAX; i++) m.setColorAt(i, new THREE.Color(CONF_COLS[i % CONF_COLS.length]));
      this.mesh[p] = m;
    }
    this.wipeMesh = {};
    let o = 1000;
    for (const p of ["heart", "petal", "star", "sparkle"]) if (kit.get(p)) this.wipeMesh[p] = mk(kit.get(p), this.wipeMat, this.wipeN[p], o++);
    this.compiled = false;
    return true;
  }

  // the materials' programs, compiled ahead (compile(object) -> Promise: the island's warm-up), so the first jump
  // never links one on the spot
  async warm(compile) {
    await this.ready;
    if (!this.mesh || this.compiled) return;
    const all = [...Object.values(this.mesh), ...Object.values(this.wipeMesh)];
    for (const m of all) {
      m.count = 1;
      m.visible = true;
    }
    try {
      await compile(this.group);
    } catch {}
    for (const m of all) {
      m.count = 0;
      m.visible = false;
    }
    this.compiled = true;
  }

  get busy() {
    return this.bursts.length > 0 || this.wipes.length > 0;
  }

  // a burst at `at` (the feet): "out" (leaving), "hold" (the portal waiting at the other end), "in" (arriving)
  burst(kind, at, quick = false, seed = (Math.random() * 1e9) | 0) {
    const b = { kind, p: at.clone(), t: 0, q: quick ? 0.65 : 1, seed, from: null };
    b.D = kind === "out" ? WARP.out * b.q : kind === "in" ? WARP.in * b.q : Infinity;
    this.bursts.push(b);
    return b;
  }
  // a waiting portal opens up: you come out of it
  release(b) {
    if (!b) return;
    b.from = b.t;
    b.kind = "in";
    b.t = 0;
    b.D = WARP.in * b.q;
  }
  end(b) {
    const i = this.bursts.indexOf(b);
    if (i >= 0) this.bursts.splice(i, 1);
  }
  wipe(quick = false, seed = (Math.random() * 1e9) | 0) {
    const w = { t: 0, D: WARP.wipe * (quick ? 0.75 : 1), seed };
    this.wipes.push(w);
    return w;
  }
  clear() {
    this.bursts.length = 0;
    this.wipes.length = 0;
    this.update(0);
  }

  put(part, x, y, z, q, sx, sy = sx, sz = sx, wipe = false) {
    const m = (wipe ? this.wipeMesh : this.mesh)[part];
    if (!m) return;
    const key = wipe ? "w" + part : part;
    const i = this.n[key] || 0;
    if (i >= m.instanceMatrix.count) return;
    if (sx < 1e-4) return;
    _p.set(x, y, z);
    _s.set(sx, sy, sz);
    _m.compose(_p, q, _s);
    _m.toArray(m.instanceMatrix.array, i * 16);
    this.n[key] = i + 1;
  }
  qy(a, x = 0, z = 0) {
    return _q.setFromEuler(_e.set(x, a, z, "YXZ"));
  }

  update(dt) {
    for (const k in this.n) this.n[k] = 0;
    if (this.mesh) {
      for (let i = this.bursts.length - 1; i >= 0; i--) {
        const b = this.bursts[i];
        b.t += dt;
        if (b.t >= b.D) {
          this.bursts.splice(i, 1);
          continue;
        }
        if (b.kind === "out") this.out(b);
        else if (b.kind === "in") this.in(b);
        else this.hold(b);
      }
      for (let i = this.wipes.length - 1; i >= 0; i--) {
        const w = this.wipes[i];
        w.t += dt;
        if (w.t >= w.D) {
          this.wipes.splice(i, 1);
          continue;
        }
        this.flurry(w);
      }
    } else {
      // (no kit: the timeline still runs, just without the pieces)
      for (let i = this.bursts.length - 1; i >= 0; i--) if ((this.bursts[i].t += dt) >= this.bursts[i].D) this.bursts.splice(i, 1);
      for (let i = this.wipes.length - 1; i >= 0; i--) if ((this.wipes[i].t += dt) >= this.wipes[i].D) this.wipes.splice(i, 1);
      return;
    }
    const upd = (m, key) => {
      const c = this.n[key] || 0;
      m.count = c;
      m.visible = c > 0;
      if (c) m.instanceMatrix.needsUpdate = true;
    };
    for (const p in this.mesh) upd(this.mesh[p], p);
    for (const p in this.wipeMesh) upd(this.wipeMesh[p], "w" + p);
  }

  portal(b, s, t) {
    if (s <= 0.001) return;
    this.put("portal", b.p.x, b.p.y + 0.015, b.p.z, this.qy(t * 1.8), s, s * (0.8 + 0.2 * s), s);
  }
  swirls(b, t, r, sy, grow, speed = 6.5) {
    if (grow <= 0.001) return;
    for (let k = 0; k < 2; k++) this.put("swirl", b.p.x, b.p.y + 0.02, b.p.z, this.qy(t * speed + k * Math.PI), r * grow, sy * grow, r * grow);
  }
  twinkles(b, n, t, live, rMax = 0.8, yMax = 1.9) {
    if (live <= 0.001) return;
    for (let i = 0; i < n; i++) {
      const a = rnd(b.seed, i, 41) * TAU;
      const r = 0.25 + rnd(b.seed, i, 42) * (rMax - 0.25);
      const y = 0.15 + rnd(b.seed, i, 43) * (yMax - 0.15);
      const tw = Math.sin(Math.PI * ((t * (1.8 + rnd(b.seed, i, 44)) + rnd(b.seed, i, 45)) % 1));
      const s = 0.55 + 0.6 * rnd(b.seed, i, 46);
      this.put("sparkle", b.p.x + Math.cos(a + t * 0.8) * r, b.p.y + y, b.p.z + Math.sin(a + t * 0.8) * r, this.qy(a + Math.PI / 2, 0, t * 2 + i), s * tw * live);
    }
  }
  // pieces flying out from a point (the moment you vanish or appear)
  pop(b, part, n, k, at = 0.55, reach = 0.9, size = 1, salt = 50) {
    if (k <= 0 || k >= 1) return;
    const e = easeOutCubic(k);
    for (let i = 0; i < n; i++) {
      const a = (i / n) * TAU + rnd(b.seed, i, salt);
      const up = (rnd(b.seed, i, salt + 1) - 0.35) * 1.2;
      const d = reach * (0.7 + 0.5 * rnd(b.seed, i, salt + 2)) * e;
      const s = Math.sin(Math.PI * k) * size * (0.8 + 0.4 * rnd(b.seed, i, salt + 3));
      this.put(part, b.p.x + Math.cos(a) * d, b.p.y + at + up * d, b.p.z + Math.sin(a) * d, this.qy(-a + Math.PI / 2, 0, k * 5 + i), s);
    }
  }

  out(b) {
    const t = b.t / b.q;
    const u = b.t / b.D;
    const P = this.per;
    const open = easeOutBack(clamp01(u / 0.22));
    const close = 1 - smooth(0.84, 1, u);
    this.portal(b, 0.95 * open * close, t);
    const grow = easeOutCubic(clamp01(u / 0.2)) * (1 - smooth(0.8, 0.97, u));
    this.swirls(b, t, 1 - 0.5 * smooth(0.35, 0.85, u), 1 - 0.75 * smooth(0.5, 0.95, u), grow);
    // the spiral of hearts, stars and petals, closing in and sinking into the portal
    const sink = smooth(0.5, 0.86, u);
    const orbit = (part, n, salt, size) => {
      for (let i = 0; i < n; i++) {
        const g = easeOutBack(clamp01((u - rnd(b.seed, i, salt) * 0.22) / 0.2));
        if (g <= 0) continue;
        const a = rnd(b.seed, i, salt + 1) * TAU + t * (3.2 + 2 * rnd(b.seed, i, salt + 2)) * (1 + sink * 1.6);
        const r = (0.5 + 0.32 * rnd(b.seed, i, salt + 3)) * (1 - 0.78 * sink) * (0.6 + 0.4 * Math.min(1, g));
        const y = (0.2 + 1.55 * rnd(b.seed, i, salt + 4)) * (1 - sink) + 0.08 * Math.sin(t * 5 + i) + 0.06;
        const s = size * (0.75 + 0.5 * rnd(b.seed, i, salt + 5)) * g * (1 - smooth(0.8, 0.95, u));
        const spin = part === "petal" ? t * (3 + i % 3) : Math.sin(t * 4 + i) * 0.4;
        this.put(part, b.p.x + Math.cos(a) * r, b.p.y + y, b.p.z + Math.sin(a) * r, this.qy(-a, part === "petal" ? t * 2 + i : 0, spin), s);
      }
    };
    orbit("heart", P.heart - 4, 10, 1.15);
    orbit("star", P.star - 1, 20, 1.0);
    orbit("petal", P.petal, 30, 1.25);
    this.twinkles(b, P.sparkle - 6, t, grow);
    // pop! where you were: sparkles and a few hearts burst out
    const k = (u - 0.74) / 0.26;
    this.pop(b, "sparkle", 6, k, 0.5, 0.95, 1.3, 60);
    this.pop(b, "heart", 4, k, 0.55, 0.75, 1.0, 70);
    this.pop(b, "star", 1, k, 0.9, 0.5, 0.9, 80);
  }

  hold(b) {
    const t = b.t;
    const open = easeOutBack(clamp01(t / 0.3));
    this.portal(b, 0.95 * open, t);
    // the portal fizzing: a low spiral turning fast, twinkles rising off it
    this.swirls(b, t, 0.85, 0.32 + 0.06 * Math.sin(t * 6), open, 9);
    this.twinkles(b, this.per.sparkle - 6, t, open, 0.6, 1.1);
  }

  in(b) {
    const t = b.t / b.q;
    const u = b.t / b.D;
    const P = this.per;
    const pt = (b.from || 0) + b.t;
    const open = b.from != null ? 1 : easeOutBack(clamp01(u / 0.15));
    this.portal(b, 0.95 * open * (1 - smooth(0.45, 0.7, u)), pt);
    // the spiral unwinds and flies off
    this.swirls(b, pt, 0.85 + 0.9 * smooth(0, 0.45, u), 0.32 + 0.5 * smooth(0, 0.3, u), 1 - smooth(0.2, 0.5, u), 9);
    // the pop as you come out
    this.pop(b, "sparkle", 6, u / 0.36, 0.7, 1.1, 1.4, 90);
    this.pop(b, "star", 3, (u - 0.04) / 0.45, 0.9, 1.0, 1.1, 100);
    // a ring of cloud puffs rolling out over the ground
    for (let i = 0; i < P.puff; i++) {
      const k = clamp01((u - 0.02) / 0.6);
      if (k <= 0 || k >= 1) continue;
      const a = (i / P.puff) * TAU + rnd(b.seed, i, 110) * 0.6;
      const r = 0.3 + 0.8 * easeOutCubic(k);
      const s = Math.sin(Math.PI * k) ** 0.7 * (0.85 + 0.35 * rnd(b.seed, i, 111)) * 1.5;
      this.put("puff", b.p.x + Math.cos(a) * r, b.p.y + 0.12 + 0.25 * k, b.p.z + Math.sin(a) * r, this.qy(a), s);
    }
    // confetti thrown up, tumbling down onto the ground
    const tc = t - 0.03;
    if (tc > 0)
      for (let i = 0; i < P.confetti; i++) {
        const a = rnd(b.seed, i, 120) * TAU;
        const sp = 0.9 + 1.9 * rnd(b.seed, i, 121);
        const vy = 3.0 + 2.6 * rnd(b.seed, i, 122);
        const y0 = 0.5;
        const land = (vy + Math.sqrt(vy * vy + 19.6 * (y0 - 0.03))) / 9.8;
        const te = Math.min(tc, land);
        const h = ((1 - Math.exp(-1.6 * te)) / 1.6) * sp;
        // (falling paper drifts: a slow sway once it tops out)
        const sway = Math.sin(te * 7 + i) * 0.08 * smooth(0.25, 0.6, te);
        const y = Math.max(0.03, y0 + vy * te - 4.9 * te * te * 0.72);
        const s = 1.3 * (1 - smooth(0.8, 1, u));
        const sx = te * (8 + 6 * rnd(b.seed, i, 123));
        this.put("confetti", b.p.x + Math.cos(a) * h + sway, b.p.y + y, b.p.z + Math.sin(a) * h, _q2.setFromEuler(_e.set(sx, a, te * 5, "XYZ")), s);
      }
    // hearts floating up off you
    for (let i = 0; i < P.heart - 6; i++) {
      const k = clamp01((u - 0.12 - i * 0.05) / 0.75);
      if (k <= 0 || k >= 1) continue;
      const a = rnd(b.seed, i, 130) * TAU;
      const r = 0.25 + 0.35 * k;
      const s = easeOutBack(clamp01(k / 0.25)) * (1 - smooth(0.7, 1, k)) * 1.1;
      this.put("heart", b.p.x + Math.cos(a) * r + Math.sin(k * 9 + i) * 0.08, b.p.y + 0.9 + 1.2 * k, b.p.z + Math.sin(a) * r, this.qy(-a + Math.PI / 2, 0, Math.sin(k * 8 + i) * 0.3), s);
    }
    this.twinkles(b, 6, pt, 1 - smooth(0.5, 0.9, u), 0.9, 1.8);
  }

  // the flurry: hearts spiral in from the edges of the view until they cover it, then spiral out again
  flurry(w) {
    const cam = this.camera;
    const u = w.t / w.D;
    const d = 0.55;
    const halfH = Math.tan(THREE.MathUtils.degToRad(cam.fov) / 2) * d;
    const halfW = halfH * cam.aspect;
    let rm, ao, sc;
    if (u < 0.5) {
      const e = easeOutCubic(u / 0.5);
      rm = 1 + 1.7 * (1 - e);
      ao = 2.4 * (1 - e);
      sc = 0.35 + 0.65 * easeOutBack(e);
    } else {
      const e = easeInCubic((u - 0.5) / 0.5);
      rm = 1 + 1.9 * e;
      ao = -2.4 * e;
      sc = 1 - 0.45 * e;
    }
    const cq = cam.quaternion;
    const place = (part, nx, ny, spin, size) => {
      // (spiralled about the middle of the view)
      const r = Math.hypot(nx, ny) * rm + (rm - 1) * 0.6;
      const a = Math.atan2(ny, nx) + ao;
      _c.set(Math.cos(a) * r * halfW, Math.sin(a) * r * halfH, -d).applyMatrix4(cam.matrixWorld);
      _q2.setFromAxisAngle(_p.set(0, 0, 1), spin + ao);
      _q.copy(cq).multiply(_q2);
      this.put(part, _c.x, _c.y, _c.z, _q, size, size, size * 0.6, true);
    };
    // two staggered grids of hearts, about square cells whatever the shape of the screen
    const N = this.wipeN.heart;
    const cols = Math.max(3, Math.round(Math.sqrt((N / 2) * cam.aspect)));
    const rows = Math.max(3, Math.ceil(N / 2 / cols));
    const cw = (2 * halfW) / cols;
    const ch = (2 * halfH) / rows;
    const hs = (Math.max(cw, ch) * 2.3) / 0.2;
    let j = 0;
    for (let g = 0; g < 2; g++)
      for (let y = 0; y < rows; y++)
        for (let x = 0; x < cols; x++, j++) {
          const nx = ((x + 0.5 + g * 0.5) / cols) * 2 - 1 + (rnd(w.seed, j, 1) - 0.5) * 0.12;
          const ny = ((y + 0.5 + g * 0.5) / rows) * 2 - 1 + (rnd(w.seed, j, 2) - 0.5) * 0.12;
          place("heart", nx * 1.08, ny * 1.08, (rnd(w.seed, j, 3) - 0.5) * 0.9, hs * sc * (0.85 + 0.3 * rnd(w.seed, j, 4)));
        }
    // petals, stars and twinkles over them, tumbling
    const deco = (part, n, salt, base) => {
      for (let i = 0; i < n; i++) {
        const nx = rnd(w.seed, i, salt) * 2 - 1;
        const ny = rnd(w.seed, i, salt + 1) * 2 - 1;
        place(part, nx, ny, w.t * (4 + 3 * rnd(w.seed, i, salt + 2)) + i, ((Math.max(cw, ch) * base) / 0.12) * sc);
      }
    };
    deco("petal", this.wipeN.petal, 10, 0.9);
    deco("star", this.wipeN.star, 20, 0.9);
    deco("sparkle", this.wipeN.sparkle, 30, 1.0);
  }
}
