// "My face": a photo of your own face on your avatar, as a soft toon decal over the front of the head (W18).
// The face lives only in your own saves (the tdd3d.avatarface.v1 key, which sync.js keeps in your own row): a small
// square crop (~256 px webp, jpeg where webp can't be written) plus its mask shape and edge softness. Your look
// carries only its id (faceImg), so the other screen fetches it from your row (members only) when it sees a new id.
// The decal is drawn here: toon posterize, the colours pulled toward the avatar's skin, rosy cheeks, a soft oval edge.
import * as THREE from "three";

export const FACE_KEY = "tdd3d.avatarface.v1";
// the decal's square on the face, in unit face coords (w17_look surf: u across, v up; R = the head radius)
export const FACE_BOX = { u0: -0.55, u1: 0.55, v0: -0.8, v1: 0.3, R: 0.4 };
// where the guides sit in the crop (0..1 from the top-left): the eye line and the mouth line
export const FACE_GUIDE = { eyes: 0.4, mouth: 0.7 };

const data = new Map(); // id -> { img: HTMLImageElement, shape, soft }
const asks = new Map(); // id -> Promise<boolean>
const texs = new Map(); // id|skin -> texture
const geos = new WeakMap(); // skull geometry -> decal geometry

export function hashOf(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 0x01000193);
  return (h >>> 0).toString(36) + s.length.toString(36);
}

export function myFace() {
  try {
    const f = JSON.parse(localStorage.getItem(FACE_KEY) || "null");
    return f && typeof f.img === "string" && f.id ? f : null;
  } catch {
    return null;
  }
}
export function saveMyFace(img, shape, soft) {
  const f = { v: 1, img, shape, soft: Math.round(soft * 100) / 100 };
  f.id = hashOf(img + shape + f.soft);
  try {
    localStorage.setItem(FACE_KEY, JSON.stringify(f));
  } catch {
    return null;
  }
  return f.id;
}
export function clearMyFace() {
  try {
    localStorage.removeItem(FACE_KEY);
  } catch {}
}

const loadImg = (src) =>
  new Promise((res) => {
    const im = new Image();
    im.onload = () => res(im);
    im.onerror = () => res(null);
    im.src = src;
  });

async function fromRow(user, id) {
  const sb = window.__tddBridge?.supabase;
  if (!sb || !user) return null;
  for (let k = 0; k < 6; k++) {
    try {
      const { data: row } = await sb.from("widgets").select("data").eq("id", `__prefs:game:${user}`).maybeSingle();
      const raw = row?.data?.values?.[FACE_KEY];
      const f = raw ? JSON.parse(raw) : null;
      if (f?.id === id) return f;
    } catch {}
    // (the owner's save goes up a few seconds after a change: look again a little later)
    await new Promise((r) => setTimeout(r, 3000 * (k + 1)));
  }
  return null;
}

// the face for an id when it is here (decoded), else null
export const faceReady = (id) => (id && data.get(id)) || null;
// fetch (yours: from this device; theirs: from their row) -> true once ready
export function wantFace(id, user) {
  if (!id) return Promise.resolve(false);
  if (data.has(id)) return Promise.resolve(true);
  if (asks.has(id)) return asks.get(id);
  const p = (async () => {
    const mine = myFace();
    const f = mine?.id === id ? mine : await fromRow(user, id);
    const img = f && (await loadImg(f.img));
    if (!img) return false;
    data.set(id, { img, shape: f.shape === "circle" ? "circle" : "oval", soft: Number.isFinite(f.soft) ? f.soft : 0.5 });
    return true;
  })();
  asks.set(id, p);
  p.then((ok) => ok || setTimeout(() => asks.delete(id), 20000));
  return p;
}
// (a new face of your own: decoded right away, so the look changes at once)
export async function primeFace(id) {
  asks.delete(id);
  return wantFace(id, null);
}

export function maskOf(shape) {
  return shape === "circle" ? { rx: 0.45, ry: 0.45 } : { rx: 0.4, ry: 0.49 };
}

const hexRgb = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16) || 0);
const sm = (a, b, x) => {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
};

// the toon face: softened, posterized (soft steps), pulled toward the avatar's skin, rosy cheeks, a soft oval edge
export function faceCanvas(face, skin, N = 256) {
  const c = document.createElement("canvas");
  c.width = c.height = N;
  const g = c.getContext("2d", { willReadFrequently: true });
  const small = document.createElement("canvas");
  small.width = small.height = 88;
  small.getContext("2d").drawImage(face.img, 0, 0, 88, 88);
  g.imageSmoothingQuality = "high";
  g.drawImage(small, 0, 0, N, N);
  const blur = g.getImageData(0, 0, N, N).data;
  g.clearRect(0, 0, N, N);
  g.drawImage(face.img, 0, 0, N, N);
  const im = g.getImageData(0, 0, N, N);
  const d = im.data;
  const { rx, ry } = maskOf(face.shape);
  // the photo's own skin: the cheeks and nose area
  let sr = 0, sg = 0, sb = 0, sn = 0;
  for (let y = Math.floor(N * 0.45); y < N * 0.68; y++)
    for (let x = Math.floor(N * 0.3); x < N * 0.7; x++) {
      const i = (y * N + x) * 4;
      sr += blur[i];
      sg += blur[i + 1];
      sb += blur[i + 2];
      sn++;
    }
  const sk = hexRgb(skin || "#f6cfb4");
  const gain = [sr, sg, sb].map((v, k) => Math.min(1.7, Math.max(0.55, sk[k] / Math.max(8, v / Math.max(1, sn)))));
  const soft = Math.min(1, Math.max(0, face.soft ?? 0.5));
  const steps = 6;
  for (let y = 0; y < N; y++)
    for (let x = 0; x < N; x++) {
      const i = (y * N + x) * 4;
      const dx = (x + 0.5) / N - 0.5;
      const dy = (y + 0.5) / N - 0.5;
      const r = Math.hypot(dx / rx, dy / ry);
      let R = d[i] * 0.5 + blur[i] * 0.5;
      let G = d[i + 1] * 0.5 + blur[i + 1] * 0.5;
      let B = d[i + 2] * 0.5 + blur[i + 2] * 0.5;
      // colour match: toward the avatar's skin (strongest on skin-like pixels, eyes and brows keep their own darks)
      R = R * (1 + (gain[0] - 1) * 0.8);
      G = G * (1 + (gain[1] - 1) * 0.8);
      B = B * (1 + (gain[2] - 1) * 0.8);
      // toon: the brightness in a few soft steps, the colour a touch richer
      const L = (0.299 * R + 0.587 * G + 0.114 * B) / 255;
      const q = L * steps;
      const f = q - Math.floor(q);
      const Lq = (Math.floor(q) + sm(0.3, 0.7, f)) / steps;
      const k = L > 0.004 ? (0.35 * L + 0.65 * Lq) / L : 1;
      R *= k;
      G *= k;
      B *= k;
      const m = (R + G + B) / 3;
      R = m + (R - m) * 1.14;
      G = m + (G - m) * 1.14;
      B = m + (B - m) * 1.14;
      // rosy cheeks
      for (const cx of [0.29, 0.71]) {
        const b = Math.max(0, 1 - Math.hypot((x / N - cx) / 0.1, (y / N - 0.64) / 0.07));
        const a = 0.28 * b * b;
        R += (255 - R) * a;
        G += (143 - G) * a;
        B += (177 - B) * a;
      }
      // the edge melts into the head's skin
      const e = sm(0.62 - 0.25 * soft, 1.0, r);
      R += (sk[0] - R) * e * 0.6;
      G += (sk[1] - G) * e * 0.6;
      B += (sk[2] - B) * e * 0.6;
      d[i] = R;
      d[i + 1] = G;
      d[i + 2] = B;
      d[i + 3] = 255 * (1 - sm(0.8 - 0.3 * soft, 1.0, r));
    }
  g.putImageData(im, 0, 0);
  return c;
}

function faceTexture(id, face, skin) {
  const k = id + "|" + skin;
  if (texs.has(k)) return texs.get(k);
  const t = new THREE.CanvasTexture(faceCanvas(face, skin));
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  if (texs.size > 8) {
    const [k0, t0] = texs.entries().next().value;
    t0.dispose();
    texs.delete(k0);
  }
  texs.set(k, t);
  return t;
}

const _ray = new THREE.Raycaster();
const _o = new THREE.Vector3();
const _d = new THREE.Vector3(0, 0, -1);
// the decal: a grid over the face square, each point cast straight back onto the skull (nose and cheeks included)
// and lifted a few millimetres off it along the surface
function decalGeometry(skull) {
  if (geos.has(skull.geometry)) return geos.get(skull.geometry);
  const m = new THREE.Mesh(skull.geometry);
  m.matrix.copy(skull.matrix);
  m.matrixAutoUpdate = false;
  m.updateMatrixWorld(true);
  const { u0, u1, v0, v1, R } = FACE_BOX;
  const n = 26;
  const pos = [];
  const uv = [];
  const idx = [];
  const p = new THREE.Vector3();
  for (let j = 0; j <= n; j++)
    for (let i = 0; i <= n; i++) {
      const u = u0 + ((u1 - u0) * i) / n;
      const v = v0 + ((v1 - v0) * j) / n;
      _o.set(u * R, v * R, R * 2);
      _ray.set(_o, _d);
      const hit = _ray.intersectObject(m, false)[0];
      if (hit) {
        const nn = hit.face.normal.clone().transformDirection(m.matrixWorld);
        p.copy(hit.point).addScaledVector(nn, 0.0045);
      } else {
        const z = Math.sqrt(Math.max(0.02, 1 - u * u - v * v));
        p.set(u, v, z).multiplyScalar(R + 0.0045);
      }
      pos.push(p.x, p.y, p.z);
      uv.push(i / n, j / n);
    }
  for (let j = 0; j < n; j++)
    for (let i = 0; i < n; i++) {
      const a = j * (n + 1) + i;
      idx.push(a, a + 1, a + n + 2, a, a + n + 2, a + n + 1);
    }
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute("uv", new THREE.Float32BufferAttribute(uv, 2));
  g.setIndex(idx);
  g.computeVertexNormals();
  g.userData.kit = true; // (shared between avatars: never disposed with one of them)
  geos.set(skull.geometry, g);
  return g;
}

// on a freshly dressed avatar: the face decal on its head joint
export function faceOn(head, skull, id, skin) {
  const face = faceReady(id);
  if (!face || !head || !skull) return null;
  const mat = new THREE.MeshStandardMaterial({
    map: faceTexture(id, face, skin),
    transparent: true,
    depthWrite: false,
    roughness: 0.82,
    metalness: 0,
    polygonOffset: true,
    polygonOffsetFactor: -2,
    polygonOffsetUnits: -2,
  });
  const m = new THREE.Mesh(decalGeometry(skull), mat);
  m.name = "avatar.face";
  m.renderOrder = 2;
  m.castShadow = false;
  m.receiveShadow = true;
  head.add(m);
  return m;
}
