// Into the water (user 2026-11-27: "i should sink in the water not just walk on it"). Every pool you can walk into
// (the lake, the garden pond, the fountain's basin, the cave's lagoon) is as deep as its real water draws it
// (render/water.js depthAt: the same shore distance and depth profile the surface shades its bed with):
//   - shallow: you wade, sunk to the bed with the water round your legs, your arms lifting clear (the Blender clip
//     `wade`, by depth), slower, the water sloshing and splashing round your steps;
//   - deep: you sink to swimming depth and float with your head and shoulders out, treading water when still and
//     paddling when moving (the Blender clips `swim_tread` / `swim_stroke`, anim/graphs.js), a bob on each stroke;
//   - in: a splash, ripples and drops as you wade in; jumping in, a plunge (a splash crown, a foam ring, a dip under
//     and a bob back up); out: the body rises with the bed as you walk up the shore, dripping for a moment;
//   - rides: the scooter and the kart only go into ankle-deep water, the unicorn up to its knees: deeper water stops
//     them like a shore, and they sink into what they may go in, throwing spray. Land in deep water from a jump and
//     the ride poofs home and you swim.
// One Swimmer per avatar (yours and your person's, from what each screen sees: no message). The splash parts are
// Blender's (assets/blender/props/swimfx/_build_swimfx.py -> props/prp_swimfx_parts.glb: drop, crown, foam).
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { MeshoptDecoder } from "three/examples/jsm/libs/meshopt_decoder.module.js";
import { zonePack } from "./zones/mode.js";
import { waterOf } from "./render/water.js";

// the waterline above the root while swimming (x the body's k): the shoulders (rig: 0.91), so head and shoulders
// are out of the water; the swim clips carry the body's lean and bob round it
export const SWIM_LINE = 0.78;
// the pools you can walk into (the troughs, wells and the fountain's top bowl are not to be swum in)
const WALK_IN = new Set(["lake", "pond", "lagoon", "fountain"]);
// how deep each ride may go: wheels to the axle, the unicorn to its knees
export const RIDE_DEPTH = { kart: 0.22, scooter: 0.26, unicorn: 0.6 };
const smooth = (a, b, x) => {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
};

// the water under world (x, z) you can be in: { y, depth, kind } or null
export function waterUnder(world, x, z) {
  const w = waterOf(world).depthAt(x, z);
  if (!w || !WALK_IN.has(w.kind)) return null;
  // (the fountain: only its wide basin, never the small top bowl or the well)
  if (w.kind === "fountain" && w.pool.r < 0.8) return null;
  return w;
}

// ---- the splashes: drops, crowns and foam from one small Blender kit, drawn as instanced pools ----------------------
const _m = new THREE.Matrix4();
const _q = new THREE.Quaternion();
const _p = new THREE.Vector3();
const _s = new THREE.Vector3();
const _v = new THREE.Vector3();
const UP = new THREE.Vector3(0, 1, 0);
export class SwimFx {
  constructor(scene, { lowEnd = false } = {}) {
    this.scene = scene;
    this.k = lowEnd ? 0.55 : 1;
    this.drops = null; // { mesh, cap, n, d }
    this.bursts = []; // crown / foam meshes, each { m, kind, t, life, y, s }
    this.geo = null;
    this.load();
  }
  load() {
    const base = zonePack();
    if (!base) return;
    new GLTFLoader()
      .setMeshoptDecoder(MeshoptDecoder)
      .loadAsync(base + "props/prp_swimfx_parts.glb")
      .then((g) => {
        const geo = {};
        g.scene.traverse((o) => {
          if (!o.isMesh) return;
          const role = o.userData?.tdd_role || /^INST_prp_swimfx_parts_(.+)$/.exec(o.name)?.[1];
          if (role) geo[role] = o.geometry;
          o.material?.dispose?.();
        });
        this.build(geo);
      })
      .catch((e) => console.warn("swim fx", e));
  }
  build(geo) {
    this.geo = geo;
    // (wet and glossy, a touch see-through; lit like everything else so they sit in the theme's light)
    const mat = (o = {}) => new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.12, metalness: 0, transparent: true, opacity: 0.85, depthWrite: false, emissive: "#9fd6f2", emissiveIntensity: 0.18, ...o });
    if (geo.drop) {
      const cap = Math.ceil(150 * this.k);
      const mesh = new THREE.InstancedMesh(geo.drop, mat({ opacity: 0.9 }), cap);
      mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      mesh.count = 0;
      mesh.frustumCulled = false;
      mesh.castShadow = false;
      mesh.renderOrder = 2;
      mesh.name = "swimfx_drop";
      this.scene.add(mesh);
      // per drop: px py pz vx vy vz life max size floor
      this.drops = { mesh, cap, n: 0, d: new Float32Array(cap * 10) };
    }
    for (const kind of ["crown", "foam"]) {
      if (!geo[kind]) continue;
      for (let i = 0; i < 3; i++) {
        const m = new THREE.Mesh(geo[kind], mat(kind === "foam" ? { opacity: 0.8, roughness: 0.5, polygonOffset: true, polygonOffsetFactor: -6, polygonOffsetUnits: -12 } : { side: THREE.DoubleSide }));
        m.visible = false;
        m.castShadow = false;
        m.renderOrder = 2;
        m.name = "swimfx_" + kind;
        this.scene.add(m);
        this.bursts.push({ m, kind, t: 1, life: 1, y: 0, s: 1 });
      }
    }
  }
  drop(x, y, z, vx, vy, vz, floor, size = 1) {
    const P = this.drops;
    if (!P) return;
    let i = P.n;
    if (i >= P.cap) i = Math.floor(Math.random() * P.cap);
    else P.n++;
    const o = i * 10;
    const d = P.d;
    d[o] = x;
    d[o + 1] = y;
    d[o + 2] = z;
    d[o + 3] = vx;
    d[o + 4] = vy;
    d[o + 5] = vz;
    d[o + 6] = d[o + 7] = 1.6;
    d[o + 8] = size * (0.7 + Math.random() * 0.6);
    d[o + 9] = floor;
  }
  // a fan of drops thrown up round (x, z) on the surface y: n of them, out at `spread` m/s, up at `up`, pushed along (hx, hz)
  spray(x, y, z, n, spread, up, hx = 0, hz = 0, r = 0.15, size = 1) {
    n = Math.max(1, Math.round(n * this.k));
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2;
      const s = spread * (0.4 + Math.random() * 0.6);
      this.drop(x + Math.cos(a) * r, y + 0.02, z + Math.sin(a) * r, Math.cos(a) * s + hx, up * (0.55 + Math.random() * 0.6), Math.sin(a) * s + hz, y, size);
    }
  }
  burst(kind, x, y, z, s = 1) {
    let b = null;
    for (const q of this.bursts) if (q.kind === kind && (!b || q.t > b.t)) b = q;
    if (!b) return;
    b.t = 0;
    b.life = kind === "crown" ? 0.6 : 2.2;
    b.y = y;
    b.s = s;
    b.m.position.set(x, y + (kind === "foam" ? 0.015 : -0.03), z);
    b.m.rotation.set(0, Math.random() * Math.PI * 2, 0);
    b.m.visible = true;
  }
  update(dt) {
    for (const b of this.bursts) {
      if (b.t >= 1) continue;
      b.t = Math.min(1, b.t + dt / b.life);
      const t = b.t;
      if (b.kind === "crown") {
        // up fast, flaring out as it rises, then it slumps back into the water
        const e = 1 - Math.pow(1 - t, 3);
        b.m.scale.set(b.s * (0.55 + 0.75 * e), b.s * (1.25 * Math.sin(Math.PI * Math.min(1, t * 1.15)) + 0.02), b.s * (0.55 + 0.75 * e));
        b.m.material.opacity = 0.85 * Math.min(1, (1 - t) * 2.2);
      } else {
        const e = 1 - Math.pow(1 - t, 2);
        b.m.scale.set(b.s * (0.55 + 0.8 * e), 1, b.s * (0.55 + 0.8 * e));
        b.m.material.opacity = 0.75 * Math.min(1, t * 8) * (1 - t);
      }
      if (t >= 1) b.m.visible = false;
    }
    const P = this.drops;
    if (!P || !P.n) {
      if (P) P.mesh.count = 0;
      return;
    }
    const d = P.d;
    for (let i = 0; i < P.n; i++) {
      const o = i * 10;
      d[o + 6] -= dt;
      d[o + 4] -= 9.8 * dt;
      d[o] += d[o + 3] * dt;
      d[o + 1] += d[o + 4] * dt;
      d[o + 2] += d[o + 5] * dt;
      // (back into the water: gone)
      if (d[o + 6] <= 0 || (d[o + 4] < 0 && d[o + 1] < d[o + 9])) {
        P.n--;
        if (i !== P.n) d.copyWithin(o, P.n * 10, P.n * 10 + 10);
        i--;
        continue;
      }
      // (drawn along its flight: the tail streaks behind, longer the faster it goes)
      _v.set(d[o + 3], d[o + 4], d[o + 5]);
      const sp = _v.length();
      _q.setFromUnitVectors(UP, sp > 1e-3 ? _v.multiplyScalar(-1 / sp) : UP);
      const sc = d[o + 8] * Math.min(1, (d[o + 7] - d[o + 6]) / 0.05);
      _m.compose(_p.set(d[o], d[o + 1], d[o + 2]), _q, _s.set(sc, sc * (1 + Math.min(1.2, sp * 0.12)), sc));
      P.mesh.setMatrixAt(i, _m);
    }
    P.mesh.count = P.n;
    P.mesh.instanceMatrix.needsUpdate = true;
  }
}

// ---- one avatar in the water ---------------------------------------------------------------------------------
export class Swimmer {
  // fx: SwimFx, audio: the island's, self: yours (louder, and the camera follows)
  constructor({ world, fx, audio, self = false }) {
    Object.assign(this, { world, fx, audio, self });
    this.water = waterOf(world);
    this.off = 0; // the root below the feet's ground (negative), sprung
    this.vel = 0;
    this.in = false;
    this.swimming = false;
    this.depth = 0;
    this.y = 0; // the surface
    this.wade = 0;
    this.step = 0;
    this.stroke = 0;
    this.drip = 0;
    this.still = 0;
    this.lastY = null;
    this.wasAir = false;
    this.airVy = 0;
    this.swamAgo = 99;
    this.plungeT = 0;
  }
  // pos: the feet (physics), k: the body's size, o: { airborne, vy, speed, heading, avatar, ride (kind or null) }
  update(dt, pos, k, o = {}) {
    const fx = this.fx;
    const w = waterUnder(this.world, pos.x, pos.z);
    const line = SWIM_LINE * k;
    // in the water: standing on its bed (the island's ground under the surface), not up on a jetty or in the air over it
    const inNow = Boolean(w) && pos.y <= w.y + 0.12 && pos.y > w.y - 3 && !o.airborne;
    const wasIn = this.in;
    const depth = inNow ? w.depth : 0;
    this.depth = depth;
    if (w) this.y = w.y;
    if (o.ride) {
      // on a ride: sunk to what it may go in (its own limit), never swimming
      this.swimming = false;
      this.wade = 0;
    } else {
      // (swimming once the bed is too deep to stand with the shoulders out; standing again a little shallower)
      if (!inNow) this.swimming = false;
      else if (!this.swimming && depth > line * 0.94) this.swimming = true;
      else if (this.swimming && depth < line * 0.8) this.swimming = false;
      this.wade = inNow && !this.swimming ? 0.9 * smooth(0.06, 0.5 * k, depth) : 0;
    }
    const sinkTo = !inNow ? 0 : o.ride ? Math.min(depth, RIDE_DEPTH[o.ride] ?? 0.25) : Math.min(depth, line);
    // the root's place: the surface minus the sink, never above the feet's own ground
    const target = inNow ? Math.min(0, w.y - sinkTo - pos.y) : 0;
    // jumped or fell in: a plunge, a dip under and a bob back up
    const speed = o.speed || 0;
    if (inNow && !wasIn) {
      const fall = this.wasAir ? Math.max(0, -this.airVy) : 0;
      if (fall > 2.5 && depth > 0.3) this.plunge(pos, w.y, fall, k);
      else this.enter(pos, w.y, speed, o.heading || 0);
    } else if (!inNow && wasIn) this.leave(pos);
    this.in = inNow;
    this.wasAir = Boolean(o.airborne);
    this.airVy = o.airborne ? o.vy || 0 : 0;
    this.swamAgo = this.swimming ? 0 : this.swamAgo + dt;
    // the spring: critically damped walking in and out (the sink follows the bed), springy after a plunge
    const om = this.plungeT > 0 ? 9 : 11;
    const ze = this.plungeT > 0 ? 0.42 : 1;
    const h = Math.min(dt, 1 / 30);
    this.vel += (om * om * (target - this.off) - 2 * ze * om * this.vel) * h;
    this.off += this.vel * h;
    if (this.plungeT > 0) this.plungeT -= dt;
    if (!inNow && Math.abs(this.off) < 0.002 && Math.abs(this.vel) < 0.01) this.off = this.vel = 0;
    // (never pushed up through the ground nor left above it)
    if (this.off > 0) (this.off = 0), (this.vel = Math.min(0, this.vel));
    if (!fx) return this;
    // ---- life in the water
    const hx = Math.sin(o.heading || 0);
    const hz = Math.cos(o.heading || 0);
    if (inNow && o.ride) {
      // a ride through the shallows: spray off the wheels / hooves and a bow wave
      if (speed > 1.5 && (this.step -= dt) <= 0) {
        this.step = 0.07;
        const s = Math.min(1, speed / 14);
        for (const side of [-1, 1]) fx.spray(pos.x + hz * side * 0.3, w.y, pos.z - hx * side * 0.3, 3 + 4 * s, 1.2 + 2 * s, 1.6 + 2.6 * s, -hx * speed * 0.15 + hz * side * 1.2, -hz * speed * 0.15 - hx * side * 1.2, 0.05);
        this.water.ripple(pos.x, pos.z, 0.5 + 0.6 * s);
        if ((this.slosh = (this.slosh || 0) - 0.07) <= 0) {
          this.slosh = 0.5 + Math.random() * 0.2;
          this.sound("wade_slosh", pos, 0.5 + 0.4 * s, 1.15);
        }
      }
    } else if (inNow && this.swimming) {
      // a paddle: each hand's scoop throws a few drops ahead and rings the water; a gentle ring now and then when still
      const ph = o.avatar?.anim?.strokePh ?? 0;
      const half = ph < 0.5 ? 0 : 1;
      const moving = speed > 0.35;
      if (moving && half !== this.stroke) {
        this.stroke = half;
        const side = half ? -1 : 1;
        const ax = pos.x + hx * 0.32 * k + hz * side * 0.16 * k;
        const az = pos.z + hz * 0.32 * k - hx * side * 0.16 * k;
        fx.spray(ax, w.y, az, 4, 0.5, 1.1, hx * 0.4, hz * 0.4, 0.05, 0.8);
        // (the kick behind)
        fx.spray(pos.x - hx * 0.5 * k, w.y, pos.z - hz * 0.5 * k, 2, 0.35, 0.9, -hx * 0.3, -hz * 0.3, 0.06, 0.7);
        this.water.ripple(ax, az, 0.55);
        this.sound("swim_stroke", pos, 0.55);
      } else if (!moving && (this.still -= dt) <= 0) {
        this.still = 1.1 + Math.random() * 0.5;
        this.water.ripple(pos.x, pos.z, 0.4);
        if (Math.random() < 0.5) fx.spray(pos.x + (Math.random() - 0.5) * 0.4, w.y, pos.z + (Math.random() - 0.5) * 0.4, 2, 0.25, 0.6, 0, 0, 0.1, 0.6);
        if (Math.random() < 0.35) this.sound("swim_stroke", pos, 0.25, 0.85);
      }
    } else if (inNow && speed > 0.4) {
      // wading: each step kicks a little splash forward, deeper water a bigger one, and sloshes
      const an = o.avatar?.anim?.an;
      const ph = an?.current?.()?.name === "@loco" ? an.phase : (this.stepPh = ((this.stepPh || 0) + dt * 1.6) % 1);
      const half = ph < 0.5 ? 0 : 1;
      if (half !== this.step) {
        this.step = half;
        const side = half ? -1 : 1;
        const fx0 = pos.x + hx * 0.2 + hz * side * 0.09;
        const fz0 = pos.z + hz * 0.2 - hx * side * 0.09;
        const d = Math.min(1, depth / (0.5 * k));
        fx.spray(fx0, w.y, fz0, 3 + 5 * d, 0.5 + 0.6 * d + speed * 0.06, 1.0 + 1.0 * d + speed * 0.1, hx * speed * 0.25, hz * speed * 0.25, 0.08, 0.8 + 0.3 * d);
        this.water.ripple(fx0, fz0, 0.45 + 0.4 * d);
        this.sound("wade_slosh", pos, 0.32 + 0.4 * d + Math.min(0.2, speed * 0.03));
      }
    }
    // dripping as you come out
    if (this.drip > 0 && !inNow) {
      this.drip -= dt;
      if ((this.dripT = (this.dripT || 0) - dt) <= 0) {
        this.dripT = 0.06 + Math.random() * 0.08;
        const a = Math.random() * Math.PI * 2;
        const y0 = pos.y + this.off + (0.3 + Math.random() * 0.6) * k;
        fx.drop(pos.x + Math.cos(a) * 0.16 * k, y0, pos.z + Math.sin(a) * 0.16 * k, Math.cos(a) * 0.15, -0.3, Math.sin(a) * 0.15, pos.y + this.off - 0.05, 0.75);
      }
    }
    return this;
  }
  sound(id, pos, gain, rate = 1) {
    if (!this.audio) return;
    // (your person's from where they are, softer)
    this.audio.play(id, { pos, gain: gain * (this.self ? 1 : 0.8), rate: rate * (0.94 + Math.random() * 0.12) });
  }
  // walking in (or riding in): a splash about the feet, rings
  enter(pos, y, speed, heading) {
    const fx = this.fx;
    if (fx) fx.spray(pos.x, y, pos.z, 6 + speed * 1.5, 0.6 + speed * 0.15, 1.3 + speed * 0.12, Math.sin(heading) * speed * 0.25, Math.cos(heading) * speed * 0.25, 0.12);
    this.water.ripple(pos.x, pos.z, 1.2);
    this.sound("wade_in", pos, 0.55 + Math.min(0.35, speed * 0.06));
    this.drip = 0;
  }
  // jumped or fell in: a crown of water, a ring of foam, drops all round, a deep plunge and a bob back up
  plunge(pos, y, fall, k) {
    const fx = this.fx;
    const s = Math.min(1, fall / 9);
    if (fx) {
      fx.burst("crown", pos.x, y, pos.z, (0.85 + 0.45 * s) * k);
      fx.burst("foam", pos.x, y, pos.z, (0.9 + 0.5 * s) * k);
      fx.spray(pos.x, y, pos.z, 18 + 16 * s, 1.4 + 1.4 * s, 3.2 + 2.4 * s, 0, 0, 0.3 * k, 1.1);
    }
    this.water.ripple(pos.x, pos.z, 2.2);
    this.water.ripple(pos.x, pos.z, 1.4);
    this.vel = -Math.min(5, fall * 0.55);
    this.plungeT = 1.4;
    this.sound("swim_plunge", pos, 0.65 + 0.35 * s);
    this.drip = 0;
  }
  // out onto the shore: drips for a moment, a little pour-off
  leave(pos) {
    const swam = this.swamAgo < 8;
    this.drip = swam ? 1.8 : 0.8;
    this.sound("swim_out", pos, swam ? 0.6 : 0.35);
  }
  // a splash kick (jump pressed while swimming): drops up, a ring
  kick(pos, k) {
    if (!this.in) return;
    if (this.fx) this.fx.spray(pos.x, this.y, pos.z, 14, 1.2, 2.6, 0, 0, 0.25 * k, 1);
    this.water.ripple(pos.x, pos.z, 1.5);
    this.vel = Math.max(this.vel, 1.6);
    this.plungeT = 0.8;
    this.sound("swim_plunge", pos, 0.4, 1.2);
  }
}
