// The shared decor system (TODO "Shared home", PROJECT_STATE §00 29c): the DATA of placed pieces, for any place we
// decorate together: our home (home.js), the secret cave (29e), and later gifts kept or placed (29d).
// No three.js here: a DecorSet holds the pieces of one place and every change to them as small ops, so the same op is
// applied here, saved, and sent live to the other one (net) and applied there. Drawing is the place's own (home.js).
//
//   const set = new DecorSet({ place: "home", catalogue: PIECES, items, bounds: (it) => true })
//   set.add({ piece: "sofa", x, z, rot, room, slots })      -> the new piece (an id is made)
//   set.move(id, { x, z, y, room })  set.rotate(id, rot)  set.recolour(id, slot, "#rrggbb" | { kind, color })
//   set.stack(id, onId, top)  (on another piece: y = its top, follows it when it moves)   set.unstack(id)
//   set.remove(id)   set.get(id)   set.items   set.children(id)
//   set.on((op, set) => ...)            every change, as an op ({ t: "add" | "move" | ..., ... , by, at })
//   set.apply(op)                       an op from the other one (net) or a replay; false if it does not apply
//   set.json() / DecorSet.parse(text)   the save (versioned, checked)
//   set.giftPiece(gift)                 a gift kept in the place: a piece of kind "gift" with what it holds (29d)
//
// Saving for both: the place gives the set a store ({ load() -> text | null, save(text) }); the set saves (debounced)
// after its own changes, never after an applied one (the one who made it saves it, as shared.js does).

const VERSION = 1;
const HEX = /^#[0-9a-f]{6}$/i;
const ID = /^[a-z0-9_-]{1,40}$/i;
const num = (v, lo, hi, d = 0) => (Number.isFinite(+v) ? Math.min(hi, Math.max(lo, +v)) : d);

function cleanSlots(slots) {
  const out = {};
  if (!slots || typeof slots !== "object") return out;
  for (const [k, v] of Object.entries(slots).slice(0, 24)) {
    if (!/^[a-z0-9_]{1,24}$/i.test(k)) continue;
    if (typeof v === "string" && HEX.test(v)) out[k] = v;
    else if (v && typeof v === "object" && HEX.test(v.color || "") && /^[a-z]{1,16}$/.test(v.kind || "")) out[k] = { kind: v.kind, color: v.color };
  }
  return out;
}

export class DecorSet {
  // place: its name ("home", "cave"); catalogue: { piece: { ... } } (unknown pieces are refused); items: the start;
  // bounds(item) -> true when a piece may stand there; store: { load, save }; who: () -> "toto" | "dodo"
  constructor({ place, catalogue, items = [], bounds = null, store = null, who = () => "" } = {}) {
    this.place = place;
    this.catalogue = catalogue || {};
    this.bounds = bounds;
    this.store = store;
    this.who = who;
    this.map = new Map();
    this.listeners = new Set();
    this.n = 0;
    this.saveT = 0;
    for (const it of items) {
      const c = this.clean(it);
      if (c) this.map.set(c.id, c);
    }
  }

  get items() {
    return [...this.map.values()];
  }
  get(id) {
    return this.map.get(id) || null;
  }
  children(id) {
    return this.items.filter((it) => it.on === id);
  }
  on(fn) {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  // a piece as stored: only what we know, in range
  clean(it) {
    if (!it || typeof it !== "object" || !this.catalogue[it.piece] || !ID.test(String(it.id || ""))) return null;
    const c = { id: String(it.id), piece: it.piece, room: typeof it.room === "string" ? it.room.slice(0, 24) : "", x: num(it.x, -200, 200), z: num(it.z, -200, 200), rot: num(it.rot, -100, 100) };
    if (it.y) c.y = num(it.y, -5, 20);
    if (it.len) c.len = num(it.len, 0.2, 40, 1);
    if (it.level) c.level = Math.round(num(it.level, 0, 5)); // (which floor)
    if (it.sx) c.sx = num(it.sx, 0.1, 5, 1); // (stretched along its width)
    if (it.off) c.off = true; // (a lamp switched off)
    if (it.on && ID.test(String(it.on))) c.on = String(it.on);
    if (typeof it.special === "string") c.special = it.special.slice(0, 24);
    const s = cleanSlots(it.slots);
    if (Object.keys(s).length) c.slots = s;
    if (it.gift && typeof it.gift === "object") c.gift = JSON.parse(JSON.stringify(it.gift).slice(0, 4000));
    return c;
  }

  newId(piece) {
    let id;
    do id = `${piece.slice(0, 12)}-${Date.now().toString(36)}${(this.n++).toString(36)}`;
    while (this.map.has(id));
    return id;
  }

  // ---- the changes: each one an op, applied the same way here and there
  add(it) {
    return this.commit({ t: "add", item: { ...it, id: it.id || this.newId(it.piece) } }) ? this.get(this.lastId) : null;
  }
  move(id, to) {
    return this.commit({ t: "move", id, to });
  }
  rotate(id, rot) {
    return this.commit({ t: "move", id, to: { rot } });
  }
  recolour(id, slot, look) {
    return this.commit({ t: "colour", id, slot, look });
  }
  stack(id, onId, top) {
    return this.commit({ t: "stack", id, on: onId, y: top });
  }
  unstack(id) {
    return this.commit({ t: "stack", id, on: null, y: 0 });
  }
  remove(id) {
    return this.commit({ t: "remove", id });
  }
  // a gift kept in this place (29d): what it holds rides along with the piece
  giftPiece(gift, at) {
    return this.add({ piece: "gift", ...at, gift });
  }

  commit(op) {
    op.by = this.who();
    op.at = Date.now();
    if (!this.apply(op, true)) return false;
    this.scheduleSave();
    return true;
  }

  // an op (ours, the other one's, a replay); false when it does not fit (an unknown piece, out of bounds, gone)
  apply(op, mine = false) {
    if (!op || typeof op !== "object") return false;
    let it = op.id ? this.map.get(op.id) : null;
    switch (op.t) {
      case "add": {
        const c = this.clean(op.item);
        if (!c || this.map.has(c.id) || (this.bounds && !this.bounds(c))) return false;
        this.map.set(c.id, c);
        this.lastId = c.id;
        break;
      }
      case "move": {
        if (!it || !op.to) return false;
        const next = this.clean({ ...it, ...op.to, id: it.id, piece: it.piece });
        if (!next || (this.bounds && !this.bounds(next))) return false;
        const dx = next.x - it.x, dz = next.z - it.z, dy = (next.y || 0) - (it.y || 0), dr = next.rot - it.rot;
        this.map.set(it.id, next);
        // (what stands on it goes with it, turned round it)
        for (const ch of this.children(it.id)) {
          const lx = ch.x - it.x, lz = ch.z - it.z;
          const c = Math.cos(dr), s = Math.sin(dr);
          ch.x = next.x + lx * c + lz * s;
          ch.z = next.z - lx * s + lz * c;
          ch.rot += dr;
          if (dy) ch.y = (ch.y || 0) + dy;
          void dx;
          void dz;
        }
        break;
      }
      case "colour": {
        if (!it || !/^[a-z0-9_]{1,24}$/i.test(op.slot || "")) return false;
        const s = cleanSlots({ [op.slot]: op.look });
        it.slots = { ...(it.slots || {}) };
        if (s[op.slot]) it.slots[op.slot] = s[op.slot];
        else delete it.slots[op.slot]; // (back to the piece's own colour)
        break;
      }
      case "stack": {
        if (!it) return false;
        if (op.on) {
          const base = this.map.get(op.on);
          if (!base || base.id === it.id || this.chain(base.id).includes(it.id)) return false;
          it.on = base.id;
          it.y = num(op.y, -5, 20);
        } else {
          delete it.on;
          it.y = num(op.y, -5, 20);
        }
        break;
      }
      case "remove": {
        if (!it) return false;
        this.map.delete(it.id);
        for (const ch of this.children(it.id)) {
          delete ch.on;
          ch.y = 0;
        }
        break;
      }
      case "load": {
        const parsed = DecorSet.parse(op.text, this.catalogue);
        if (!parsed) return false;
        this.map = new Map(parsed.map((c) => [c.id, c]));
        break;
      }
      default:
        return false;
    }
    for (const fn of this.listeners) fn(op, this, mine);
    return true;
  }

  // what a piece stands on, down to the floor
  chain(id) {
    const out = [];
    for (let it = this.map.get(id); it && out.length < 32; it = it.on ? this.map.get(it.on) : null) out.push(it.id);
    return out;
  }

  json() {
    return JSON.stringify({ v: VERSION, place: this.place, items: this.items });
  }
  static parse(text, catalogue) {
    try {
      const d = typeof text === "string" ? JSON.parse(text) : text;
      if (!d || d.v !== VERSION || !Array.isArray(d.items)) return null;
      const tmp = new DecorSet({ catalogue });
      return d.items.slice(0, 2000).map((it) => tmp.clean(it)).filter(Boolean);
    } catch {
      return null;
    }
  }

  // saving: the store's own (debounced, our own changes only)
  scheduleSave() {
    if (!this.store?.save) return;
    clearTimeout(this.saveT);
    this.saveT = setTimeout(() => this.store.save(this.json()), 1200);
  }
  async loadSaved() {
    const text = await this.store?.load?.();
    return text ? this.apply({ t: "load", text }) : false;
  }
}
