// Which zones are drawn from their Blender GLBs (v2) and which by the legacy builders.
// Decided once, synchronously, before the World is built (the World constructor and startGame
// are synchronous; boot.js is frozen). v2 needs a build that ships the zone pack: the workspace
// builds define __TDD_ZONE_PACK__ (rebuild/qa/harness/build-app.mjs); the production build does
// not yet (model delivery waits on D9), so it stays legacy without asking the network anything.
//   localStorage tdd3d.zones = "legacy"  -> every zone legacy (the fallback switch)
//   ?zones=legacy in the address          -> the same, for one visit
export const V2_ZONES = ["gate", "plaza", "paths", "scatter", "farm", "lake", "chill", "swings", "picnic", "bakery", "stall", "garden", "shell", "shellfar", "balloon", "cinema", "lookout", "coaster", "race", "trail", "games", ...["song", "note", "photos", "calendar", "poems", "gift", "art", "diary", "weather", "wishlist", "discord", "heart", "pinboard"].map((id) => `dr_${id}`), ...["diary", "song", "note", "photos", "calendar", "poems", "gift", "art", "bakery"].map((id) => `rm_${id}`)];

export function zonePack() {
  // eslint-disable-next-line no-undef
  return typeof __TDD_ZONE_PACK__ !== "undefined" ? __TDD_ZONE_PACK__ : null;
}

export function zoneMode() {
  let forced = null;
  try {
    forced = new URLSearchParams(location.search).get("zones") || localStorage.getItem("tdd3d.zones");
  } catch {}
  if (forced === "legacy" || !zonePack()) return { v2: false, ids: new Set(), base: null };
  return { v2: true, ids: new Set(V2_ZONES), base: zonePack() };
}
