// The unicorn's rainbow trail (user, 2026-11-20): while it moves, a soft ribbon of six pastel bands streams from
// its tail and fades out over about a second.
// - One ribbon mesh in world space, sampled by distance (every STEP m) from a point behind the tail, with its head
//   vertex pinned to the live tail so it never lags a frame.
// - Each vertex carries its birth time; the shader fades by age (frame-rate independent, keeps fading after a stop)
//   and turns the band to face the camera (seen from above it stays a band, not a line).
// - Bands blend smoothly across the width, both edges are feathered; no depth writes, a fixed render order and a
//   small lift off the ground, so it never flickers against the scene or itself.
import * as THREE from "three";

const BANDS = ["#ff8fb1", "#ffb36b", "#ffe07a", "#9fe0a6", "#8fd3f0", "#b79be8"];
const MAX = 64; // points kept (STEP * MAX m of trail at most)
const STEP = 0.14;
const LIFE = 1.0; // s
const WIDTH = 0.34;
const EMIT = new THREE.Vector3(0, -0.16, -0.26); // in the tail's frame: a little behind and below the dock

const VERT = /* glsl */ `
attribute vec3 tangent3;
attribute float side;
attribute float birth;
uniform float uTime;
varying float vSide;
varying float vAge;
void main() {
  float age = clamp((uTime - birth) / ${LIFE.toFixed(2)}, 0.0, 1.0);
  vec3 c = position;
  vec3 toCam = normalize(cameraPosition - c);
  vec3 s = cross(tangent3, toCam);
  float l = length(s);
  s = l > 1e-4 ? s / l : vec3(0.0, 1.0, 0.0);
  float w = ${WIDTH.toFixed(3)} * (1.0 - 0.45 * age);
  vSide = side * 0.5 + 0.5;
  vAge = age;
  gl_Position = projectionMatrix * viewMatrix * vec4(c + s * side * w * 0.5, 1.0);
}`;
const FRAG = /* glsl */ `
uniform vec3 uCols[6];
uniform float uOpacity;
varying float vSide;
varying float vAge;
void main() {
  float x = clamp(vSide, 0.0, 1.0) * 5.0;
  float i = floor(x);
  float f = smoothstep(0.2, 0.8, x - i);
  vec3 a = uCols[0], b = uCols[1];
  if (i >= 4.0) { a = uCols[4]; b = uCols[5]; }
  else if (i >= 3.0) { a = uCols[3]; b = uCols[4]; }
  else if (i >= 2.0) { a = uCols[2]; b = uCols[3]; }
  else if (i >= 1.0) { a = uCols[1]; b = uCols[2]; }
  vec3 col = mix(a, b, f);
  float edge = smoothstep(0.0, 0.2, vSide) * smoothstep(1.0, 0.8, vSide);
  float alpha = pow(1.0 - vAge, 1.6) * edge * uOpacity;
  if (alpha < 0.004) discard;
  gl_FragColor = vec4(col, alpha);
  #include <colorspace_fragment>
}`;

let sharedMat = null;
function material() {
  if (sharedMat) return sharedMat;
  sharedMat = new THREE.ShaderMaterial({
    uniforms: { uTime: { value: 0 }, uOpacity: { value: 0.82 }, uCols: { value: BANDS.map((h) => new THREE.Color(h)) } },
    vertexShader: VERT,
    fragmentShader: FRAG,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  return sharedMat;
}
const now = () => performance.now() / 1000;
const _p = new THREE.Vector3();

export class RainbowTrail {
  constructor(u) {
    this.u = u;
    this.pts = []; // newest first: { p: Vector3, t }
    this.moving = false;
    this.shown = false;
    this.lastT = 0;
    const g = new THREE.BufferGeometry();
    this.pos = new Float32Array(MAX * 2 * 3);
    this.tan = new Float32Array(MAX * 2 * 3);
    this.birth = new Float32Array(MAX * 2);
    const side = new Float32Array(MAX * 2);
    for (let i = 0; i < MAX; i++) {
      side[i * 2] = -1;
      side[i * 2 + 1] = 1;
    }
    const idx = [];
    for (let i = 0; i < MAX - 1; i++) {
      const a = i * 2;
      idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
    }
    g.setIndex(idx);
    g.setAttribute("position", new THREE.BufferAttribute(this.pos, 3).setUsage(THREE.DynamicDrawUsage));
    g.setAttribute("tangent3", new THREE.BufferAttribute(this.tan, 3).setUsage(THREE.DynamicDrawUsage));
    g.setAttribute("birth", new THREE.BufferAttribute(this.birth, 1).setUsage(THREE.DynamicDrawUsage));
    g.setAttribute("side", new THREE.BufferAttribute(side, 1));
    g.setDrawRange(0, 0);
    this.geo = g;
    const m = new THREE.Mesh(g, material());
    m.frustumCulled = false;
    m.renderOrder = 6;
    m.visible = false;
    m.onBeforeRender = () => this.frame();
    this.mesh = m;
  }
  // per animation frame from animateUnicorn: is it moving (the sampling itself runs at render, when the tail's
  // world matrix is this frame's)
  update(speed) {
    this.live();
    this.moving = speed > 0.5 && this.shown;
    if (this.moving && !this.mesh.parent) {
      const scene = this.u.root.parent;
      if (scene) scene.add(this.mesh);
    }
    if (this.moving) this.mesh.visible = true;
  }
  // (2026-11-27, TODO 16: the long line on a summon) a ribbon only ever joins samples of one appearance: put away,
  // the unicorn stops emitting and its samples go; summoned again (anywhere, even a step away) it starts afresh
  live() {
    const shown = this.u.root.visible;
    if (shown !== this.shown) {
      this.shown = shown;
      this.moving = false;
      this.pts.length = 0;
      this.geo.setDrawRange(0, 0);
    }
    return shown;
  }
  frame() {
    const t = now();
    material().uniforms.uTime.value = t;
    if (!this.u.root.parent) return this.dispose();
    this.live();
    const dt = Math.min(t - this.lastT, 0.1);
    this.lastT = t;
    const pts = this.pts;
    while (pts.length && t - pts[pts.length - 1].t > LIFE) pts.pop();
    // (no samples while the summon grows it from nothing: the tail sweeps up out of the ground then)
    const head = this.moving && this.u.clips?.an.current().name !== "summon" ? this.u.tail.localToWorld(_p.copy(EMIT)) : null;
    if (head) {
      // a jump no gallop makes in one frame (a teleport, a respawn, a remote rider's first fix): a new ribbon
      if (pts.length && pts[0].p.distanceTo(head) > Math.max(0.8, 40 * dt)) pts.length = 0;
      if (!pts.length || pts[0].p.distanceTo(head) >= STEP) {
        pts.unshift({ p: head.clone(), t });
        if (pts.length > MAX - 1) pts.length = MAX - 1;
      }
    }
    // the ribbon: the live head (if moving), then the samples, newest first
    const list = head && pts.length && pts[0].p.distanceToSquared(head) > 1e-6 ? [{ p: head, t }, ...pts] : pts;
    const n = Math.min(list.length, MAX);
    if (n < 2) {
      this.geo.setDrawRange(0, 0);
      if (!this.moving) this.mesh.visible = false;
      return;
    }
    for (let i = 0; i < n; i++) {
      const p = list[i].p;
      const a = list[Math.max(0, i - 1)].p;
      const b = list[Math.min(n - 1, i + 1)].p;
      let tx = a.x - b.x,
        ty = a.y - b.y,
        tz = a.z - b.z;
      const l = Math.hypot(tx, ty, tz) || 1;
      tx /= l;
      ty /= l;
      tz /= l;
      for (let k = 0; k < 2; k++) {
        const j = (i * 2 + k) * 3;
        this.pos[j] = p.x;
        this.pos[j + 1] = Math.max(p.y, 0.12);
        this.pos[j + 2] = p.z;
        this.tan[j] = tx;
        this.tan[j + 1] = ty;
        this.tan[j + 2] = tz;
        this.birth[i * 2 + k] = list[i].t;
      }
    }
    const at = this.geo.attributes;
    at.position.needsUpdate = true;
    at.tangent3.needsUpdate = true;
    at.birth.needsUpdate = true;
    this.geo.setDrawRange(0, (n - 1) * 6);
  }
  dispose() {
    this.mesh.removeFromParent();
    this.geo.dispose();
    this.pts.length = 0;
  }
}
