export class Stage {
  // o: { scene, world, small (phone / low tier) }; attach() hands over the rest once the island has made it
  constructor(scene, world, { small = false } = {}) {
    this.off = !STAGE_ON;
    if (this.off) return;
    this.scene = scene;
    this.world = world;
    this.small = small;
    this.root = new THREE.Group();
    this.root.name = "stage";
    this.root.position.copy(SPOT);
    this.root.rotation.y = YAW;
    this.root.updateMatrixWorld(true);
    this.root.visible = false;
    scene.add(this.root);
    this.inv = new THREE.Matrix4().copy(this.root.matrixWorld).invert();
    this.ready = false;
    this.loading = null;
    this.t = 0;
    this.near = false;
    this.lights = 0; // how lit the show is (0 idle .. 1 live), eased
    this.live = null; // mine: { stream, peers, at, muted, facing }
    this.remote = null; // theirs: { key, name, at, beat }
    this.watch = null; // their picture and sound coming in
    this.seen = new WeakMap(); // avatar -> last emote seq (the crowd's sounds)
    this.sticks = new Map(); // avatar -> lightstick mesh
    this.seats = [];

    // the meadow's trees, rocks, flowers and tufts keep off it (zones/runtime.js drops their instances in
    // world.clearings; the legacy colliders of the small ones go here)
    const inv = this.inv;
    const clearing = { ...CLEAR, inv };
    clearing.has = (x, z) => {
      const p = _v.set(x, 0, z).applyMatrix4(inv);
      return p.x > CLEAR.x0 && p.x < CLEAR.x1 && p.z > CLEAR.z0 && p.z < CLEAR.z1;
    };
    (world.clearings ||= []).push(clearing);
    for (let i = world.circles.length - 1; i >= 0; i--) {
      const c = world.circles[i];
      if (c.r <= 1.6 && clearing.has(c.x, c.z)) world.circles.splice(i, 1);
    }
    // the deck (stood on, top DECK: stepped up onto from the steps), the thrust, the steps
    const circle = (x, z, r, top) => world.circles.push({ ...this.flat(x, z), r, top });
    for (let x = -3.6; x <= 3.61; x += 1.2) for (const z of [-1.9, -0.8, 0.3, 1.4]) circle(x, z, 1.0, DECK - 0.02);
    for (const x of [-1.6, -0.55, 0.55, 1.6]) circle(x, 2.25, 0.85, DECK - 0.02);
    for (const sx of [-1, 1]) {
      for (const dx of [-0.33, 0.33]) {
        circle(sx * STEP_X + dx, DZ1 + 0.22, 0.42, 0.5);
        circle(sx * STEP_X + dx, DZ1 + 0.67, 0.42, 0.25);
      }
    }
    // the back wall and the truss feet; the speakers
    for (let x = -DX; x <= DX + 0.01; x += 0.55) circle(x, -2.4, 0.3, Infinity);
    for (const sx of [-1, 1]) for (const z of [TRUSS_ZF, TRUSS_ZB]) circle(sx * TRUSS_X, z, 0.36, Infinity);
    for (const sx of [-1, 1]) circle(sx * 6.2, 1.6, 0.72, 2.4);
    // the seats: each one is the sit system's (island.js sitDown), facing the stage
    for (const [i, s] of seatSpots().entries()) {
      const pos = this.toWorld(s.x, 0, s.z);
      const facing = YAW + s.yaw;
      const seat = { pos, facing, h: 0.45, measured: true, stage: true, id: `stage-seat-${i}` };
      // (the prompt at the seat's front edge, reached from in front or from the row behind; the seats' colliders slim
      // enough that you walk between the rows: the first row was out of reach behind the second's backs)
      const tap = this.toWorld(s.x + Math.sin(s.yaw) * 0.3, 0, s.z + Math.cos(s.yaw) * 0.3);
      world.interactables.push({ id: `stage-seat-${i}`, label: "sit and watch the stage 🎤", pos: tap, radius: 0.85, hits: [], action: { type: "sit", seat } });
      circle(s.x - Math.sin(s.yaw) * 0.05, s.z - Math.cos(s.yaw) * 0.05, 0.22, 0.47);
      this.seats.push({ ...s, seat });
    }
    // the stage's own prompt: go live (or, someone else is on)
    const self = this;
    this.item = {
      id: "stage-live",
      get label() {
        if (self.live) return "end the live ⏹";
        if (self.remote) return `${self.remote.name || "your person"} is on stage ✨ grab a seat`;
        return "go live on the stage 🎤📷";
      },
      pos: this.toWorld(0, DECK, 1.2),
      get radius() {
        return 2.6;
      },
      hits: [],
      action: { type: "stage" },
    };
    world.interactables.push(this.item);
    // the show has its own prompt, in front of the stage between it and the seats (the user: "the show play button
    // should be individual not only appears if i pressed go live")
    this.showItem = {
      id: "stage-show",
      get label() {
        if (self.show) return "";
        if (self.live || self.remote) return "";
        return "play the show 🎬";
      },
      pos: this.toWorld(0, 0, 4.1),
      get radius() {
        return self.show || self.live || self.remote ? 0 : 1.7;
      },
      hits: [],
      action: { type: "stage", what: "show" },
    };
    world.interactables.push(this.showItem);
  }

  flat(x, z) {
    const p = _v.set(x, 0, z).applyMatrix4(this.root.matrixWorld);
    return { x: p.x, z: p.z };
  }
  toWorld(x, y, z) {
    return new THREE.Vector3(x, y, z).applyMatrix4(this.root.matrixWorld);
  }
  local(p) {
    return _v2.copy(p).applyMatrix4(this.inv);
  }
  onDeck(p) {
    const l = this.local(p);
    if (l.y < DECK - 0.3) return false;
    if (l.x > -DX && l.x < DX && l.z > DZ0 && l.z < DZ1 + 0.05) return true;
    return l.z >= DZ1 && (l.x / THRUST_R) ** 2 + ((l.z - DZ1) / THRUST_D) ** 2 < 1;
  }

  // o: { audio, net, player, avatar, toast, h, root (the HUD element), emote(name), camera, isTouch, onShadows, myName() }
  attach(o) {
    if (this.off) return;
    const { root: hud, ...rest } = o;
    Object.assign(this, rest);
    this.hud = hud;
    if (!document.getElementById("g3d-stage-css")) {
      const st = document.createElement("style");
      st.id = "g3d-stage-css";
      st.textContent = css;
      document.head.append(st);
    }
    const h = this.h;
    // the go-live sheet: what happens, said plainly, and nothing turns on until "go live"
    this.goBtn = h("button", { class: "g3d-stage-btn go", type: "button", onclick: () => this.start() }, "📷🎙️ go live");
    this.sheet = h(
      "div",
      { class: "g3d-stage-sheet", hidden: true, role: "dialog", "aria-label": "go live on the stage" },
      h("h3", {}, "🎤 go live on our stage"),
      h("p", {}, "your camera and mic turn on only now, for this show. your picture goes on the big screen and straight to your person on the island. nothing is recorded or saved, and it all switches off the moment you stop or step off the stage."),
      h("div", { class: "g3d-stage-row" }, this.goBtn, h("button", { class: "g3d-stage-btn", type: "button", onclick: () => this.closeSheet() }, "not now")),
    );
    // on air: the pill at the top, always in view while the camera and mic are on
    this.muteBtn = h("button", { type: "button", title: "mute the mic", "aria-label": "mute the mic", onclick: () => this.toggleMute() }, "🎙️");
    this.flipBtn = h("button", { type: "button", title: "switch camera", "aria-label": "switch camera", hidden: !this.isTouch, onclick: () => this.flip() }, "🔄");
    this.timeEl = h("span", {}, "0:00");
    this.onair = h(
      "div",
      { class: "g3d-stage-onair", hidden: true, role: "status", "aria-live": "polite" },
      h("span", { class: "g3d-stage-dot", "aria-hidden": "true" }),
      h("span", {}, "ON AIR · "),
      this.timeEl,
      this.muteBtn,
      this.flipBtn,
      h("button", { type: "button", class: "end", title: "end the show", "aria-label": "end the show and turn the camera and mic off", onclick: () => this.stop("you ended the live ♡") }, "⏹ end live"),
    );
    // the audience's moves, while you're in a seat or in the crowd
    const btn = (icon, label, fn) => h("button", { type: "button", title: label, "aria-label": label, onclick: fn }, icon);
    this.crowd = h(
      "div",
      { class: "g3d-stage-crowd", hidden: true },
      btn("👏", "clap", () => this.act("clap")),
      btn("🙌", "cheer", () => this.act("cheer")),
      btn("💡", "wave a lightstick", () => this.act("glow")),
      btn("💃", "dance", () => this.act(this.player.sitting ? "groove" : "dance")),
      btn("🎬", "put on the show", () => this.requestShow()),
    );
    hud.append(this.sheet, this.onair, this.crowd);
    // Esc (or the phone's back gesture) ends your live too
    this.onKey = (e) => {
      if (e.key === "Escape" && this.live) {
        e.preventDefault();
        this.stop("you ended the live ♡");
      }
    };
    window.addEventListener("keydown", this.onKey, true);
    this.onBack = () => this.live && this.stop("you ended the live ♡");
    window.addEventListener("popstate", this.onBack);
    this.onHide = () => {
      if (document.visibilityState === "hidden" && this.live) this.stop("the show ended when the island went to the background");
    };
    document.addEventListener("visibilitychange", this.onHide);
    window.addEventListener("pagehide", this.onHide);
  }

  // ---- the kit: fetched when you come near, let go far away -------------------------------------------------------
  load() {
    const zm = zoneMode();
    if (this.loading || !zm.base) return;
    const sfx = this.small ? "_lite" : "";
    const L = new GLTFLoader().setMeshoptDecoder(MeshoptDecoder);
    const parts = ["prp_stage", "prp_stage_rig", "prp_stage_seat"].map((n) => `${n}${sfx}`);
    const want = [...parts.map((f) => L.loadAsync(`${zm.base}props/${f}.glb`)), this.clipsIn() ? null : L.loadAsync(`${zm.base}clips/prp_stage_clips.glb`).catch(() => null)];
    this.loading = Promise.all(want)
      .then((gs) => {
        const geo = new Map();
        gs.slice(0, 3).forEach((g, i) => {
          const re = new RegExp(`^INST_${parts[i]}_(.+)$`);
          g.scene.traverse((m) => {
            if (!m.isMesh) return;
            const role = m.userData?.tdd_role || re.exec(m.name)?.[1];
            if (role) geo.set(role, m.geometry);
            m.material?.dispose?.();
          });
        });
        if (gs[3]) this.clipGLTF = gs[3];
        this.mergeClips();
        this.build(geo);
      })
      .catch((e) => {
        console.warn("stage kit", e);
        this.loading = null;
      });
  }

  // the audience's clips go into the avatar's own library (matched by joint name), so every avatar plays them
  clipsIn() {
    const lib = clipLib("chr_avatar_clips");
    return Boolean(lib?.get("clap"));
  }
  mergeClips() {
    const lib = clipLib("chr_avatar_clips");
    if (!lib || !this.clipGLTF || lib.get("clap")) return;
    try {
      const src = ClipLib.fromGLTF(this.clipGLTF, "prp_stage_clips");
      const map = src.roles.map((r) => lib.index.get(r) ?? -1);
      for (const c of src.clips.values()) {
        const tracks = c.tracks.filter((t) => map[t.ri] >= 0).map((t) => ({ ...t, ri: map[t.ri] }));
        const cover = new Uint8Array(lib.roles.length * 3);
        for (const t of tracks) cover[t.ri * 3 + t.kind] = 1;
        const un = [];
        for (let ri = 0; ri < lib.roles.length; ri++) for (let g = 0; g < 3; g++) if (!cover[ri * 3 + g]) un.push(ri * STRIDE + (g === 0 ? 0 : g === 1 ? 3 : 7), g);
        lib.clips.set(c.name, { ...c, tracks, uncovered: Int32Array.from(un) });
      }
    } catch (e) {
      console.warn("stage clips", e);
    }
  }

  build(geo) {
    const R = this.root;
    const lit = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.62, metalness: 0 });
    // (the seats behind you dissolve when the camera comes up to them: nothing between the camera and you in a seat)
    const seatMat = nearFade(new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.7, metalness: 0 }), 0.7, 2.2);
    const bulbMat = new THREE.MeshBasicMaterial({ vertexColors: true, toneMapped: false });
    const beamMat = new THREE.MeshBasicMaterial({ vertexColors: true, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending, side: THREE.DoubleSide, toneMapped: false, fog: false });
    const glowMat = new THREE.MeshBasicMaterial({ vertexColors: true, toneMapped: false, transparent: true, depthWrite: false });
    this.mats = [lit, seatMat, bulbMat, beamMat, glowMat];
    this.beamMat = beamMat;
    this.glowMat = glowMat;
    this.geos = geo;
    const add = (role, cast = true) => {
      const g = geo.get(role);
      if (!g) return null;
      const m = new THREE.Mesh(g, lit);
      m.castShadow = cast;
      m.receiveShadow = true;
      m.name = "stage." + role;
      R.add(m);
      return m;
    };
    for (const r of ["deck", "back", "curtains", "truss"]) add(r, r !== "truss" || !this.small);
    const inst = (role, list, mat, cast = false, tints = null) => {
      const g = geo.get(role);
      if (!g || !list.length) return null;
      const m = new THREE.InstancedMesh(g, mat, list.length);
      list.forEach((M, i) => m.setMatrixAt(i, M));
      if (tints) tints.forEach((c, i) => m.setColorAt(i, _c.set(c)));
      m.castShadow = cast;
      m.receiveShadow = true;
      m.name = "stage." + role;
      m.computeBoundingSphere();
      R.add(m);
      return m;
    };
    const M = (x, y, z, yaw = 0, s = 1, q = null) => new THREE.Matrix4().compose(_v.set(x, y, z), q || _q.setFromEuler(_e.set(0, yaw, 0)), _s.set(s, s, s));
    inst("speaker", [-1, 1].map((sx) => M(sx * 6.2, 0, 1.6, -sx * 0.25)), lit, true);
    // the cans along the front beam, each looking at the deck; a beam of light from each
    const nCan = this.small ? 4 : 6;
    this.cans = [];
    for (let i = 0; i < nCan; i++) {
      const x = -3.9 + (7.8 * i) / (nCan - 1);
      this.cans.push({ p: new THREE.Vector3(x, TRUSS_H - 0.22, TRUSS_ZF), x, ph: i * 1.3, tint: new THREE.Color(BEAM_TINTS[i % BEAM_TINTS.length]) });
    }
    this.canMesh = inst("can", this.cans.map(() => new THREE.Matrix4()), lit);
    this.beamMesh = inst("beam", this.cans.map(() => new THREE.Matrix4()), beamMat, false, this.cans.map((c) => c.tint));
    if (this.beamMesh) {
      this.beamMesh.renderOrder = 6;
      this.beamMesh.frustumCulled = false;
    }
    // the seats, each its own pastel
    const S = this.seats;
    inst("seat_frame", S.map((s) => M(s.x, 0, s.z, s.yaw)), seatMat, !this.small);
    inst("seat_pad", S.map((s) => M(s.x, 0, s.z, s.yaw)), seatMat, !this.small, S.map((s) => s.tint));
    // the bulbs: round the screen, the footlights, the string under the front beam
    this.bulbs = bulbSpots();
    this.bulbMesh = inst("bulb", this.bulbs.map((b) => M(b.p.x, b.p.y, b.p.z, 0, b.g === 1 ? 0.9 : 1)), bulbMat, false, this.bulbs.map((b, i) => BULB_TINTS[i % BULB_TINTS.length]));
    // the notes and hearts that float up from the speakers during a show
    this.floaters = [];
    const nF = this.small ? 10 : 18;
    for (let i = 0; i < nF; i++) this.floaters.push({ t: -Math.random() * 6, side: i % 2 ? 1 : -1, kind: i % 3 === 0 ? "heart" : "note", tint: new THREE.Color(STICK_TINTS[i % STICK_TINTS.length]) });
    this.noteMesh = inst("note", this.floaters.filter((f) => f.kind === "note").map(() => new THREE.Matrix4()), glowMat, false, this.floaters.filter((f) => f.kind === "note").map((f) => f.tint));
    this.heartMesh = inst("heart", this.floaters.filter((f) => f.kind === "heart").map(() => new THREE.Matrix4()), lit);
    for (const m of [this.noteMesh, this.heartMesh]) if (m) m.frustumCulled = false;
    // the screen: a picture in front of the dark glass, the idle card when nobody is on
    this.makeScreen();
    this.ready = true;
    R.visible = true;
    this.update(0, { night: this.night || 0 });
    this.onShadows?.();
  }

  unload() {
    if (!this.ready) return;
    this.ready = false;
    this.loading = null;
    for (const c of [...this.root.children]) {
      this.root.remove(c);
      if (c.isInstancedMesh) c.dispose();
    }
    for (const g of this.geos?.values() || []) g.dispose();
    for (const m of this.mats || []) m.dispose();
    this.screenMat?.dispose();
    this.idleTex?.dispose();
    this.badgeTex?.dispose();
    this.vidTex?.dispose();
    this.vidTex = null;
    this.geos = null;
    this.root.visible = false;
    this.onShadows?.();
  }

  // ---- the big screen -----------------------------------------------------------------------------------------------
  makeScreen() {
    const cv = document.createElement("canvas");
    cv.width = this.small ? 384 : 512;
    cv.height = Math.round((cv.width * 9) / 16);
    this.idleCv = cv;
    this.idleTex = new THREE.CanvasTexture(cv);
    this.idleTex.colorSpace = THREE.SRGBColorSpace;
    this.drawIdle(0);
    this.screenU = {
      uIdle: { value: this.idleTex },
      uVid: { value: this.idleTex },
      uLive: { value: 0 },
      uAspect: { value: 16 / 9 },
      uMirror: { value: 0 },
      uTime: { value: 0 },
    };
    this.screenMat = new THREE.ShaderMaterial({
      uniforms: this.screenU,
      toneMapped: false,
      vertexShader: "varying vec2 vUv; void main() { vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }",
      fragmentShader: `
        uniform sampler2D uIdle, uVid; uniform float uLive, uAspect, uMirror, uTime; varying vec2 vUv;
        void main() {
          vec2 uv = vUv;
          // the picture fills the 16:9 screen (cropped, never stretched), mirrored for your own selfie camera
          float sa = ${(SCREEN_W / SCREEN_H).toFixed(4)};
          vec2 v = uv - 0.5;
          if (uAspect > sa) v.x *= sa / uAspect; else v.y *= uAspect / sa;
          v += 0.5;
          if (uMirror > 0.5) v.x = 1.0 - v.x;
          vec3 live = texture2D(uVid, v).rgb;
          // a touch brighter and warmer, a soft vignette and the LED screen's fine grid
          live = pow(live, vec3(0.92)) * vec3(1.04, 1.0, 1.02);
          vec3 idle = texture2D(uIdle, uv).rgb;
          vec3 c = mix(idle, live, uLive);
          vec2 q = uv - 0.5;
          c *= 1.0 - dot(q, q) * 0.55;
          vec2 g = fract(uv * vec2(${(SCREEN_W * 60).toFixed(0)}.0, ${(SCREEN_H * 60).toFixed(0)}.0));
          c *= 0.93 + 0.07 * smoothstep(0.0, 0.25, min(g.x, g.y));
          // a soft glow along the edge
          float e = min(min(uv.x, 1.0 - uv.x), min(uv.y, 1.0 - uv.y));
          c += vec3(1.0, 0.75, 0.9) * (1.0 - smoothstep(0.0, 0.035, e)) * 0.18;
          gl_FragColor = vec4(c, 1.0);
        }`,
    });
    const scr = new THREE.Mesh(new THREE.PlaneGeometry(SCREEN_W, SCREEN_H), this.screenMat);
    scr.position.set(0, SCREEN_Y, SCREEN_Z - 0.01);
    scr.name = "stage.screen";
    this.root.add(scr);
    this.screen = scr;
    // the "● LIVE · name" badge in the screen's corner
    const bc = document.createElement("canvas");
    bc.width = 256;
    bc.height = 64;
    this.badgeCv = bc;
    this.badgeTex = new THREE.CanvasTexture(bc);
    this.badgeTex.colorSpace = THREE.SRGBColorSpace;
    const badge = new THREE.Mesh(new THREE.PlaneGeometry(1.2, 0.3), new THREE.MeshBasicMaterial({ map: this.badgeTex, transparent: true, toneMapped: false, depthWrite: false }));
    badge.position.set(-SCREEN_W / 2 + 0.75, SCREEN_Y + SCREEN_H / 2 - 0.27, SCREEN_Z + 0.005);
    badge.visible = false;
    badge.renderOrder = 2;
    this.badge = badge;
    this.mats.push(badge.material);
    this.root.add(badge);
  }
  drawBadge(name) {
    const x = this.badgeCv.getContext("2d");
    x.clearRect(0, 0, 256, 64);
    x.fillStyle = "rgba(40, 14, 40, 0.72)";
    x.beginPath();
    x.roundRect(4, 6, 248, 52, 26);
    x.fill();
    x.fillStyle = "#ff3b5c";
    x.beginPath();
    x.arc(34, 32, 10, 0, TAU);
    x.fill();
    x.fillStyle = "#fff";
    x.font = "700 26px ui-rounded, 'Arial Rounded MT Bold', system-ui, sans-serif";
    x.textBaseline = "middle";
    const t = `LIVE · ${name}`.slice(0, 18);
    x.fillText(t, 54, 33);
    this.badgeTex.needsUpdate = true;
  }
  // the idle card: a pastel sky drifting, hearts floating, "our stage · step up and go live"
  drawIdle(t) {
    const cv = this.idleCv;
    const x = cv.getContext("2d");
    const W = cv.width;
    const H = cv.height;
    const g = x.createLinearGradient(0, 0, W, H);
    const a = 0.5 + 0.5 * Math.sin(t * 0.4);
    g.addColorStop(0, `hsl(${320 + a * 20}, 80%, ${78 - a * 6}%)`);
    g.addColorStop(0.5, `hsl(${265 + a * 15}, 70%, 76%)`);
    g.addColorStop(1, `hsl(${200 - a * 15}, 75%, 78%)`);
    x.fillStyle = g;
    x.fillRect(0, 0, W, H);
    for (let i = 0; i < 9; i++) {
      const px = ((i * 97 + t * 18 * (1 + (i % 3) * 0.3)) % (W + 40)) - 20;
      const py = H * (0.15 + ((i * 37) % 70) / 100) + Math.sin(t * 1.3 + i) * 8;
      x.globalAlpha = 0.35;
      x.font = `${18 + (i % 3) * 8}px serif`;
      x.fillText(i % 2 ? "♡" : "✦", px, py);
    }
    x.globalAlpha = 1;
    x.fillStyle = "#fff";
    x.textAlign = "center";
    x.textBaseline = "middle";
    x.shadowColor = "rgba(91, 58, 120, 0.45)";
    x.shadowBlur = 12;
    x.font = `800 ${Math.round(W * 0.085)}px ui-rounded, 'Arial Rounded MT Bold', system-ui, sans-serif`;
    x.fillText("✨ our stage ✨", W / 2, H * 0.42);
    x.font = `600 ${Math.round(W * 0.045)}px ui-rounded, 'Arial Rounded MT Bold', system-ui, sans-serif`;
    x.fillText(this.show ? "🎬 the show ♪" : this.remote && !this.watch ? "the show is starting…" : "step up and go live 🎤", W / 2, H * 0.62);
    x.shadowBlur = 0;
    x.textAlign = "start";
    this.idleTex.needsUpdate = true;
  }
  showStream(stream, { mirror = false, name = "" } = {}) {
    if (!this.ready) return;
    this.vidTex?.dispose();
    this.vidTex = null;
    if (!stream) {
      this.screenU.uVid.value = this.idleTex;
      this.badge.visible = false;
      return;
    }
    const v = this.vidEl || (this.vidEl = Object.assign(document.createElement("video"), { muted: true, playsInline: true, autoplay: true }));
    v.setAttribute("playsinline", "");
    v.muted = true;
    if (v.srcObject !== stream) v.srcObject = stream;
    v.play().catch(() => {});
    const tex = new THREE.VideoTexture(v);
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.minFilter = THREE.LinearFilter;
    tex.magFilter = THREE.LinearFilter;
    tex.generateMipmaps = false;
    this.vidTex = tex;
    this.screenU.uVid.value = tex;
    this.screenU.uMirror.value = mirror ? 1 : 0;
    const fit = () => v.videoWidth && (this.screenU.uAspect.value = v.videoWidth / v.videoHeight);
    v.onloadedmetadata = v.onresize = fit;
    fit();
    this.drawBadge(name);
    this.badge.visible = true;
  }

  // ---- going live (mine) --------------------------------------------------------------------------------------------
  use(a) {
    if (this.off) return;
    if (a?.what === "show") return this.requestShow();
    if (this.live) return this.stop("you ended the live ♡");
    if (this.show) {
      this.toast("the show is on ✨ grab a seat");
      return;
    }
    if (this.remote) {
      this.toast(`${this.remote.name || "your person"} is on stage right now ✨ grab a seat and cheer`);
      return;
    }
    if (!navigator.mediaDevices?.getUserMedia) {
      this.toast("this browser can’t use a camera here ♡");
      return;
    }
    // (up the steps and onto the deck, if you asked from the ground in front)
    if (!this.onDeck(this.player.pos)) {
      const p = this.toWorld(0, DECK, 0.6);
      this.teleport(p, YAW);
    }
    this.sheet.hidden = false;
    this.audio.play("ui_open");
  }
  closeSheet() {
    this.sheet.hidden = true;
  }
  async start() {
    this.goBtn.disabled = true;
    let stream;
    try {
      stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "user", width: { ideal: this.small ? 640 : 1280 }, height: { ideal: this.small ? 480 : 720 }, frameRate: { ideal: 30, max: 30 } },
        audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
      });
    } catch {
      this.goBtn.disabled = false;
      this.toast("couldn’t use the camera or mic. check the browser’s permission ♡");
      return;
    }
    this.goBtn.disabled = false;
    this.sheet.hidden = true;
    // (someone else went on while you were asked: theirs stands)
    if (this.remote) {
      stream.getTracks().forEach((t) => t.stop());
      this.toast(`${this.remote.name || "your person"} just went on stage ✨`);
      return;
    }
    this.live = { stream, peers: new Map(), at: Date.now(), muted: false, facing: "user", beat: 0, off: 0 };
    for (const t of stream.getTracks()) t.addEventListener("ended", () => this.live?.stream === stream && this.stop("the camera stopped"));
    this.showStream(stream, { mirror: true, name: this.myName?.() || "you" });
    this.onair.hidden = false;
    this.muteBtn.textContent = "🎙️";
    this.muteBtn.classList.remove("off");
    this.audio.play("stage_live_on");
    this.beat();
    this.toast(this.net.remotes.size ? "you’re live ✨ they can see and hear you" : "you’re live ✨ your person sees you when they come by");
  }
  beat() {
    if (!this.live) return;
    this.live.beat = 2.5;
    this.net.send("stage", { k: "live", on: 1, at: this.live.at, name: this.myName?.() || "" });
  }
  stop(why = "") {
    const L = this.live;
    if (!L) return;
    this.live = null;
    L.stream.getTracks().forEach((t) => t.stop());
    for (const p of L.peers.values()) p.pc.close();
    L.peers.clear();
    this.net?.send("stage", { k: "live", on: 0 });
    this.onair.hidden = true;
    this.showStream(null);
    if (this.vidEl) this.vidEl.srcObject = null;
    this.audio?.play("stage_live_off");
    if (why) this.toast(why);
  }
  toggleMute() {
    const L = this.live;
    if (!L) return;
    L.muted = !L.muted;
    for (const t of L.stream.getAudioTracks()) t.enabled = !L.muted;
    this.muteBtn.textContent = L.muted ? "🔇" : "🎙️";
    this.muteBtn.classList.toggle("off", L.muted);
  }
  async flip() {
    const L = this.live;
    if (!L) return;
    const facing = L.facing === "user" ? "environment" : "user";
    let s;
    try {
      s = await navigator.mediaDevices.getUserMedia({ video: { facingMode: facing, width: { ideal: 640 }, height: { ideal: 480 }, frameRate: { ideal: 30, max: 30 } } });
    } catch {
      return;
    }
    if (this.live !== L) {
      s.getTracks().forEach((t) => t.stop());
      return;
    }
    const nt = s.getVideoTracks()[0];
    const old = L.stream.getVideoTracks()[0];
    L.stream.removeTrack(old);
    old.stop();
    L.stream.addTrack(nt);
    for (const p of L.peers.values()) p.video?.replaceTrack(nt).catch(() => {});
    L.facing = facing;
    this.showStream(L.stream, { mirror: facing === "user", name: this.myName?.() || "you" });
  }
  // a viewer asked for the picture: one connection each, the performer calls
  async offerTo(key) {
    const L = this.live;
    if (!L) return;
    L.peers.get(key)?.pc.close();
    const pc = new RTCPeerConnection({ iceServers: ICE });
    const peer = { pc, video: null, ice: [] };
    L.peers.set(key, peer);
    pc.onicecandidate = (e) => e.candidate && this.net.send("stage", { k: "ice", c: e.candidate.toJSON(), to: "viewer" }, key);
    pc.onconnectionstatechange = () => {
      if (pc.connectionState === "failed" || pc.connectionState === "closed") {
        if (L.peers.get(key) === peer) L.peers.delete(key);
      }
    };
    for (const t of L.stream.getTracks()) {
      const s = pc.addTrack(t, L.stream);
      if (t.kind === "video") {
        peer.video = s;
        const p = s.getParameters();
        p.encodings = p.encodings?.length ? p.encodings : [{}];
        p.encodings[0].maxBitrate = this.small ? 700_000 : 1_600_000;
        p.encodings[0].maxFramerate = 30;
        s.setParameters(p).catch(() => {});
      }
    }
    const offer = await pc.createOffer();
    await pc.setLocalDescription(offer);
    this.net.send("stage", { k: "offer", sdp: offer.sdp }, key);
  }

  // ---- watching (theirs) --------------------------------------------------------------------------------------------
  async answer(p, key) {
    this.closeWatch(false);
    const pc = new RTCPeerConnection({ iceServers: ICE });
    const w = { pc, key, stream: null, src: null, panner: null, ice: [], ok: false };
    this.watch = w;
    pc.onicecandidate = (e) => e.candidate && this.net.send("stage", { k: "ice", c: e.candidate.toJSON(), to: "performer" }, key);
    pc.onconnectionstatechange = () => {
      if (pc.connectionState === "connected") w.ok = true;
      if (pc.connectionState === "failed" && this.watch === w) {
        this.closeWatch(false);
        this.toast("couldn’t connect to the stage’s picture (your networks may block it)");
      }
    };
    pc.ontrack = (e) => {
      const s = e.streams[0] || new MediaStream([e.track]);
      if (w.stream !== s) {
        w.stream = s;
        this.showStream(s, { name: this.remote?.name || "your person" });
      }
      if (e.track.kind === "audio") this.hear(w, s);
    };
    await pc.setRemoteDescription({ type: "offer", sdp: p.sdp });
    const ans = await pc.createAnswer();
    await pc.setLocalDescription(ans);
    for (const c of w.ice.splice(0)) pc.addIceCandidate(c).catch(() => {});
    this.net.send("stage", { k: "answer", sdp: ans.sdp }, key);
  }
  // their sound out of the stage, placed in the world (the island's own listener rides the camera)
  hear(w, stream) {
    const snd = this.audio?.snd;
    const ctx = this.audio?.ctx;
    if (!snd || !ctx || w.src) return;
    try {
      // (Chrome only feeds a remote WebRTC track to Web Audio while a media element plays it too: the muted video does)
      w.src = ctx.createMediaStreamSource(stream);
      const pn = ctx.createPanner();
      pn.panningModel = this.isTouch ? "equalpower" : "HRTF";
      pn.distanceModel = "inverse";
      pn.refDistance = 7;
      pn.maxDistance = WATCH;
      pn.rolloffFactor = 1.1;
      const at = this.toWorld(0, SCREEN_Y, SCREEN_Z + 1.5);
      if (pn.positionX) {
        pn.positionX.value = at.x;
        pn.positionY.value = at.y;
        pn.positionZ.value = at.z;
      } else pn.setPosition(at.x, at.y, at.z);
      const g = ctx.createGain();
      g.gain.value = 1.4;
      w.src.connect(g).connect(pn).connect(snd.bus.voice || snd.bus.sfx);
      w.panner = pn;
      w.gain = g;
    } catch (e) {
      console.warn("stage sound", e);
    }
  }
  closeWatch(clear = true) {
    const w = this.watch;
    if (!w) return;
    this.watch = null;
    w.pc.close();
    try {
      w.src?.disconnect();
      w.gain?.disconnect();
      w.panner?.disconnect();
    } catch {}
    if (clear) {
      this.showStream(null);
      if (this.vidEl) this.vidEl.srcObject = null;
    }
  }

  onRemote(p, r) {
    if (this.off) return;
    if (!r) return;
    const key = p.key;
    switch (p.k) {
      case "live":
        if (p.on) {
          // (both went on at once: the one who started first keeps the stage)
          if (this.live && (this.live.at > p.at || (this.live.at === p.at && this.net.myKey > key))) this.stop(`${r.name || "your person"} got on stage first ✨`);
          if (this.live) return;
          const fresh = !this.remote || this.remote.key !== key;
          this.remote = { key, name: String(p.name || r.name || "").slice(0, 24), at: p.at, beat: 8, asked: fresh ? 0 : this.remote.asked };
          if (fresh) {
            this.audio?.play("stage_live_on");
            const d = r.pos.distanceTo(SPOT);
            this.toast(`${this.remote.name || "your person"} is live on the stage ✨${d > 30 ? " come watch" : ""}`);
          }
        } else if (this.remote?.key === key) this.endRemote();
        return;
      case "want":
        if (this.live) this.offerTo(key);
        return;
      case "show":
        if (!this.show && !this.live) this.startShow(r.name || "your person");
        return;
      case "bye":
        if (this.live) {
          this.live.peers.get(key)?.pc.close();
          this.live.peers.delete(key);
        }
        return;
      case "offer":
        if (this.remote?.key === key) this.answer(p, key).catch((e) => console.warn("stage answer", e));
        return;
      case "answer": {
        const peer = this.live?.peers.get(key);
        if (peer && !peer.pc.currentRemoteDescription)
          peer.pc
            .setRemoteDescription({ type: "answer", sdp: p.sdp })
            .then(() => peer.ice.splice(0).forEach((c) => peer.pc.addIceCandidate(c).catch(() => {})))
            .catch(() => {});
        return;
      }
      case "ice":
        if (p.to === "performer") {
          const peer = this.live?.peers.get(key);
          if (!peer) return;
          if (peer.pc.remoteDescription) peer.pc.addIceCandidate(p.c).catch(() => {});
          else peer.ice.push(p.c);
        } else if (this.watch?.key === key) {
          if (this.watch.pc.remoteDescription) this.watch.pc.addIceCandidate(p.c).catch(() => {});
          else this.watch.ice.push(p.c);
        }
        return;
      default:
    }
  }
  endRemote() {
    if (this.watch) this.net.send("stage", { k: "bye" }, this.watch.key);
    this.closeWatch();
    this.remote = null;
    this.audio?.play("stage_live_off");
  }

  // ---- the show ----------------------------------------------------------------------------------------------------
  requestShow() {
    if (this.show) return this.toast("the show is already on ✨");
    if (this.live || this.remote) return this.toast("someone is live on the stage right now ♡");
    this.closeSheet();
    this.audio?.ensure?.(); // (the tap wakes the island's sound up, so the song can play)
    this.net.send("stage", { k: "show" });
    this.startShow();
  }
  // everyone's own copy starts the moment the button is pressed (theirs when the word arrives): the song and the
  // dance run from that one clock
  async startShow(who = "") {
    const show = { t0: performance.now() / 1000, on: false, done: false };
    this.show = show;
    this.toast(who ? `${who} put on the show 🎬 come watch` : "🎬 the show is starting ✨");
    if (!this.ready) this.load();
    const zm = zoneMode();
    const sfx = this.small ? "_lite" : "";
    const L = new GLTFLoader().setMeshoptDecoder(MeshoptDecoder);
    try {
      const [a, b, rig] = await Promise.all([L.loadAsync(`${zm.base}props/prp_show_a${sfx}.glb`), L.loadAsync(`${zm.base}props/prp_show_b${sfx}.glb`), L.loadAsync(`${zm.base}clips/prp_show_clips.glb`)]);
      if (this.show !== show) return;
      const parts = new Map();
      [[a, `prp_show_a${sfx}`], [b, `prp_show_b${sfx}`]].forEach(([g, n]) => {
        const re = new RegExp(`^INST_${n}_(.+)$`);
        g.scene.traverse((m) => {
          if (!m.isMesh) return;
          const role = m.userData?.tdd_role || re.exec(m.name)?.[1];
          if (role) parts.set(role, m.geometry);
          m.material?.dispose?.();
        });
      });
      // the cast: the carrier's joints, each with its part ("hen2_arm_l" wears "hen_arm_l")
      const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.45, metalness: 0 });
      const pre = "ANIM_prp_show_clips_";
      rig.scene.traverse((o) => {
        if (!o.name.startsWith(pre)) return;
        const role = o.name.slice(pre.length);
        const i = role.indexOf("_");
        const g = parts.get(role.slice(0, i).replace(/\d+$/, "") + role.slice(i));
        if (!g) return;
        const m = new THREE.Mesh(g, mat);
        m.castShadow = !this.small;
        m.receiveShadow = true;
        o.add(m);
      });
      // the banner's words, painted (Blender cannot join Arabic letters; the browser does)
      const cv = document.createElement("canvas");
      cv.width = 1024;
      cv.height = 132;
      const x = cv.getContext("2d");
      x.fillStyle = "#d8202a";
      x.font = "bold 92px 'Segoe UI', Tahoma, Arial, sans-serif";
      x.textAlign = "center";
      x.textBaseline = "middle";
      x.direction = "rtl";
      x.fillText("نجاح كبير بالمغرب", 512, 70);
      const tex = new THREE.CanvasTexture(cv);
      tex.colorSpace = THREE.SRGBColorSpace;
      const words = new THREE.Mesh(new THREE.PlaneGeometry(4.6, 0.6), new THREE.MeshBasicMaterial({ map: tex, transparent: true, depthWrite: false }));
      words.position.set(0, 4.55, 1.905);
      words.renderOrder = 2;
      const group = new THREE.Group();
      group.name = "stage.show";
      group.add(rig.scene, words);
      this.root.add(group);
      const mixer = new THREE.AnimationMixer(rig.scene);
      const clip = rig.animations.find((c) => c.name === "show");
      const idle = rig.animations.find((c) => c.name === "idle");
      const act = mixer.clipAction(clip);
      act.setLoop(THREE.LoopOnce, 1);
      act.clampWhenFinished = true;
      act.play();
      Object.assign(show, { group, mixer, act, idleAct: idle ? mixer.clipAction(idle) : null, len: clip.duration, parts, mat, tex, words, on: true });
      this.playSong(show);
      this.onShadows?.();
    } catch (e) {
      console.warn("stage show", e);
      if (this.show === show) this.endShow();
    }
  }
  // the song from the stage, on the island's own audio (placed at the stage, into the voice bus)
  async playSong(show) {
    const A = this.audio;
    const ctx = A?.ctx;
    const snd = A?.snd;
    if (!ctx || !snd || show.songAsked) return;
    show.songAsked = true;
    try {
      // (the browser's own format first, then the other one: a browser that can't decode one gets the other)
      const get = (url) => fetch(url).then((r) => (r.ok ? r.arrayBuffer() : Promise.reject(new Error(r.status)))).then((ab) => ctx.decodeAudioData(ab));
      const other = snd.ext === "ogg" ? "m4a" : "ogg";
      this.songBuf ||= await get(snd.url("stage_show_song")).catch(() => get(snd.url("stage_show_song").replace(`/${snd.ext}/stage_show_song.${snd.ext}`, `/${other}/stage_show_song.${other}`)));
      if (this.show !== show || show.done) return;
      const src = ctx.createBufferSource();
      src.buffer = this.songBuf;
      const pn = ctx.createPanner();
      pn.panningModel = this.isTouch ? "equalpower" : "HRTF";
      pn.distanceModel = "inverse";
      pn.refDistance = 9;
      pn.maxDistance = WATCH;
      pn.rolloffFactor = 1;
      const at = this.toWorld(0, 2.5, 1.0);
      if (pn.positionX) {
        pn.positionX.value = at.x;
        pn.positionY.value = at.y;
        pn.positionZ.value = at.z;
      } else pn.setPosition(at.x, at.y, at.z);
      const g = ctx.createGain();
      g.gain.value = 1.2;
      src.connect(g).connect(pn).connect(snd.bus.voice || snd.bus.sfx);
      const off = Math.max(0, performance.now() / 1000 - show.t0);
      src.start(0, Math.min(off, this.songBuf.duration - 0.05));
      show.song = { src, g, pn, at: ctx.currentTime - off };
    } catch (e) {
      console.warn("stage song", e);
    }
  }
  updateShow(dt) {
    const S = this.show;
    if (!S.on) return;
    // (the song's own clock when it plays, else the wall clock: both from the moment of the button)
    // (no sound yet when the word came before your first tap: the song joins in, in step, once it wakes)
    if (!S.song && !S.songAsked && this.audio?.ctx && !S.done) this.playSong(S);
    const t = S.song ? this.audio.ctx.currentTime - S.song.at : performance.now() / 1000 - S.t0;
    if (!S.done) {
      S.mixer.setTime(Math.min(t, S.len));
      if (t >= S.len) {
        S.done = true;
        S.end = t;
        S.act.fadeOut(0.6);
        if (S.idleAct) S.idleAct.reset().fadeIn(0.6).play();
        this.audio?.play("stage_cheer");
      }
    } else {
      S.mixer.update(dt);
      if (t - S.end > 5) this.endShow();
    }
  }
  endShow() {
    const S = this.show;
    if (!S) return;
    this.show = null;
    try {
      S.song?.src.stop();
      S.song?.g.disconnect();
    } catch {}
    if (S.group) {
      S.mixer.stopAllAction();
      S.group.removeFromParent();
      for (const g of S.parts.values()) g.dispose();
      S.mat.dispose();
      S.tex.dispose();
      S.words.geometry.dispose();
      S.words.material.dispose();
      this.onShadows?.();
    }
  }

  // ---- the crowd ----------------------------------------------------------------------------------------------------
  act(name) {
    this.emote?.(name);
  }
  // a lightstick in the hand of everyone waving one (their right hand: arm 1's elbow, the hand 0.2 m down it)
  stickFor(a, on, dt) {
    let s = this.sticks.get(a);
    if (!on) {
      if (s) {
        s.removeFromParent();
        this.sticks.delete(a);
      }
      return;
    }
    const hand = a.kitJoints?.get("body:elbow_1") || a.arms?.[1]?.elbow;
    if (!hand || !this.geos) return;
    if (!s) {
      s = new THREE.Group();
      s.name = "stage.lightstick";
      const st = new THREE.Mesh(this.geos.get("stick"), this.mats[0]);
      const gm = this.mats[4].clone();
      const gl = new THREE.Mesh(this.geos.get("stick_glow"), gm);
      gl.renderOrder = 3;
      s.add(st, gl);
      s.userData.glow = gm;
      s.userData.tint = new THREE.Color(STICK_TINTS[this.sticks.size % STICK_TINTS.length]);
      s.position.set(0, -0.17, 0.0);
      s.rotation.set(Math.PI, 0, 0);
      s.scale.setScalar(1.25);
      this.sticks.set(a, s);
      this.mats.push(gm);
    }
    if (s.parent !== hand) hand.add(s);
    const k = 0.8 + 0.2 * Math.sin(this.t * 6 + s.id);
    s.userData.glow.color.copy(s.userData.tint).multiplyScalar(1.4 * k);
  }

  // ---- per frame ----------------------------------------------------------------------------------------------------
  update(dt, { night = 0 } = {}) {
    if (this.off) return;
    this.t += dt;
    this.night = night;
    const P = this.player?.pos;
    if (!P) return;
    const d = Math.hypot(P.x - SPOT.x, P.z - SPOT.z);
    if (d < LOAD && !this.loading && zoneMode().v2) this.load();
    else if (d > DROP && this.ready && !this.live && !this.watch) this.unload();
    // mine: the beat that tells the others, stepping off ends it
    const L = this.live;
    if (L) {
      L.beat -= dt;
      if (L.beat <= 0) this.beat();
      const s = Math.floor((Date.now() - L.at) / 1000);
      const txt = `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
      if (this.timeEl.textContent !== txt) this.timeEl.textContent = txt;
      const l = this.local(P);
      const off = !this.onDeck(P) && !(Math.abs(l.x) < DX + 1.5 && l.z > DZ0 && l.z < DZ1 + 1.2 && l.y < DECK + 0.5);
      L.off = off ? L.off + dt : 0;
      if (L.off > 2.5) this.stop("you stepped off the stage, so the show ended ♡");
    }
    // theirs: ask for the picture while near, let it go when far; a silent performer has gone
    const R = this.remote;
    if (R) {
      R.beat -= dt;
      const r = this.net.remotes.get(R.key);
      if (R.beat <= 0 || !r) this.endRemote();
      else if (d < WATCH && !this.watch) {
        R.asked -= dt;
        if (R.asked <= 0) {
          R.asked = 4;
          this.net.send("stage", { k: "want" }, R.key);
        }
      } else if (d > WATCH + 15 && this.watch) {
        this.net.send("stage", { k: "bye" }, R.key);
        this.closeWatch();
      }
    }
    // (their sound joins once the island's audio has woken up: it needs a tap)
    if (this.watch?.stream && !this.watch.src && this.audio?.ctx) this.hear(this.watch, this.watch.stream);
    if (L) for (const key of [...L.peers.keys()]) if (!this.net.remotes.has(key)) (L.peers.get(key).pc.close(), L.peers.delete(key));
    // the music steps back while a show plays near you
    if (this.show) this.updateShow(dt);
    const showNear = (L || this.watch || this.show?.on) && d < 60;
    if (showNear !== this.ducked) {
      this.ducked = showNear;
      this.audio?.duck("stage", showNear);
    }
    // the crowd's moves: their sounds where they happen, the lightsticks in hand
    const near = d < 45;
    // (the stage's tray: in a seat, or anywhere in the audience's lawn in front of the stage)
    const lp = this.local(P);
    const lawn = lp.z > DZ1 + 0.5 && lp.z < CLEAR.z1 && Math.abs(lp.x) < CLEAR.x1 && !this.onDeck(P);
    this.crowd.hidden = !(near && !this.live && (this.player.sitting?.stage || lawn));
    if (this.ready) {
      const avs = [this.avatar, ...[...this.net.remotes.values()].map((r) => r.avatar)];
      for (const a of avs) {
        if (!a) continue;
        const pos = a.root.position;
        const close = Math.hypot(pos.x - SPOT.x, pos.z - SPOT.z) < 45;
        const seq = a.emoteSeq || 0;
        if (this.seen.get(a) !== seq) {
          this.seen.set(a, seq);
          if (close && a.emote && STAGE_EMOTES[a.emote]) this.audio?.play("stage_" + a.emote, { pos: _v.copy(pos).setY(pos.y + 1) });
        }
        this.stickFor(a, close && a.emote === "glow", dt);
      }
      for (const a of this.sticks.keys()) if (!avs.includes(a)) this.stickFor(a, false, dt);
    }
    if (!this.ready) return;
    // the show's lights: the beams sweep and the bulbs chase while someone is on; warm and still otherwise
    const on = L || this.watch || this.remote || this.show?.on ? 1 : 0;
    this.lights += (on - this.lights) * (1 - Math.exp(-dt * 1.5));
    const lit = this.lights;
    const t = this.t;
    if (this.beamMesh) {
      this.beamMat.opacity = (0.1 + 0.55 * night) * (0.25 + 0.75 * lit) * (this.small ? 0.8 : 1);
      this.cans.forEach((c, i) => {
        const sx = Math.sin(t * (0.45 + 0.1 * i) + c.ph) * (0.25 + 0.35 * lit);
        const tz = Math.cos(t * (0.33 + 0.07 * i) + c.ph) * 0.18;
        // aim: from the can down and back onto the deck, swinging side to side
        const dir = _v.set(-c.x * 0.12 + sx * 2.2, -(TRUSS_H - DECK), -2.2 + tz * 4).normalize();
        _q.setFromUnitVectors(_v2.set(0, -1, 0), dir);
        this.canMesh?.setMatrixAt(i, _m.compose(c.p, _q, _s.set(1, 1, 1)));
        const len = 6.6;
        const rad = 0.55 + 0.25 * lit;
        _m.compose(_v2.copy(c.p).addScaledVector(dir, 0.42), _q, _s.set(rad * 1.6, len, rad * 1.6));
        this.beamMesh.setMatrixAt(i, _m);
      });
      this.beamMesh.instanceMatrix.needsUpdate = true;
      if (this.canMesh) this.canMesh.instanceMatrix.needsUpdate = true;
    }
    if (this.bulbMesh) {
      this.bulbT = (this.bulbT || 0) - dt;
      if (this.bulbT <= 0) {
        this.bulbT = this.small ? 0.12 : 0.06;
        const base = 0.55 + 0.45 * night;
        this.bulbs.forEach((b, i) => {
          const chase = lit * (0.5 + 0.5 * Math.sin(i * 0.8 - t * 7));
          const k = base * (0.75 + 0.25 * Math.sin(t * 1.3 + i * 2.1)) * (1 - lit * 0.4) + chase * 0.9;
          _c.set(BULB_TINTS[i % BULB_TINTS.length]).multiplyScalar(0.55 + k * 0.9);
          this.bulbMesh.setColorAt(i, _c);
        });
        this.bulbMesh.instanceColor.needsUpdate = true;
      }
    }
    // the notes and hearts float up from the speakers while a show is on
    if (this.noteMesh || this.heartMesh) {
      let ni = 0;
      let hi = 0;
      for (const f of this.floaters) {
        f.t += dt;
        if (f.t > 4.5) f.t = lit > 0.5 ? -Math.random() * 1.5 : -Math.random() * 6;
        const u = f.t / 4.5;
        const vis = f.t > 0 && lit > 0.05;
        const s = vis ? Math.sin(Math.PI * clamp01(u)) * (f.kind === "heart" ? 1.6 : 1.4) * lit : 0;
        _v.set(f.side * 6.2 + Math.sin(f.t * 2 + f.side) * 0.5, 2.5 + u * 3.5, 1.6 + Math.cos(f.t * 1.5) * 0.4);
        _q.setFromEuler(_e.set(0, Math.sin(f.t * 1.7) * 0.6 - YAW * 0, Math.sin(f.t * 2.3) * 0.3));
        _m.compose(_v, _q, _s.set(s, s, s));
        if (f.kind === "note") this.noteMesh?.setMatrixAt(ni++, _m);
        else this.heartMesh?.setMatrixAt(hi++, _m);
      }
      if (this.noteMesh) this.noteMesh.instanceMatrix.needsUpdate = true;
      if (this.heartMesh) this.heartMesh.instanceMatrix.needsUpdate = true;
    }
    // the screen: live, or the idle card (redrawn a few times a second, only when you're near enough to see it)
    const showing = Boolean(this.vidTex);
    this.screenU.uLive.value += ((showing ? 1 : 0) - this.screenU.uLive.value) * (1 - Math.exp(-dt * 4));
    this.screenU.uTime.value = t;
    if (!showing && d < 70) {
      this.idleT = (this.idleT || 0) - dt;
      if (this.idleT <= 0) {
        this.idleT = this.small ? 0.2 : 0.1;
        this.drawIdle(t);
      }
    }
  }

  destroy() {
    if (this.off) return;
    this.endShow();
    if (this.live) this.stop();
    this.closeWatch();
    this.unload();
    document.removeEventListener("visibilitychange", this.onHide);
    window.removeEventListener("keydown", this.onKey, true);
    window.removeEventListener("popstate", this.onBack);
    window.removeEventListener("pagehide", this.onHide);
    this.sheet?.remove();
    this.onair?.remove();
    this.crowd?.remove();
    this.scene.remove(this.root);
  }
}
