// The same number of lights in every frame (E1: no shader compiles while you play).
//
// three.js builds each shader for an exact number of lights, counting only lights that are shown.
// The campfire's flicker light and the barn's lamp sit inside groups that are hidden by distance, so
// walking about changed the count (2, 3, 4 point lights) and every lit material compiled its shader
// again for the new count: most of the 57 hitches measured in play (audit 05 §4 #8).
//
// Each such light keeps its place and its own code keeps setting its colour and brightness, but it no
// longer counts itself (it is moved to a layer the camera never sees); a stand-in at the top of the
// world, always shown, copies its position, colour, reach and brightness every frame, and is dark
// (brightness 0) whenever the original would not have been shown. Same light, same look, one count.
import * as THREE from "three";

const LAYER = 31; // a layer the island's cameras never enable
const _p = new THREE.Vector3();

function shown(o, root) {
  for (let p = o; p; p = p.parent) {
    if (!p.visible) return false;
    if (p === root) return true;
  }
  return false;
}

export class SteadyLights {
  constructor(scene) {
    this.scene = scene;
    this.pairs = [];
  }

  // every point / spot light below the top level (top-level lights never hide)
  adopt() {
    const found = [];
    this.scene.traverse((o) => {
      if (!(o.isPointLight || o.isSpotLight) || o.parent === this.scene || o.userData.steadyProxy) return;
      if (this.pairs.some((p) => p.src === o)) return;
      found.push(o);
    });
    for (const src of found) {
      const proxy = src.isPointLight ? new THREE.PointLight(src.color, 0, src.distance, src.decay) : new THREE.SpotLight(src.color, 0, src.distance, src.angle, src.penumbra, src.decay);
      proxy.userData.steadyProxy = true;
      proxy.castShadow = false;
      proxy.matrixAutoUpdate = false;
      src.layers.set(LAYER);
      this.scene.add(proxy);
      this.pairs.push({ src, proxy });
    }
    this.update();
    return found.length;
  }

  // once a frame, after the world's own code has set its lights and before the picture is drawn
  // (TODO 50, the user: "shadows and light sometimes spawns suddenly if i entered an area": a light whose place comes
  // into view, or goes, eases in and out over about half a second instead of switching; its own flicker still passes
  // straight through)
  update() {
    const now = performance.now();
    const dt = Math.min(0.1, Math.max(0, (now - (this.last || now)) / 1000));
    this.last = now;
    const k = 1 - Math.exp(-dt * 6);
    for (const pair of this.pairs) {
      const { src, proxy } = pair;
      const on = Boolean(src.parent) && shown(src, this.scene);
      pair.w = (pair.w ?? (on ? 1 : 0)) + ((on ? 1 : 0) - (pair.w ?? (on ? 1 : 0))) * k;
      if (pair.w < 0.002) pair.w = on ? pair.w : 0;
      proxy.intensity = src.intensity * pair.w;
      if (!on && pair.w === 0) continue;
      proxy.color.copy(src.color);
      proxy.distance = src.distance;
      proxy.decay = src.decay;
      src.updateWorldMatrix(true, false);
      _p.setFromMatrixPosition(src.matrixWorld);
      if (!proxy.position.equals(_p)) {
        proxy.position.copy(_p);
        proxy.updateMatrix();
        proxy.matrixWorldNeedsUpdate = true;
      }
    }
  }

  dispose() {
    for (const { src, proxy } of this.pairs) {
      proxy.removeFromParent();
      proxy.dispose();
      src.layers.set(0);
    }
    this.pairs = [];
  }
}
