// The local zones (farm, lake, campfire, swings, picnic, bakery, flower stall, garden), v2: their
// legacy builders still run exactly as before (every collider, seat, interactable, slot, RNG stream
// and every runtime piece: animals, plants, stock, bouquets, ducks, fire...), and register here the
// parts that only LOOK: their static pieces. When the place's Blender zone has streamed in
// (zones/runtime.js), those pieces leave the scene and the zone draws the place instead; until then
// (or if the zone never comes) the legacy pieces stay, so a place is never empty.
// Runtime materials the zone binds by name (lake water, the bakery's paper / floor / neon / glass,
// the garden's water) are registered in world.zoneMats by their builders.
import { bakeWhenSettled } from "../bake.js";

// is this piece only a look? (a light, a halo, something clickable, something live, see-through or
// glowing additively is kept, unless its material is one the zone takes over)
function lookOnly(o, mats, keep = null) {
  if (keep?.has(o)) return false;
  if (o.isLight || o.isSprite || o.isPoints || o.userData.live || o.userData.item) return false;
  if (o.userData.zoneLook) return true; // (a see-through piece its zone models all the same)
  if (o.isMesh) {
    const m = Array.isArray(o.material) ? o.material[0] : o.material;
    if (mats.has(m)) return true;
    if (m.transparent || m.blending === 2) return false;
    return true;
  }
  return true;
}

// the static pieces under o: o itself when everything in it is a look, else its static parts
function collect(o, mats, out, keep = null) {
  let all = lookOnly(o, mats, keep);
  if (all)
    o.traverse((c) => {
      if (c !== o && !lookOnly(c, mats, keep)) all = false;
    });
  if (all) out.push(o);
  else if (!o.isMesh && !keep?.has(o)) for (const c of o.children) collect(c, mats, out, keep);
  return out;
}

// groups: wholly static groups (a builder's `still`); items: single pieces; direct: { parent,
// before } = the pieces a builder added straight to parent (everything not in before), sorted
// into static and kept by lookOnly
export function zoneSink(world, zone, { groups = [], items = [], direct = null, motion = null, keep = [] } = {}) {
  if (!world.zones?.ids?.has(zone)) return;
  // (motion: a room whose animations are run once when the zone arrives; whatever they move stays)
  if (motion) (world.zoneMotion ||= new Map()).set(zone, motion);
  const mats = new Set(Object.values(world.zoneMats || {}));
  const list = [...groups.filter(Boolean), ...items.filter(Boolean)];
  const keepSet = new Set(keep);
  if (direct) for (const c of direct.parent.children) if (!direct.before.has(c) && !keepSet.has(c)) collect(c, mats, list, keepSet);
  for (const o of list) {
    // (never merged by the phone's bake or bakeWhenSettled: they may leave any moment)
    o.userData.zoneSink = zone;
    o.traverse((c) => (c.__noBake = true));
    if (o.isGroup && groups.includes(o) && !o.userData.live) {
      o.userData.live = true;
      o.userData.zoneLiveSet = true;
    }
  }
  const sinks = (world.zoneSinks ||= new Map());
  if (!sinks.has(zone)) sinks.set(zone, []);
  sinks.get(zone).push(...list);
  // (the zone is in already: built late, say a room furnished after it streamed; or will never come)
  if (world.zoneReady?.has(zone)) sinkNow(world, zone);
  else if (world.zoneGone?.has(zone)) releaseSink(world, zone);
}

// the zone will not come (left out of the pack, or it failed): its legacy look stays for good, so
// it is handed back to the merging it would have had (bakeWhenSettled, the phone's bake)
export function releaseSink(world, zone) {
  const list = world.zoneSinks?.get(zone) || [];
  for (const o of list) {
    delete o.userData.zoneSink;
    if (o.userData.zoneLiveSet) {
      delete o.userData.live;
      delete o.userData.zoneLiveSet;
    }
    o.traverse((c) => (c.__noBake = false));
    if (o.isGroup && o.parent) bakeWhenSettled(o);
  }
  list.length = 0;
  (world.zoneGone ||= new Set()).add(zone);
}

// the zone is in: its legacy look leaves. Returns the canvas faces it showed (signs, boards,
// chalk menus), with where they were, for the zone's SCREEN_ planes to show from now on.
export function sinkNow(world, zone) {
  (world.zoneReady ||= new Set()).add(zone);
  let list = world.zoneSinks?.get(zone) || [];
  // (no room-inside zones on this device, phones: a house zone leaves the room's own floor in place)
  if (world.roomsZoned === false) list = list.filter((o) => !o.userData.roomFloor);
  const room = world.zoneMotion?.get(zone);
  if (room && list.length) {
    // what the place's animations move (a swinging sign, notes, clock hands, a vane) stays ours: run
    // them at two other moments and keep every piece that changed
    const mat = (o) => {
      const m = o.material && !Array.isArray(o.material) ? o.material : null;
      return m ? [m.emissiveIntensity ?? 0, m.opacity, m.emissive?.getHex?.() ?? 0, m.color?.getHex?.() ?? 0].join() : "";
    };
    const take = (o) => [o.position.x, o.position.y, o.position.z, o.quaternion.x, o.quaternion.y, o.quaternion.z, o.quaternion.w, o.scale.x, o.scale.y, o.scale.z, o.visible ? 1 : 0, mat(o)].join();
    const before = new Map();
    for (const o of list) o.traverse((c) => before.set(c, take(c)));
    // (motion: a room, whose closures carry it; or the closures themselves, for a ride built outside any room)
    const fns = Array.isArray(room) ? room : world.animated.filter((f) => f.__room === room);
    for (const t of [world.time + 0.731, world.time + 2.417])
      for (const f of fns) {
        try {
          f(t, 0.016);
        } catch {}
      }
    const moved = (o) => {
      let m = false;
      o.traverse((c) => (m ||= before.get(c) !== take(c)));
      return m;
    };
    // (only what moves stays: a group that moves as a whole stays whole; a still group with a moving
    // part inside, a roof with its spinning spire, keeps that part and gives up the rest)
    const out = [];
    const split = (o) => {
      if (!moved(o)) return out.push(o);
      if (before.get(o) !== take(o) || !o.children.length || o.isMesh) return;
      for (const c of [...o.children]) split(c);
    };
    for (const o of list) split(o);
    list = out;
    world.zoneSinks.set(zone, list);
  }
  const faces = [];
  for (const o of list) {
    if (!o.parent) continue;
    o.updateWorldMatrix(true, true);
    o.traverse((c) => {
      const m = c.isMesh && (Array.isArray(c.material) ? c.material.find((q) => q.map?.isCanvasTexture) || c.material[0] : c.material);
      const img = m?.map?.image;
      if (m && img && (m.map.isCanvasTexture || (typeof HTMLCanvasElement !== "undefined" && img instanceof HTMLCanvasElement))) {
        if (!c.geometry.boundingSphere) c.geometry.computeBoundingSphere();
        faces.push({ material: m, at: c.geometry.boundingSphere.center.clone().applyMatrix4(c.matrixWorld), area: c.geometry.boundingSphere.radius });
      }
    });
    o.removeFromParent();
  }
  // (memory, review fix 7: their geometry goes unless something still drawn shares it)
  if (list.length && world.scene) {
    const used = new Set();
    const usedTex = new Set(faces.map((f) => f.material.map));
    const texOf = (c, add) => {
      for (const m of Array.isArray(c.material) ? c.material : c.material ? [c.material] : []) for (const k of ["map", "emissiveMap", "alphaMap"]) if (m[k]) add(m[k]);
    };
    world.scene.traverse((c) => {
      if (c.geometry) used.add(c.geometry);
      texOf(c, (t) => usedTex.add(t));
    });
    const gone = new Set();
    const goneTex = new Set();
    for (const o of list)
      o.traverse((c) => {
        if (c.geometry && !used.has(c.geometry)) gone.add(c.geometry);
        // (a phone's painted pixels are let go once uploaded, textures.js: such a texture stays on the card, a
        // zone's sign may show it later, and it could never be sent again)
        texOf(c, (t) => !usedTex.has(t) && !t.userData?.dropped && goneTex.add(t));
      });
    for (const g of gone) g.dispose();
    // (and the textures only the look that left used; the shared materials stay, and a texture
    // drawn again later is simply uploaded again, performance 21)
    for (const t of goneTex) t.dispose();
    for (const o of list) if (o.isGroup || o.children.length) o.clear();
  }
  list.length = 0;
  // (the room floors kept above were a filtered copy: the stored list let go of too, or every piece that
  // left stayed in memory, ~70 MB of the garden's on a phone, review 2026-11-20)
  const stored = world.zoneSinks?.get(zone);
  if (stored?.length) {
    const floors = stored.filter((o) => o.userData.roomFloor);
    stored.length = 0;
    stored.push(...floors);
  }
  return faces;
}
