// Our shared home (TODO "Shared home", part 1: the house): the place that was "our room" (the profiles room) is now a
// whole house: a living room with the fire and our two profiles, a kitchen, our bedroom with the mirror (change your
// look) and the bed, a bathroom, a reading nook, a porch with a swing, a balcony off the bedroom and a garden.
// Everything is laid from the house's data (homedata.js): every wall with its doors and windows, every floor, the
// roof, every placed piece and every colour, so the editor (part 2) changes the data and the house is laid again.
// The pieces are the Blender kit (assets/blender/buildings/home/_build_home.py): one mesh per piece and material
// slot; here each slot's colour is multiplied into its vertex colours and the house is merged per kind of surface
// (a few draws for the whole house). Phones load the _lite kit, only when near.
// Inside, the walls between the camera and you are cut down (a dollhouse view: island.js sets the camera) and the
// roof fades away; the colliders, seats and taps are there from the start (no download needed to walk in).
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { MeshoptDecoder } from "three/examples/jsm/libs/meshopt_decoder.module.js";
import { mergeGeometries } from "three/examples/jsm/utils/BufferGeometryUtils.js";
import { zonePack } from "./zones/mode.js";
import { withSurfaceMap } from "./textures.js";
import { HOME_DEFAULT, PIECES, SURFACE_KINDS, OPENINGS, SHELL_SLOTS, LEVEL_H, PLOT, slotLook } from "./homedata.js";
import KITFILES from "./homekit.json";
import { DecorSet } from "./decor.js";

const FLOOR_TOP = 0.012; // (the floor tiles' top: everything inside stands on it)
const DETAIL_MEAN = { wood: 0.242, glaze: 0.219, plaster: 0.22, fabric: 0.27, stone: 0.24 };
const _m = new THREE.Matrix4();
const _m2 = new THREE.Matrix4();
const _v = new THREE.Vector3();
const _c = new THREE.Color();
const UP = new THREE.Vector3(0, 1, 0);

// the kit: role ("piece__slot") -> geometry, loaded once per tier
const kitPs = {};
function loadKit(small) {
  if (kitPs[small]) return kitPs[small];
  const base = zonePack();
  if (!base) return (kitPs[small] = Promise.resolve(null));
  const loader = new GLTFLoader().setMeshoptDecoder(MeshoptDecoder);
  const kitP = Promise.all(
    KITFILES.files.map((f) =>
      loader.loadAsync(`${base}home/bld_home_${f}${small ? "_lite" : ""}.glb`).then((g) => g.scene, (e) => (console.warn("home kit", f, e), null)),
    ),
  ).then((scenes) => {
    const kit = new Map();
    for (const sc of scenes) {
      if (!sc) continue;
      sc.traverse((o) => {
        if (!o.isMesh) return;
        const role = o.userData?.tdd_role;
        if (!role) return;
        const g = o.geometry;
        // (every attribute as plain floats, so any two merge)
        for (const k of Object.keys(g.attributes)) {
          const a = g.attributes[k];
          if (a.isInterleavedBufferAttribute || !(a.array instanceof Float32Array) || a.normalized) {
            const arr = new Float32Array(a.count * a.itemSize);
            for (let i = 0; i < a.count; i++) for (let j = 0; j < a.itemSize; j++) arr[i * a.itemSize + j] = a.getComponent(i, j);
            g.setAttribute(k, new THREE.BufferAttribute(arr, a.itemSize));
          }
        }
        if (g.attributes.color?.itemSize === 4) {
          const a = g.attributes.color;
          const arr = new Float32Array(a.count * 3);
          for (let i = 0; i < a.count; i++) for (let j = 0; j < 3; j++) arr[i * 3 + j] = a.getComponent(i, j);
          g.setAttribute("color", new THREE.BufferAttribute(arr, 3));
        }
        if (!g.index) g.setIndex([...Array(g.attributes.position.count).keys()]);
        kit.set(role, g);
        o.material?.dispose?.();
      });
    }
    return kit.size ? kit : null;
  });
  return (kitPs[small] = kitP);
}

// a wallpaper's pattern: near white with its print a little darker, tinted by the wall's colour (0.5 m a repeat)
const patterns = new Map();
function patternTexture(name) {
  if (patterns.has(name)) return patterns.get(name);
  const N = 256;
  const c = document.createElement("canvas");
  c.width = c.height = N;
  const x = c.getContext("2d");
  x.fillStyle = "#ffffff";
  x.fillRect(0, 0, N, N);
  const ink = "rgba(120,100,120,0.18)";
  const light = "rgba(255,255,255,0.9)";
  x.fillStyle = ink;
  const heart = (cx, cy, r) => {
    x.beginPath();
    x.moveTo(cx, cy + r * 0.9);
    x.bezierCurveTo(cx - r * 1.4, cy - r * 0.1, cx - r * 0.6, cy - r * 1.2, cx, cy - r * 0.45);
    x.bezierCurveTo(cx + r * 0.6, cy - r * 1.2, cx + r * 1.4, cy - r * 0.1, cx, cy + r * 0.9);
    x.fill();
  };
  if (name === "stripes") for (let i = 0; i < 4; i++) (x.fillRect(i * 64 + 8, 0, 26, N), (x.fillStyle = "rgba(120,100,120,0.1)"), x.fillRect(i * 64 + 40, 0, 6, N), (x.fillStyle = ink));
  if (name === "dots") for (let i = 0; i < 4; i++) for (let j = 0; j < 4; j++) (x.beginPath(), x.arc(i * 64 + (j % 2) * 32 + 16, j * 64 + 32, 9, 0, Math.PI * 2), x.fill());
  if (name === "hearts") for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) heart(i * 85 + (j % 2) * 42 + 30, j * 85 + 42, 16);
  if (name === "flowers")
    for (let i = 0; i < 3; i++)
      for (let j = 0; j < 3; j++) {
        const cx = i * 85 + (j % 2) * 42 + 30, cy = j * 85 + 42;
        for (let k = 0; k < 5; k++) (x.beginPath(), x.arc(cx + Math.cos((k / 5) * Math.PI * 2) * 11, cy + Math.sin((k / 5) * Math.PI * 2) * 11, 8, 0, Math.PI * 2), x.fill());
        x.fillStyle = light;
        x.beginPath();
        x.arc(cx, cy, 6, 0, Math.PI * 2);
        x.fill();
        x.fillStyle = ink;
      }
  if (name === "gingham") {
    x.fillStyle = "rgba(120,100,120,0.12)";
    for (let i = 0; i < 4; i++) (x.fillRect(i * 64, 0, 32, N), x.fillRect(0, i * 64, N, 32));
  }
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(2, 2);
  t.colorSpace = THREE.SRGBColorSpace;
  patterns.set(name, t);
  return t;
}

// a slot's look by its kind; "fixed" and the glowing bits keep their own colours
const SPECIAL = {
  fixed: { kind: "fixed", color: "#ffffff" },
  glowfix: { kind: "glow", color: "#ffffff" },
  fire: { kind: "glow", color: "#ffffff" },
  mirror: { kind: "mirror", color: "#ffffff" },
};

export class Home {
  // world: the World; room: the place ("wardrobe"); o: { small (phone kit), kit (world.js ZONE_KIT helpers) }
  constructor(world, room, o = {}) {
    this.world = world;
    this.room = room;
    this.small = Boolean(o.small);
    this.K = o.kit;
    this.data = HOME_DEFAULT;
    // every placed piece lives in the shared decor set (decor.js): the editor (part 2) changes it, both of us see it
    this.decor = new DecorSet({ place: "home", catalogue: PIECES, items: HOME_DEFAULT.items });
    this.group = new THREE.Group();
    this.group.name = "home";
    room.group.add(this.group);
    this.layers = { cut: new THREE.Group(), furn: new THREE.Group(), plain: new THREE.Group(), roof: new THREE.Group() };
    for (const [k, g] of Object.entries(this.layers)) {
      g.name = `home.${k}`;
      this.group.add(g);
    }
    // the dollhouse cut: where you are, which way the camera is from you, how far it is in (0 out .. 1 in)
    this.U = { uCutP: { value: new THREE.Vector3() }, uCutD: { value: new THREE.Vector2(0, 1) }, uCutOn: { value: 0 }, uCutBase: { value: 0 }, uMaxY: { value: 99 }, uRoofHide: { value: 0 }, uGlow: { value: 0 } };
    this.level = 0;
    this.mats = new Map();
    this.cut = 0;
    this.inside = false;
    this.built = false;
    this.loading = false;
    this.screens = [];
    this.lampAt = new THREE.Vector3();
  }

  // ---- the house in the world: walls, circles, decks, seats, taps (straight away, from the data) -----------------
  lay() {
    const W = this.world;
    const room = this.room;
    const D = this.data;
    room.group.updateMatrixWorld(true);
    const toW = (x, z, y = 0) => W.toWorld(room, x, y, z);
    this.segs = [];
    this.circles = [];
    this.items = [];
    // the meadow keeps off the house and its decks (no grass up through the floors), and the scenery's little trees
    // and rocks that stood there go (zones/runtime.js world.clearings)
    const inv = new THREE.Matrix4().copy(room.group.matrixWorld).invert();
    const [hx0, hz0, hx1, hz1] = D.rect;
    // (the whole fenced plot, front garden and backyard: homedata.js, its fence)
    const CLEAR = [[PLOT[0] - 0.2, PLOT[2] + 0.2, PLOT[1] - 0.2, PLOT[3] + 0.25]];
    void [hx0, hz0, hx1, hz1];
    const clearing = {
      home: true,
      has: (x, z) => {
        const q = _v.set(x, 0, z).applyMatrix4(inv);
        return CLEAR.some(([x0, x1, z0, z1]) => q.x > x0 && q.x < x1 && q.z > z0 && q.z < z1);
      },
    };
    (W.clearings ||= []).push(clearing);
    for (let i = W.circles.length - 1; i >= 0; i--) {
      const c = W.circles[i];
      if (c.r <= 2.5 && clearing.has(c.x, c.z)) W.circles.splice(i, 1);
    }
    const seg = (ax, az, bx, bz, h = 4, y0 = 0) => {
      const a = toW(ax, az);
      const b = toW(bx, bz);
      W.addWallSegment(a.x, a.z, b.x, b.z, h, y0);
      const s = W.segments[W.segments.length - 1];
      s.home = true;
      this.segs.push(s);
    };
    // the walls: solid everywhere but the doorways (laid again when a room is closed or opened: relayWalls)
    this.layWalls = () => {
    for (const w of D.walls) {
      const L = Math.hypot(w.b[0] - w.a[0], w.b[1] - w.a[1]);
      const dx = (w.b[0] - w.a[0]) / L, dz = (w.b[1] - w.a[1]) / L;
      const holes = w.open.map((o) => ({ o, def: OPENINGS[o.kind] })).filter(({ o, def }) => def && !def.solid && def.sill === 0 && !this.shut(w, o)).map(({ o, def }) => [o.at - def.w / 2, o.at + def.w / 2]).sort((p, q) => p[0] - q[0]);
      let s = 0;
      for (const [h0, h1] of [...holes, [L, L]]) {
        // (downstairs walls end under the upper floor: up there you walk over them; upstairs ones start on it)
        const y0 = (w.level || 0) * LEVEL_H;
        if (h0 - s > 0.02) seg(w.a[0] + dx * s, w.a[1] + dz * s, w.a[0] + dx * h0, w.a[1] + dz * h0, w.level ? y0 + 3.0 : 3.1, w.level ? y0 - 0.2 : 0);
        s = Math.max(s, h1);
      }
    }
    };
    this.wallRec = this.track(this.layWalls);
    // the placed pieces: their circles, their seats, the special ones
    this.recs = new Map();
    for (const it of this.decor.items) this.layItem(it);
    // the decks you step up onto (the porch, the balcony), the upper floor, the stairs: platforms (world.solids)
    const solid = (x, z, r, top, bottom) => {
      const p = toW(x, z);
      const sol = { type: "cyl", x: p.x, z: p.z, r, top, bottom, home: true };
      W.solids.push(sol);
      (this.solids ||= []).push(sol);
    };
    const deck = (x0, x1, z0, z1, top, skip = null) => {
      for (let x = x0 + 0.35; x <= x1 - 0.3 + 1e-6; x += 0.62)
        for (let z = z0 + 0.35; z <= z1 - 0.3 + 1e-6; z += 0.62) if (!skip?.(x, z)) solid(x, z, 0.42, top, top - 0.3);
    };
    for (const [x0, x1, z0, z1, top] of D.decks || []) {
      deck(x0, x1, z0, z1, top);
      // (a raised one has its railing on its three open sides)
      if (top > 1) {
        seg(x0, z0, x1, z0, top + 1.1, top - 0.3);
        seg(x0, z0, x0, z1 - 0.2, top + 1.1, top - 0.3);
        seg(x1, z0, x1, z1 - 0.2, top + 1.1, top - 0.3);
      }
    }
    if ((D.levels || 1) > 1) {
      const [hx0b, hz0b, hx1b, hz1b] = D.rect;
      const [ox0, oz0, ox1, oz1] = D.hole;
      deck(hx0b, hx1b, hz0b, hz1b, LEVEL_H, (x, z) => x > ox0 - 0.36 && x < ox1 + 0.36 && z > oz0 - 0.36 && z < oz1 + 0.36);
      // the rail round the stairs' hole, up there
      seg(ox1, oz0, ox1, oz1, LEVEL_H + 1.1, LEVEL_H - 0.2);
      seg(ox0, oz1, ox1, oz1, LEVEL_H + 1.1, LEVEL_H - 0.2);
    }
    const st = D.stairs;
    if (st) {
      for (let i = 1; i <= st.n; i++) {
        const z = st.at[1] - (i - 0.5) * st.tread;
        for (const sx of [-0.3, 0.3]) solid(st.at[0] + sx * st.w, z, 0.34, i * st.rise, i * st.rise - 0.35);
      }
      // its sides (the wall it runs along has one; the open side, a banister)
      seg(st.at[0] + st.w / 2 + 0.05, st.at[1] - 0.3, st.at[0] + st.w / 2 + 0.05, st.at[1] - st.n * st.tread, 3.1, 0.9);
    }
    // the veranda's railings (D.rails: [x0, z0, x1, z1]), open at its steps
    for (const [ax, az, bx, bz] of D.rails || []) seg(ax, az, bx, bz, 1.1);
    // the light indoors: over the middle of whichever room you are in (island.js roomLight)
    room.lampY = 2.55;
    // the bouquet vase: on the photo dresser (bouquets.js)
    const dr = this.decor.items.find((i) => i.special === "profiles");
    if (dr) room.vaseSpot = { x: dr.x, z: dr.z + 0.04, y: 0.86 + FLOOR_TOP };
  }

  // the room on one side of a wall at s metres along it
  sideRoom(w, side, s) {
    let r = side === "l" ? w.l : w.r;
    for (const [at, name] of (side === "l" ? w.split : w.splitR) || []) if (s >= at) r = name;
    return r;
  }
  // a door into a room we closed (the editor's "closed"): shut, and solid
  shut(w, o) {
    if (o.kind !== "door_in") return false;
    const locked = (id) => this.data.rooms.find((r) => r.id === id)?.locked;
    return Boolean(locked(this.sideRoom(w, "l", o.at)) || locked(this.sideRoom(w, "r", o.at)));
  }

  // a piece's matrix in the house's frame
  itemMatrix(it, out = new THREE.Matrix4()) {
    const y = (it.y || 0) + (it.level || 0) * LEVEL_H + (it.room && it.room !== "out" ? FLOOR_TOP : 0);
    out.makeRotationY(it.rot || 0).setPosition(it.x, y, it.z);
    if (it.sx) out.multiply(_m2.makeScale(it.sx, 1, 1));
    return out;
  }

  // what laying something added to the world (its colliders, taps, little markers), so it can be taken back
  track(fn) {
    const W = this.world;
    const n = { segments: W.segments.length, circles: W.circles.length, solids: W.solids.length, inter: W.interactables.length, anim: W.animated.length, kids: this.group.children.length };
    fn();
    return {
      segments: W.segments.slice(n.segments),
      circles: W.circles.slice(n.circles),
      solids: W.solids.slice(n.solids),
      inter: W.interactables.slice(n.inter),
      anim: W.animated.slice(n.anim),
      kids: this.group.children.slice(n.kids),
    };
  }
  untrack(r) {
    if (!r) return;
    const W = this.world;
    const drop = (arr, list) => {
      if (!list.length) return;
      const set = new Set(list);
      for (let i = arr.length - 1; i >= 0; i--) if (set.has(arr[i])) arr.splice(i, 1);
    };
    drop(W.segments, r.segments);
    drop(W.circles, r.circles);
    drop(W.solids, r.solids);
    drop(W.interactables, r.inter);
    drop(W.animated, r.anim);
    for (const k of r.kids) {
      k.removeFromParent();
      k.traverse?.((o) => o.geometry?.dispose?.());
    }
    drop(this.circles, r.circles);
    drop(this.solids || [], r.solids);
    drop(this.segs || [], r.segments);
    drop(this.screens, r.kids);
  }
  // a piece laid again (moved, turned, recoloured), or taken away
  relayItem(id) {
    this.untrack(this.recs.get(id));
    this.recs.delete(id);
    this.items = this.items.filter((q) => q.id !== id);
    const it = this.decor.get(id);
    if (it) this.layItem(it);
  }

  layItem(it) {
    this.recs.set(it.id, this.track(() => this.layItem0(it)));
  }

  layItem0(it) {
    const W = this.world;
    const room = this.room;
    const P = PIECES[it.piece];
    if (!P) return;
    const cos = Math.cos(it.rot || 0), sin = Math.sin(it.rot || 0);
    const loc = (x, z) => [it.x + x * cos + z * sin, it.z - x * sin + z * cos];
    const toW = (x, z) => {
      const [lx, lz] = loc(x, z);
      return W.toWorld(room, lx, 0, lz);
    };
    // runs (a fence, a flower bed): a low wall along them
    // (on its own floor: the landing's banister stood as a low wall at the foot of the stairs, "there is something
    // blocking me", user 2026-11-28; the stairs' hole has its own rail, lay())
    if (P.run && it.len && it.piece !== "stair_rail") {
      const a = toW(-it.len / 2, 0), b = toW(it.len / 2, 0);
      const y0 = (it.level || 0) * LEVEL_H;
      W.addWallSegment(a.x, a.z, b.x, b.z, y0 + (it.piece === "fence" ? 1.0 : 0.5), y0);
      const s = W.segments[W.segments.length - 1];
      s.home = true;
      s.free = true; // (low: the camera looks over it, as over any fence)
      s.room = "";
      (this.segs ||= []).push(s);
    }
    const base = (it.level || 0) * LEVEL_H + (it.room === "out" ? it.y || 0 : 0);
    for (const [x, z, r] of P.col || []) {
      const p = toW(x, z);
      // (downstairs a circle; upstairs a platform with a foot, so nothing up there is in the way down here)
      const top = base + Math.max(P.top ?? 1, 0.5);
      const c = it.level ? { type: "cyl", x: p.x, z: p.z, r, top, bottom: base, home: true } : { x: p.x, z: p.z, r, top, home: true };
      if (it.level) (W.solids.push(c), (this.solids ||= []).push(c));
      else (W.circles.push(c), this.circles.push(c));
    }
    const facing = room.group.rotation.y + (it.rot || 0);
    const y0 = base;
    let k = 0;
    for (const [x, z, h] of P.seats || []) {
      const [lx, lz] = loc(x, z);
      const pos = W.toWorld(room, lx, 0, lz);
      pos.y = y0;
      const id = `seat-home-${it.id}-${k++}`;
      const label = it.piece === "porch_swing" ? "swing together ♡" : it.piece === "beanbag" ? "flop in the bean bag ♡" : it.piece === "window_seat" ? "curl up by the window ♡" : "sit ♡";
      // (its own piece to measure the cushion on, island.js measureSeat: never the whole merged house)
      W.interact(room, { id, label, local: [lx, y0, lz], radius: 1.2, action: { type: "sit", seat: { pos, facing, h, id, meshes: () => this.seatMeshes(it.id) } } });
    }
    if (P.lie) {
      const seats = P.lie.map(([x, z]) => {
        const [lx, lz] = loc(x, z);
        return { pos: W.toWorld(room, lx, 0, lz).setY(y0), facing, h: 0.7, lie: true, local: [lx, lz] };
      });
      seats.forEach((seat, i) => {
        seat.pair = seats;
        W.interact(room, { id: `bed-${it.id}-${i}`, label: "lie down ♡", local: [seat.local[0], y0, seat.local[1]], radius: 1.4, action: { type: "sit", seat } });
      });
    }
    // our two profiles, side by side over the dresser; the mirror: change your look
    if (it.special === "profile" || it.special === "profile-partner") {
      const partner = it.special === "profile-partner";
      const s = this.K.makeScreen(1.0, 1.35, { placeholder: "profile ♡", border: partner ? "#f29ac0" : "#b79be8" });
      this.itemMatrix(it, _m);
      s.mesh.matrixAutoUpdate = true;
      s.mesh.position.set(0, 0, 0.035).applyMatrix4(_m);
      s.mesh.rotation.y = it.rot || 0;
      this.group.add(s.mesh);
      this.screens.push(s.mesh);
      const [fx, fz] = loc(0, 1.25);
      W.interact(room, partner ? { id: "profile-partner", label: "open their profile ♡", local: [fx, y0, fz], radius: 1.3, action: { type: "partnerProfile" }, screen: { s, source: { type: "profile", who: "partner" } } } : { id: "profile", label: "open your profile", local: [fx, y0, fz], radius: 1.3, action: { type: "click", selector: "#profileBtn" }, screen: { s, source: { type: "profile" } } });
      this.K.marker(W, this.group, ...new THREE.Vector3(0, 0.95, 0.1).applyMatrix4(_m).toArray());
    }
    if (it.special === "mirror") {
      const [fx, fz] = loc(0, 1.1);
      W.interact(room, { id: "mirror", label: "change your look", local: [fx, y0, fz], radius: 1.6, action: { type: "avatar" } });
      this.itemMatrix(it, _m);
      this.K.marker(W, this.group, ...new THREE.Vector3(0, 2.25, 0).applyMatrix4(_m).toArray());
    }
    this.items.push(it);
  }

  // how far a point (world, x z) stands outside the fenced plot (0 inside it)
  plotDist(x, z) {
    const l = this.room.group.worldToLocal(_v.set(x, 0, z));
    return Math.hypot(Math.max(PLOT[0] - l.x, 0, l.x - PLOT[2]), Math.max(PLOT[1] - l.z, 0, l.z - PLOT[3]));
  }
  // is a point (world) inside the house's walls?
  contains(p) {
    const l = this.room.group.worldToLocal(_v.copy(p));
    const [x0, z0, x1, z1] = this.data.rect;
    return l.x > x0 && l.x < x1 && l.z > z0 && l.z < z1 && l.y < (this.data.levels || 1) * LEVEL_H;
  }
  // inside the walls (house frame x, z)?
  containsLocal(x, z) {
    const [x0, z0, x1, z1] = this.data.rect;
    return x > x0 && x < x1 && z > z0 && z < z1;
  }
  // colliders that are not the house's own but stand inside its walls (zones streamed in later: the old room's, the
  // scenery's) go: one stood at the foot of the stairs ("there is something blocking me", user 2026-11-28)
  sweep() {
    const W = this.world;
    const n = W.circles.length + W.solids.length * 1000 + W.segments.length * 1000000;
    if (n === this._swept) return;
    const g = this.room.group;
    const [x0, z0, x1, z1] = this.data.rect;
    const inPlot = (x, z) => {
      const l = g.worldToLocal(_v.set(x, 0, z));
      return l.x > x0 - 0.6 && l.x < x1 + 0.6 && l.z > z0 - 0.6 && l.z < z1 + 0.6;
    };
    const keep = (c) => c.home || !inPlot(c.x, c.z);
    // (and the trees' and rocks' little circles streamed in later inside the fence: the garden and the backyard)
    const inYard = (x, z) => {
      const l = g.worldToLocal(_v.set(x, 0, z));
      return l.x > PLOT[0] - 0.2 && l.x < PLOT[2] + 0.2 && l.z > PLOT[1] - 0.2 && l.z < PLOT[3] + 0.25;
    };
    for (let i = W.circles.length - 1; i >= 0; i--) {
      const c = W.circles[i];
      if (!keep(c) || (!c.home && c.r <= 2.5 && !c.soft && inYard(c.x, c.z))) W.circles.splice(i, 1);
    }
    for (let i = W.solids.length - 1; i >= 0; i--) if (!keep(W.solids[i])) W.solids.splice(i, 1);
    for (let i = W.segments.length - 1; i >= 0; i--) {
      const s = W.segments[i];
      if (!s.home && inPlot((s.ax + s.bx) / 2, (s.az + s.bz) / 2)) W.segments.splice(i, 1);
    }
    this._swept = W.circles.length + W.solids.length * 1000 + W.segments.length * 1000000;
  }
  // how far along from -> to (world) stays inside the house's walls (the rooms' camera, island.js roomReach)
  reach(from, to) {
    const g = this.room.group;
    const A = g.worldToLocal(_v.copy(from));
    const ax = A.x, az = A.z;
    const B = g.worldToLocal(_v.copy(to));
    const bx = B.x - ax, bz = B.z - az;
    const [x0, z0, x1, z1] = this.data.rect;
    const m = 0.35;
    if (ax < x0 + m || ax > x1 - m || az < z0 + m || az > z1 - m) return 1;
    let s = 1;
    if (Math.abs(bx) > 1e-9) s = Math.min(s, ((bx > 0 ? x1 - m : x0 + m) - ax) / bx);
    if (Math.abs(bz) > 1e-9) s = Math.min(s, ((bz > 0 ? z1 - m : z0 + m) - az) / bz);
    return Math.max(0, s);
  }
  // the ceiling over a point inside (world y): the floor above, or up the stairs' hole the upper ceiling
  ceilAt(p) {
    const l = this.room.group.worldToLocal(_v.copy(p));
    const gy = this.room.group.position.y;
    const two = (this.data.levels || 1) > 1;
    const [hx0, hz0, hx1, hz1] = this.data.hole || [0, 0, 0, 0];
    const inHole = two && l.x > hx0 - 0.7 && l.x < hx1 + 0.7 && l.z > hz0 - 0.7 && l.z < hz1 + 0.7;
    return gy + (inHole || this.levelOf(p) ? LEVEL_H : 0) + this.data.wallH;
  }
  // which floor a point is on
  levelOf(p) {
    return (this.data.levels || 1) > 1 && p.y > LEVEL_H - 1.2 ? 1 : 0;
  }
  // the room you are in (by the data), for the light
  roomOf(p) {
    const l = this.room.group.worldToLocal(_v.copy(p));
    const lv = this.levelOf(p);
    return this.data.rooms.find((r) => (r.level || 0) === lv && l.x >= r.rect[0] && l.x <= r.rect[2] && l.z >= r.rect[1] && l.z <= r.rect[3]) || null;
  }

  // ---- the look: the kit, merged per kind of surface ------------------------------------------------------------
  // tier: "base" the house's own flat faces (walls, ceilings), drawn a hair behind; "front" the placed pieces, a hair
  // in front: whatever lies flat on a wall or a floor wins the depth test, never fights it (the flicker inside and
  // out, user 2026-11-28)
  material(kind, layer, tier = "") {
    const key = `${kind}|${layer}|${tier}`;
    if (this.mats.has(key)) return this.mats.get(key);
    const K = SURFACE_KINDS[kind] || SURFACE_KINDS.fixed;
    let m;
    if (kind === "glass") m = new THREE.MeshStandardMaterial({ vertexColors: true, transparent: true, opacity: 0.28, roughness: 0.05, metalness: 0.1, depthWrite: false });
    else if (kind === "mirror") m = new THREE.MeshStandardMaterial({ color: "#eef4ff", roughness: 0.06, metalness: 0.95 });
    else m = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: K.rough ?? 0.7, metalness: K.metal || 0, map: K.pattern ? patternTexture(K.pattern) : null });
    m.name = `home_${key}`;
    if (tier) {
      m.polygonOffset = true;
      m.polygonOffsetFactor = tier === "base" ? 1 : -1;
      m.polygonOffsetUnits = tier === "base" ? 2 : -2;
    }
    if (layer === "cut" || layer === "furn") m.side = THREE.DoubleSide;
    // (only back faces into the sun's shadow map: the two-sided walls shadowed their own lit faces in stripes)
    m.shadowSide = THREE.BackSide;
    const U = this.U;
    const cutY = layer === "cut" ? 0.95 : layer === "furn" ? 1.25 : -1; // (above your floor: uCutBase)
    const detail = K.map && !this.small ? { uDetailK: { value: K.k }, uDetailMean: { value: DETAIL_MEAN[K.map] || 0.24 } } : null;
    const glow = K.glow || 0;
    m.onBeforeCompile = (sh) => {
      Object.assign(sh.uniforms, U, detail || {});
      sh.vertexShader = sh.vertexShader.replace("void main() {", "varying vec3 vHomeW;\nvoid main() {").replace("#include <worldpos_vertex>", "#include <worldpos_vertex>\nvHomeW = (modelMatrix * vec4(transformed, 1.0)).xyz;");
      const head = "varying vec3 vHomeW;\nuniform vec3 uCutP;\nuniform vec2 uCutD;\nuniform float uCutOn;\nuniform float uCutBase;\nuniform float uMaxY;\nuniform float uRoofHide;\nuniform float uGlow;\n";
      let body = layer === "roof" ? "" : "if (vHomeW.y > uMaxY) discard;\n";
      if (cutY > 0)
        body += `{ float side = dot(vHomeW.xz - uCutP.xz, uCutD); float k = uCutOn * step(0.25, side); if (vHomeW.y > mix(60.0, uCutBase + ${cutY.toFixed(2)}, k)) discard; }\n`;
      if (layer === "roof") body += "if (uRoofHide > 0.001 && fract(sin(dot(floor(gl_FragCoord.xy), vec2(12.9898, 78.233))) * 43758.5453) < uRoofHide) discard;\n";
      sh.fragmentShader = sh.fragmentShader.replace("void main() {", head + (detail ? "uniform float uDetailK;\nuniform float uDetailMean;\n" : "") + "void main() {\n" + body);
      if (detail)
        sh.fragmentShader = sh.fragmentShader.replace(
          "#include <map_fragment>",
          `#ifdef USE_MAP
  { vec3 dT = texture2D(map, vMapUv).rgb; float dl = pow(max(dot(dT, vec3(0.3333)), 1e-4), 1.0 / 2.2) / uDetailMean; diffuseColor.rgb *= clamp(mix(1.0, dl, uDetailK), 0.45, 1.6); }
#endif`,
        );
      // (a wall or piece cut down shows a clean flat cap: what is seen of its inside is drawn as a level top in one
      // soft colour, lit from above, instead of the hollow edges of its faces)
      if (cutY > 0)
        sh.fragmentShader = sh.fragmentShader
          .replace("#include <color_fragment>", "#include <color_fragment>\nif (!gl_FrontFacing && uCutOn > 0.01) diffuseColor.rgb = vec3(0.93, 0.89, 0.86);")
          .replace("#include <normal_fragment_maps>", "#include <normal_fragment_maps>\nif (!gl_FrontFacing && uCutOn > 0.01) normal = normalize((viewMatrix * vec4(0.0, 1.0, 0.0, 0.0)).xyz);");
      if (glow) sh.fragmentShader = sh.fragmentShader.replace("#include <emissivemap_fragment>", `#include <emissivemap_fragment>\n#ifdef USE_COLOR\ntotalEmissiveRadiance += vColor.rgb * ${glow.toFixed(2)} * (0.25 + uGlow);\n#endif`);
    };
    m.customProgramCacheKey = () => `home|${layer}|${detail ? 1 : 0}|${glow}`;
    if (detail)
      withSurfaceMap(K.map, K.rep || 1, (t) => {
        m.map = t;
        m.bumpMap = t;
        m.bumpScale = K.bump || 0.3;
        m.needsUpdate = true;
      });
    this.mats.set(key, m);
    return m;
  }

  // load the kit and lay the house's look (once; again when the data changes)
  async build() {
    if (this.built || this.loading) return;
    this.loading = true;
    const kit = await loadKit(this.small);
    // (computers: the Blender _lite kit, about a quarter of the triangles, is the outside's far version: update())
    const far = this.small ? null : await loadKit(true).catch(() => null);
    this.loading = false;
    if (!kit || this.gone) return;
    this.kit = kit;
    this.kitFar = far;
    this.assemble();
    this.built = true;
    this.world.onShadowsChanged?.();
  }

  // part: "all", "shell" (the house itself: walls, floors, roof) or "items" (the placed pieces); skip: a piece left out
  // (lifted by the editor: it is drawn on its own while it moves)
  assemble(part = "all", skip = null) {
    const kit = this.kit;
    const D = this.data;
    const buckets = new Map(); // `${kind}|${layer}` -> [geometry]
    const doShell = part !== "items";
    const doItems = part !== "shell";
    let curPart = "shell";
    // (the outside's pieces twice where there is a far kit: "near" from the full kit, "far" from the lite one, the
    // same piece in the same place; the insides once, "in")
    const put = (role, look, matrix, layer) => {
      const g = kit.get(role);
      if (!g || !look) return;
      const gf = this._inner ? null : this.kitFar?.get(role);
      put1(g, role, look, matrix, layer, this._inner ? "|in" : gf ? "|near" : "");
      if (gf) put1(gf, role, look, matrix, layer, "|far");
    };
    const put1 = (g, role, look, matrix, layer, lod) => {
      const c = g.clone();
      c.applyMatrix4(matrix);
      // (floor tiles lie flat: their bevels' smoothed normals made every board shade light to dark from above)
      // (the siding's laps face straight out: their capped ends' smoothed normals read as blocks a metre long)
      if (role === "siding_course__siding" && c.attributes.normal) {
        const nn = new THREE.Vector3(0, 0, 1).transformDirection(matrix);
        for (let i = 0; i < c.attributes.normal.count; i++) c.attributes.normal.setXYZ(i, nn.x, nn.y, nn.z);
      }
      if (role.startsWith("floor_") && c.attributes.normal) for (let i = 0; i < c.attributes.normal.count; i++) c.attributes.normal.setXYZ(i, 0, 1, 0);
      // the slot's colour into its vertex colours
      if (look.kind !== "fixed" && look.kind !== "mirror" && look.color) {
        _c.set(look.color);
        const col = c.attributes.color;
        // (floorboards: their tones and joints a little softer seen from above)
        if (look.kind === "floorwood" && col) for (let i = 0; i < col.count; i++) for (let j = 0; j < 3; j++) col.setComponent(i, j, 0.93 + (col.getComponent(i, j) - 0.93) * 0.7);
        if (col) for (let i = 0; i < col.count; i++) col.setXYZ(i, col.getX(i) * _c.r, col.getY(i) * _c.g, col.getZ(i) * _c.b);
      }
      const key = `${curPart}|${look.kind === "fixed" ? "fixed" : look.kind}|${layer}|${lod.slice(1)}|${curPart === "items" ? "front" : ""}`;
      if (!buckets.has(key)) buckets.set(key, []);
      buckets.get(key).push(c);
    };
    // every slot of a piece: its own look, the house's surfaces for the shell's slots
    const piece = (name, matrix, layer, lookOf) => {
      for (const role of this.rolesOf(name)) {
        const slot = role.slice(name.length + 2);
        put(role, SPECIAL[slot] || lookOf(slot), matrix, layer);
      }
    };
    const surf = (name) => D.surfaces[name] || null;
    const wallGeo = new Map(); // kind|layer -> {pos, nrm, uv, col}
    const quad = (kind, layer, p0, p1, p2, p3, n, color, shade = null) => {
      const key = `shell|${kind}|${layer}|${this._inner ? "in" : ""}|base`;
      if (!wallGeo.has(key)) wallGeo.set(key, { pos: [], nrm: [], uv: [], col: [] });
      const G = wallGeo.get(key);
      _c.set(color);
      const ax = Math.abs(n.x) > Math.abs(n.z) ? "z" : "x";
      for (const [p, i] of [[p0, 0], [p1, 1], [p2, 2], [p0, 0], [p2, 2], [p3, 3]]) {
        G.pos.push(p.x, p.y, p.z);
        G.nrm.push(n.x, n.y, n.z);
        G.uv.push(n.y > 0.5 || n.y < -0.5 ? p.x : p[ax], n.y > 0.5 || n.y < -0.5 ? p.z : p.y);
        const s = shade ? shade(p, i) : 1;
        G.col.push(_c.r * s, _c.g * s, _c.b * s);
      }
    };
    // (computers: what is only seen from inside (the rooms' faces, floors, ceilings, trims and furniture) is merged
    // apart from what shows outside, so the house seen from far off draws its outside alone, update(); it was
    // 780k triangles of the willow's view, most of them furniture behind the walls)
    this._inner = false;
    if (doShell) this.assembleShell(D, piece, put, quad, surf);
    // ---- every placed piece
    curPart = "items";
    if (doItems)
      for (const it of this.decor.items) {
        if (it.id === skip) continue;
        this._inner = !this.small && it.room !== "out";
        this.pieceOf(it, piece);
      }
    this._inner = false;
    this.merge(buckets, wallGeo, part);
  }

  // one placed piece's parts (piece(name, matrix, layer, lookOf))
  pieceOf(it, piece) {
    const P = PIECES[it.piece];
    if (!P) return;
    const layer = it.room === "out" && !it.level ? "plain" : P.flat ? "plain" : "furn";
    const look = (slot) => {
      const l = slotLook(this.data, it, slot);
      // (a lamp switched off: its glow goes dim)
      return it.off && l && (l.kind === "glow" || l.kind === "shade") ? { kind: l.kind === "glow" ? "fixed" : "fabric", color: l.color } : l;
    };
    const m = this.itemMatrix(it, new THREE.Matrix4());
    if (P.run && it.len) {
      const n = Math.max(1, Math.round(it.len / (this.small ? 2 : 1)));
      const sx = it.len / n;
      for (let k = 0; k < n; k++) piece(it.piece, m.clone().multiply(new THREE.Matrix4().makeScale(sx, 1, 1).setPosition(-it.len / 2 + (k + 0.5) * sx, 0, 0)), layer, look);
      // (a fence stands on posts: one at each end and about every 2.5 m)
      if (it.piece === "fence") {
        const np = Math.max(1, Math.round(it.len / 2.5));
        for (let k = 0; k <= np; k++) piece("fence_post", m.clone().multiply(new THREE.Matrix4().makeTranslation(-it.len / 2 + (k * it.len) / np, 0, -0.015)), layer, look);
      }
    } else piece(it.piece, m, layer, look);
  }

  // the house itself: walls, trims, doors and windows, floors, ceilings, the roof
  assembleShell(D, piece, put, quad, surf) {
    const WH = D.wallH;
    const T = D.wallT;
    // (phones: the trims in 2 m lengths, the floors in 2 m tiles, no siding courses or stone foot: the painted wall)
    const BIG = this.small ? 2 : 1;
    const two = (D.levels || 1) > 1;
    // ---- walls: their faces (plaster in the rooms' colours, paint outside), skirting, cornices, panelling, siding
    const roomAt = (w, side, s) => {
      let r = side === "l" ? w.l : w.r;
      for (const [at, name] of (side === "l" ? w.split : w.splitR) || []) if (s >= at) r = name;
      return r;
    };
    const roomDef = (id) => D.rooms.find((r) => r.id === id);
    for (const w of D.walls) {
      const a = new THREE.Vector3(w.a[0], 0, w.a[1]);
      const b = new THREE.Vector3(w.b[0], 0, w.b[1]);
      const L = a.distanceTo(b);
      const d = b.clone().sub(a).divideScalar(L);
      const nL = new THREE.Vector3(d.z, 0, -d.x);
      const nR = nL.clone().negate();
      // (its floor: downstairs walls run up to the upper floor's top, upstairs ones stand on it)
      const Y0 = (w.level || 0) * LEVEL_H;
      const H = !w.level && two ? LEVEL_H : WH;
      const at = (s, y = 0) => a.clone().addScaledVector(d, s).setY(y + Y0);
      // (a soft darkening near the floor and under the cornice, like the baked AO on the pieces)
      const wallShade = (p) => 0.86 + 0.14 * Math.min(1, (p.y - Y0) / 0.7) - 0.06 * Math.max(0, (p.y - Y0 - (WH - 0.4)) / 0.4);
      const opens = w.open.map((o) => ({ ...o, def: OPENINGS[o.kind] })).filter((o) => o.def);
      // the breaks along the wall: the openings' edges and the rooms' changes
      const cuts = new Set([0, L]);
      for (const o of opens) if (!o.def.solid) (cuts.add(o.at - o.def.w / 2), cuts.add(o.at + o.def.w / 2));
      for (const [s] of [...(w.split || []), ...(w.splitR || [])]) cuts.add(s);
      const xs = [...cuts].filter((s) => s >= 0 && s <= L).sort((p, q) => p - q);
      for (let i = 0; i < xs.length - 1; i++) {
        const s0 = xs[i], s1 = xs[i + 1];
        if (s1 - s0 < 0.005) continue;
        const mid = (s0 + s1) / 2;
        const o = opens.find((q) => !q.def.solid && Math.abs(q.at - mid) < q.def.w / 2);
        const spans = o ? [[0, o.def.sill], [o.def.sill + o.def.h, H]].filter(([y0, y1]) => y1 - y0 > 0.01) : [[0, H]];
        for (const side of ["l", "r"]) {
          const n = side === "l" ? nL : nR;
          const rid = roomAt(w, side, mid);
          const out = rid === "out";
          const color = out ? surf("siding")?.color : surf(roomDef(rid)?.wall)?.color;
          const kind = out ? "paint" : surf(roomDef(rid)?.wall)?.kind || "plaster";
          const off = n.clone().multiplyScalar(T / 2);
          this._inner = !out && !this.small;
          for (const [y0, y1] of spans) {
            const p0 = at(s0, y0).add(off), p1 = at(s1, y0).add(off), p2 = at(s1, y1).add(off), p3 = at(s0, y1).add(off);
            if (side === "l") quad(kind, "cut", p1, p0, p3, p2, n, color || "#ffffff", out ? null : wallShade);
            else quad(kind, "cut", p0, p1, p2, p3, n, color || "#ffffff", out ? null : wallShade);
          }
        }
        this._inner = false;
        // the top cap, and the reveals' tops and bottoms are the openings' own linings
        const tl = at(s0, H).add(nL.clone().multiplyScalar(T / 2)), tr = at(s1, H).add(nL.clone().multiplyScalar(T / 2));
        const bl = at(s0, H).add(nR.clone().multiplyScalar(T / 2)), br = at(s1, H).add(nR.clone().multiplyScalar(T / 2));
        quad("paint", "cut", bl, br, tr, tl, UP, surf("trim")?.color || "#ffffff");
      }
      // the wall's two ends (a free end shows), the reveals beside each opening
      for (const s of [0, L]) {
        const n = s === 0 ? d.clone().negate() : d.clone();
        const pL = at(s).add(nL.clone().multiplyScalar(T / 2)), pR = at(s).add(nR.clone().multiplyScalar(T / 2));
        const q = [pL.clone(), pR.clone(), pR.clone().setY(Y0 + H), pL.clone().setY(Y0 + H)];
        if (s === 0) quad("paint", "cut", q[1], q[0], q[3], q[2], n, surf("trim")?.color || "#ffffff");
        else quad("paint", "cut", q[0], q[1], q[2], q[3], n, surf("trim")?.color || "#ffffff");
      }
      // ---- the trims along each face
      for (const side of ["l", "r"]) {
        const n = side === "l" ? nL : nR;
        const t = new THREE.Vector3(n.z, 0, -n.x); // (the module's +x along the face, its +z out of it)
        const flip = t.dot(d) < 0;
        const face = (s0, s1, y, role, look, layer, sy = 1) => {
          if (s1 - s0 < 0.04) return;
          const len = s1 - s0;
          const nm = Math.max(1, Math.round(len / BIG));
          const sx = len / nm;
          for (let k = 0; k < nm; k++) {
            const sa = flip ? s1 - k * sx : s0 + k * sx;
            // (the skirting stands 3 mm proud of the panelling it runs along: their faces lay in one plane)
            const o = at(sa, y).add(n.clone().multiplyScalar(T / 2 + (role === "base_in__skirting" ? 0.003 : 0)));
            _m.makeBasis(t.clone().multiplyScalar(sx), UP.clone().multiplyScalar(sy), n).setPosition(o);
            put(role, look, _m, layer);
          }
        };
        // spans of this face between [from, to] avoiding the openings (pad: their casings), split at room changes
        const free = (blocks, s0 = 0, s1 = L) => {
          const out = [];
          let s = s0;
          for (const [b0, b1] of blocks.sort((p, q) => p[0] - q[0])) {
            if (b0 > s) out.push([s, Math.min(b0, s1)]);
            s = Math.max(s, b1);
          }
          if (s < s1) out.push([s, s1]);
          return out.filter(([p, q]) => q - p > 0.03);
        };
        const ends = (s0, s1) => [Math.max(s0, 0 + (w.l === "out" || w.r === "out" ? -T / 2 : T / 2)), Math.min(s1, L - (w.l === "out" || w.r === "out" ? -T / 2 : T / 2))];
        const rid0 = roomAt(w, side, 0.01);
        const isOut = rid0 === "out";
        const breaks = [0, ...[...(side === "l" ? w.split || [] : w.splitR || [])].map(([s]) => s), L];
        for (let bi = 0; bi < breaks.length - 1; bi++) {
          let [r0, r1] = [breaks[bi], breaks[bi + 1]];
          const rid = roomAt(w, side, (r0 + r1) / 2);
          if (rid === "out") {
            // outside: the stone foot, the siding's courses, avoiding the openings and their casings
            const doorBlocks = opens.filter((o) => !o.def.solid && o.def.sill === 0).map((o) => [o.at - o.def.w / 2 - 0.15, o.at + o.def.w / 2 + 0.15]);
            [r0, r1] = [r0 - T / 2, r1 + T / 2];
            if (this.small) continue;
            if (!w.level) for (const [p, q] of free(doorBlocks, r0, r1)) face(p, q, 0, "plinth__plinth", surf("plinth"), "cut");
            // (a band of trim between the storeys)
            else for (const [p, q] of free(doorBlocks, r0, r1)) face(p, q, -0.1, "base_in__skirting", surf("trim"), "cut", 1.2);
            for (let y = w.level ? 0.05 : 0.42; y < H - 0.05; y += 0.205) {
              const blocks = opens.filter((o) => !o.def.solid && y + 0.205 > o.def.sill - 0.14 && y < o.def.sill + o.def.h + 0.2).map((o) => [o.at - o.def.w / 2 - 0.13, o.at + o.def.w / 2 + 0.13]);
              for (const [p, q] of free(blocks, r0, r1)) face(p, q, y, "siding_course__siding", surf("siding"), "cut", Math.min(1, (H - y) / 0.205));
            }
          } else {
            const rd = roomDef(rid);
            this._inner = !this.small;
            const pad = (side === "l" ? w.l : w.r) === "out" || (side === "l" ? w.r : w.l) === "out" ? 0 : 0;
            void pad;
            // the face runs between the walls that meet it (their half thickness in)
            const s0 = r0 === 0 ? T / 2 : r0 + T / 2, s1 = r1 === L ? L - T / 2 : r1 - T / 2;
            const doorBlocks = opens.filter((o) => !o.def.solid && o.def.sill === 0).map((o) => [o.at - o.def.w / 2 - 0.12, o.at + o.def.w / 2 + 0.12]);
            const lowBlocks = opens.filter((o) => (!o.def.solid && o.def.sill < 1.06) || o.def.solid).map((o) => [o.at - o.def.w / 2 - 0.12, o.at + o.def.w / 2 + 0.12]);
            const fireBlocks = opens.filter((o) => o.def.solid).map((o) => [o.at - o.def.w / 2 - 0.05, o.at + o.def.w / 2 + 0.05]);
            for (const [p, q] of free([...doorBlocks, ...fireBlocks], s0, s1)) face(p, q, 0, "base_in__skirting", surf("skirting"), "cut");
            for (const [p, q] of free(fireBlocks, s0, s1)) face(p, q, WH, "crown_in__skirting", surf("skirting"), "cut");
            if (rd?.wainscot) for (const [p, q] of free(lowBlocks, s0, s1)) face(p, q, 0, "wainscot__wainscot", surf(rd.wainscot), "cut");
            this._inner = false;
          }
        }
        void isOut;
        void ends;
      }
      // ---- the doors and windows
      for (const o of opens) {
        if (o.def.solid) continue;
        const pieceName = o.def.piece || o.kind;
        const p = at(o.at);
        _m.makeBasis(new THREE.Vector3(nR.z, 0, -nR.x), UP, nR).setPosition(p);
        if (o.def.scaleY) _m.multiply(_m2.makeScale(1, o.def.scaleY, 1)).setPosition(p.clone().setY(Y0 + o.def.sill - OPENINGS[pieceName].sill * o.def.scaleY));
        const slots = SHELL_SLOTS[pieceName] || {};
        const rA = roomAt(w, "r", o.at), rB = roomAt(w, "l", o.at);
        // (a closed room's door: its leaf swung back shut into its frame, Blender's open swing undone about its hinge)
        if (this.shut(w, o)) {
          const close = new THREE.Matrix4().makeTranslation(-0.48, 0.01, 0).multiply(new THREE.Matrix4().makeRotationY(-(Math.PI / 2 + 0.1))).multiply(new THREE.Matrix4().makeTranslation(0.48, -0.01, 0.13));
          for (const role of this.rolesOf(pieceName)) {
            const slot = role.slice(pieceName.length + 2);
            put(role, surf(slots[slot]) || surf(slot), slot === "door" || slot === "metal" ? _m.clone().multiply(close) : _m, "cut");
          }
          continue;
        }
        piece(pieceName, _m, "cut", (slot) => {
          if (slot === "wallA") return rA === "out" ? { kind: "paint", color: surf("siding").color } : surf(roomDef(rA)?.wall) || { kind: "plaster", color: "#ffffff" };
          if (slot === "wallB") return rB === "out" ? { kind: "paint", color: surf("siding").color } : surf(roomDef(rB)?.wall) || { kind: "plaster", color: "#ffffff" };
          return surf(slots[slot]) || surf(slot);
        });
      }
    }
    // the outside corners, a board up each storey
    {
      const [x0, z0, x1, z1] = D.rect;
      for (const [x, z, ry] of [[x0 - T / 2, z1 + T / 2, -Math.PI / 2], [x1 + T / 2, z1 + T / 2, 0], [x1 + T / 2, z0 - T / 2, Math.PI / 2], [x0 - T / 2, z0 - T / 2, Math.PI]])
        for (let lv = 0; lv < (D.levels || 1); lv++) {
          const h = !lv && two ? LEVEL_H : WH;
          _m.makeRotationY(ry).multiply(_m2.makeScale(1, h / 3.04, 1)).setPosition(x, lv * LEVEL_H, z);
          piece("corner", _m, "cut", (sl) => surf(sl));
        }
    }
    // the rooms' floor areas (upstairs round the stairs' hole)
    const areas = (r) => {
      const [x0, z0, x1, z1] = r.rect;
      if (!r.level || !D.hole) return [r.rect];
      const [hx0, hz0, hx1, hz1] = D.hole;
      if (hx1 <= x0 || hx0 >= x1 || hz1 <= z0 || hz0 >= z1) return [r.rect];
      return [[x0, z0, hx0, z1], [hx1, z0, x1, z1], [hx0, z0, hx1, hz0], [hx0, hz1, hx1, z1]].filter(([a0, b0, a1, b1]) => a1 - a0 > 0.08 && b1 - b0 > 0.08);
    };
    // ---- floors: each room's tiles in its slots
    this._inner = !this.small;
    for (const r of D.rooms) {
      const fy = (r.level || 0) * LEVEL_H;
      for (const [x0, z0, x1, z1] of areas(r)) {
        const w = x1 - x0, dd = z1 - z0;
        const nx = Math.max(1, Math.round(w / BIG)), nz = Math.max(1, Math.round(dd / BIG));
        const sx = w / nx, sz = dd / nz;
        for (let i = 0; i < nx; i++)
          for (let j = 0; j < nz; j++) {
            _m.makeScale(sx, 1, sz).setPosition(x0 + (i + 0.5) * sx, fy, z0 + (j + 0.5) * sz);
            piece(r.floor.tile, _m, "plain", (slot) => surf(r.floor.slots[slot]));
          }
      }
    }
    // ---- downstairs ceilings (under the upper floor), the stairs' hole's sides
    if (two) {
      const DOWN = new THREE.Vector3(0, -1, 0);
      const cc = surf("ceiling")?.color || "#ffffff";
      for (const r of D.rooms)
        for (const [x0, z0, x1, z1] of r.level ? [r.rect] : areas({ ...r, level: 1 })) {
          const y = (r.level || 0) * LEVEL_H + WH;
          quad("plaster", "cut", new THREE.Vector3(x0, y, z0), new THREE.Vector3(x1, y, z0), new THREE.Vector3(x1, y, z1), new THREE.Vector3(x0, y, z1), DOWN, cc);
        }
      if (D.hole) {
        const [hx0, hz0, hx1, hz1] = D.hole;
        const tc = surf("trim")?.color || "#ffffff";
        const P3 = (x, y, z) => new THREE.Vector3(x, y, z);
        const y0 = WH, y1 = LEVEL_H;
        quad("paint", "cut", P3(hx0, y0, hz0), P3(hx1, y0, hz0), P3(hx1, y1, hz0), P3(hx0, y1, hz0), new THREE.Vector3(0, 0, 1), tc);
        quad("paint", "cut", P3(hx1, y0, hz1), P3(hx0, y0, hz1), P3(hx0, y1, hz1), P3(hx1, y1, hz1), new THREE.Vector3(0, 0, -1), tc);
        quad("paint", "cut", P3(hx0, y0, hz1), P3(hx0, y0, hz0), P3(hx0, y1, hz0), P3(hx0, y1, hz1), new THREE.Vector3(1, 0, 0), tc);
        quad("paint", "cut", P3(hx1, y0, hz0), P3(hx1, y0, hz1), P3(hx1, y1, hz1), P3(hx1, y1, hz0), new THREE.Vector3(-1, 0, 0), tc);
      }
    }
    this._inner = false;
    // ---- the roof, the porch's roof, the chimney
    const roofLook = (slot) => surf(D.roof.slots[slot] || slot);
    _m.identity();
    piece(D.roof.piece, _m, "roof", roofLook);
    piece(D.roof.porch.piece, _m, "roof", roofLook);
    if (D.roof.dormers) piece(D.roof.dormers, _m, "roof", roofLook);
    piece(D.roof.chimney.piece, _m, "plain", (s) => surf(s === "chimney" ? "chimney" : D.roof.slots[s] || s));
  }

  // merge each part's geometry per kind and layer into its meshes (replacing that part's old ones)
  merge(buckets, wallGeo, part) {
    // ---- merge per kind and layer
    const parts = part === "all" ? ["shell", "items"] : [part];
    for (const g of Object.values(this.layers)) {
      for (const c of [...g.children]) {
        if (!parts.includes(c.userData.part)) continue;
        c.geometry?.dispose();
        g.remove(c);
      }
    }
    // (the walls, floors and ceilings drawn here are the shell's)
    for (const [key, G] of wallGeo) {
      const g = new THREE.BufferGeometry();
      g.setAttribute("position", new THREE.Float32BufferAttribute(G.pos, 3));
      g.setAttribute("normal", new THREE.Float32BufferAttribute(G.nrm, 3));
      g.setAttribute("uv", new THREE.Float32BufferAttribute(G.uv, 2));
      g.setAttribute("color", new THREE.Float32BufferAttribute(G.col, 3));
      g.setIndex([...Array(G.pos.length / 3).keys()]);
      if (!buckets.has(key)) buckets.set(key, []);
      buckets.get(key).push(g);
    }
    let tris = 0;
    for (const [key, list] of buckets) {
      const [kp, kind, layer, lod, tier] = key.split("|");
      const norm = list.map((g) => {
        // (the same attributes on every part)
        for (const k of Object.keys(g.attributes)) if (!["position", "normal", "uv", "color"].includes(k)) g.deleteAttribute(k);
        if (!g.attributes.uv) g.setAttribute("uv", new THREE.Float32BufferAttribute(new Float32Array(g.attributes.position.count * 2), 2));
        if (!g.attributes.color) g.setAttribute("color", new THREE.Float32BufferAttribute(new Float32Array(g.attributes.position.count * 3).fill(1), 3));
        if (!g.attributes.normal) g.computeVertexNormals();
        return g;
      });
      const merged = mergeGeometries(norm, false);
      for (const g of norm) g.dispose();
      if (!merged) continue;
      merged.computeBoundingSphere();
      tris += merged.index ? merged.index.count / 3 : merged.attributes.position.count / 3;
      const mesh = new THREE.Mesh(merged, this.material(kind, layer, tier));
      mesh.name = `home.${part}.${key}`;
      mesh.userData.part = kp;
      if (lod) mesh.userData.lod = lod;
      // (taps and the editor's picking test the near pieces)
      if (lod === "far") mesh.raycast = () => {};
      mesh.castShadow = kind !== "glass" && kind !== "glow";
      mesh.receiveShadow = true;
      mesh.matrixAutoUpdate = false;
      mesh.__noBake = true;
      this.layers[layer].add(mesh);
    }
    this.innerOn = null;
    this.group.updateMatrixWorld(true);
    let draws = 0;
    for (const g of Object.values(this.layers)) draws += g.children.length;
    this.stats = { draws, tris: Math.round(tris) };
  }

  // ---- for the editor (homeedit.js) ------------------------------------------------------------------------------
  // a piece drawn on its own (lifted out of the merged house while it is carried): a group in the house's frame
  pieceGroup(it) {
    const g = new THREE.Group();
    if (!this.kit) return g;
    const buckets = new Map();
    const piece = (name, matrix, layer, lookOf) => {
      for (const role of this.rolesOf(name)) {
        const slot = role.slice(name.length + 2);
        const look = SPECIAL[slot] || lookOf(slot);
        const src = this.kit.get(role);
        if (!src || !look) continue;
        const c = src.clone();
        c.applyMatrix4(matrix);
        if (look.kind !== "fixed" && look.kind !== "mirror" && look.color) {
          _c.set(look.color);
          const col = c.attributes.color;
          if (col) for (let i = 0; i < col.count; i++) col.setXYZ(i, col.getX(i) * _c.r, col.getY(i) * _c.g, col.getZ(i) * _c.b);
        }
        const key = `${look.kind}|${layer}`;
        if (!buckets.has(key)) buckets.set(key, []);
        buckets.get(key).push(c);
      }
    };
    this.pieceOf({ ...it, x: 0, z: 0, rot: 0, y: it.y || 0, level: 0, room: it.room }, piece);
    for (const [key, list] of buckets) {
      const [kind] = key.split("|");
      const merged = list.length > 1 ? mergeGeometries(list, false) : list[0];
      if (!merged) continue;
      const m = new THREE.Mesh(merged, this.material(kind, "plain"));
      m.castShadow = true;
      g.add(m);
    }
    return g;
  }
  // a placed piece alone, where it stands in the world (a seat's cushion is measured on it): null until the kit is in
  seatMeshes(id) {
    const it = this.decor.get(id);
    if (!it || !this.kit) return null;
    const c = (this._seatG ||= new Map()).get(id);
    if (c && c.it === it && c.x === it.x && c.z === it.z && c.rot === it.rot) return c.meshes;
    const g = this.pieceGroup(it);
    // (pieceGroup keeps its own height over the floor: here only where it stands and its turn)
    g.matrix.makeRotationY(it.rot || 0).setPosition(it.x, (it.level || 0) * LEVEL_H, it.z);
    g.matrixAutoUpdate = false;
    g.matrixWorld.multiplyMatrices(this.room.group.matrixWorld, g.matrix);
    const meshes = [];
    for (const m of g.children) {
      m.updateMatrix();
      m.matrixWorld.multiplyMatrices(g.matrixWorld, m.matrix);
      meshes.push(m);
    }
    for (const m of c?.meshes || []) m.geometry.dispose();
    this._seatG.set(id, { it, x: it.x, z: it.z, rot: it.rot, meshes });
    return meshes;
  }
  // the house's data changed: lay again what it touches ("items" the pieces only, "shell" the house itself)
  refresh(part = "items", skip = null) {
    if (this.built) this.assemble(part, skip);
  }
  relayWalls() {
    this.untrack(this.wallRec);
    this.wallRec = this.track(this.layWalls);
  }
  // the whole house again (a saved house arrived): colliders, taps and look
  relayAll() {
    if (this.layWalls) this.relayWalls();
    for (const [id] of this.recs) this.untrack(this.recs.get(id));
    this.recs.clear();
    this.items = [];
    for (const it of this.decor.items) this.layItem(it);
    if (this.built) this.assemble("all");
  }
  // the piece at a point (house frame) on a level: the one whose footprint is nearest, within reach
  pieceAt(x, z, level, reach = 0.9) {
    let best = null;
    let bd = reach;
    for (const it of this.decor.items) {
      if ((it.level || 0) !== level) continue;
      const P = PIECES[it.piece];
      if (!P || P.fixedPlace) continue;
      const cs = P.col?.length ? P.col : [[0, 0, P.flat ? 1.0 : 0.35]];
      const cos = Math.cos(it.rot || 0), sin = Math.sin(it.rot || 0);
      for (const [cx, cz, r] of cs) {
        const px = it.x + cx * cos + cz * sin, pz = it.z - cx * sin + cz * cos;
        const d = Math.hypot(x - px, z - pz) - r * (P.flat ? 1.0 : 0.6);
        // (a rug is found only when nothing standing is there)
        const dd = P.flat ? d + 0.4 : d;
        if (dd < bd) {
          bd = dd;
          best = it;
        }
      }
    }
    return best;
  }
  // how high something set down at (x, z) on a level would stand: on the table, counter or shelf it is over
  topAt(x, z, level, skipId) {
    let top = 0;
    for (const it of this.decor.items) {
      if (it.id === skipId || (it.level || 0) !== level) continue;
      const P = PIECES[it.piece];
      if (!P || !P.col || P.seats || P.lie || !(P.top < 1.3)) continue;
      const cos = Math.cos(it.rot || 0), sin = Math.sin(it.rot || 0);
      for (const [cx, cz, r] of P.col) {
        const px = it.x + cx * cos + cz * sin, pz = it.z - cx * sin + cz * cos;
        if (Math.hypot(x - px, z - pz) < r * 0.9) top = Math.max(top, (it.y || 0) + P.top);
      }
    }
    return top;
  }

  rolesOf(name) {
    if (!this._roles) {
      this._roles = new Map();
      for (const role of this.kit.keys()) {
        const p = role.split("__")[0];
        if (!this._roles.has(p)) this._roles.set(p, []);
        this._roles.get(p).push(role);
      }
    }
    return this._roles.get(name) || [];
  }

  // ---- every frame (island.js): stream in when near, the dollhouse cut, the roof, the night's glow --------------
  update(dt, playerPos, camPos, night = 0) {
    const p = this.room.group.position;
    const d = Math.hypot(playerPos.x - p.x, playerPos.z - p.z);
    const near = this.small ? 70 : 160;
    if (!this.built && !this.loading && d < near) this.build();
    // (phones: the whole house goes beyond its reach, as the ring's _lite zones do)
    this.group.visible = this.built && (!this.small || Math.hypot(camPos.x - p.x, camPos.z - p.z) < 75);
    this.sweep();
    const inside = this.contains(playerPos);
    // (the garden and the backyard: inside the fences round the house)
    {
      const l = this.room.group.worldToLocal(_v.copy(playerPos));
      const [x0, z0, x1, z1] = this.data.rect;
      this.nearGarden = l.x > x0 - 1 && l.x < x1 + 1 && l.z > z0 - 8.5 && l.z < z1 + 3.6 && l.y < 2;
    }
    this.inside = inside;
    const k = 1 - Math.exp(-dt * 5);
    // (inside, the camera is the rooms' own, at eye level under the ceiling (user 2026-11-28: "not a airial view, but we
    // move inside it"); the dollhouse cut stays as a fallback, this.dollhouse)
    const wantCut = inside && this.dollhouse ? 1 : 0;
    this.cut += (wantCut - this.cut) * k;
    if (Math.abs(this.cut - wantCut) < 0.002) this.cut = wantCut;
    // (the rooms' camera keeps under this ceiling: island.js reads room.wallH)
    if (inside) this.room.wallH = this.ceilAt(playerPos);
    const U = this.U;
    U.uCutOn.value = this.cut;
    // (inside, what is above your floor is not drawn: downstairs the ceiling, the upper floor and all upstairs;
    // the world's own y: the house stands on the ground)
    const lv = inside ? this.levelOf(playerPos) : 0;
    this.level = lv;
    const gy = this.room.group.position.y;
    U.uCutBase.value = gy + lv * LEVEL_H;
    U.uMaxY.value = this.dollhouse && inside && lv === 0 && (this.data.levels || 1) > 1 ? gy + LEVEL_H - 0.22 : 99;
    U.uCutP.value.copy(playerPos);
    const cx = camPos.x - playerPos.x, cz = camPos.z - playerPos.z;
    const cl = Math.hypot(cx, cz) || 1;
    U.uCutD.value.set(cx / cl, cz / cl);
    U.uRoofHide.value = THREE.MathUtils.smoothstep(this.cut, 0.0, 0.85);
    const roofOn = this.cut < 0.98;
    if (this.layers.roof.visible !== roofOn) {
      this.layers.roof.visible = roofOn;
    }
    U.uGlow.value = night;
    // (phones: the furniture inside is not drawn from outside: through the windows it is not missed)
    const furnOn = !this.small || inside || this.cut > 0.01;
    if (this.layers.furn.visible !== furnOn) this.layers.furn.visible = furnOn;
    // (computers: the rooms' insides are drawn within ~30 m of the walls; further off the
    // windows are a few pixels, and the outside is the lite kit's (380k triangles of the willow's view were the
    // full one's windows, doors, fence and garden pieces). The switch stands clear of the willow's own view,
    // 36-38 m off, so that view never sits on it)
    if (!this.small) {
      const l = this.room.group.worldToLocal(_v.copy(camPos));
      const [x0, z0, x1, z1] = this.data.rect;
      const dOut = Math.hypot(Math.max(x0 - l.x, 0, l.x - x1), Math.max(z0 - l.z, 0, l.z - z1));
      const innerOn = inside || this.cut > 0.01 || dOut < (this.innerOn ? 33 : 29);
      if (this.innerOn !== innerOn) {
        this.innerOn = innerOn;
        for (const g of Object.values(this.layers)) for (const c of g.children) if (c.userData.lod) c.visible = (c.userData.lod === "far") !== innerOn;
      }
    }
    // the room light over the room you are in
    const r = inside ? this.roomOf(playerPos) : null;
    if (r) this.lampAt.set((r.rect[0] + r.rect[2]) / 2, this.room.lampY + (r.level || 0) * LEVEL_H, (r.rect[1] + r.rect[3]) / 2);
    return inside;
  }
}
