// Gifts for your person (TODO "Gift system, including giving a bouquet"; the user: "let me be able to give the other
// person a bouquet", and "Gift system: besides bouquets, give cakes from the bakery, things from the garden and photos,
// wrapped with a little animation"). Pick something (a bouquet you made, a treat from the bakery's case, fruit or a
// flower from the garden, a photo), choose the paper, its print and the ribbon, add a note: it's wrapped right there in
// front of you, hops off and flies to your person (or, if they're not on the island, into their gift inbox). They get a
// notice, the present lands by them, and when they unwrap it the bow comes loose, the lid pops off and the gift rises out;
// then it's theirs: it's kept in their gifts, and they can eat it, hold it, put it in a vase...
//
// The present, its prints, the fruit, the basket and the photo card are the Blender kit props/prp_gift_box[_lite].glb
// (assets/blender/props/gift/_build_gift.py); every move is a keyed clip of the carrier clips/prp_gift_clips.glb
// (_anim_gift.py), played on the kit's pivots; the sounds are the gift_* set (rebuild/tools/audio/synth.js).
// Each gift is one hidden widgets row (__prefs:game:gift:<id>, never shown by the diary: it skips every __prefs: row),
// written by the one who gives it and marked kept by the one who gets it; so a gift is never lost to the other one
// saving something at the same time, and it waits for them however long they're away.
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { MeshoptDecoder } from "three/examples/jsm/libs/meshopt_decoder.module.js";
import { zoneMode } from "./zones/mode.js";
import { clipLib, setClipsFromGLTF } from "./anim/clips.js";
import { RolePlayer } from "./anim/props.js";
import { choiceCard } from "./choice.js";

const ROW = "__prefs:game:gift:";
const QUEUE = "tdd3dGiftQueue"; // (not a "tdd3d." key: sync.js mirrors those into the prefs row)
const SEEN = "tdd3dGiftSeen";
const CARRIER = "prp_gift_clips";
// the paper, its print and the ribbon (the kit's paper and ribbon are near-white: these tint them)
export const PAPERS = [
  { name: "blush", c: "#ffc2d6", print: "#ff6f9f" },
  { name: "lilac", c: "#dccbff", print: "#9a76e6" },
  { name: "mint", c: "#bdeed9", print: "#3fb489" },
  { name: "butter", c: "#ffe7a3", print: "#f39b3a" },
  { name: "sky", c: "#bfe0ff", print: "#5a97e6" },
  { name: "cherry", c: "#ff7f9f", print: "#ffffff" },
  { name: "cream", c: "#fff4e4", print: "#ff8fb1" },
];
export const PRINTS = ["hearts", "dots", "stars", "plain"];
export const RIBBONS = ["#ffffff", "#ff5f96", "#ffd166", "#9a76e6", "#d93f6c", "#6cc3a0"];
const PRINT_ICON = { hearts: "♡", dots: "•", stars: "☆", plain: "–" };
const FRUIT = { apple: { name: "apples", one: "apple", emoji: "🍎" }, orange: { name: "oranges", one: "orange", emoji: "🍊" } };
// the box (the kit's own pivots: _build_gift.py / _anim_gift.py)
const PIVOT = { root: [0, 0, 0], band: [0, 0, 0], item: [0, 0.03, 0], lid: [0, 0.25, 0], lidband: [0, 0, 0], bow: [0, 0.106, 0], tail_l: [-0.012, 0.012, 0.022], tail_r: [0.012, 0.012, 0.022], tag: [0.17, 0.06, 0.222] };
const ROLES = Object.keys(PIVOT);
const FPS = 30;
// when each clip's moments happen (s): the sounds, the gift showing, the sparkles
const AT = (f) => f / FPS;

const hex = (c) => typeof c === "string" && /^#[0-9a-f]{6}$/i.test(c);
const clampI = (v, a, b) => Math.max(a, Math.min(b, Math.round(Number(v) || 0)));
const newId = () => `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
const ease = (u) => (u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2);
function readJSON(key, def) {
  try {
    const v = JSON.parse(localStorage.getItem(key) || "null");
    return v ?? def;
  } catch {
    return def;
  }
}
function writeJSON(key, v) {
  try {
    localStorage.setItem(key, JSON.stringify(v));
  } catch {}
}

// only what a gift may hold comes in (from the network or the database)
export function cleanWrap(w) {
  return { p: clampI(w?.p, 0, PAPERS.length - 1), pr: PRINTS.includes(w?.pr) ? w.pr : "hearts", r: clampI(w?.r, 0, RIBBONS.length - 1) };
}
function cleanGift(g, cleanTreat) {
  if (!g || typeof g !== "object" || typeof g.id !== "string" || !/^[a-z0-9]{6,24}$/.test(g.id)) return null;
  const out = { id: g.id, kind: g.kind, wrap: cleanWrap(g.wrap), note: String(g.note || "").slice(0, 80), from: String(g.from || "").slice(0, 64), fromName: String(g.fromName || "").slice(0, 24), to: String(g.to || "").slice(0, 64), at: Number(g.at) || Date.now() };
  const it = g.item || {};
  if (g.kind === "bouquet") {
    const cols = Array.isArray(it.cols) ? it.cols.filter(hex).slice(0, 12) : [];
    if (!cols.length) return null;
    out.item = { cols, kinds: Array.isArray(it.kinds) ? it.kinds.map((k) => (typeof k === "string" && /^[a-z]{0,20}$/i.test(k) ? k : "")).slice(0, 12) : [], w: clampI(it.w, -1, 4) };
  } else if (g.kind === "treat") {
    const t = cleanTreat?.(it);
    if (!t) return null;
    out.item = t;
  } else if (g.kind === "fruit") {
    if (!FRUIT[it.f]) return null;
    out.item = { f: it.f, n: clampI(it.n, 1, 6) };
  } else if (g.kind === "photo") {
    if (typeof it.src !== "string" || !/^data:image\/(webp|jpeg|png);base64,/.test(it.src) || it.src.length > 400000) return null;
    out.item = { src: it.src, by: String(it.by || "").slice(0, 24), at: Number(it.at) || 0 };
  } else return null;
  return out;
}
function giftTitle(g) {
  const it = g.item;
  if (g.kind === "bouquet") return it.cols.length === 1 ? "a flower" : "a bouquet";
  if (g.kind === "fruit") return `${it.n} ${it.n === 1 ? FRUIT[it.f].one : FRUIT[it.f].name}`;
  if (g.kind === "photo") return "a photo";
  return "a treat";
}

// ---- the kit and the clips, fetched once, the first time a gift is wrapped or arrives ----------------------------
let kitP = null;
function loadKit(small) {
  if (kitP) return kitP;
  const zm = zoneMode();
  if (!zm.base) return (kitP = Promise.resolve(null));
  const L = new GLTFLoader().setMeshoptDecoder(MeshoptDecoder);
  const sfx = small ? "_lite" : "";
  const re = new RegExp(`^INST_prp_gift_box${sfx}_(.+)$`);
  kitP = Promise.all([L.loadAsync(`${zm.base}props/prp_gift_box${sfx}.glb`), clipLib(CARRIER) ? null : L.loadAsync(`${zm.base}clips/${CARRIER}.glb`)])
    .then(([g, c]) => {
      if (c) setClipsFromGLTF(c, CARRIER);
      const m = new Map();
      g.scene.traverse((o) => {
        if (!o.isMesh) return;
        const role = o.userData?.tdd_role || re.exec(o.name)?.[1];
        if (!role) return;
        o.geometry.userData.kit = true;
        m.set(role, o.geometry);
        o.material?.dispose?.();
      });
      return m;
    })
    .catch((e) => {
      console.warn("gift kit", e);
      kitP = null;
      return null;
    });
  return kitP;
}
const mats = new Map();
function mat(key, make) {
  let m = mats.get(key);
  if (!m) mats.set(key, (m = make()));
  return m;
}
const paperMat = (c) => mat(`p${c}`, () => new THREE.MeshStandardMaterial({ vertexColors: true, color: c, roughness: 0.78 }));
const ribbonMat = (c) => mat(`r${c}`, () => new THREE.MeshStandardMaterial({ vertexColors: true, color: c, roughness: 0.28, metalness: 0.08 }));
const plainMat = () => mat("plain", () => new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.6 }));

// ---- one present in the world --------------------------------------------------------------------------------------
class Present {
  constructor(kit, wrap, item) {
    const W = cleanWrap(wrap);
    const P = PAPERS[W.p];
    this.holder = new THREE.Group();
    this.holder.name = "gift";
    this.holder.userData.live = true;
    this.nodes = {};
    for (const r of ROLES) {
      const n = new THREE.Group();
      n.position.fromArray(PIVOT[r]);
      this.nodes[r] = n;
    }
    const N = this.nodes;
    N.root.add(N.band, N.item, N.lid);
    N.lid.add(N.lidband, N.bow, N.tag);
    N.bow.add(N.tail_l, N.tail_r);
    N.tail_l.scale.x = -1; // (the right tail, mirrored)
    this.holder.add(N.root);
    const mesh = (part, m, into) => {
      const g = kit.get(part);
      if (!g) return null;
      const o = new THREE.Mesh(g, m);
      o.castShadow = true;
      into.add(o);
      return o;
    };
    const paper = paperMat(P.c);
    const rib = ribbonMat(RIBBONS[W.r]);
    mesh("base", paper, N.root);
    mesh("lid", paper, N.lid);
    if (W.pr !== "plain") {
      const pm = paperMat(P.print);
      mesh(`${W.pr}_base`, pm, N.root);
      mesh(`${W.pr}_lid`, pm, N.lid);
    }
    mesh("band", rib, N.band);
    mesh("lidband", rib, N.lidband);
    mesh("bow", rib, N.bow);
    mesh("tail", rib, N.tail_l);
    mesh("tail", rib, N.tail_r);
    mesh("tag", plainMat(), N.tag);
    // the scale-mirrored tail was built with its rest scale; the clip writes scale relative to it
    this.players = ROLES.map((r) => new RolePlayer(CARRIER, r, N[r], { mode: "rest" }));
    this.ready = this.players.every((p) => p.ready());
    this.itemObj = null;
    if (item) this.setItem(item);
    this.clip = "";
    this.t = 0;
    this.cues = [];
    this.onClip = null;
  }
  // what's inside, fitted to the box (it's hidden while the lid is on)
  setItem(obj) {
    if (this.itemObj) this.nodes.item.remove(this.itemObj);
    this.itemObj = obj;
    if (!obj) return;
    const fit = new THREE.Group();
    fit.add(obj);
    const box = new THREE.Box3().setFromObject(obj);
    const size = box.getSize(new THREE.Vector3());
    const k = Math.min(0.36 / Math.max(size.x, size.z, 1e-3), 0.44 / Math.max(size.y, 1e-3), 3);
    obj.scale.multiplyScalar(k);
    const b2 = new THREE.Box3().setFromObject(obj);
    obj.position.x -= (b2.min.x + b2.max.x) / 2;
    obj.position.z -= (b2.min.z + b2.max.z) / 2;
    obj.position.y -= b2.min.y;
    this.itemObj = fit;
    fit.visible = false;
    this.nodes.item.add(fit);
  }
  play(name, fade = 0.12) {
    for (const p of this.players) p.play(name, fade, 0);
    this.clip = name;
    this.t = 0;
  }
  // (s, fn): once, while this clip plays
  cue(clip, at, fn) {
    this.cues.push({ clip, at, fn });
  }
  update(dt) {
    const before = this.t;
    this.t += dt;
    for (const p of this.players) p.update(dt);
    const now = this.players[0].name();
    if (now && now !== this.clip) {
      this.clip = now;
      this.t = 0;
      this.onClip?.(now);
    }
    for (let i = this.cues.length - 1; i >= 0; i--) {
      const c = this.cues[i];
      if (c.clip === this.clip && c.at >= before && c.at < this.t) {
        this.cues.splice(i, 1);
        c.fn();
      }
    }
    // the gift shows only with the lid off: while it drops in, and from the moment the lid pops
    if (this.itemObj) this.itemObj.visible = (this.clip === "gift_wrap" && this.t < AT(23)) || (this.clip === "gift_unwrap" && this.t > AT(27)) || this.clip === "gift_open";
  }
  dispose() {
    this.holder.parent?.remove(this.holder);
    this.itemObj?.traverse((o) => {
      if (o.isMesh && !o.geometry.userData.kit) o.geometry.dispose();
      if (o.material?.map && o.userData.ownMap) o.material.map.dispose();
      if (o.userData.ownMat) o.material.dispose();
    });
  }
}

