        const glow = role === "glow" || role === "berries" || role === "setglow";
        const mesh = add(geo, role === "rock" ? M.rock : role === "shafts" ? M.shaft : role === "cloth" ? M.cloth : role === "canopy" ? M.canopy : glow ? M.glow : M.baked, `${file}_${role}`);
        if (role === "cloth") mesh.receiveShadow = mesh.castShadow = true;
