      const seat = { pos: new THREE.Vector3(s.pos[0] + O.x, s.foot + O.y, s.pos[2] + O.z), facing: s.facing, h: s.h, lie: Boolean(s.lie), measured: true, cave: true, freeCam: true };
      seat.base = seat.pos.clone();
