// The Wave 10 avatar look rules (port of assets/blender/characters/avatar_look.mjs, unchanged logic):
// a config -> which SM_ parts of which chr_avatar_* GLB show, with each part's tint channels, glow and fits.

const toLin = (c) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
const toSrgb = (c) => (c <= 0.0031308 ? c * 12.92 : 1.055 * c ** (1 / 2.4) - 0.055);
const rgb = (h) => [1, 3, 5].map((i) => toLin(parseInt(h.slice(i, i + 2), 16) / 255));
const hex = (v) => "#" + v.map((x) => Math.round(Math.min(1, Math.max(0, toSrgb(Math.min(1, Math.max(0, x))))) * 255).toString(16).padStart(2, "0")).join("");
export const shade = (h, k) => (k === 1 ? h : hex(rgb(h).map((x) => x * k)));
export const mix = (a, b, t) => hex(rgb(a).map((x, i) => x + (rgb(b)[i] - x) * t));

export const DEFAULT_AVATAR = { style: "girl", body: "regular", face: "cute", cheeks: "rosy", hair: "bob", top: "hoodie", bottom: "pants", accessory: "bow",
  skin: "#f6cfb4", hairColor: "#5a3825", topColor: "#f29ac0", bottomColor: "#3a3f58", shoesColor: "#fff7f2", accentColor: "#e2557f", eyeColor: "#2a1d26",
  shoes: "sneakers", makeup: "none", layerColor: "#5b3a7a", streakColor: "", faceImg: "" };
const RETIRED_HAIR = { short: "messy", buzz: "wolfcut", quiff: "wolfcut", sidepart: "wolfcut", curtains: "flow", fade: "wolfcut", undercut: "wolfcut", cornrows: "twists" };
const OPEN_EARS = new Set(["ponytail", "pigtails", "braid", "bun", "spacebuns", "manbun", "pixie", "mohawk", "spiky", "bald"]);
const HAIRS = ["messy", "wolfcut", "emo", "mohawk", "manbun", "flow", "bob", "pixie", "long", "hime", "ponytail", "pigtails", "braid", "bun", "spacebuns", "afro", "twists", "curly", "spiky", "scene", "metal", "bald"];
const ACCS = ["glasses", "bandana", "bow", "headphones", "catEars", "crown", "scarf", "flower", "halo", "bunny", "sunglasses", "beret", "starclips", "choker", "studs", "beard", "goatee"];
const GIRL_EXTRAS = new Set(["bow", "catEars", "crown", "flower", "halo", "bunny", "starclips"]);
const PANTS = new Set(["pants", "jeans", "joggers", "cargo", "overalls", "trackpants", "flares", "ripped"]);
const EXTRA_LEG = new Set(["cargo", "trackpants", "boardshorts", "flares", "jeans", "shorts"]);
const EXTRA_KNEE = new Set(["jeans", "joggers", "trackpants", "flares"]);
const SPINE_TOPS = new Set(["hoodie", "shirt", "jacket", "jersey", "vest", "varsity", "puffer", "flannel", "polo", "tracksuit", "turtleneck", "crop", "cardigan", "blouse", "sundress", "sweater", "tank", "goth", "band", "metal"]);
const FORE_TOP = ["hoodie", "sweater", "shirt", "jacket", "puffer", "flannel", "tracksuit", "turtleneck", "cardigan"];
const TOPS_BOY = new Set(["shirt", "jacket", "jersey", "vest", "varsity", "polo", "tracksuit", "puffer"]);
const MULTI = new Set(["starclips", "catEars", "bunny", "headphones"]);
// (W18 wardrobe) the goth and metal sets live in their own body sets: chr_avatar_<body>_goth / _metal (+ _lite_)
const WARDROBE = { top_goth: "goth", forex_goth: "goth", skirt_tutu: "goth", legx_tights: "goth", kneex_tights: "goth", choker: "goth", shin_platforms: "goth",
  top_band: "metal", top_metal: "metal", legx_ripped: "metal", kneex_ripped: "metal", shin_combat: "metal", forex_studs: "metal" };
const BODY_EXTRAS = new Set(["scarf", "choker", "studs"]); // (worn on the body, not on the head)
const SHOES = { platforms: "shin_platforms", combat: "shin_combat" };

export function accessoryList(v) {
  return [...new Set(String(v || "none").split("+"))].filter((id) => id !== "none" && ACCS.includes(id));
}
// colour KEYS (what a part's colour is made of; a key names a user colour or is a fixed '#hex')
export function keyCtx(c) {
  const isDress = c.top === "dress" || c.top === "sundress";
  const skirtish = isDress || c.bottom === "skirt" || c.bottom === "pleated" || c.bottom === "tutu";
  return {
    skin: "skin", hair: "hair", top: "top", bottom: "bottom", shoes: "shoes", accent: "accent", eye: "eye", layer: "layer", streak: "streak",
    pelvis: isDress ? "top" : "bottom",
    thigh: skirtish ? "skin" : "bottom",
    shin: PANTS.has(c.bottom) && !isDress ? "bottom" : "skin",
    sleeveU: c.top === "tank" || c.top === "sundress" ? "skin" : c.top === "vest" || c.top === "varsity" ? "#fff7f2" : "top",
    sleeveF: FORE_TOP.includes(c.top) ? "top" : c.top === "vest" || c.top === "varsity" ? "#fff7f2" : "skin",
  };
}
// colour keys -> colours (avatar_rig.json 'ch' = [key, k] per mask channel)
export function colourCtx(c) {
  const k = keyCtx(c);
  const user = { skin: c.skin, hair: c.hairColor, top: c.topColor, bottom: c.bottomColor, shoes: c.shoesColor, accent: c.accentColor, eye: c.eyeColor || "#2a1d26",
    layer: c.layerColor || "#5b3a7a", streak: c.streakColor || c.hairColor };
  const out = { blush: mix(c.skin, "#ff8fb1", 0.55) }; // legacy: #ff8fb1 at 55 % over the skin
  for (const [n, v] of Object.entries(k)) out[n] = v.startsWith("#") ? v : user[v];
  return out;
}
// the variants of one body joint for a look (null: the joint carries no option parts)
export function nodeVariants(node, c) {
  const isDress = c.top === "dress" || c.top === "sundress";
  const extras = accessoryList(c.accessory).filter((id) => c.style !== "boy" || !GIRL_EXTRAS.has(id));
  const k = keyCtx(c);
  if (node === "hips") return ["pelvis"].concat(isDress ? [c.top === "sundress" ? "skirt_sundress" : "skirt_dress"] : c.bottom === "skirt" ? ["skirt_skirt"] : c.bottom === "pleated" ? ["skirt_pleated"] : c.bottom === "tutu" ? ["skirt_tutu"] : []);
  const legx = !isDress && c.bottom === "tutu" ? "tights" : !isDress && c.bottom === "ripped" ? "ripped" : null;
  if (node.startsWith("leg_")) return ["thigh"].concat(!isDress && EXTRA_LEG.has(c.bottom) ? ["legx_" + c.bottom] : legx ? ["legx_" + legx] : []);
  if (node.startsWith("knee_")) return [SHOES[c.shoes] || "shin"].concat(!isDress && EXTRA_KNEE.has(c.bottom) ? ["kneex_" + c.bottom] : legx ? ["kneex_" + legx] : []);
  if (node === "torso") return [c.top === "puffer" ? "torso_puffer" : c.top === "crop" ? "torso_crop" : c.top === "flannel" ? "torso_flannel" : "torso"];
  if (node === "spine") {
    const v = [];
    if (SPINE_TOPS.has(c.top)) v.push("top_" + c.top);
    if (c.bottom === "overalls" && !isDress) v.push("overalls");
    if (extras.includes("scarf")) v.push("scarf");
    if (extras.includes("choker")) v.push("choker");
    return v;
  }
  if (node.startsWith("shoulder_")) {
    const v = [c.top === "flannel" ? "upper_flannel" : "upper"];
    if (k.sleeveF !== "top" && k.sleeveU === "top") v.push("upperx_cuff");
    if (["puffer", "blouse", "tracksuit"].includes(c.top)) v.push("upperx_" + c.top);
    return v;
  }
  if (node.startsWith("elbow_")) {
    const v = [c.top === "flannel" ? "fore_flannel" : "fore"];
    if (k.sleeveF === "top") v.push("forex_cuff");
    if (["puffer", "tracksuit", "varsity"].includes(c.top)) v.push("forex_" + c.top);
    if (c.top === "goth") v.push("forex_goth");
    if (extras.includes("studs")) v.push("forex_studs");
    return v;
  }
  if (node === "tail") return extras.includes("bunny") ? ["tail"] : [];
  return null;
}
export const BODY_JOINTS = ["body", "hips", "leg_0", "knee_0", "leg_1", "knee_1", "spine", "torso", "shoulder_0", "elbow_0", "shoulder_1", "elbow_1", "neck", "head", "tail"];
export function bodyVariants(c) {
  const out = [];
  for (const node of BODY_JOINTS) for (const v of nodeVariants(node, c) || []) out.push([node, v]);
  return out;
}
const topOf = (v) => {
  if (v === "skirt_dress" || v === "skirt_sundress") return v.slice(6);
  for (const p of ["top_", "torso_", "upperx_", "forex_", "upper_", "fore_"]) if (v.startsWith(p) && !["cuff"].includes(v.slice(p.length))) return v.slice(p.length);
  return null;
};
// which body GLB holds a variant: chr_avatar_<body>[_tops|_topsboy|_flannel] (full) / [_lite|_lite_tops] (phones, LOD1)
export function bodyAsset(body, variant, lite = false) {
  if (WARDROBE[variant]) return `chr_avatar_${body}${lite ? "_lite_" : "_"}${WARDROBE[variant]}`;
  const t = topOf(variant);
  if (lite) return `chr_avatar_${body}${t ? "_lite_tops" : "_lite"}`;
  return `chr_avatar_${body}${!t ? "" : TOPS_BOY.has(t) ? "_topsboy" : t === "flannel" ? "_flannel" : "_tops"}`;
}
const meshName = (asset, node, v) => `SM_${asset}_${v === node ? node : node + "_" + v}`;

// the whole look: [{asset, mesh, node, tint: {R,G,B}, emissive?}] + head joints to fit + eye/mouth info
export function avatarLook(cfg, rig, { lite = false } = {}) {
  const c = { ...DEFAULT_AVATAR, ...cfg };
  if (RETIRED_HAIR[c.hair]) c.hair = RETIRED_HAIR[c.hair];
  const body = ["regular", "slim", "chubby", "tall"].includes(c.body) ? c.body : "regular";
  const x = colourCtx(c);
  const tintOf = (asset, mesh) => {
    const e = rig.assets[asset] && rig.assets[asset].meshes[mesh];
    if (!e) throw new Error("no mesh " + mesh + " in " + asset);
    const t = {};
    for (const [ch, [key, k]] of Object.entries(e.ch || {})) t[ch] = shade(x[key], k);
    // legacy glow: halo = accent at intensity 1.0, crown 0.3 (of a darker accent), star clips 0.25
    return { tint: t, emissive: e.emissive ? { color: x[e.emissive[0]], k: e.emissive[1] } : null, node: e.node };
  };
  const parts = [];
  for (const [node, v] of bodyVariants(c)) {
    const asset = bodyAsset(body, v, lite);
    const mesh = meshName(asset, node, v);
    parts.push({ asset, mesh, ...tintOf(asset, mesh) });
  }
  const head = "chr_avatar_head" + (lite ? "_lite" : "");
  const face = c.face || "cute";
  const push = (asset, mesh) => parts.push({ asset, mesh, ...tintOf(asset, mesh) });
  push(head, `SM_${head}_skull`);
  // (W17: the ears show only where the hair leaves them open; covering styles hide them under the hair)
  if (OPEN_EARS.has(HAIRS.includes(c.hair) ? c.hair : "messy") && rig.assets[head].meshes[`SM_${head}_ears`]) push(head, `SM_${head}_ears`);
  // (W18: with a face photo on, the photo is the face: no drawn eyes, mouth, cheeks or makeup)
  const photo = Boolean(c.faceImg);
  if (!photo && c.cheeks === "freckles") push(head, `SM_${head}_cheeks_freckles`);
  else if (!photo && c.cheeks !== "none") push(head, `SM_${head}_cheeks_rosy`);
  const liner = c.makeup === "liner" && !photo;
  [0, 1].forEach((i) => {
    const s = i ? 1 : -1;
    const arc = face === "happy" || (face === "wink" && s === 1);
    if (photo) return;
    push(head, `SM_${head}_${arc ? "eyearc" : "eye"}_${i}`);
    if (liner && !arc && rig.assets[head].meshes[`SM_${head}_liner_${i}`]) push(head, `SM_${head}_liner_${i}`);
  });
  // (the mouth option: smile = the closed smile line "mouth"; grin / open / flat when the rig has them)
  const mouthMesh = `SM_${head}_mouth${["grin", "open", "flat"].includes(c.mouth) ? "_" + c.mouth : ""}`;
  if (!photo) push(head, rig.assets[head].meshes[mouthMesh] ? mouthMesh : `SM_${head}_mouth`);
  if (liner && rig.assets[head].meshes[`SM_${head}_lips`]) push(head, `SM_${head}_lips`);
  const extras = accessoryList(c.accessory).filter((id) => c.style !== "boy" || !GIRL_EXTRAS.has(id));
  const hairId = HAIRS.includes(c.hair) ? c.hair : "messy";
  let hairAsset = null;
  if (hairId !== "bald") {
    const beret = extras.includes("beret") && rig.assets[`chr_avatar_hair_${hairId}_beret`];
    const base = `chr_avatar_hair_${hairId}${beret ? "_beret" : ""}`;
    hairAsset = lite && rig.assets[base + "_lite"] ? base + "_lite" : base;
    push(hairAsset, `SM_${hairAsset}_hair`);
  }
  const acc = "chr_avatar_acc" + (lite ? "_lite" : "");
  const fits = {};
  for (const id of extras) {
    if (BODY_EXTRAS.has(id)) continue;
    if (MULTI.has(id)) for (const m of Object.keys(rig.assets[acc].meshes).filter((m) => m.startsWith(`SM_${acc}_${id}_`))) push(acc, m);
    else push(acc, `SM_${acc}_${id}`);
    const f = (rig.fits[hairId] || {})[id];
    if (f) for (const [joint, v] of Object.entries(f)) fits[`ANIM_${acc}_${joint.slice(4)}`] = v;
  }
  return { body, parts, fits, sleepy: face === "sleepy", hairAsset, photo };
}
