    g.add(box);
    const floor = mesh("gift_floor");
    box.add(floor);
    const walls = [];
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * TAU;
      const p = new THREE.Group();
      p.rotation.y = a;
      const h = new THREE.Group(); // the hinge at the wall's foot
      h.position.set(0, 0, WALL);
      p.add(h);
      h.add(mesh("gift_wall"));
      box.add(p);
      walls.push(h);
    }
    const lid = new THREE.Group();
    lid.position.set(0, 1.12, 0);
    lid.add(mesh("gift_lid"));
    const bow = mesh("gift_bow");
    bow.position.y = 0.24;
    lid.add(bow);
