    const locket = new THREE.Group();
    const ks = new THREE.Mesh(k.get("keepsake"), new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.28, metalness: 0.35, emissive: new THREE.Color("#ff9fc0"), emissiveIntensity: 0 }));
