  // ---- the moving parts ------------------------------------------------------------------------------------------
  newSkyLantern(spread) {
    const a = rnd() * TAU, r = 6 + Math.sqrt(rnd()) * 60;
    return { x: Math.sin(a) * r, z: Math.cos(a) * r, y: spread ? rnd() * 60 : -rnd() * 8, v: 0.55 + rnd() * 0.45, ph: rnd() * TAU, c: new THREE.Color(pick(LANTERN_TINTS)), s: 0.85 + rnd() * 0.5 };
  }

  // a confetti burst at p, mostly along dir, n pieces
