function tinyCull(scene, camera, TINY = TINY_PHONE) {
  let list = [];
  let age = 99;
  let timer = 0;
  const v = new THREE.Vector3();
  const collect = () => {
    for (const o of list) if (o.__tiny) o.layers.mask = o.__tiny;
    list = [];
    scene.traverse((o) => {
      if (o.isInstancedMesh || o.isSkinnedMesh || o.isPoints || o.isLine || !o.frustumCulled) return;
      if (!(o.isMesh || o.isSprite) || o.userData.noTiny) return;
      if (o.isSprite && o.material?.sizeAttenuation === false) return;
      // (the plain still pieces are the phone's bake's, merged per patch of ground: bake.js; left to it)
      const m = o.material;
      if (o.isMesh && !o.__noBake && !Object.keys(o.userData).length && m && !Array.isArray(m) && !m.transparent) return;
      o.__tiny = 0;
      list.push(o);
    });
    age = 0;
  };
  const tick = (dt) => {
    timer -= dt;
    if (timer > 0) return;
    timer = 0.5;
    if ((age += 0.5) > 4) collect();
    const k = 1 / Math.tan((camera.fov * Math.PI) / 360);
    const cp = camera.getWorldPosition(v.set(0, 0, 0)).clone();
    for (const o of list) {
      if (!o.parent) continue;
      const g = o.geometry;
      if (!g) continue;
      if (!g.boundingSphere) g.computeBoundingSphere();
      const bs = g.boundingSphere;
      v.copy(bs.center).applyMatrix4(o.matrixWorld);
      const r = bs.radius * o.matrixWorld.getMaxScaleOnAxis();
      const d = Math.max(0.1, v.distanceTo(cp));
      const f = (r / d) * k;
      if (o.__tiny) {
        if (f > TINY * 1.4) {
          o.layers.mask = o.__tiny;
          o.__tiny = 0;
        }
      } else if (f < TINY && o.layers.mask === 1) {
        o.__tiny = o.layers.mask;
        o.layers.mask = 0;
      }
    }
  };
  // (the map's picture: the small things too, for that one frame; gives back the undo)
  tick.showAll = () => {
    const off = list.filter((o) => o.__tiny);
    for (const o of off) o.layers.mask = o.__tiny;
    return () => {
      for (const o of off) if (o.__tiny) o.layers.mask = 0;
    };
  };
  return tick;
}

