const NO_COLOUR_EMOJI = new RegExp(String.fromCharCode(0xfe0f), "g");
const h = (tag, attrs = {}, ...kids) => {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === "class") el.className = v;
    else if (k.startsWith("on")) el.addEventListener(k.slice(2), v);
    else if (v !== false && v != null) el.setAttribute(k, v === true ? "" : v);
  }
  for (const kid of kids.flat()) if (kid != null) el.append(kid.nodeType ? kid : document.createTextNode(typeof kid === "string" ? kid.replace(NO_COLOUR_EMOJI, "") : kid));
  return el;
};
const widgetTitle = (role) => (document.querySelector(`.widget[data-role="${role}"] .widget-bar span`)?.textContent || "").trim();
