const plain = (icon) => String(icon).replace(/️/g, "");
// everything a renderer has put on the graphics card. Shapes, materials and pictures shared
// at module level outlive an island, and each one the renderer has touched keeps that
// renderer (and with it the whole old island) alive until it is let go of on the way out
const onCard = new Set();
const addListener = THREE.EventDispatcher.prototype.addEventListener;
THREE.EventDispatcher.prototype.addEventListener = function (type, fn) {
  if (type === "dispose") onCard.add(this);
  return addListener.call(this, type, fn);
};
// (and let go of the moment it is disposed during play: three removes its own dispose listener
// then; review-threejs performance 2)
const removeListener = THREE.EventDispatcher.prototype.removeEventListener;
THREE.EventDispatcher.prototype.removeEventListener = function (type, fn) {
  removeListener.call(this, type, fn);
  if (type === "dispose" && !this._listeners?.dispose?.length) onCard.delete(this);
};

