// Willow plaza (the "plaza" room): the LEGACY pieces world.js builds, carved verbatim out of it
// (P0). The willow itself (tree, planter, heart sign, decorations) is the Willow class in
// tree.js, built by island.js; the plaza ring path is one line of the island-wide trail network
// (trails.js); the keep-clear lawn in front of the heart sign is layout data. Those stay where
// they are. Both parts here run with the World as `this`, at the very same point of the build
// as before. Picked by zones/registry.js while ZONES.plaza.impl is "legacy".
import * as THREE from "three";

// INTERIORS.plaza: the pink marker bobbing over the heart sign (built when the plaza is furnished)
export function interior(room, kit) {
  const { marker } = kit;
  marker(this, room.group, 0, 3.0, 7.4);
}

// World.buildDecor: the 10 lamp posts just outside the plaza ring, stepped off the trail spokes
export function ringLamps(kit, ringR) {
  const { add, cyl, std, glow, glowSprite } = kit;
  // lamp posts along the plaza ring
  const lampCount = 10;
  // (where trails leave the ring: the avenues and the little spurs by the willow)
  const spokes = this.trailSpokes || [];
  for (let i = 0; i < lampCount; i++) {
    let a = (i / lampCount) * Math.PI * 2 + 0.31;
    // step off any path out to a place
    const lampGap = 2.2 / (ringR + 1.6);
    for (const sa of spokes) {
      const d = Math.atan2(Math.sin(a - sa), Math.cos(a - sa));
      if (Math.abs(d) < lampGap) a = sa + Math.sign(d || 1) * lampGap;
    }
    const x = Math.sin(a) * (ringR + 1.6);
    const z = Math.cos(a) * (ringR + 1.6) - 0.5;
    const lamp = new THREE.Group();
    lamp.position.set(x, 0, z);
    add(lamp, cyl(0.07, 0.1, 2.8, 6), std("#5b4a5a"), 0, 1.4, 0);
    add(lamp, new THREE.IcosahedronGeometry(0.24, 2), glow.warm, 0, 2.95, 0, { cast: false });
    const sp = glowSprite("#ffd08a", 2.2);
    sp.position.y = 2.95;
    lamp.add(sp);
    this.root.add(lamp);
    this.addCircle(x, z, 0.2);
  }
}
