// The island's atmosphere and the sky race's dressing (2026-11-20), all from the Blender sky kit
// (assets/blender/environment/sky; vertex colours, no texture memory), loaded after the far range streams in:
//   - the six floating target islets re-made (they ride the legacy islet groups: bob + sniper boards unchanged)
//   - the drifting clouds round the island soft and smooth (the race road's puffs: race_kit act_race_cloud)
//   - big cumulus drifting high round the island, gull flocks circling
//   - moss cushions, ferns and shrubs at the feet of the trees and rocks
// Phones take the _lite models and fewer of everything.
import * as THREE from "three";
import { mergeGeometries } from "three/examples/jsm/utils/BufferGeometryUtils.js";
import { skyLoader } from "./skyrange.js";

const TAU = Math.PI * 2;
const UP = new THREE.Vector3(0, 1, 0);

function load(base, name) {
  return new Promise((res) =>
    skyLoader().load(
      base + `sky/${name}.glb`,
      (gl) => {
        // (a big asset comes in several pieces, the exporter's cells: all of them, merged)
        const parts = [];
        gl.scene.updateMatrixWorld(true);
        gl.scene.traverse((o) => o.isMesh && parts.push(o.geometry.clone().applyMatrix4(o.matrixWorld)));
        if (!parts.length) return res(null);
        for (const g of parts) for (const k of Object.keys(g.attributes)) if (!parts.every((q) => q.attributes[k])) g.deleteAttribute(k);
        const flat = parts.some((g) => !g.index);
        res(parts.length === 1 ? parts[0] : mergeGeometries(flat ? parts.map((g) => (g.index ? g.toNonIndexed() : g)) : parts, false));
      },
      undefined,
      () => res(null),
    ),
  );
}

const vcMat = (extra = {}) => new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.9, metalness: 0, ...extra });

export function loadSky(world, { small }) {
  const base = world.zones?.base;
  if (!base || world.skyLoaded) return;
  world.skyLoaded = true;
  const L = small ? "_lite" : "";
  const rand = (() => {
    let s = 7;
    return () => ((s = (s * 16807) % 2147483647) - 1) / 2147483646;
  })();
  const anims = [];
  world.animated.push((t, dt) => {
    for (const f of anims) f(t, dt || 0.016);
  });

  // ---- clouds: one soft material for every small puff, the theme's cloud colour ---------------
  const cloudMat = vcMat({ roughness: 1, emissive: "#ffffff", emissiveIntensity: 0.12 });
  // (shared: the theme / night tint follows; its self-light too, in the theme's cloud colour: a white one read as a
  // flat grey blob over the halloween moon at night, TODO 45)
  if (world.cloudMat) {
    cloudMat.color = world.cloudMat.color;
    cloudMat.emissive = world.cloudMat.emissive;
  }
  load(base, "env_sky_puff" + L).then((puff) => {
    if (!puff) return;
    // the drifting clouds: their legacy unit (~10.4 m) is the puff's own size
    const swapped = new WeakSet();
    const swap = (im, geo) => {
      if (swapped.has(im)) return;
      swapped.add(im);
      im.geometry = geo;
      im.material = cloudMat;
      im.castShadow = false;
    };
    const C = world.clouds;
    if (C) swap(C, puff);
    let next = 0;
    anims.push((t) => {
      if (t < next) return;
      next = t + 3;
      // (the zone and the leftovers stream in after us: look again now and then)
      for (const o of C?.parent?.children || []) if (o.isInstancedMesh && /^env_cloud_[abc]/.test(o.name)) swap(o, puff);
    });
  });

  // ---- the target islets ------------------------------------------------------------------------
  const islets = world.islets || [];
  Promise.all(islets.map((_, i) => load(base, `env_sky_islet_${i}${L}`))).then((geos) => {
    if (!geos.every(Boolean)) return;
    const mat = vcMat();
    geos.forEach((g, i) => {
      const m = new THREE.Mesh(g, mat);
      m.castShadow = !small;
      m.receiveShadow = true;
      m.name = `sky_islet_${i}`;
      islets[i].add(m);
    });
    // the shell zone's islet looks (they follow the same groups) stop drawing
    const hide = () =>
      world.scene.traverse((o) => {
        if (/^ANIM_env_shell_islet_\d_bob/.test(o.name)) o.visible = false;
      });
    hide();
    setTimeout(hide, 4000);
  });

  // ---- big cumulus, high round the island ------------------------------------------------------
  Promise.all(["a", "b", "c"].map((v) => load(base, `env_sky_cloud_${v}${L}`))).then((geos) => {
    if (!geos.every(Boolean)) return;
    const mat = vcMat({ roughness: 1, emissive: "#ffffff", emissiveIntensity: 0.18, fog: false });
    if (world.cloudMat) {
      mat.color = world.cloudMat.color;
      mat.emissive = world.cloudMat.emissive; // (TODO 45: self-lit in the theme's cloud colour, never a grey glow at night)
    }
    const n = small ? 6 : 12;
    const list = [];
    for (let i = 0; i < n; i++) {
      const m = new THREE.Mesh(geos[i % 3], mat);
      m.castShadow = false;
      m.frustumCulled = true;
      const c = { m, a: (i / n) * TAU + rand() * 0.4, r: 170 + rand() * 150, y: 70 + rand() * 55, s: 0.8 + rand() * 0.7, sp: 0.003 + rand() * 0.004 };
      m.scale.setScalar(c.s);
      list.push(c);
      world.scene.add(m);
    }
    anims.push((t) => {
      for (const c of list) {
        const a = c.a + t * c.sp;
        c.m.position.set(Math.sin(a) * c.r, c.y, Math.cos(a) * c.r);
        c.m.rotation.y = a + Math.PI / 2;
      }
    });
  });

  // ---- gulls: flocks circling, wings flapping in the vertex shader -----------------------------
  load(base, "env_sky_bird").then((geo) => {
    // (the full gull on every tier: 320 tris x 5, the decimated one broke into shards)
    if (!geo) return;
    const flocks = small ? [5] : [6, 5];
    const total = flocks.reduce((a, b) => a + b, 0);
    const mat = vcMat({ roughness: 0.8, emissive: "#ffffff", emissiveIntensity: 0.6 }); // (seen from below the wings and belly stay white)
    const time = { value: 0 };
    mat.onBeforeCompile = (sh) => {
      sh.uniforms.skyT = time;
      sh.vertexShader = sh.vertexShader
        .replace("#include <common>", "#include <common>\nuniform float skyT;")
        .replace(
          "#include <begin_vertex>",
          "#include <begin_vertex>\n{ float ph = instanceMatrix[3].x * 0.37 + instanceMatrix[3].z * 0.21; float s = abs(position.x); float w = sin(skyT * 4.0 + ph) * 0.32 + 0.06; transformed.y += s * s * w; transformed.x *= 1.0 - 0.08 * abs(w); }",
        );
    };
    mat.customProgramCacheKey = () => "skyGull";
    const im = new THREE.InstancedMesh(geo, mat, total);
    im.frustumCulled = false;
    im.castShadow = false;
    im.name = "sky_gulls";
    world.scene.add(im);
    const birds = [];
    flocks.forEach((cnt, f) => {
      const R = 46 + f * 30, Y = 26 + f * 9, sp = (f % 2 ? -1 : 1) * (0.12 - f * 0.02);
      for (let i = 0; i < cnt; i++) birds.push({ R: R + (rand() - 0.5) * 8, Y: Y + (rand() - 0.5) * 4, sp, off: i * 0.07 + rand() * 0.03, bob: rand() * TAU, s: 0.9 + rand() * 0.3 });
    });
    const m = new THREE.Matrix4(), q = new THREE.Quaternion(), p = new THREE.Vector3(), sc = new THREE.Vector3();
    const e = new THREE.Euler();
    // halloween (user 2026-11-22): the flocks are bats, the gulls stay in every other theme. The bat is the sky kit's
    // Blender model (environment/sky/build_sky_bats.py) with its keyed wing-beat clip "flap": arms and hands on their
    // own pivots, one InstancedMesh per part, the clip sampled for each bat at its own phase. Loaded the first time
    // the theme shows.
    let bats = null;
    const loadBats = () => {
      bats = { parts: [], ready: false };
      skyLoader().load(
        base + `sky/env_sky_bat${L}.glb`,
        (gl) => {
          const clip = gl.animations.find((c) => c.name === "flap") || gl.animations[0];
          if (!clip) return;
          const batMat = vcMat({ roughness: 0.85, side: THREE.DoubleSide, emissive: "#3a2448", emissiveIntensity: 0.35 });
          gl.scene.traverse((o) => {
            if (!o.isMesh) return;
            const part = new THREE.InstancedMesh(o.geometry, batMat, birds.length);
            part.frustumCulled = false;
            part.castShadow = false;
            part.name = "sky_bats_" + o.name;
            world.scene.add(part);
            bats.parts.push({ src: o, im: part });
          });
          bats.root = gl.scene;
          bats.mixer = new THREE.AnimationMixer(gl.scene);
          bats.mixer.clipAction(clip).play();
          bats.len = clip.duration;
          bats.ready = true;
        },
        undefined,
        () => {},
      );
    };
    const bm = new THREE.Matrix4();
    anims.push((t) => {
      time.value = t;
      const spooky = Boolean(world.spooky?.visible);
      im.visible = !spooky;
      if (spooky && !bats) loadBats();
      const batsOn = spooky && bats?.ready;
      if (bats?.ready) for (const pt of bats.parts) pt.im.visible = batsOn;
      birds.forEach((b, i) => {
        const a = t * b.sp + b.off + (b.sp > 0 ? 0 : 2);
        p.set(Math.sin(a) * b.R, b.Y + Math.sin(t * 0.7 + b.bob) * 1.5, Math.cos(a) * b.R);
        // nose (-z) along the circle, banked into the turn
        e.set(0, a + (b.sp > 0 ? Math.PI / 2 : -Math.PI / 2) + Math.PI, (b.sp > 0 ? 1 : -1) * 0.25);
        m.compose(p, q.setFromEuler(e), sc.setScalar(b.s));
        if (!batsOn) return im.setMatrixAt(i, m);
        // (each bat a little out of step with the next, some beating a touch faster)
        bats.mixer.setTime((t * (0.92 + (i % 5) * 0.04) + b.bob) % bats.len);
        bats.root.updateMatrixWorld(true);
        for (const pt of bats.parts) pt.im.setMatrixAt(i, bm.multiplyMatrices(m, pt.src.matrixWorld));
      });
      if (batsOn) for (const pt of bats.parts) pt.im.instanceMatrix.needsUpdate = true;
      else im.instanceMatrix.needsUpdate = true;
    });
  });

  // (TODO 64, the user: "there is a cone of light remove it or fix it" / "there are multipole ones": the day's light
  // shafts were solid leaning cones standing on the island, lit the same way whatever the sun did, so they read as pale
  // wedges over the mountains. Gone on every theme and tier; the sun's own light and haze carry the day)

  // ---- moss and underbrush at the feet of trees and rocks ---------------------------------------
  Promise.all(["moss_a", "moss_b", "fern", "shrub"].map((v) => load(base, `env_sky_${v}${L}`))).then((geos) => {
    if (!geos.every(Boolean) || !world.circles) return;
    const want = small ? [22, 14, 18, 12] : [55, 35, 45, 30];
    // (the wild belt only: trees and rocks out past the places, never in a garden, a pen or on a path)
    const feet = world.circles.filter((c) => c.r >= 0.25 && c.r <= 1.6 && Math.hypot(c.x, c.z) > 30 && Math.hypot(c.x, c.z) < 79);
    const pos = geos.map(() => []);
    for (let tries = 0; tries < 4000 && feet.length; tries++) {
      const k = tries % 4;
      if (pos[k].length >= want[k]) continue;
      const c = feet[Math.floor(rand() * feet.length)];
      const a = rand() * TAU, d = c.r + 0.15 + rand() * (k < 2 ? 0.4 : 0.9);
      const x = c.x + Math.sin(a) * d, z = c.z + Math.cos(a) * d;
      let ok = !world.isFree || world.isFree(x, z, 0.4);
      for (const p of world.pathPoints || []) if (Math.abs(p.x - x) < 2 && Math.abs(p.z - z) < 2 && Math.hypot(p.x - x, p.z - z) < 1.7) ok = false;
      for (const q of world.reserved || []) if (Math.hypot(x - q.x, z - q.z) < q.r) ok = false;
      // (nor under a ride: the daisy wheel's deck, ferris.js world.clearings)
      for (const cl of world.clearings || []) if (cl.has?.(x, z)) ok = false;
      if (!ok) continue;
      pos[k].push([x, z, rand() * TAU, (k < 2 ? 0.7 : k === 3 ? 0.55 : 0.8) + rand() * (k === 3 ? 0.3 : 0.5)]);
    }
    const mat = vcMat({ roughness: 0.95 });
    const m = new THREE.Matrix4(), q = new THREE.Quaternion(), p = new THREE.Vector3(), s = new THREE.Vector3();
    // (all four kinds in one mesh, one draw instead of four (TODO 1, the phone's draws): they never move; the
    // instanced path stays for a set whose shapes can't be joined)
    const parts = [];
    geos.forEach((g, k) =>
      pos[k].forEach(([x, z, r, sc]) => {
        const c = (g.index ? g.toNonIndexed() : g.clone()).applyMatrix4(m.compose(p.set(x, -0.02, z), q.setFromAxisAngle(UP, r), s.setScalar(sc)));
        for (const n of Object.keys(c.attributes)) if (n !== "position" && n !== "normal" && n !== "color") c.deleteAttribute(n);
        parts.push(c);
      }),
    );
    const one = parts.length ? mergeGeometries(parts) : null;
    for (const c of parts) c.dispose();
    if (one) {
      one.computeBoundingSphere();
      const mesh = new THREE.Mesh(one, mat);
      mesh.castShadow = false;
      mesh.receiveShadow = true;
      mesh.matrixAutoUpdate = false;
      mesh.name = "sky_brush";
      world.scene.add(mesh);
      return;
    }
    geos.forEach((g, k) => {
      if (!pos[k].length) return;
      const im = new THREE.InstancedMesh(g, mat, pos[k].length);
      pos[k].forEach(([x, z, r, sc], i) => im.setMatrixAt(i, m.compose(p.set(x, -0.02, z), q.setFromAxisAngle(UP, r), s.setScalar(sc))));
      im.computeBoundingSphere();
      im.castShadow = false;
      im.receiveShadow = true;
      im.name = "sky_brush_" + k;
      world.scene.add(im);
    });
  });
}
