// Our shared home's editor (TODO "Shared home": "control every aingle detail of the house, inside and outside and all
// the furniture", user 2026-11-28 "everything should be editable and customizable"): everything in the house, saved for
// both of us and live on both screens.
//   furniture: add any piece from the catalogue, pick up anything (tap it) and carry it where you like, turn it, set it
//              on a table or a shelf (it stands on what it is over), raise or lower it, recolour each of its parts,
//              copy it, put it away; lamps switch on and off
//   rooms:     each room's walls (colour and wallpaper), its panelling, its floor (boards, checks or tiles, their colours),
//              its windows (small, medium, large), open or closed
//   outside:   the walls, trims, roof, shutters, flower boxes, front door, inside doors, curtains, chimney, the stone foot,
//              the fences
// The house's data (homedata.js) is changed by small ops (decor.js for the pieces); each op is applied here, sent live
// to the other one (net "home") and the whole house saved to its row (__prefs:game:home:house, the same table the gifts
// and the cave keep theirs in). Controls: big buttons in a bar for phones, the same with the mouse; tap to pick up.
import * as THREE from "three";
import { PIECES, PALETTE, WALLPAPERS, FLOOR_TILES, SURFACE_KINDS, HOME_DEFAULT, LEVEL_H, PLOT } from "./homedata.js";

const ROW = "__prefs:game:home:house";
const CACHE = "tdd3dHome";
const VERSION = 3;
// (v3, 2026-11-28: the plot fenced all round with its gate, the backyard laid out from the kitchen's back doors, path
// lights for the lamp posts: a v2 house keeps everything but these, which come from the new default)
const V3_OUTSIDE = /^(fence(L|R|SL|SR|B|BL|BR)|fp\d|lampL|blamp|patio|ptable|pc\d|bbq|lounge\d|ppot\d|plight\d|ss\d+)$/;
const STEP_TURN = Math.PI / 12;
const HEX = /^#[0-9a-f]{6}$/i;

// the catalogue's shelves
const SHELVES = [
  ["sofas & chairs", ["sofa", "armchair", "reading_chair", "wicker_chair", "pouf", "beanbag", "floor_cushions", "window_seat", "entry_bench", "bed_bench", "chair", "desk_chair"]],
  ["tables & storage", ["coffee_table", "side_table", "dining_table", "long_table", "desk", "console", "sideboard", "nightstand", "bookshelf", "wardrobe", "clothes_rail", "tv_console"]],
  ["kitchen", ["counter", "counter_sink", "stove", "fridge", "upper_cab", "open_shelf", "hood", "backsplash"]],
  ["bed & bath", ["bed", "mirror", "tub", "toilet", "vanity", "towel_ladder", "bath_shelf", "bathmat"]],
  ["cosy things", ["fireplace", "piano", "guitar_stand", "plant_big", "plant_small", "planter", "wall_art", "coat_rack", "profile_frame", "fairy_lights"]],
  ["lights", ["floor_lamp", "table_lamp", "pendant", "lamp_post"]],
  ["rugs", ["rug_living", "rug_oval", "rug_round", "doormat", "bathmat"]],
  ["garden", ["garden_bench", "bistro_chair", "bistro_table", "parasol_table", "lounger", "bbq", "porch_swing", "mailbox", "flowerbed", "fence", "fence_post", "arbor", "stepping_stone"]],
];
const EMOJI = { sofa: "🛋️", armchair: "💺", bed: "🛏️", tub: "🛁", toilet: "🚽", fridge: "🧊", stove: "🍳", piano: "🎹", guitar_stand: "🎸", tv_console: "📺", plant_big: "🪴", plant_small: "🌱", planter: "🌷", floor_lamp: "💡", table_lamp: "💡", pendant: "💡", lamp_post: "🏮", bookshelf: "📚", mirror: "🪞", fireplace: "🔥", bbq: "🍖", mailbox: "📮", wall_art: "🖼️", profile_frame: "🖼️", fairy_lights: "✨", rug_living: "🟪", rug_oval: "🟣", rug_round: "⭕", doormat: "🟫", bathmat: "🟦" };
const OUTSIDE = [["siding", "walls outside"], ["trim", "trims & window frames"], ["roof", "roof"], ["fascia", "roof edges"], ["shutter", "shutters"], ["flowerbox", "flower boxes"], ["front_door", "front door"], ["doors", "inside doors"], ["curtain", "curtains"], ["brass", "door knobs"], ["chimney", "chimney"], ["plinth", "stone foot"], ["ceiling", "ceilings"], ["skirting", "skirting & cornices"]];
const WINDOWS = ["window_s", "window_m", "window_l"];

let styled = false;
