// Device tiers (REBUILD-PLAN §6.3, review m1). Picked BEFORE the first frame, because two things
// can only be chosen once: the canvas's own smoothing (fixed when the drawing context is made) and
// the render path (look.js: the picture drawn off-screen with glow on high/ultra, straight onto the
// canvas on low/mid; switching later would compile every shader a second time).
//
// How it's picked, most trusted first:
//   1. a forced tier (localStorage "tdd3d.tierOverride": low | mid | high | ultra; for testing);
//   2. what this device measured itself last time (localStorage "tdd3d.tier.v1"; the warm-up below);
//   3. a conservative guess from what the browser says (touch, the graphics chip's name where it is
//      given, cores, memory) plus a ~20 ms timing of plain script work. Device strings are only a
//      hint: an iPhone says "Apple GPU" and Safari/Firefox have no deviceMemory.
// Then a short warm-up after the first frame measures the real frame and moves one step within the
// same render path (ultra <-> high, mid <-> low) for the things that can change while running:
// sharpness, shadow detail, moving shadows. The adaptive step in the loop (island.js) stays as the
// safety net.
//
// Nothing here changes what is in the world, where it is or how it plays: only how it is drawn.

const KEY = "tdd3d.tier.v1";
const OVERRIDE = "tdd3d.tierOverride";
export const TIERS = ["low", "mid", "high", "ultra"];

// what each tier draws with
//   path: "composer" (off-screen picture + glow, look.js) | "direct" (straight onto the canvas)
//   canvasAA: the canvas's own smoothing (only used by the direct path)
//   msaa: smoothing samples of the off-screen picture (composer path)
//   maxRatio: sharpest pixel ratio
//   shadow: map size, filter, the cached box's half-width and how far you walk before it is
//     re-centred, and whether moving things get real shadows each frame (overlay) or soft blobs;
//     cache: the size of the copy of the still map the movers' patches are restored from, as a
//     share of the map (D-E1c: half on high, 32 MB instead of 128 MB; full on ultra)
//   density: share of purely decorative moving particles (weather, confetti)
//   photo: the map photo's size
export const PRESETS = {
  low: { path: "direct", canvasAA: true, msaa: 0, maxRatio: 1, shadow: { size: 1024, soft: false, radius: 2, half: 28, recentre: 8, overlay: false }, density: 0.5, photo: 1024 },
  mid: { path: "direct", canvasAA: true, msaa: 0, maxRatio: 1.5, shadow: { size: 2048, soft: false, half: 28, recentre: 4, overlay: true, cache: 0.5 }, density: 1, photo: 1024 },
  high: { path: "composer", canvasAA: false, msaa: 4, maxRatio: 1.5, shadow: { size: 4096, soft: true, half: 28, recentre: 4, overlay: true, cache: 0.5 }, density: 1, photo: 2048 },
  ultra: { path: "composer", canvasAA: false, msaa: 4, maxRatio: 2, shadow: { size: 4096, soft: true, half: 28, recentre: 4, overlay: true }, density: 1, photo: 2048 },
};
// A phone or tablet keeps the low tier's 1024 shadow map on every tier, its PCF taps spread over 2 texels so
// the steps blur instead of reading blocky: an iPhone picks mid, and mid's 2048 map (with its depth) was ~25 MB
// of graphics memory more than the phone budget (PROJECT_STATE, ~192 MB measured on low) allowed for; its moving
// shadows are drawn only for what can cast into the view (shadows.js renderOverlay)
function fitTouch(preset, touch) {
  if (touch) preset.shadow = { ...preset.shadow, size: Math.min(preset.shadow.size, 1024), radius: 2, viewCull: true };
  // (computers: only the per-view test of the moving casters, shadows.js renderOverlay; the rest of viewCull is the phone's)
  else preset.shadow = { ...preset.shadow, moverCull: true };
  return preset;
}
// the step down / up within one render path
const DOWN = { ultra: "high", high: "high", mid: "low", low: "low" };
const UP = { low: "mid", mid: "mid", high: "ultra", ultra: "ultra" };

function readJSON(k) {
  try {
    return JSON.parse(localStorage.getItem(k) || "null");
  } catch {
    return null;
  }
}

// ~20 ms of plain script work: how quick this device's main thread is (a phone runs it 3-6x slower
// than a desktop; the island's frame is mostly main-thread work handing out draws)
// (bounded by rounds too: a clock that doesn't move, as in a test harness, never holds it up; then
// the score is unknown and the other signals decide)
function cpuScore() {
  const t0 = performance.now();
  let n = 0;
  let x = 0;
  const a = new Float64Array(256);
  while (n < 3000 && performance.now() - t0 < 20) {
    for (let i = 0; i < 2000; i++) {
      const k = i & 255;
      a[k] = a[k] * 0.5 + Math.sqrt(i + x);
      x = (x + a[k]) % 1000;
    }
    n++;
  }
  const ms = performance.now() - t0;
  return ms > 1 ? Math.round(n / (ms / 20)) : null; // rounds of 2000 in 20 ms
}

// the graphics chip's name, where the browser gives it (a throwaway context, let go at once)
function gpuName() {
  try {
    const c = document.createElement("canvas");
    const gl = c.getContext("webgl2") || c.getContext("webgl");
    if (!gl) return { name: "", webgl2: false };
    const ext = gl.getExtension("WEBGL_debug_renderer_info");
    const name = String(ext ? gl.getParameter(ext.UNMASKED_RENDERER_WEBGL) : gl.getParameter(gl.RENDERER) || "");
    const max = gl.getParameter(gl.MAX_TEXTURE_SIZE) || 4096;
    const webgl2 = typeof WebGL2RenderingContext !== "undefined" && gl instanceof WebGL2RenderingContext;
    gl.getExtension("WEBGL_lose_context")?.loseContext();
    return { name, maxTexture: max, webgl2 };
  } catch {
    return { name: "", webgl2: false };
  }
}

const SOFTWARE = /swiftshader|llvmpipe|softpipe|basic render|software/i;
const DISCRETE = /nvidia|geforce|quadro|rtx|gtx|radeon (rx|pro|vii)|radeon\(tm\) rx|rx \d{3,4}|arc\(tm\) a|arc a\d/i;
const WEAK_MOBILE = /mali-(g5[0-9]|g6[0-9]|g7[0-2]|t)|adreno \(tm\) (3|4|5|6[0-1])\d\d|powervr|videocore/i;

export function pickTier({ isTouch }) {
  const forced = (() => {
    try {
      return localStorage.getItem(OVERRIDE);
    } catch {
      return null;
    }
  })();
  const info = { touch: isTouch, cores: navigator.hardwareConcurrency || 0, memory: navigator.deviceMemory || 0, dpr: devicePixelRatio || 1 };
  let name;
  let reason;
  if (TIERS.includes(forced)) {
    name = forced;
    reason = "forced";
  } else {
    const saved = readJSON(KEY);
    if (saved && TIERS.includes(saved.tier) && saved.ua === navigator.userAgent && saved.touch === isTouch) {
      name = saved.tier;
      reason = "measured last time";
    }
  }
  const gpu = gpuName();
  info.gpu = gpu.name;
  info.cpu = cpuScore();
  if (!name) {
    if (SOFTWARE.test(gpu.name)) {
      name = "low";
      reason = "software graphics";
    } else if (isTouch) {
      const weak = (info.memory && info.memory <= 3) || (info.cores && info.cores <= 4) || WEAK_MOBILE.test(gpu.name) || (info.cpu != null && info.cpu < 90);
      name = weak ? "low" : "mid";
      reason = weak ? "touch, modest device" : "touch";
    } else if (DISCRETE.test(gpu.name) && (info.cpu == null || info.cpu >= 120)) {
      name = "ultra";
      reason = "discrete graphics";
    } else {
      // laptops with built-in graphics, Macs, or a browser that doesn't say: the off-screen
      // picture with glow, a little less sharp; the warm-up raises it if there's room
      const slow = info.cpu != null && info.cpu < 60;
      name = slow ? "mid" : "high";
      reason = slow ? "slow main thread" : "built-in or unknown graphics";
    }
  }
  return makeTier(name, reason, info);
}

function makeTier(name, reason, info) {
  const t = {
    __e1: "tier",
    name,
    reason,
    info,
    preset: fitTouch({ ...PRESETS[name], shadow: { ...PRESETS[name].shadow } }, info.touch),
    bench: null,
    // the render path and the shadow filter never change once the island is running
    get path() {
      return this.preset.path;
    },
  };
  return t;
}

// The warm-up: after the first frame, ~2 s of real frames decide whether to step down or up within
// the render path. onChange(preset) applies what changed (sharpness, shadow size, moving shadows).
// The result is kept for the next visit, so the render path itself can follow next time.
export class WarmUp {
  constructor(tier, onChange) {
    this.tier = tier;
    this.onChange = onChange;
    this.frames = [];
    this.skip = 20; // (the first frames after the loading screen include one-off work)
    this.done = false;
  }

  // once a frame: the time the loop took (ms) and the time since the last frame (ms)
  sample(loopMs, intervalMs) {
    if (this.done) return;
    if (this.skip > 0) {
      this.skip--;
      return;
    }
    this.frames.push([loopMs, intervalMs]);
    if (this.frames.length < 120) return;
    this.done = true;
    const loops = this.frames.map((f) => f[0]).sort((a, b) => a - b);
    const ivs = this.frames.map((f) => f[1]).sort((a, b) => a - b);
    const p50 = loops[loops.length >> 1];
    const iv50 = ivs[ivs.length >> 1];
    const t = this.tier;
    const from = t.name;
    let to = from;
    // (for the next visit the step may cross render paths; within this one it never does)
    let next = from;
    const slow = p50 > (t.path === "direct" ? 30 : 18) || iv50 > (t.path === "direct" ? 40 : 24);
    const roomy = p50 < (t.path === "direct" ? 9 : 7) && iv50 < 18;
    // slow: the main thread can't keep ~30 fps (phones) / ~50 fps (computers)
    if (slow) {
      to = DOWN[from];
      next = TIERS[Math.max(0, TIERS.indexOf(from) - 1)];
    } else if (roomy) {
      // lots of room: a step up
      to = UP[from];
      next = TIERS[Math.min(TIERS.length - 1, TIERS.indexOf(from) + 1)];
    }
    // (a phone or tablet stays on the straight-to-canvas path: its graphics gain nothing from the
    // off-screen picture)
    if (t.info.touch && TIERS.indexOf(next) > TIERS.indexOf("mid")) next = "mid";
    t.bench = { loopP50: +p50.toFixed(2), intervalP50: +iv50.toFixed(2), from, to, next };
    if (to !== from) {
      t.name = to;
      t.reason += `; warm-up ${from} -> ${to}`;
      const keepSoft = t.preset.shadow.soft;
      t.preset = fitTouch({ ...PRESETS[to], shadow: { ...PRESETS[to].shadow, soft: keepSoft } }, t.info.touch);
      t.preset.path = PRESETS[from].path; // (fixed for this visit)
      this.onChange?.(t.preset, from);
    }
    if (t.reason !== "forced") {
      try {
        localStorage.setItem(KEY, JSON.stringify({ tier: next, ua: navigator.userAgent, touch: t.info.touch, at: Date.now(), bench: t.bench }));
      } catch {}
    }
  }
}
