// Every animal's clip graph (scale.md "Graph notes per family"), one data-driven graph on the cat's pattern:
// idle variety by seeded weight, "@loco" as one blend space with one normalised phase (speed-matched),
// pose families (enter -> loop -> exit, the clips' own tdd_next), one-shots and turns as overlays, the
// happy layer. The behaviour code keeps its state and passes it in; nothing new goes on the network.
//
//   critterClips(owner, skin, carrier, s, dt, camD, opts) -> true when the clips own the rig this frame
//   (false: no carrier yet, the rig not worn, or zones=legacy: the legacy motion runs as before)
//
// Each animal is one SkinnedMesh whose bones are its ANIM_ pivots (zones/animals.js merge), so a clip
// drives the pivots and the skeleton does the rest; there are no InstancedMesh herds to write. Per animal:
// a seeded phase and idle pick (mulberry, never Math.random), and a distance Tier (phones: mid at best).
import { clipLib } from "./clips.js";
import { Animator, RigBinding, AnimClock, Tier, mulberry, isCalm } from "./runtime.js";

// idles [name, weight]; loco clip names (slow to fast); fam: pose families [enter, loop, exit]
const QUAD = { idles: [["idle_breathe", 3], ["idle_look", 2], ["idle_tail", 1]], loco: ["walk", "trot"], fam: { graze: ["graze_down", "graze_loop", "graze_up"], lie: ["lie_down", "lie_loop", "stand_up"] } };
export const SPECIES = {
  cow: { ...QUAD, shots: ["moo"] },
  goat: { ...QUAD, shots: ["hop", "headbutt"] },
  sheep: { ...QUAD, shots: ["baa", "shake"] },
  deer: { ...QUAD, loco: ["walk", "trot", "run"], shots: [] },
  hen: { idles: [["idle_breathe", 3], ["idle_look", 2]], loco: ["walk", "run"], fam: { peck: ["peck_start", "peck_loop", null], roost: ["sit_down", "roost_loop", "stand_up"] }, shots: ["flap"] },
  chick: { idles: [["idle_breathe", 3], ["idle_look", 2]], loco: ["walk"], fam: { peck: [null, "peck_loop", null], sleep: [null, "sleep_loop", null] }, shots: ["hop", "flap"] },
  duck: { idles: [["idle_float", 3], ["idle_look", 2]], loco: ["paddle", "paddle_fast"], fam: { feed: [null, "feed_loop", null] }, shots: ["dabble", "preen", "wing_flap", "shake", "quack"] },
  bunny: {
    idles: [["idle_breathe", 3], ["idle_sniff", 2], ["idle_earflick", 1]],
    loco: ["hop", "hop_run"],
    fam: { tall: ["tall_up", "tall_loop", "tall_down"], groom: ["groom_start", "groom_loop", "groom_end"], loaf: ["lie_down", "lie_loop", "stand_up"], belly: ["flop", "flop_loop", "flop_up"], eat: [null, "eat_loop", null] },
    shots: [],
  },
  frog: { idles: [["idle_breathe", 3], ["idle_look", 1]], loco: [], fam: {}, shots: ["croak"] },
  hedgehog: { idles: [["idle_sniff", 1]], loco: ["walk"], fam: { curl: ["curl", "curl_loop", "uncurl"] }, shots: [] },
  bee: { idles: [["hover", 1]], loco: ["fly"], fam: {}, shots: [] },
  butterfly: { idles: [["perch_loop", 1]], loco: ["flap_loop"], fam: { glide: [null, "glide_loop", null] }, shots: [] },
  dookie: { idles: [["idle_loop", 1]], loco: [], fam: { vanish: [null, "vanish", null] }, shots: [], start: "appear" },
};
SPECIES.rooster = { ...SPECIES.hen, shots: ["crow", "flap"] };
SPECIES.duckling = SPECIES.duck;

export class CritterAnim {
  constructor(binding, cfg, seed) {
    const lib = binding.lib;
    this.lib = lib;
    this.cfg = cfg;
    this.an = new Animator(binding);
    this.loco = cfg.loco.map((n) => lib.get(n)).filter(Boolean).map((c) => ({ clip: c, speed: c.extras.tdd_speed || 1 }));
    // (track D: one gait per held speed, the change-over crossfaded over 0.3 s, runtime locoSwitch; a speed-mapped
    // blend of a walk and a trot played half of each stride at once, and the legs read as a shuffle)
    if (this.loco.length > 1) this.loco.fade = 0.3;
    this.idles = cfg.idles.filter(([n]) => lib.get(n));
    this.famOf = new Map();
    for (const [f, list] of Object.entries(cfg.fam)) for (const n of list) if (n) this.famOf.set(n, f);
    this.rng = mulberry(seed);
    this.an.phase = this.rng();
    this.shotIn = 4 + this.rng() * 10;
    this.seq = 0;
    this.turnSeq = 0;
    if (cfg.start && lib.get(cfg.start)) this.an.play(cfg.start, 0);
    else this.an.play(this.pickIdle(), 0).t = this.rng() * 4;
  }
  pickIdle(not = "") {
    const I = this.idles;
    if (!I.length) return "";
    if (isCalm()) return I[0][0];
    let tot = 0;
    for (const [n, w] of I) if (n !== not) tot += w;
    let r = this.rng() * tot;
    for (const [n, w] of I) if (n !== not && (r -= w) <= 0) return n;
    return I[0][0];
  }
  // s: { speed, moving, fam ("" or a family), happy, shot, shotSeq, turn (-1 / 0 / 1), turnSeq }
  update(clock, s) {
    const dt = clock.dt;
    const an = this.an;
    const cur = an.current();
    const name = cur.name;
    const fam = this.cfg.fam;
    const moving = this.loco.length > 0 && (s.moving || s.speed > 0.05) && !s.fam;
    const inFam = this.famOf.get(name) || "";
    const want = moving ? "" : s.fam || "";
    if (moving) {
      if (name !== "@loco") {
        // (out of a lying or grazing family through its own exit when it has one, then walk)
        const f = inFam && fam[inFam];
        if (f && f[2] && name !== f[2] && inFam !== "graze") an.play(f[2], 0.2);
        else if (!f || !f[2] || name !== f[2] || cur.t >= cur.clip.duration - 0.15) an.play("@loco", inFam ? 0.35 : 0.22);
      }
    } else if (want && inFam !== want) {
      // into the wanted family: leave the current one through its exit first
      const f = inFam && fam[inFam];
      if (f && f[2] && name !== f[2]) an.play(f[2], 0.2);
      else if (!f || !f[2] || cur.t >= cur.clip.duration - 0.12) {
        const g = fam[want];
        if (g) an.play(g[0] || g[1], 0.25);
      }
    } else if (!want && inFam && name !== fam[inFam][2]) {
      const f = fam[inFam];
      an.play(f[2] || this.pickIdle(), 0.25);
    } else if (name === "@loco") {
      an.play(this.pickIdle(), 0.3);
    } else if (cur.clip && !cur.clip.loop && inFam && inFam === want && fam[inFam][1] === name) {
      // (a family whose "loop" is a one-shot, the dookie's vanish: it holds its last frame)
    } else if (cur.clip && !cur.clip.loop && cur.t >= cur.clip.duration - 0.12) {
      // a transition's own next (graze_down -> graze_loop, stand_up -> an idle, appear -> idle_loop)
      let nx = cur.clip.extras.tdd_next;
      if (!nx || !this.lib.get(nx) || (this.famOf.has(nx) && this.famOf.get(nx) !== want) || this.idles.some(([n]) => n === nx)) nx = this.pickIdle();
      an.play(nx, 0.2);
    } else if (cur.clip && cur.clip.loop && !inFam && cur.t >= cur.clip.duration - 0.3 && this.idles.length > 1) {
      an.play(this.pickIdle(name), 0.5);
    }
    // one-shots: asked for (react, a voice) or sprinkled in now and then while idle
    if (s.shot && s.shotSeq !== this.seq) {
      this.seq = s.shotSeq;
      an.overlay(s.shot, true, 0.12, true, 0.25);
    }
    if (!moving && !s.fam && this.cfg.shots.length && !isCalm() && (this.shotIn -= dt) <= 0) {
      this.shotIn = 9 + this.rng() * 14;
      an.overlay(this.cfg.shots[Math.floor(this.rng() * this.cfg.shots.length)], true, 0.15, true, 0.3);
    }
    if (s.turn && s.turnSeq !== this.turnSeq) {
      this.turnSeq = s.turnSeq;
      an.overlay(s.turn > 0 ? "turn_l" : "turn_r", true, 0.12, true, 0.25);
    }
    if (this.lib.get("happy")) an.overlay("happy", s.happy > 0, 0.3);
    const locoOn = this.loco.length && an.layers.some((l) => l.loco);
    return an.update(dt, s.speed, locoOn ? this.loco : null);
  }
}

// bind (and rebind on a level switch: full <-> lite share one graph) and step one animal. owner: the
// object the state lives on (gets .clipAnim). camD: camera distance. opts: { near (always tier 0),
// small (phones: mid at best), get(nodes, role) (a role map for rigs without ANIM_ pivots) }
let seedN = 11;
export function critterClips(owner, skin, carrier, species, s, dt, camD, opts = {}) {
  const lib = clipLib(carrier);
  if (!lib || !skin?.worn) return false;
  const L = skin.levels;
  if (skin.cur >= L.length) return true; // (the far rest mesh: nothing moves)
  const lvl = L[skin.cur];
  let A = owner.clipAnim;
  if (!A || A.lvl !== lvl) {
    const nodes = lvl.nodes || {};
    const get = opts.get ? (r) => opts.get(lvl, r) : (r) => nodes[r] || null;
    const b = new RigBinding(lib, get, null);
    if (!A) A = owner.clipAnim = { g: new CritterAnim(b, SPECIES[species], (seedN += 7)), clock: new AnimClock(), tier: new Tier() };
    else {
      A.g.an.binding = b;
      A.g.an.pose = b.newPose();
    }
    A.b = b;
    A.lvl = lvl;
  }
  let tier = opts.near ? 0 : A.tier.pick(dt, camD, opts.cut ?? 60, Boolean(opts.small));
  if (opts.near) A.tier.tier = 0;
  // (phones: past the lite distance, 25 m, the far row's every 4th frame: never dearer than the old sines)
  else if (opts.small && tier === 1 && camD > 25) tier = A.tier.tier = 2;
  const step = A.tier.step(dt);
  if (!step) return true;
  const clock = A.clock.tick(step);
  A.g.an.snap = tier >= 2;
  A.b.apply(A.g.update(clock, s));
  return true;
}
