// Dodo's flower stall's customers (TODO 20): real animals from the Blender animals kit, as in the bakery (the
// same pet rigs, looks and one-draw skinned meshes, zones/animals.js), in a cute mix of species: kitties, bunnies,
// a hedgehog and a chick. Each walks up the path on its own gait, browses along the buckets of flowers, reaches
// for the bouquet it wants, pays with a happy thank-you and carries it away. Every moment is a keyed Blender clip:
// the species' own walk / hop / idles plus its shop clips (assets/blender/animals/w20_anim_shop.py:
// shop_browse, shop_pick, shop_pay, shop_carry), added to the species' library by role here.
// Phone memory: the rigs, their atlas and tinted materials are the bakery's (shared, a small fixed palette); each
// customer's own merged skin and skeleton and its bouquet are freed when it leaves. One customer at a time.
import * as THREE from "three";
import { buildPetModels } from "./creatures.js";
import { skinAnimal, animalsReady } from "./zones/animals.js";
import { clipLib } from "./anim/clips.js";
import { RigBinding, Animator, AnimClock, STRIDE } from "./anim/runtime.js";
import { fade } from "./render/fade.js";

// species: rig carriers, gait, scale (world m per rig m), where the bouquet is held (a role, its spot and size in
// that role's frame), the speech bubble's height (world m) and its voice
const SPECIES = {
  cat: { base: "ani_pet_cat_clips", shop: "ani_pet_cat_shop_clips", loco: ["walk"], idle: "idle_breathe", scale: 1.35, pace: 0.85, hold: "head", at: [0, -0.08, 0.2], tilt: 0.35, size: 0.6, bubble: 1.0, voice: "cat_trill", hi: "cat_meow:1@0.35", emoji: "🐱", who: "a kitty" },
  bunny: { base: "ani_pet_bunny_clips", shop: "ani_pet_bunny_shop_clips", loco: ["hop"], idle: "idle_breathe", scale: 1.35, pace: 0.9, hold: "body", at: [0, 0.04, 0.23], tilt: 0.2, size: 0.62, bubble: 1.0, voice: "bunny_squeak", hi: "bunny_sniff@0.4", emoji: "🐰", who: "a bunny" },
  hedgehog: { base: "ani_hedgehog_clips", shop: "ani_hedgehog_shop_clips", loco: ["walk"], idle: "idle_sniff", scale: 1.3, pace: 2.0, hold: "body", at: [0, 0.12, -0.02], tilt: -0.15, size: 0.42, bubble: 0.62, voice: "hedgehog_snuffle", hi: "hedgehog_snuffle@0.4", emoji: "🦔", who: "a hedgehog", asset: "ani_hedgehog" },
  chick: { base: "ani_chick_clips", shop: "ani_chick_shop_clips", loco: ["walk"], idle: "idle_breathe", scale: 2.2, pace: 1.0, hold: "head", at: [0, -0.01, 0.08], tilt: 0.3, size: 0.42, bubble: 0.8, voice: "chick_peep", hi: "chick_peep@0.4", emoji: "🐥", who: "a chick", asset: "ani_chick" },
};
// (a fixed palette: every look is a tinted material kept for the visit, zones/animals.js tintCache)
const CATS = [
  { fur: "#f4a259", accent: "#fff1e0", pattern: "tabby", collar: "#ff8fb1", hat: "flower" },
  { fur: "#2b2633", accent: "#ffffff", pattern: "tuxedo", collar: "#ffd166", hat: "bow" },
  { fur: "#fff7f0", accent: "#ffffff", pattern: "siamese", collar: "#7b5cd6", hat: "none", eyes: "#5aa0e0" },
  { fur: "#9a9aa8", accent: "#ffffff", pattern: "socks", collar: "#8fd3b6", hat: "star", ears: "fold" },
  { fur: "#f3d9b1", accent: "#fff1e0", pattern: "calico", collar: "#e2557f", hat: "party", coat: "fluffy" },
];
const BUNNIES = [
  { fur: "#fff7f0", accent: "#ffffff", collar: "#ff8fb1", hat: "flower", ears: "fold" },
  { fur: "#c98a5a", accent: "#fff1e0", collar: "#ffd166", hat: "none", pattern: "socks" },
  { fur: "#9a9aa8", accent: "#ffffff", collar: "#7b5cd6", hat: "bow" },
  { fur: "#f3d9b1", accent: "#ffffff", collar: "#8fd3b6", hat: "star", coat: "fluffy" },
];
const MIX = ["cat", "bunny", "cat", "bunny", "hedgehog", "chick"];

// ---- the species' library with its shop clips, by role (one ClipLib-shaped object per pair) ----
const libs = new Map();
function shopLib(sp) {
  const S = SPECIES[sp];
  const a = clipLib(S.base);
  const b = clipLib(S.shop);
  if (!a || !b) return null;
  const hit = libs.get(sp);
  if (hit && hit.a === a && hit.b === b) return hit.lib;
  const lib = Object.create(Object.getPrototypeOf(a));
  Object.assign(lib, { asset: a.asset, roles: a.roles, index: a.index, rest: a.rest, clips: new Map(a.clips) });
  for (const [n, c] of b.clips) {
    const tracks = c.tracks.map((t) => ({ ...t, ri: a.index.get(b.roles[t.ri]) })).filter((t) => t.ri !== undefined);
    const cover = new Uint8Array(a.roles.length * 3);
    for (const t of tracks) cover[t.ri * 3 + t.kind] = 1;
    const un = [];
    for (let ri = 0; ri < a.roles.length; ri++) for (let g = 0; g < 3; g++) if (!cover[ri * 3 + g]) un.push(ri * STRIDE + (g === 0 ? 0 : g === 1 ? 3 : 7), g);
    lib.clips.set(n, { ...c, tracks, uncovered: Int32Array.from(un) });
  }
  libs.set(sp, { a, b, lib });
  return lib;
}

// what to call one (toasts, the stall sheet)
export const customerLabel = (sp) => ({ emoji: SPECIES[sp]?.emoji || "🐾", who: SPECIES[sp]?.who || "a customer" });

// can customers come now (the kit and every clip library in)
export function customersReady() {
  if (!animalsReady()) return false;
  return Object.keys(SPECIES).every((sp) => shopLib(sp));
}

let order = 0;
function pickSpecies() {
  // the mix goes round in a shuffled order, so every kind comes by
  const sp = MIX[(order + Math.floor(Math.random() * 2)) % MIX.length];
  order += 1 + Math.floor(Math.random() * 2);
  return sp;
}

function buildAnimal(sp) {
  const S = SPECIES[sp];
  if (sp === "cat" || sp === "bunny") {
    const L = (sp === "cat" ? CATS : BUNNIES)[Math.floor(Math.random() * (sp === "cat" ? CATS.length : BUNNIES.length))];
    const b = buildPetModels({ kind: sp, [sp]: { ...L } })[0];
    return { holder: b.model.root, skin: b.model.skin };
  }
  // (an empty holder: wear() takes the shadow flag from the parts it replaces, so it is set here)
  const holder = new THREE.Group();
  const skin = skinAnimal(holder, {}, { asset: S.asset });
  holder.traverse((o) => o.isMesh && (o.castShadow = true));
  return { holder, skin };
}

const _v = new THREE.Vector3();
const _q = new THREE.Quaternion();
const ease = (x) => (x <= 0 ? 0 : x >= 1 ? 1 : x * x * (3 - 2 * x));

// one customer. ctx: { stall (world.stall), root (world.root), audio, wish, wishBubble(text), slotX() (the stall-local x
// of the bouquet it will take), sale() -> { bouquet (its group, off the stall, no longer freeing itself when moved),
// world (where it stood), happy } | null (takes the bouquet off the stall: the wish one, or the front one, and pays) }
export function stallCustomer(ctx) {
  const st = ctx.stall;
  const G = st.slots[0].parent; // (the stall's own frame: its local z faces the path)
  const sp = pickSpecies();
  const S = SPECIES[sp];
  const lib = shopLib(sp);
  const { holder, skin } = buildAnimal(sp);
  if (!lib || !skin?.worn) return null;
  holder.scale.setScalar(S.scale);
  holder.userData.live = true;
  const local = (x, z) => G.localToWorld(new THREE.Vector3(x, 0, z)).setY(st.front.y);
  const door = st.door.clone();
  holder.position.copy(door);
  ctx.root.add(holder);
  holder.updateMatrixWorld(true);
  fade(holder, 0, 1, 0.6);
  ctx.audio.play(S.hi, { pos: holder.position });

  // the visit: up the path, along the buckets (two looks), to the bouquet it wants, then home again
  const side = Math.random() < 0.5 ? -1 : 1;
  const spotA = local(side * (0.35 + Math.random() * 0.5), 1.95);
  const spotB = local(-side * (0.3 + Math.random() * 0.55), 1.98);
  const faceStall = local(0, -5).sub(local(0, 0));
  const yawStall = Math.atan2(faceStall.x, faceStall.z);
  const plan = [
    { go: spotA },
    { stay: "shop_browse", dur: 3.2 + Math.random() * 1.4 },
    { go: spotB },
    { stay: "shop_browse", dur: 2.6 + Math.random() * 1.2 },
    { go: null }, // (to the bouquet it picks: set when it gets there)
    { pick: true },
    { pay: true },
    { go: local(side * 1.2, 3.2), carry: true },
    { go: door, carry: true, last: true },
  ];

  // its clips
  const an = { a: null, lvl: null, b: null };
  const clock = new AnimClock();
  const loco = S.loco.map((n) => lib.get(n)).filter(Boolean).map((c) => ({ clip: c, speed: c.extras.tdd_speed || 1 }));
  const walkV = (loco[0]?.speed || 1) * S.pace; // (rig m/s; the world speed is this x the scale)
  let socket = null;
  let held = null; // the bouquet, once picked
  let heldIn = false; // (in the socket, its flight from the counter done)
  const bind = () => {
    const lvl = skin.levels?.[Math.min(skin.cur, skin.levels.length - 1)];
    if (!lvl || lvl === an.lvl) return;
    const b = new RigBinding(lib, (r) => lvl.nodes[r] || null, null);
    if (!an.a) {
      an.a = new Animator(b);
      an.a.play(S.idle, 0);
    } else {
      an.a.binding = b;
      an.a.pose = b.newPose();
    }
    an.b = b;
    an.lvl = lvl;
    socket = lvl.nodes[S.hold] || null;
    if (held && socket && held.parent !== socket && heldIn) socket.add(held);
  };
  bind();

  const bubble = ctx.wishBubble(`${ctx.wish.name}?`);
  bubble.visible = false;
  ctx.root.add(bubble);
  const say = (text) => {
    const old = bubble.material.map;
    bubble.material.map = ctx.wishBubble(text).material.map;
    old.dispose();
    bubble.visible = true;
  };

  let step = 0;
  let t = 0; // time in this step
  let speed = 0;
  let yaw = Math.atan2(spotA.x - door.x, spotA.z - door.z);
  let fly = null; // { from (world matrix parts), t }
  let picked = false;
  let fadingOut = false;
  let stepSnd = 0;
  holder.rotation.y = yaw;

  const c = {
    gone: false,
    species: sp,
    tick(dt) {
      if (c.gone) return;
      if (!holder.parent) return c.end();
      bind();
      const A = an.a;
      if (!A) return;
      t += dt;
      const p = holder.position;
      const s = plan[step];
      let moving = false;
      let wantYaw = yaw;
      if (s?.go !== undefined) {
        // (the bouquet it wants decides where along the counter it stands)
        if (!s.go) s.go = local(Math.max(-0.95, Math.min(0.95, ctx.slotX())), 1.92);
        _v.subVectors(s.go, p).setY(0);
        const d = _v.length();
        const v = walkV * S.scale;
        if (d < 0.05) {
          step++;
          t = 0;
        } else {
          moving = true;
          speed += (v - speed) * Math.min(1, dt * 4);
          const k = Math.min(d, speed * dt);
          p.addScaledVector(_v.normalize(), k);
          wantYaw = Math.atan2(_v.x, _v.z);
          if ((stepSnd -= dt) <= 0 && (sp === "cat" || sp === "bunny")) {
            stepSnd = sp === "bunny" ? 0.42 : 0.34;
            ctx.audio.play(sp === "bunny" ? "hop_bunny@0.25" : "paw_cat@0.25", { pos: p });
          }
          if (s.last && d < 1.6 && !fadingOut) {
            fadingOut = true;
            fade(holder, 1, 0, 0.7, () => c.end());
          }
        }
      } else {
        speed += (0 - speed) * Math.min(1, dt * 8);
        wantYaw = yawStall;
        if (s?.stay) {
          if (t < dt * 1.5) A.play(s.stay, 0.35);
          if (t > s.dur) {
            step++;
            t = 0;
            A.play(S.idle, 0.3);
          }
        } else if (s?.pick) {
          const clip = lib.get("shop_pick");
          if (t < dt * 1.5) {
            A.play("shop_pick", 0.25);
            ctx.audio.play(S.voice + "@0.35", { pos: p });
          }
          if (!picked && t >= clip.duration * (clip.extras.tdd_grab ?? 0.5)) {
            picked = true;
            const got = ctx.sale();
            if (got) {
              held = got.bouquet;
              // it hops down off the counter into the customer's paws (or mouth, or spines)
              const from = { p: new THREE.Vector3(), q: new THREE.Quaternion(), s: new THREE.Vector3() };
              got.world.decompose(from.p, from.q, from.s);
              ctx.root.add(held);
              held.position.copy(from.p);
              held.quaternion.copy(from.q);
              held.scale.copy(from.s);
              fly = { from, t: 0 };
              ctx.audio.play("wrap_paper@0.5", { pos: p });
              c.happy = got.happy;
            }
          }
          if (t >= clip.duration - 0.05) {
            step++;
            t = 0;
          }
        } else if (s?.pay) {
          const clip = lib.get("shop_pay");
          if (t < dt * 1.5) {
            A.play("shop_pay", 0.2);
            if (held) {
              say(c.happy ? "yay ♡" : "thank you ♡");
              ctx.audio.play(c.happy ? "till+coin@0.2" : "till", { pos: p });
            }
          }
          if (t >= clip.duration - 0.05) {
            step++;
            t = 0;
            if (held) ctx.audio.play(S.voice + "@0.3", { pos: p });
          }
        }
      }
      // turning toward where it goes (or the stall), never snapping
      const dy = Math.atan2(Math.sin(wantYaw - yaw), Math.cos(wantYaw - yaw));
      yaw += dy * Math.min(1, dt * (moving ? 7 : 4));
      holder.rotation.y = yaw;
      // the gait while it moves, its shop clip / idle when it stands
      const cur = A.current();
      if (moving && cur.name !== "@loco") A.play("@loco", 0.25);
      if (!moving && cur.name === "@loco") A.play(S.idle, 0.3);
      A.overlay("shop_carry", Boolean(heldIn) && !s?.pay, 0.3);
      const pose = A.update(clock.tick(dt).dt, moving ? speed / S.scale : 0, loco);
      an.b.apply(pose);
      // the bouquet's flight into its hold
      if (fly && socket) {
        fly.t += dt / 0.55;
        const k = ease(fly.t);
        holder.updateMatrixWorld(true);
        const tgt = socketTarget();
        held.position.lerpVectors(fly.from.p, tgt.p, k);
        held.position.y += Math.sin(Math.min(1, fly.t) * Math.PI) * 0.35;
        held.quaternion.slerpQuaternions(fly.from.q, tgt.q, k);
        held.scale.lerpVectors(fly.from.s, tgt.s, k);
        if (fly.t >= 1) {
          fly = null;
          socket.add(held);
          held.position.fromArray(S.at);
          held.quaternion.setFromAxisAngle(_v.set(1, 0, 0), S.tilt);
          held.scale.setScalar(holdScale());
          heldIn = true;
        }
      }
      // the bubble rides over its head
      bubble.position.set(p.x, p.y + S.bubble + Math.sin(performance.now() / 500) * 0.02, p.z);
      if (step === 0 && t > 0.8 && !bubble.visible) bubble.visible = true; // its wish, on the way up
      if (step >= plan.length) c.end();
    },
    end() {
      if (c.gone) return;
      c.gone = true;
      if (held) {
        held.removeFromParent();
        held.userData.dispose?.(); // (its own merged bunch)
      }
      bubble.removeFromParent();
      bubble.material.map.dispose();
      bubble.material.dispose();
      holder.removeFromParent();
      // this customer's own skin (the kit's geometry stays: every rig shares it)
      holder.traverse((o) => {
        if (o.isSkinnedMesh) o.skeleton?.dispose();
        if (o.geometry && !o.geometry.userData.kit) o.geometry.dispose();
      });
    },
  };
  // the socket's world pose for the bouquet (where its flight lands)
  const socketTarget = () => {
    socket.updateMatrixWorld(true);
    const m = new THREE.Matrix4().compose(_v.fromArray(S.at), _q.setFromAxisAngle(new THREE.Vector3(1, 0, 0), S.tilt), new THREE.Vector3().setScalar(holdScale()));
    const w = new THREE.Matrix4().multiplyMatrices(socket.matrixWorld, m);
    const out = { p: new THREE.Vector3(), q: new THREE.Quaternion(), s: new THREE.Vector3() };
    w.decompose(out.p, out.q, out.s);
    return out;
  };
  // the bouquet's size in the socket's frame: S.size world metres per bouquet unit, whatever the rig's own scale
  const holdScale = () => {
    socket.updateMatrixWorld(true);
    socket.matrixWorld.decompose(_v, _q, _sc);
    return S.size / Math.max(1e-3, _sc.x);
  };
  return c;
}
const _sc = new THREE.Vector3();
