// a slot's look: a surface name (the house's surfaces) or a piece's own slot (its default, or what the placed piece says)
export function slotLook(home, item, slot) {
  const def = item ? PIECES[item.piece]?.slots?.[slot] : null;
  const own = item?.slots?.[slot];
  if (own) return typeof own === "string" ? { kind: def?.kind || "paint", color: own } : own;
  if (def) return def;
  return home.surfaces[slot] || null;
}
