// Our two boards on the important-dates tower (user 2026-11-27, in place of today's date pages): one counts the
// days we've been together, the other counts down to our next anniversary, with a "today!" of its own on the day.
// The boards themselves are Blender (buildings/_diaryring/dr_pav.py style_calendar: a heart on one, two linked rings
// on the other); their faces (SCREEN_calendar_date_a / _b) show these two canvases, redrawn whenever what they say
// changes (island.js reads the diary each few seconds, so they follow the diary and roll over at midnight).
import * as THREE from "three";
import { textCanvas } from "./textures.js";

const W = 512, H = 449; // the face is 1.62 x 1.42 m
const FONT = '"Fredoka", "Quicksand", "Noto Sans", sans-serif';
const INK = "#5b3a55";
const LOOK = {
  a: { accent: "#ff7fa8", soft: "#ffe3ee", deep: "#e2557f" },
  b: { accent: "#3fb08c", soft: "#ddf6ec", deep: "#2c8a6c" },
};
const boards = {};
// the material for board "a" (days together) or "b" (the anniversary countdown); glTF UVs, so the canvas is not flipped
export function datesBoard(which) {
  if (!boards[which]) {
    const t = textCanvas(W, H);
    t.tex.flipY = false;
    const material = new THREE.MeshStandardMaterial({ map: t.tex, roughness: 0.85, metalness: 0 });
    boards[which] = { ...t, material, key: null };
    paint(which, null);
  }
  return boards[which].material;
}

// (so the zones never give one of them to some other sign)
export const isDatesBoard = (m) => !!m && (m === boards.a?.material || m === boards.b?.material);

// what the boards say, worked out from the diary: `days` = days together (0 when unknown), `start` = the day we
// got together when it's known, `dates` = the important dates widget's lines (title, then "N days left" /
// "today ♡" / "N days ago")
export function datesInfo(days, dateLines, now = new Date()) {
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const start = days > 0 ? addDays(today, -days) : null;
  // the anniversary from the important dates: the soonest one coming
  let next = null;
  for (let i = 0; i + 1 < dateLines.length; i++) {
    if (!/anniv/i.test(dateLines[i])) continue;
    const s = dateLines[i + 1];
    let d = null;
    let m;
    if (/^today/i.test(s)) d = today;
    else if ((m = s.match(/^(\d[\d,]*)\s+days?\s+left/i))) d = addDays(today, +m[1].replace(/,/g, ""));
    else if ((m = s.match(/^(\d[\d,]*)\s+days?\s+ago/i))) d = addDays(today, -m[1].replace(/,/g, ""));
    if (!d) continue;
    // (the diary counts down to the very date it was given and then says "ago": the next one comes round each year)
    const n = d >= today ? d : yearly(d, today);
    if (!next || n < next) next = n;
    i++;
  }
  // none in the dates: the day we got together comes round each year
  if (!next && start) next = yearly(start, today);
  const out = { days: Math.max(0, days | 0), since: start ? short(start) : "", left: null, on: "", nth: 0 };
  if (next) {
    out.left = Math.round((next - today) / 86400000);
    out.on = short(next);
    // which one it is, when it falls on the day we got together
    if (start && next.getMonth() === start.getMonth() && Math.abs(next.getDate() - start.getDate()) <= 1) out.nth = next.getFullYear() - start.getFullYear();
  }
  return out;
}
// our special day today, if it is one (anniv.js decorates the whole island for it), from the same diary as the boards:
// the day we got together comes round (our anniversary, `nth` years), any of the important dates falls on today's day
// and month (an anniversary, a birthday or another date of ours, `title` its line), or it's the day of the month we got
// together on (a monthiversary, `nth` months; the last day of a shorter month stands in for a 29th-31st).
// -> null | { kind: "anniversary" | "birthday" | "date" | "monthiversary", nth, title, key }
export function occasionOf(days, dateLines, now = new Date()) {
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const start = days > 0 ? addDays(today, -days) : null;
  const sameDay = (d) => d.getMonth() === today.getMonth() && (d.getDate() === today.getDate() || (d.getMonth() === 1 && d.getDate() === 29 && today.getDate() === 28 && new Date(today.getFullYear(), 1, 29).getMonth() !== 1));
  const key = (kind) => `${kind}:${today.getFullYear()}-${today.getMonth() + 1}-${today.getDate()}`;
  const found = [];
  if (start && sameDay(start) && today.getFullYear() > start.getFullYear()) found.push({ kind: "anniversary", nth: today.getFullYear() - start.getFullYear(), title: "" });
  for (let i = 0; i + 1 < dateLines.length; i++) {
    const s = dateLines[i + 1];
    let d = null;
    let m;
    if (/^today/i.test(s)) d = today;
    else if ((m = s.match(/^(\d[\d,]*)\s+days?\s+ago/i))) d = addDays(today, -m[1].replace(/,/g, ""));
    else if (/^\d[\d,]*\s+days?\s+left/i.test(s)) {
      i++;
      continue;
    }
    if (!d) continue;
    const title = dateLines[i].slice(0, 60);
    i++;
    if (!sameDay(d)) continue;
    const years = today.getFullYear() - d.getFullYear();
    const kind = /anniv/i.test(title) ? "anniversary" : /birth|bday|b-day/i.test(title) ? "birthday" : "date";
    found.push({ kind, nth: kind === "anniversary" ? years || (start ? today.getFullYear() - start.getFullYear() : 0) : years, title });
  }
  const order = ["anniversary", "birthday", "date"];
  found.sort((a, b) => order.indexOf(a.kind) - order.indexOf(b.kind));
  if (found[0]) return { ...found[0], key: key(found[0].kind) };
  if (start && days >= 20) {
    const last = new Date(today.getFullYear(), today.getMonth() + 1, 0).getDate();
    const want = Math.min(start.getDate(), last);
    if (today.getDate() === want) {
      const nth = (today.getFullYear() - start.getFullYear()) * 12 + today.getMonth() - start.getMonth();
      if (nth > 0) return { kind: "monthiversary", nth, title: "", key: key("monthiversary") };
    }
  }
  return null;
}

const addDays = (d, n) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);
// that date's day and month, this year or (once it's gone by) next year; 29 february on the 28th in other years
function yearly(d, today) {
  const on = (y) => {
    const leap = d.getMonth() === 1 && d.getDate() === 29 && new Date(y, 1, 29).getMonth() !== 1;
    return new Date(y, d.getMonth(), leap ? 28 : d.getDate());
  };
  const n = on(today.getFullYear());
  return n >= today ? n : on(today.getFullYear() + 1);
}
const short = (d) => `${d.getDate()} ${d.toLocaleString("en", { month: "short" }).toLowerCase()} ${d.getFullYear()}`;
const ordinal = (n) => {
  const s = ["th", "st", "nd", "rd"], v = n % 100;
  return n + (s[(v - 20) % 10] || s[v] || s[0]);
};

// redraw both boards if what they say changed
export function drawDates(info) {
  // (a visitor's copy came over the network: only the shape the boards draw)
  info = info && {
    days: Math.max(0, Math.floor(Number(info.days) || 0)),
    since: String(info.since || "").slice(0, 24),
    left: Number.isFinite(info.left) ? Math.max(0, Math.round(info.left)) : null,
    on: String(info.on || "").slice(0, 24),
    nth: Math.max(0, Math.floor(Number(info.nth) || 0)),
  };
  for (const which of ["a", "b"]) if (boards[which]) paint(which, info);
}

function paint(which, info) {
  const B = boards[which];
  const key = JSON.stringify(info);
  if (B.key === key) return;
  B.key = key;
  const g = B.ctx;
  const L = LOOK[which];
  g.clearRect(0, 0, W, H);
  g.fillStyle = "#fff8ec";
  g.fillRect(0, 0, W, H);
  // a soft scalloped band across the top in the board's colour, and a dotted line inside the edge
  g.fillStyle = L.soft;
  g.beginPath();
  g.moveTo(0, 0);
  g.lineTo(W, 0);
  g.lineTo(W, 92);
  for (let x = W; x >= 0; x -= 32) g.arc(x - 16, 92, 16, 0, Math.PI, false);
  g.closePath();
  g.fill();
  g.setLineDash([3, 11]);
  g.lineCap = "round";
  g.lineWidth = 5;
  g.strokeStyle = L.accent;
  g.globalAlpha = 0.45;
  g.strokeRect(18, 18, W - 36, H - 36);
  g.globalAlpha = 1;
  g.setLineDash([]);
  g.textAlign = "center";
  g.textBaseline = "middle";
  const title = which === "a" ? "days together" : "next anniversary";
  g.fillStyle = L.deep;
  g.font = `700 54px ${FONT}`;
  g.fillText(title, W / 2, 60);
  const heart = (x, y, s, col) => {
    g.fillStyle = col;
    g.beginPath();
    g.moveTo(x, y + s * 0.35);
    g.bezierCurveTo(x - s * 1.1, y - s * 0.35, x - s * 0.45, y - s * 1.05, x, y - s * 0.45);
    g.bezierCurveTo(x + s * 0.45, y - s * 1.05, x + s * 1.1, y - s * 0.35, x, y + s * 0.35);
    g.fill();
  };
  const big = (text, y, max = 210) => {
    let size = max;
    g.font = `700 ${size}px ${FONT}`;
    while (g.measureText(text).width > W - 80 && size > 60) g.font = `700 ${(size -= 8)}px ${FONT}`;
    g.fillStyle = INK;
    g.fillText(text, W / 2, y);
  };
  const line = (text, y, size, col = INK, weight = 600) => {
    g.font = `${weight} ${size}px ${FONT}`;
    while (g.measureText(text).width > W - 64 && size > 20) g.font = `${weight} ${(size -= 2)}px ${FONT}`;
    g.fillStyle = col;
    g.fillText(text, W / 2, y);
  };
  if (!info) {
    big("♡", 250, 180);
    B.tex.needsUpdate = true;
    return;
  }
  if (which === "a") {
    if (info.days > 0) {
      big(info.days.toLocaleString("en"), 238);
      line("and counting ♡", 340, 50, L.deep, 700);
      if (info.since) line(`since ${info.since}`, 400, 40, "#8a6d82");
    } else {
      big("♡", 240, 180);
      line("every day with you", 360, 46, L.deep, 700);
    }
  } else if (info.left === null) {
    big("♡", 220, 160);
    line("add our anniversary", 330, 44, L.deep, 700);
    line("to the important dates", 386, 38, "#8a6d82");
  } else if (info.left === 0) {
    // the day itself
    for (const [x, y, s, c] of [[70, 150, 26, "#ff9fc0"], [442, 160, 22, "#ffd166"], [96, 320, 18, "#c7b0f5"], [420, 318, 24, "#ff7fa8"], [256, 118, 16, "#ff7fa8"]]) heart(x, y, s, c);
    big("today!", 226, 150);
    line(info.nth > 0 ? `happy ${ordinal(info.nth)} anniversary` : "happy anniversary", 330, 44, "#e2557f", 700);
    line("i love you ♡", 392, 42, L.deep, 700);
  } else {
    big(String(info.left), 228);
    line(info.left === 1 ? "day to go ♡" : "days to go ♡", 340, 50, L.deep, 700);
    line(info.nth > 0 ? `our ${ordinal(info.nth)} · ${info.on}` : info.on, 400, 40, "#8a6d82");
  }
  B.tex.needsUpdate = true;
}
