// Riding through the island's trees, bushes, stones and little props, and the unicorn's double jump (TODO 27, the
// user 2026-11-22: "while riding the scooter or unicorn, obstacles like trees and stone i should be able to clip
// through them, also unicorn should be able to double jump"). The parts are Blender's (assets/blender/props/ridefx/
// _build_ridefx.py -> props/prp_ridefx_parts.glb: leaf, petal, pebble, star, heart, rainbow): one small shared GLB
// of instance sources, each kind drawn as one InstancedMesh from a fixed pool. The crowns part round a rider and
// swing back on a spring through render/libmat.js PUSH (every leaf material takes it with nearFade).
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { MeshoptDecoder } from "three/examples/jsm/libs/meshopt_decoder.module.js";
import { zonePack } from "./zones/mode.js";
import { PUSH } from "./render/libmat.js";

const KINDS = { leaf: 140, petal: 110, pebble: 50, star: 90, heart: 30 };
const _m = new THREE.Matrix4();
const _q = new THREE.Quaternion();
const _p = new THREE.Vector3();
const _s = new THREE.Vector3();
const _ax = new THREE.Vector3();
const _c = new THREE.Color();
// the rainbow's pastel stars, in the rainbow ring's own band colours (_build_ridefx.py)
const RAINBOW = ["#ff9fb8", "#ffc59a", "#ffe9a0", "#b8efb4", "#a8d8ff", "#cdb6ff"];
const GREENS = ["#6fae6a", "#88bf6c", "#5d9a5e", "#a3c977", "#7fb48a"];

export class RideFx {
  constructor(scene, { lowEnd = false } = {}) {
    this.scene = scene;
    this.k = lowEnd ? 0.6 : 1; // (phones: fewer bits in every burst)
    this.pools = null; // kind -> { mesh, n, cap, d: Float32Array per particle }
    this.rings = [];
    this.pushers = new Map(); // key -> { x, z, y, amp, vel, want, seen }
    this.t = 0;
    this.load();
  }

  load() {
    const base = zonePack();
    if (!base) return;
    new GLTFLoader()
      .setMeshoptDecoder(MeshoptDecoder)
      .loadAsync(base + "props/prp_ridefx_parts.glb")
      .then((g) => {
        const geo = {};
        g.scene.traverse((o) => {
          if (!o.isMesh) return;
          const role = o.userData?.tdd_role || /^INST_prp_ridefx_parts_(.+)$/.exec(o.name)?.[1];
          if (role) geo[role] = o.geometry;
          o.material?.dispose?.();
        });
        this.build(geo);
      })
      .catch((e) => console.warn("ride fx", e));
  }

  build(geo) {
    this.pools = {};
    for (const [kind, cap0] of Object.entries(KINDS)) {
      if (!geo[kind]) continue;
      const cap = Math.ceil(cap0 * this.k);
      const flat = kind === "leaf" || kind === "petal";
      const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: flat ? 0.75 : 0.55, metalness: 0, side: flat ? THREE.DoubleSide : THREE.FrontSide, emissive: kind === "star" || kind === "heart" ? "#ffffff" : "#000000", emissiveIntensity: 0.12 });
      const mesh = new THREE.InstancedMesh(geo[kind], mat, cap);
      mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      mesh.setColorAt(0, _c.set("#ffffff"));
      mesh.count = 0;
      mesh.frustumCulled = false; // (the bits fly round the rider; the pool's bounds would be its first copy's)
      mesh.castShadow = false;
      mesh.name = "ridefx_" + kind;
      this.scene.add(mesh);
      // per particle: px py pz vx vy vz ax ay az ang spin life max size gy flutter
      this.pools[kind] = { mesh, cap, n: 0, d: new Float32Array(cap * 16), col: new Float32Array(cap * 3) };
    }
    if (geo.rainbow)
      for (let i = 0; i < 2; i++) {
        const m = new THREE.Mesh(geo.rainbow, new THREE.MeshBasicMaterial({ vertexColors: true, transparent: true, opacity: 0, depthWrite: false, side: THREE.DoubleSide, toneMapped: false }));
        m.visible = false;
        m.renderOrder = 3;
        m.name = "ridefx_rainbow";
        this.scene.add(m);
        this.rings.push({ m, t: 1, delay: 0 });
      }
  }

  spawn(kind, x, y, z, vx, vy, vz, life, size, color, groundY, flutter = 0) {
    const P = this.pools?.[kind];
    if (!P) return;
    let i = P.n;
    if (i >= P.cap) i = Math.floor(Math.random() * P.cap); // (full: an old one is reused)
    else P.n++;
    const d = P.d;
    const o = i * 16;
    _ax.set(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5).normalize();
    d[o] = x;
    d[o + 1] = y;
    d[o + 2] = z;
    d[o + 3] = vx;
    d[o + 4] = vy;
    d[o + 5] = vz;
    d[o + 6] = _ax.x;
    d[o + 7] = _ax.y;
    d[o + 8] = _ax.z;
    d[o + 9] = Math.random() * Math.PI * 2;
    d[o + 10] = (Math.random() < 0.5 ? -1 : 1) * (2 + Math.random() * 5);
    d[o + 11] = life;
    d[o + 12] = life;
    d[o + 13] = size;
    d[o + 14] = groundY;
    d[o + 15] = flutter;
    _c.set(color);
    P.col[i * 3] = _c.r;
    P.col[i * 3 + 1] = _c.g;
    P.col[i * 3 + 2] = _c.b;
  }

  // a rider goes into a tree, bush, stone or prop: what it shakes out (kind: the circle's `soft`, world.js),
  // where (the rider's feet), which way and how fast they were going; tint: the crown's colour (the theme's)
  // (amount: 1 for a rider; less for someone on foot, who only brushes a few leaves loose)
  rustle(kind, at, heading, speed, tint, amount = 1) {
    const fwd = Math.min(1, Math.abs(speed) / 16);
    const hx = Math.sin(heading) * speed * 0.22;
    const hz = Math.cos(heading) * speed * 0.22;
    const R = Math.random;
    if (kind === "stone") {
      const n = Math.round((4 + 5 * fwd) * this.k);
      for (let i = 0; i < n; i++) {
        const a = R() * Math.PI * 2;
        this.spawn("pebble", at.x + Math.sin(a) * 0.3, at.y + 0.15, at.z + Math.cos(a) * 0.3, hx * 0.6 + Math.sin(a) * (0.8 + R()), 1.8 + R() * 2.2, hz * 0.6 + Math.cos(a) * (0.8 + R()), 1.1 + R() * 0.5, 0.7 + R() * 0.7, ["#ffffff", "#f1e9f0", "#e2d8e2"][i % 3], at.y);
      }
      return;
    }
    if (kind === "prop") {
      const n = Math.round(5 * this.k);
      for (let i = 0; i < n; i++) {
        const a = (i / n) * Math.PI * 2;
        this.spawn("star", at.x + Math.sin(a) * 0.3, at.y + 0.9 + R() * 0.6, at.z + Math.cos(a) * 0.3, Math.sin(a) * 1.2 + hx * 0.3, 0.8 + R(), Math.cos(a) * 1.2 + hz * 0.3, 0.7 + R() * 0.3, 0.55, "#fff2c4", at.y - 10);
      }
      return;
    }
    // leaves (and the blossoms' petals) shaken out of the crown above and round the rider, carried a little the
    // way the ride goes, then fluttering down to settle on the ground
    const bush = kind === "bush";
    const n = Math.round((bush ? 7 + 6 * fwd : 9 + 9 * fwd) * this.k * amount);
    const base = tint ? _c.copy(tint) : null;
    for (let i = 0; i < n; i++) {
      const a = R() * Math.PI * 2;
      const r = 0.3 + R() * (bush ? 0.5 : 1.0);
      const y = at.y + (bush ? 0.3 + R() * 0.6 : 1.1 + R() * 1.9);
      const petal = kind === "blossom" && R() < 0.75;
      let col;
      if (base) {
        const v = 0.82 + R() * 0.3;
        col = new THREE.Color(base.r * v, base.g * v, base.b * v);
      } else col = GREENS[Math.floor(R() * GREENS.length)];
      this.spawn(petal ? "petal" : "leaf", at.x + Math.sin(a) * r, y, at.z + Math.cos(a) * r, hx + Math.sin(a) * (0.6 + R() * 1.2), 0.4 + R() * 1.4, hz + Math.cos(a) * (0.6 + R() * 1.2), 2.6 + R() * 1.6, petal ? 0.9 + R() * 0.5 : 0.8 + R() * 0.5, col, at.y, 1);
    }
  }

  // the crown round a rider bends away from them while they are in it (call every frame they are), and springs
  // back past rest when they leave
  push(key, x, z, y, amount) {
    let p = this.pushers.get(key);
    if (!p) this.pushers.set(key, (p = { x, z, y, amp: 0, vel: 0, want: 0, seen: 0 }));
    p.x = x;
    p.z = z;
    p.y = y;
    p.want = amount;
    p.seen = 2;
  }

  // the unicorn's second jump: a ring of rainbow bursts out flat under its hooves (and a second, smaller one a
  // beat behind), stars in the ring's colours and a few hearts kick out and down, as if it pushed off them
  doubleJump(at, heading) {
    const R = Math.random;
    this.rings.forEach((r, i) => {
      r.t = 0;
      r.delay = i * 0.09;
      r.size = i ? 1.7 : 2.6;
      r.m.position.set(at.x, at.y + 0.05, at.z);
      r.m.rotation.set(0, heading + i * 0.4, 0);
    });
    const n = Math.round(22 * this.k);
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2 + R() * 0.2;
      const sp = 2.6 + R() * 1.8;
      this.spawn("star", at.x + Math.sin(a) * 0.35, at.y + 0.1 + R() * 0.3, at.z + Math.cos(a) * 0.35, Math.sin(a) * sp, -0.4 + R() * 1.6, Math.cos(a) * sp, 0.8 + R() * 0.4, 0.8 + R() * 0.6, RAINBOW[i % RAINBOW.length], at.y - 0.2);
    }
    for (let i = 0; i < Math.round(6 * this.k); i++) {
      const a = R() * Math.PI * 2;
      this.spawn("heart", at.x + Math.sin(a) * 0.25, at.y + 0.6, at.z + Math.cos(a) * 0.25, Math.sin(a) * 1.4, 0.6 + R() * 1.2, Math.cos(a) * 1.4, 1.0 + R() * 0.4, 0.9 + R() * 0.4, R() < 0.5 ? "#ff8fb8" : "#ffb3cf", at.y - 0.2);
    }
  }

  update(dt) {
    this.t += dt;
    // the crowns' springs (underdamped: they part, then swing back past rest and settle)
    for (const [key, p] of this.pushers) {
      p.seen--;
      const want = p.seen > 0 ? p.want : 0;
      const h = Math.min(dt, 1 / 30);
      p.vel += (55 * (want - p.amp) - 3.6 * p.vel) * h;
      p.amp += p.vel * h;
      if (p.seen <= 0 && Math.abs(p.amp) < 0.003 && Math.abs(p.vel) < 0.02) this.pushers.delete(key);
    }
    const live = [...this.pushers.values()].sort((a, b) => Math.abs(b.amp) - Math.abs(a.amp));
    for (let i = 0; i < 4; i++) {
      const p = live[i];
      if (p) PUSH.value[i].set(p.x, p.z, p.y, p.amp || 1e-6);
      else PUSH.value[i].set(0, 0, 0, 0);
    }
    for (const r of this.rings) {
      if (r.t >= 1) continue;
      if (r.delay > 0) {
        r.delay -= dt;
        continue;
      }
      r.t = Math.min(1, r.t + dt / 0.65);
      const e = 1 - Math.pow(1 - r.t, 3);
      r.m.visible = r.t < 1;
      r.m.scale.setScalar(0.25 + e * r.size);
      r.m.position.y += dt * 0.25;
      r.m.material.opacity = 0.95 * (1 - r.t) * Math.min(1, r.t * 12);
    }
    if (!this.pools) return;
    for (const P of Object.values(this.pools)) {
      if (!P.n) {
        P.mesh.count = 0;
        continue;
      }
      const d = P.d;
      const kind = P.mesh.name.slice(7);
      const flat = kind === "leaf" || kind === "petal";
      for (let i = 0; i < P.n; i++) {
        const o = i * 16;
        d[o + 11] -= dt;
        if (d[o + 11] <= 0) {
          // (swap the last one in)
          P.n--;
          const l = P.n * 16;
          if (i !== P.n) {
            d.copyWithin(o, l, l + 16);
            P.col.copyWithin(i * 3, P.n * 3, P.n * 3 + 3);
          }
          i--;
          continue;
        }
        const g = flat ? 2.4 : kind === "pebble" ? 11 : 3.2;
        const drag = flat ? 2.2 : kind === "pebble" ? 0.3 : 1.6;
        const k = Math.exp(-drag * dt);
        d[o + 3] *= k;
        d[o + 5] *= k;
        d[o + 4] -= g * dt;
        if (flat) {
          // (a leaf falls slow and side to side, rocking as it goes)
          d[o + 4] = Math.max(d[o + 4], -0.9);
          const ph = this.t * 4.2 + d[o + 9];
          d[o] += Math.sin(ph) * 0.55 * dt;
          d[o + 2] += Math.cos(ph * 0.8) * 0.4 * dt;
        }
        d[o] += d[o + 3] * dt;
        d[o + 1] += d[o + 4] * dt;
        d[o + 2] += d[o + 5] * dt;
        const gy = d[o + 14] + (flat ? 0.02 : kind === "pebble" ? 0.02 : -9);
        if (d[o + 1] < gy) {
          d[o + 1] = gy;
          if (kind === "pebble" && d[o + 4] < -1.5) {
            d[o + 4] *= -0.3;
            d[o + 3] *= 0.5;
            d[o + 5] *= 0.5;
          } else {
            d[o + 3] = d[o + 4] = d[o + 5] = 0;
            d[o + 10] = 0;
            d[o + 15] = 0;
          }
        }
        d[o + 9] += d[o + 10] * dt;
        const age = d[o + 12] - d[o + 11];
        const left = d[o + 11];
        // (pops in, shrinks away at the end)
        const pop = kind === "star" || kind === "heart" ? Math.min(1, age / 0.12) * (1 + 0.25 * Math.max(0, 1 - age / 0.25)) : Math.min(1, age / 0.08);
        const sc = d[o + 13] * pop * Math.min(1, left / 0.45);
        _ax.set(d[o + 6], d[o + 7], d[o + 8]);
        _q.setFromAxisAngle(_ax, d[o + 9]);
        if (flat && d[o + 15] === 0 && d[o + 10] === 0) _q.setFromAxisAngle(_ax.set(0, 1, 0), d[o + 9]); // (lying on the ground)
        _m.compose(_p.set(d[o], d[o + 1], d[o + 2]), _q, _s.setScalar(Math.max(1e-4, sc)));
        P.mesh.setMatrixAt(i, _m);
        P.mesh.setColorAt(i, _c.setRGB(P.col[i * 3], P.col[i * 3 + 1], P.col[i * 3 + 2]));
      }
      P.mesh.count = P.n;
      P.mesh.instanceMatrix.needsUpdate = true;
      if (P.mesh.instanceColor) P.mesh.instanceColor.needsUpdate = true;
    }
  }
}
