// Dev-only performance overlay (TODO 1/2: real iPhone numbers). Shown only with ?perf=1 in the address; otherwise
// nothing is created and nothing is wrapped. Shows fps, frame time (average and worst over half a second), draws and
// triangles a frame (every render call of the frame added up: the shadow passes too), the pixel ratio, the canvas
// size and the device tier.
export function perfHud({ renderer, tier }) {
  // (?perf=1 is remembered on this device until ?perf=0, so a sign-in or a reload that drops the address flag keeps it)
  let on = false;
  try {
    const q = new URLSearchParams(location.search).get("perf");
    if (q === "1") localStorage.setItem("tdd.perf", "1");
    else if (q === "0") localStorage.removeItem("tdd.perf");
    on = q === "1" || localStorage.getItem("tdd.perf") === "1";
  } catch {}
  if (!on) return null;
  const box = document.createElement("div");
  box.setAttribute("aria-hidden", "true");
  box.style.cssText =
    "position:fixed;left:calc(env(safe-area-inset-left, 0px) + 8px);top:calc(env(safe-area-inset-top, 0px) + 8px);z-index:99999;pointer-events:none;font:11px/1.35 ui-monospace,Menlo,monospace;color:#fff;background:rgba(0,0,0,.62);padding:5px 7px;border-radius:6px;white-space:pre";
  // (kept inside the game's own box, so it stays visible when that box goes full screen; re-homed each refresh,
  // since the canvas is put on the page after this runs)
  const home = () => {
    const p = renderer.domElement.parentElement || document.body;
    if (box.parentElement !== p) p.append(box);
  };
  home();
  const info = renderer.info;
  const render = renderer.render;
  let calls = 0;
  let tris = 0;
  renderer.render = function (scene, camera) {
    render.call(this, scene, camera);
    calls += info.render.calls;
    tris += info.render.triangles;
  };
  let frames = 0;
  let sum = 0;
  let worst = 0;
  let dc = 0;
  let tc = 0;
  let last = performance.now();
  let shown = last;
  let alive = true;
  const tick = (t) => {
    if (!alive) return;
    const dt = t - last;
    last = t;
    frames++;
    sum += dt;
    worst = Math.max(worst, dt);
    dc += calls;
    tc += tris;
    calls = 0;
    tris = 0;
    if (t - shown >= 500 && frames > 1) {
      home();
      const c = renderer.domElement;
      box.textContent =
        `${Math.round((1000 * frames) / sum)} fps  ${(sum / frames).toFixed(1)} ms (worst ${worst.toFixed(0)})\n` +
        `${Math.round(dc / frames)} draws  ${Math.round(tc / frames / 1000)}k tris\n` +
        `ratio ${renderer.getPixelRatio().toFixed(2)} (dpr ${devicePixelRatio || 1})  ${c.width}x${c.height}\n` +
        `tier ${tier?.name || "?"}${tier?.info?.touch ? " touch" : ""}`;
      shown = t;
      frames = 0;
      sum = 0;
      worst = 0;
      dc = 0;
      tc = 0;
    }
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
  return {
    dispose() {
      alive = false;
      renderer.render = render;
      box.remove();
    },
  };
}
